\section{Appendix A}
\label{apx:1}

Here we derive the Eq. (\ref{eq:alpha_t_primes}) in detail. 
Since we have
\begin{equation}
    \mathbb{E}\left(\|z'\|^2\right) = \bar{\alpha}_{T'}\|f_0\|^2 + \left(1-\bar{\alpha_{T'}}\right)D
\end{equation}
and
\begin{equation}
\begin{split}
    \mathbb{E}\left(\|\hat{z}''\|^2\right) &= \bar{\alpha}_{T'}\|f_0\|^2 + \left(1-\bar{\alpha}_{T''}\right)D + \sigma^2_{\text{ch}}D \\
    &= \bar{\alpha}_{T'}\|f_0\|^2 + \left(1-\bar{\alpha}_{T''}\right)D \\
    &~~~+ \frac{\bar{\alpha}_{T'}\mathbb{E}\left(\|f_0\|^2\right) + (1-\bar{\alpha}_{T''}) D}{\gamma}D,
\end{split}
\end{equation}
we can get
\begin{equation}
    1-\bar{\alpha_{T''}} + \frac{\bar{\alpha}_{T'}\mathbb{E}\left(\|f_0\|^2\right) + (1-\bar{\alpha}_{T''}) D}{\gamma} = 1-\bar{\alpha_{T'}}
\end{equation}
when $\mathbb{E}\left(\|z'\|^2\right) = \mathbb{E}\left(\|\hat{z}''\|^2\right)$. Then
\begin{equation}
    \bar{\alpha}_{T''}\left(1+\frac{D}{\gamma}\right) = \bar{\alpha}_{T'}\left(1+\frac{\mathbb{E}(\|f_0\|^2)}{\gamma}\right) + \frac{D}{\gamma}.
\end{equation}
Arranging the formula above, we can get
\begin{equation}
    \bar{\alpha}_{T''} = \frac{\bar{\alpha}_{T'} \left(\gamma + \mathbb{E}\left(\|f_0\|^2\right)\right) + D}{\gamma + D}.
\end{equation}

