\section{Algorithm Details}
\label{sec:app_alg}

In this section, we provide additional descriptions and illustrations for the algorithms described in Sections~\ref{sec:background} and~\ref{sec:method} of the main paper.

\subsection{Path Mapping and Look-ahead Recursion}
\label{sec:app_rec}

First, we add a more detailed description of the path mapping recursion and its adaptions for the look-ahead heuristic, as well as pseudocode and additional illustrations.

Figure~\ref{fig:recursion} shows four cases of the recursive structure.
The first two come from the original path mapping recursion.
There, we have overall two types of cases (intuitively speaking) for subtrees $T_1[(n_1,p_1)],T_2[(n_2,p_2)]$:
\begin{itemize}
    \item[(a)] We match the root paths $(n_1,p_1),(n_2,p_2)$ onto each other and continue with recursive cases for the subtrees rooted in the children of $n_1,n_2$. In this case, the optimal assignment happens on the two sets of subtrees directly below $n_1,n_2$.
    \item[(b)] We delete one of the subtrees rooted in the children of $n_1$ or $n_2$, e.g.\ the subtree rooted in $(v_{1,2},n_1)$ in Figure~\ref{fig:recursion}. In this case, we continue in one recursive case, $T_1[(v_{1,1},p_1)]$ (the remaining child of $n_1$) with $T_2[(n_2,p_2)]$ (the second tree unchanged).
\end{itemize}

In the extended variant with look-ahead, we also add cases for deletions of edges without deleting the full subtree below them.
These deletions come in the form of collapsing sets of consecutive edges below $n_1,n_2$.
In Figure~\ref{fig:recursion}~(c,d), two example deletions are shown.

The complete algorithm in psuedocode is given in Alogirthm~\ref{alg:edist}.
\textcolor{revision}{The code uses $\delta_h(T_1,T_2,n_1,p_1,n_2,p_2)$ synonym to $\delta_h(T_1[n1,p_1],T_2[n_2,p_2])$.}
The lines that have been added for the look-ahead heuristic (and are not part of the original path mapping algorithm) are highlighted in blue.
Lines~2 to~14 describe the trivial base-cases: one of the trees is either empty or has only one edge.
Lines~17 to~21 describe the three cases for non-trivial trees as discussed in the main paper and visualized in Figure~\ref{fig:recursion}(a,b).
Line~22 adds the fourth case for the look-ahead collapse procedure, illustrated in Figure~\ref{fig:recursion}(c,d).

\SetKwComment{Comment}{/* }{ */}
\setlength{\algomargin}{5pt}
\SetAlgoVlined
\begin{algorithm}[!ht]
\caption{Path mapping distance with look-ahead}
\label{alg:edist}
\SetKwFunction{pathDist}{$\laedist$}
\SetKwProg{Fn}{Function}{:}{}
\DontPrintSemicolon
\Fn{\pathDist{$T_1,T_2,n_1,p_1,n_2,p_2$}}{
\If{$n_1=\bot$ and $n_2$ is a leaf}{
  \Return $\cost(\bot,p_2...n_2)$\;
}
\If{$n_2=\bot$ and $n_1$ is a leaf}{
  \Return $\cost(p_1...n_1,\bot)$\;
}
\If{$n_1=\bot$ and $n_2$ is an inner node}{
  \Return~$\cost(\bot,p_2...n_2) + \sum_{c_2 \in C_{T_2}(n_2)} \pathDist(\bot,\bot,c_2,n_2)$\;
}
\If{$n_2=\bot$ and $n_1$ is an inner node}{
  \Return~$\cost(p_1...n_1,\bot) + \sum_{c_1 \in C_{T_1}(n_1)} \pathDist(c_1,n_1,\bot,\bot)$\;
}
\If{$n_1$ is a leaf and $n_2$ is a leaf}{
  \Return $\cost(p_1...n_1,p_2...n_2)$\;
}
\If{$n_1$ is a leaf and $n_2$ is an inner node}{
  \Return $ \min_{c_2 \in C_{T_2}(n_2)} \{ \pathDist(n_1,p_1,c_2,p_2) 
  - \pathDist(\bot,\bot,c_2,n_2)
  + \sum_{c_2' \in C_{T_2}(n_2)} \pathDist(\bot,\bot,c_2',n_2) \} $\;
}
\If{$n_2$ is a leaf and $n_1$ is an inner node}{
  \Return $ \min_{c_1 \in C_{T_1}(n_1)} \{ \pathDist(c_1,p_1,n_2,p_2) 
  - \pathDist(c_1,n_1,\bot,\bot)
  + \sum_{c_1' \in C_{T_1}(n_1)} \pathDist(c_1',n_1,\bot,\bot) \} $\;
}
\If{$n_1$ is an inner node and $n_2$ is an inner node}{
  $d_1 \coloneqq \min_{c_2 \in C_{T_2}(n_2)} \{ \pathDist(n_1,p_1,c_2,p_2) 
  - \pathDist(\bot,\bot,c_2,n_2)
  + \sum_{c_2' \in C_{T_2}(n_2)} \pathDist(\bot,\bot,c_2',n_2) \} $\;
  $d_2 \coloneqq \min_{c_1 \in C_{T_1}(n_1)} \{ \pathDist(c_1,p_1,n_2,p_2) 
  - \pathDist(c_1,n_1,\bot,\bot)
  + \sum_{c_1' \in C_{T_1}(n_1)} \pathDist(c_1',n_1,\bot,\bot) \} $\;
  $C_1 = \bigcup_{x \in C_{T_1}(n_1)} (x,n_1)$\;
  $C_2 = \bigcup_{x \in C_{T_2}(n_2)} (x,n_2)$\;
  $d_3 \coloneqq \min\{ \cost(m,\laedist) \mid m \in PM(C_1,C_2) \}$\;
  \textcolor{blue}{$d_4 \coloneqq \texttt{OptCollapse}(T_1,T_2,n_1,n_2,h)$}\;
  \Return~$\min(d_1,d_2,\min(d_3,\textcolor{blue}{d_4})+\cost(p_1...n_1,p_2...n_2))$\;
}
}
\end{algorithm}

