& &\\
\begin{array}{c}
X = Y = 0\\
\begin{array}{l || l}
a = X; & \,b = Y;\\
\mathbf{if}(a == 1)\, & \,\mathbf{if}(b == 1)\\
\quad Y = 1; & \quad X = 1;
\end{array}\\
a = b = 1\\
(\textrm{LBD})
\end{array}
& 
