\quad\quad \mathbf{long}\ \mathsf{v} = \mathsf{counter}.\mathsf{fetch\_and\_add\_release}(-1);\\
\quad\quad \mathbf{if}\ (\mathsf{v}\;{=}{=}\;1)\ \{\\
\quad\quad\quad \mathsf{AtomicLong}.\mathsf{fence\_acquire}();\\
