\begin{thm}\label{main} Let $f_1(x), f_2(x), g_1(x)$ and $g_2(x)$ be monic divisors of $x^n-1$ over $R$ and $ (r_1(x), r_2(x)) \in (R[x])^2 $ with $\deg(f_1(x)r_1(x))<\deg(g_1(x))$ and $\deg(f_2(x)r_2(x))<\deg(g_2(x))$ such that 
$$
\mathcal{C} = \langle f_1(\overline{x})(1 + \mu r_1(\overline{x})), \mu g_1(\overline{x}) \rangle_{_{\mathcal{R}_n}}
\text{ and }
\mathcal{D}  = \langle f_2(\overline{x})(1 + \mu r_2(\overline{x})), \mu g_2(\overline{x}) \rangle_{_{\mathcal{R}_n}}
$$
 are two $ S | R $ additive cyclic codes of length $ n $. Then,   the pair $(\mathcal{C}, \mathcal{D})$ is ACP if and only if $f_1(x)f_2(x)=g_1(x)g_2(x)=x^n-1$.
\end{thm}

\begin{proof}
Assume that $\{\CC, \CD\}$ is ACP. By Theorem \ref{th-4.10} we know that  $\{\pi(\CC), \pi(\CD)\}$ is an ACP of $\mathbb F_q$-linear $\mathbb F_{q^2}$-codes.     Then $\langle \pi(f_1(x))\rangle_{_{\mathbb F_q}}+\langle \pi(f_2(x)) \rangle_{_{\mathbb F_q}}=\mathbb F_{q^2}^n$ and 
$$
 \langle \mu \pi(g_1)(\overline{x}) \rangle_{_{\mathbb F_q}}\cap\langle \mu \pi(g_2)(\overline{x}) \rangle_{_{\mathbb F_q}}\subseteq\pi(\CC)\cap\pi(\CD)=\{0\}.
$$
Thus $\mathrm{gcd}(\pi(f_1(x)), \pi(f_2(x)))=1,$ and $\lcm(\pi(g_1(x)),\pi(g_2(x))))=x^n-1$. It follows that $\pi(f_1(x))\pi(f_2(x))=\pi(g_1(x))\pi(g_2(x))=x^n-1$, since $f_1(x), f_2(x), g_1(x)$ and $g_2(x)$ are monic divisors of $x^n-1$ and $\deg(f_1(x)f_2(x))+\deg(g_1(x)g_2(x))=2n$. Hence, by Hensel lift, we have $f_1(x)f_2(x)=g_1(x)g_2(x)=x^n-1$.

Conversely, suppose that $f_1(x)f_2(x)=g_1(x)g_2(x)=x^n-1$. To prove the result, let us define a map
$$\begin{array}{cccc}
  \psi: & \CC\cap\CD & \rightarrow & \mathcal{R}_n \\
    & a(\overline{x})+\mu b(\overline{x}) & \mapsto & a(\overline{x}).
\end{array}$$   
 Clearly, $\CC\cap \CD$ is additive $R|S$ cyclic code of length $ n $. Obviously, $\texttt{Im}(\psi)=\langle f_1(x)f_2(x)\rangle$ and $\mathrm{Ker}(\psi)=\langle g_1(x)g_2(x)\rangle$. By Theorem~\ref{th-3.3}, we have
\[
\CC\cap\CD=\langle f_1(\overline{x})f_2(\overline{x})(1+\mu r(\overline{x})), \mu g_1(\overline{x})g_2(\overline{x}) \rangle_{_{\mathcal{R}_n}},
\] 
where $r(x)\in R[x]$. By hypothesis $f_1(\overline{x})f_2(\overline{x})=g_1(\overline{x})g_2(\overline{x})=\overline{x}^n-1=0$. 
Thus, we obtain $\CC\cap\CD=\{\mathbf 0\}$. Since $x^n-1$ is square-free, we get $\langle f_1(\overline{x}) \rangle+\langle f_2(\overline{x}) \rangle=\mathcal{R}_n$ ($f_1$ and $f_2$ are coprime) and $\langle g_1(\overline{x}) \rangle+\langle g_2(\overline{x})  \rangle=\mathcal{R}_n$ ($g_1(x)$ and $g_2(x)$ are coprime polynomials) which results $\rk_{_R}(\CC)+\rk_{_R}(\CD)=2n$. Therefore, applying Theorem~\ref{th-4.7}, the result follows.
\end{proof}

\begin{cor}\label{cor:norem}
      Let $f_1(x), f_2(x), g_1(x)$ and $g_2(x)$ are monic divisors of $x^n-1$ over $R$ and $ (r_1(x), r_2(x)) \in (R[x])^2 $ with $\deg(f_1(x)r_1(x))<\deg(g_1(x))$ and $\deg(f_2(x)r_2(x))<\deg(g_2(x))$ such that 
$$
\mathcal{C} = \langle f_1(\overline{x})(1 + \mu r_1(\overline{x})), \mu g_1(\overline{x}) \rangle_{_{\mathcal{R}_n}}
\text{ and }
\mathcal{D}  = \langle f_2(\overline{x})(1 + \mu r_2(\overline{x})), \mu g_2(\overline{x}) \rangle_{_{\mathcal{R}_n}}
.$$  If  $\{\mathcal{C},\mathcal{D}\}$ is ACP then $r_1(x)=r_2(x)=0$.
\end{cor}
\begin{proof}
    According to Theorem \ref{main},  it follows that $f_1f_2=g_1g_2=x^n-1$. Consider this map $$
 \begin{array}{cccc}
   \varphi : & \mathcal{S}_n & \rightarrow & \mathcal{R}_n \\
     & a(\overline{x})+\mu b(\overline{x}) & \mapsto & b(\overline{x}) 
 \end{array}
 $$ that is an epimorphism of $\mathcal{R}_n$-modules. We have $$\varphi(\mathcal{C})=\langle f_1(\overline{x}) r_1(\overline{x})),  g_1(\overline{x}) \rangle_{_{\mathcal{R}_n}}\text{ and  }\varphi(\mathcal{D})=\langle f_2(\overline{x}) r_2(\overline{x})),  g_2(\overline{x}) \rangle_{_{\mathcal{R}_n}}.$$ Note that $\mathcal{R}_n$ is a principal ideal ring, thus there exist polynomials $d_1(x)$ and $d_2(x)$  monic divisors of $x^n-1$ such that $\varphi(\mathcal{C})=\langle d_1(\overline{x})  \rangle_{_{\mathcal{R}_n}}$ and  $\varphi(\mathcal{D})=\langle d_2(\overline{x})  \rangle_{_{\mathcal{R}_n}}.$ Since $\mathcal{C}+\mathcal{D}=\mathcal{S}_n$ and $\varphi$ is an epimorphism of $\mathcal{R}_n$-modules, it follows that $\varphi(\mathcal{C})+\varphi(\mathcal{D})=\mathcal{R}_n$. Thus $d_1(x)$ and $d_2(x)$ are coprime polynomials and $d_1(x)d_2(x)$ divides $x^n-1$. According to Lemma \ref{lm-4.6}, we have $$\rk_{R}(\mathcal{R}_n)=\rk_{R}(\varphi(\mathcal{C}))+\rk_{R}(\varphi(\mathcal{D}))-\rk_{R}(\varphi(\mathcal{C})\cap\varphi(\mathcal{D})).$$ Thus $\deg(d_1(x))+\deg(d_2(x))=n$. Hence $d_1(x)d_2(x)=x^n-1$ and  $d_1(x)=g_1(x)$ and $d_2(x)=g_2(x)$.  Since $\deg(f_1(x)r_1(x))<\deg(g_1(x))$ and $\deg(f_2(x)r_2(x))<\deg(g_2(x))$, we have $f_1(x)r_2(x)=f_2(x)r_2(x)=0$.  It follows that $r_1(x)=r_2(x)=0$, since $f_1(x)$ and $f_2(x)$. 
\end{proof}

\begin{cor}\label{cor:per} Let $f_1(x), f_2(x), g_1(x)$ and $g_2(x)$ be monic divisors of $x^n-1$ over $R$  such that 
$\mathcal{C} = \mathcal{C}_1 \ \oplus \mu\mathcal{C}_2  
\text{ and }
\mathcal{D}  = \mathcal{D}_1 \ \oplus \mu\mathcal{D}_2
,$
where $\mathcal{C}_1=\langle f_1(\overline{x}) \rangle, \mathcal{C}_2=\langle g_1(\overline{x}) \rangle, \mathcal{D}_1=\langle f_2(\overline{x}) \rangle,$ and $\mathcal{D}_2=\langle g_2(\overline{x}) \rangle.$
 Let $\sigma$ be the permutation of $\{0,1,\cdots, n-1\}$ defined by $\sigma(i)=n-i-1$. Then the following assertions are equivalent.
\begin{enumerate}
  \item The pair $\{\mathcal{C},\mathcal{D}\}$ is ACP.
  \item The pairs $\{\mathcal{C}_1,\mathcal{D}_1\}$ and $\{\mathcal{C}_2,\mathcal{D}_2\}$ are LCP of codes.
  \item $\mathcal{C}_1^{^{\perp}}=\sigma(\mathcal{D}_1)$ and $\mathcal{C}_2^{^{\perp}}=\sigma(\mathcal{D}_2)$.
  \item $\mathcal{C}^{^{\perp_{\mathrm{Tr}}}}=\sigma(\mathcal{D})$. 
\end{enumerate}
\end{cor}

\begin{proof} $\quad$
\begin{description}
  \item[1) $\Rightarrow$ 2):] Assume $\{\mathcal C,\mathcal D\}$ is an ACP.  By Theorem~\ref{main}, we have
$
  f_1(x)f_2(x) \;=\; g_1(x) g_2(x) \;=\; x^n - 1.
$ Since $\gcd(f_1(x),f_2(x))=1$ (and respectively $\gcd(g_1(x),g_2(x))=1$), the cyclic codes
$
  \mathcal C_1=\langle f_1(\bar x)\rangle,
  $ and $\mathcal D_1=\langle f_2(\bar x)\rangle$
satisfy
\[
  \mathcal C_1\cap\mathcal D_1
    =\langle \operatorname{lcm}(f_1,f_2)\rangle
    = \{ 0\},
  \quad
  \mathcal C_1+\mathcal D_1
    =\langle \gcd(f_1,f_2)\rangle
    = R^n.
\]
Thus $\{\mathcal C_1,\mathcal D_1\}$ is an LCP.  Similarly $\{\mathcal C_2,\mathcal D_2\}$ is an LCP.
  \item[2) $\Rightarrow$ 3):] If $\{\mathcal C_i,\mathcal D_i\}$ is LCP, then $
  \mathcal C_i+\mathcal D_i=R^n,$ and $\mathcal C_i\cap\mathcal D_i=\{\textbf 0\},$
and for cyclic codes this is equivalent to
$f_i(x)\,g_i(x)=x^n-1.$ But by standard duality for cyclic codes, the Euclidean dual of $\langle f_i(\bar x)\rangle$ is
\[
  \langle f_i(\bar x)\rangle^\perp
    = \bigl\langle (x^n-1)/f_i^*(\bar x)\bigr\rangle,
\]
and coefficient-reversal via $\sigma(i)=n-1-i$ satisfies
$
  \langle f_i(\bar x)\rangle^\perp
    = \sigma\bigl(\langle g_i(\bar x)\rangle\bigr).
$
Hence $\mathcal C_i^\perp = \sigma(\mathcal D_i),$ for  $i=1,2.$
  \item[3) $\Rightarrow$ 4):] Assuming $\mathcal C_i^\perp=\sigma(\mathcal D_i)$ for $i=1,2$. Then  
\[
  \mathcal C^{\perp_{\mathrm{Tr}}}
    = \mathcal C_1^\perp \;\oplus\;\mu\,\mathcal C_2^\perp
    = \sigma(\mathcal D_1)\oplus\mu\,\sigma(\mathcal D_2)
    = \sigma(\mathcal D_1\oplus\mu\,\mathcal D_2)
    = \sigma(\mathcal D).
\]
  \item[4) $\Rightarrow$ 1):]  According to Corollary \ref{cor-4.5},  we have $$
\mathcal{C}^{^{\perp_{_\mathrm{Tr}}}} = \left\langle \left(\frac{x^n-1}{f_1(x)}\right)^*, \mu \left(\frac{x^n-1}{g_1(x)}\right)^* \right\rangle_{_{\mathcal{R}_n}}.
$$ On the other hand, $\sigma(\mathcal{D})=\left\langle f_2^*(x), \mu g_2^*(x) \right\rangle_{_{\mathcal{R}_n}}.$ Since $\mathcal{C}^{^{\perp_{_\mathrm{Tr}}}}=\sigma(\mathcal{D})$, by identification, it follows that $f_1(x)f_2(x)=g_1(x)g_2(x)=x^n-1$. Hence, by Theorem \ref{main}, the pair $\{\mathcal{C},\mathcal{D}\}$ is ACP. 
\end{description}

\end{proof}

Taking into account Collorary~\ref{cor:norem} and Corollary~\ref{cor:per} we have that the result of \cite{CG18} is also true for additive $S|R$ cyclic codes. 

\begin{thm} Let  the pair $\{\mathcal{C},\mathcal{D}\}$ be a ACP of $S|R$ cyclic codes of length $n$ and $\sigma$ be the permutation of $\{0,1,\cdots, n-1\}$ defined by $\sigma(i)=n-i-1$. Then $$\mathcal{C}^{^{\perp_{\mathrm{Tr}}}}=\sigma(\mathcal{D}).$$
\end{thm}





