\section{Preliminaries}\label{sec:preliminaries}
In this section, we list some basic terminology, definitions and notation that we use throughout.

\begin{definition}[Approximate Notation]
    Given real numbers $a,b>0$ and $0<\epsilon<1$, we say that $a\approx_{\epsilon} b$ if $(1-\epsilon)b \leq a \leq (1+\epsilon)b$.
\end{definition}
\begin{definition}[Coordinate Index Notation]
    For a point $a\in \R^d$, we use $a^{(i)}$ to represent the $i$-th coordinate of $a$. For a set or multiset $I = \{i_1, i_2, \dots, i_m\} \subseteq [d]$, we denote $a^{(I)}$ to be $\left(a^{(i_1)}, a^{(i_2)}, \dots, a^{(i_m)}\right) \in \R^m$.
\end{definition}

In this paper, we look into the approximate nearest neighbor problem, defined as follows.
\begin{definition}[$\alpha$-Approximate Nearest Neighbor Problem]
    Given a set $C=\{c_1, c_2, \dots, c_n\}$ of $n$ points in a metric space $(X, \dist)$, build a data structure that given any query point $q \in X$, returns index $i\in [n]$, such that $
    \dist(q, c_i) \leq \alpha \cdot \min_{j\in [n]}\dist(q, c_j). $
\end{definition}
When $C$ only has 2 points, we use the shorthand \emph{2-point comparator} to denote such an approximate nearest neighbor data structure. 
\begin{definition}[2-point Comparator]
    Given a set $C=\{c_1, c_2\}$ of $2$ points in a metric space $(X, \dist)$ and parameters $0\leq \epsilon, \delta < 1$, we call a data structure as a 2-point comparator, if for any query point $q \in X$, with probabilty $1-\delta$, it returns index $i\in \{1,2\}$, such that $
    \dist(q, c_i) \leq (1+\epsilon) \cdot \min_{j\in \{1,2\}}\dist(q, c_j). $
\end{definition}

We use the following Chernoff bounds in this paper.
\begin{theorem}[Chernoff Bound]
    Let $X_1, X_2, \dots, X_n$ be independent random variables, and $X_i \in [0, c]$. Define $X = \sum_{i=1}^n X_i$ and $\mu = \E[X]$. Then
    \begin{align*}
        &\prob{}{X \geq (1+\delta)\mu} \leq \exp(-\delta^2 \mu /(3c)), \text{ for } 0 < \delta \leq 1\\
        &\prob{}{X \geq (1+\delta)\mu} \leq \exp(-\delta \mu /(3c)), \text{ for } \delta \geq 1\\
        &\prob{}{X \leq (1-\delta)\mu} \leq \exp(-\delta^2 \mu /(2c)), \text{ for } \delta \geq 0.
    \end{align*}
\end{theorem}





\section{Near-linear Space Data Structures for \texorpdfstring{$\ell_1$}{l1} and \texorpdfstring{$\ell_2$}{l2} Metrics}
\label{sec:sample-reuse}
%In this section, we describe a data structure with better space complexity for approximate nearest neighbor under $\ell_1$ and $\ell_2$ metric.
%We prove the following theorem.
In this section, we design a data structure with near-linear space and query complexity for approximate nearest neighbor under $\ell_1$ and $\ell_2$ metrics. 
We prove the following theorem.


\begin{theorem}\label{theorem:sample-reuse-l1l2}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in \R^d$ equipped with $\ell_1$ or $\ell_2$ metric. Given $0 < \epsilon < 1/4$ and $0 < \delta < 1$, we can efficiently construct a randomized data structure such that for any query point $q\in \R^d$ the following conditions hold with probability $1-\delta$. (i) The data structure reads $O(n \log (n)/(\poly(\epsilon,\delta)))$ coordinates of $q$. (ii) It returns $i\in [n]$ where $c_i$ is a $(1+\epsilon)$-approximate nearest neighbor of $q$ in $C$. (iii) The data structure has a size of $O(n \log^2(n) \log(d)/(\poly(\epsilon,\delta)))$ words. 
\end{theorem}

The proof of \cref{theorem:sample-reuse-l1l2} for the case of $\ell_1$-metric is presented in \cref{sec:l1samplereuse} with missing proofs deferred to \cref{sec:appendixforlone}, where as the proof for the case of $\ell_2$-metric is in \cref{sec:linear-space-l2}.
Both proofs follow the same structure although they differ in details. 




\subsection{Data Structure for \texorpdfstring{$\ell_1$}{l1}-metric with Near-linear Space and Query Time}\label{sec:l1samplereuse}

The preprocessing and querying procedures of our data structure are described in \cref{alg:sample-reuse-l1}.
The algorithm receives a set $C$ of $n$ points and parameters $\epsilon, \delta \in (0,1)$ as inputs for its preprocessing phase. During preprocessing, it iteratively samples coordinates from $[d]$ to form a multiset $I$.\footnote{Multiple coordinates may be added to $I$ in the same iteration, and $I$ may contain repeated coordinates.} Let $R$ denote the set $C$ of $n$ points restricted to $I$. An $\ell_1$ dimension reduction is then applied to $R$ to further reduce the space. 
In the query phase, the algorithm receives a query $q \in \R^d$. It probes $q$ on all coordinates in $I$ and applies the same $\ell_1$ dimension reduction to the coordinate-selected query. The output, identifying which point in $C$ is the nearest neighbor of $q$, is determined by which point, after coordinate selection and dimension reduction, is closest to the query.



\begin{algorithm}[htp]\label{alg:sample-reuse-l1}
    \caption{An approximate nearest neighbor data structure for $n$ points in $\R^d$ for $\ell_1$ metric.}
