\subsubsection{Coordinate Selection Preserves Distance Ratio}
In this section, we show that, the following holds: 
for any query point $q\in \R^n$, whose nearest neighbor is $c_{i^*}$, with probability $1-2\delta'$, for all $c_i\in C$ such that $\frac{\|c_i-q\|_1}{\|c_{i^*}-q\|_1} \geq 1+\epsilon$,  the estimated ratio is significantly  larger than one, that is $\frac{\|r_i-u\|_1}{\|r_{i^*}-u\|_1} \geq 1+\epsilon\delta'/4$.
This statement is formalized in \Cref{lemma:robust-feature-selection-l1}.

To prove the statement, we first partition the coordinates in $[d]$ into good and bad regions for each pair of points. 
In the good region are the coordinates on which the query is not too far away from one of the points. 
The remaining coordinates are in the bad region.
The intuition is that, restricted to the coordinates in the good region, the distance between one of the points and the query  is bounded.
This implies that we can estimate these distances using a Chernoff bound.
For the bad coordinates the intuition is that the distances from the query to the 2 points are so large that the ratio between these distances is close to one. Additionally these distances are not overestimated because of the previous event in \cref{sec:first-section-l1}.

\begin{definition}[Good region and bad region]
    Consider two points $c_1, c_2\in \R^d$, and a query point $q\in\R^d$. We define the good region $\Good(c_1, c_2, q)$ w.r.t.\ $(c_1,c_2,q)$ as $$\{z\in [d] \mid\min\{c_1^{(z)}, c_2^{(z)}\} - \frac{8}{\epsilon \delta'} |c_1^{(z)} - c_2^{(z)}| \leq q^{(z)} \leq \max\{c_1^{(z)}, c_2^{(z)}\} + \frac{8}{\epsilon \delta'} |c_1^{(z)} - c_2^{(z)}|\}.$$ We define the bad region w.r.t.\ $(c_1,c_2,q)$ as $\Bad(c_1, c_2, q) = [d]\setminus \Good(c_1, c_2, q)$. When there is no ambiguity, we use $\Good$ for $\Good(c_1, c_2, q)$, and $\Bad$ for $\Bad(c_1, c_2, q)$. 
\end{definition}
Additionally, we define the distance between points restricted to subsets of coordinates.
\begin{definition}[Restricted distance]
    Given $x,y \in \R^d$, we define the distance between $x$ and $y$ restricted to region $J\subseteq [d]$ as 
    $\dist_J(x,y) = \sum_{z\in J} \left|x^{(z)} - y^{(z)}\right|$. 
    Furthermore, for $u,v \in \R^I$, where $I$ is a multiset, whose elements are from $[d]$, we define $\dist_J(u,v) = \sum_{z\in I} \mathbbm{1}_{z\in J}\cdot\left|x^{(z)} - y^{(z)}\right|$. 
\end{definition}
%\nithin{Is $J$ also a multiset above?}

%For bounding distance estimates on the good region, we can use Chernoff bound. For distance estimates on the bad region, we need Markov's inequality. 
%This motivates our name of the regions.

The following lemma shows that for two points, whose distances to the query differ significantly, then the majority of the distance between the two points is present in the good region. The intuition of the lemma is that if the bad region contributes a lot to the distance $\|b-a\|_1$, it implies that the bad region contributes much to $\|b-q\|_1$ and $\|a-q\|_1$, then the ratio between the two distances should be very close to 1. %The lemma is the contrapositive statement of the intuition.


\begin{lemma}\label{lemma:good-region-is-large-l1}
Consider three points \(a, b, q \in \mathbb{R}^d\). If \(\frac{\|b - q\|_1}{\|a - q\|_1} \geq 1 + \epsilon\), then \(\frac{\dist_{\Good(a, b, q)}(b, a)}{\|b - a\|_1} \geq \frac{13}{16}\).
\end{lemma}

