In the following lemma we state that our bounds on the distance estimates are good enough. Concretely, for a point that is not an approximate nearest neighbor, the estimated distance between this point and the query is significantly larger than the estimated distance between the nearest neighbor and the query.


\begin{lemma}\label{lemma:robust-feature-selection-l1}
    For any query point $q \in \R^d$, with probability $1-2\delta'$, it holds for all $i\in [n]$, if $\frac{\|c_i-q\|_1}{\|c_{i^*}-q\|_1} \geq 1+\epsilon$, then $\frac{\|r_i-u\|_1}{\|r_{i^*}-u\|_1} \geq 1+\epsilon\delta'/4$.
\end{lemma}




\subsubsection{\texorpdfstring{$\ell_1$}{l1} Dimension Reduction Preserves the Distance Ratio}
\begin{theorem}[Theorem 1 in \cite{indyk06:l1-dimension-reduction}]\label{thm:indyk06}
    Consider 2 points $a, b \in \R^d$ and parameters $0<\epsilon, \delta < 1$. We sample a random matrix $M\in \R^{m \times d}$, where $m = O(\log(1/\delta)/(\epsilon^2))$ and each entry of $M$ is sampled from Cauchy distribution, whose density function is $c(x) = \frac{1}{\pi(1+x^2)}$. Then with probability $1-\delta$, $F(Ma, Mb) \approx_\epsilon \|a-b\|_1$, where $F((x_1, \dots, x_m), (y_1, \dots, y_m)) \coloneq \mathsf{median}(|x_1-y_1|, \dots, |x_m- y_m|)$.
\end{theorem}
\begin{claim}
    Let $q\in \R^n$ be a query. Furthermore, let $i^*\in [n]$ be the index of its nearest neighbor. \Cref{alg:sample-reuse-l1} outputs an index $i$ such that
    \begin{align*}
        \frac{\|c_i - q\|_1}{\|c_{i^*} - q\|_1} \leq 1+\epsilon
    \end{align*}
    with probability $1-3\delta'$.
\end{claim}
\begin{proof}
Applying \cref{thm:indyk06} with $m = O(\log(n/\delta')/(\epsilon^2 \delta'^2))$, given any $v \in R$, it holds with probability $1-\delta'/(n+1)$, that $F(Mv, Mu) \in [1-\epsilon\delta'/100, 1+\epsilon\delta'/100] \|v- u\|_1$. By union bound, with probability $1-\delta'$, it holds for all $v\in R$.
By \Cref{lemma:robust-feature-selection-l1} it holds with probability $1-2\delta'$ that for all $i\in [n]$, if $\frac{\|c_i - q\|_1}{\|c_{i^*} - q\|_1} \geq 1+\epsilon$, then $\frac{\|r_i - u\|_1}{\|r_{i^*} - u\|_1} \geq 1+\epsilon\delta'/4$, thus $\frac{F(Mr_i, Mu)}{F(Mr_{i^*}, Mu)} > 1$ with probability $1-3\delta'$, i.e. the algorithm will not output $i$ as the index of the approximate nearest neighbor.
\end{proof}

\subsubsection{Space and Query Complexity}\label{sec:l1-space-query-analysis}
Next, we argue the space and query complexity.
The main result in this section is that for any set $C$ of centers the sum of probabilities $\sum_{b\in [d]} p^{(b)}$ is upper bounded by the number of centers.

\begin{lemma}\label{lemma:math-program}
    $1\leq \sum_{b\in [d]} p^{(b)} \leq n$.
\end{lemma}
\begin{proof}
The lower bound for $\sum_{b\in [d]} p^{(b)}$ can be seen as follows: Fix arbitrary $i_1, j_1 \in [n]$ s.t.\ $\|c_{i_1} - c_{j_1}\|_1 \neq 0$. We have, $\sum_{b\in [d]} p^{(b)} \geq \sum_{b\in [d]} \frac{\left|c_{i_1}^{(b)} - c_{j_1}^{(b)}\right|}{\|c_{i_1} - c_{j_1}\|_1} = 1$.

Next we prove the upper bound for $\sum_{b\in [d]} p^{(b)}$. We first introduce an operation that we call ``$\collapse$''.
%\begin{definition}{\bf (collapse)}
    For real numbers $\tau_1 \leq \tau_2$, 
    $$
    \collapse_{\tau_1, \tau_2}(x) \coloneq 
    \begin{cases}
        x, & x \leq \tau_1, \\
        \tau_1, & \tau_1 < x \leq \tau_2, \\
        x - (\tau_2 - \tau_1), & x > \tau_2.
    \end{cases}
    $$
    For $\tau_1 > \tau_2$, $\collapse_{\tau_1, \tau_2}(x) := \collapse_{\tau_2, \tau_1}(x)$. 

    We also slightly abuse the notation, and define for $a, b, c \in \R^d$, 
    $$\collapse_{a,b}(c) \triangleq (\collapse_{a_1, b_1}(c_1), \collapse_{a_2, b_2}(c_2), \dots, \collapse_{a_d, b_d}(c_d)) \in \R^d.$$
%\end{definition}

\begin{claim}\label{lemma:collapse-property}
Let $x,y,\tau_1,\tau_2 \in \R$, where $x \geq y$. We have 
    (i) $x - |\tau_1 -\tau_2| \leq \collapse_{\tau_1, \tau_2}(x) \leq x$ and (ii) $x-y - |\tau_1 -\tau_2| \leq\collapse_{\tau_1, \tau_2}(x) - \collapse_{\tau_1, \tau_2}(y) \leq x-y.$
\end{claim}
\begin{proof}
    Denote $x' = \collapse_{\tau_1, \tau_2}(x)$ and $y' = \collapse_{\tau_1, \tau_2}(y)$. Assume w.l.o.g.\ that $\tau_1 \leq \tau_2$, otherwise we switch them.

    For the first argument, $\forall x\in \R, x - |\tau_1 -\tau_2| \leq \collapse_{\tau_1, \tau_2}(x) \leq x$,  this is true because of the definition of collapse.

    For the second argument, $\forall x\geq y \in \R$, $x-y - |\tau_1 -\tau_2| \leq\collapse_{\tau_1, \tau_2}(x) - \collapse_{\tau_1, \tau_2}(y) \leq x-y,$ consider $$f(x) = x-\collapse_{\tau_1, \tau_2}(x) = \begin{cases}
        0, &x\leq \tau_1,\\
        x-\tau_1, &\tau_1 \leq x \leq \tau_2,\\
        \tau_2 - \tau_1, &x > \tau_2.
    \end{cases}$$
    Notice that $f(x)$ is a non-decreasing function, thus $f(x) \geq f(y)$, which proves $x-y \geq x'-y'$. Notice that $0\leq f(x) \leq \tau_2 - \tau_1$, thus $f(x) \leq f(y) + (\tau_2 -\tau_1)$, which proves $x'-y' \geq x-y-(\tau_2 - \tau_1)$.
\end{proof}

\begin{claim}\label{claim:collapse}
Let $c_{i_0}, c_{j_0}$ be the closest pair of 
points in a set $C = \{c_1, c_2, \dots, c_n\}$ of points, i.e., $(i_0, j_0) = \argmin_{(i,j)\colon i\neq j} \|c_i - c_j \|_1$.    
Define $P_n(C)$ to be $\sum_{b \in [d]} \max_{i\neq j}\frac{|c_i^{(b)} - c_j^{(b)}|}{\|c_i - c_j\|_1}$.
The set $C' = \{c_i' = \collapse_{c_{i_0}, c_{j_0}}(c_i) | i\in [n] \}$ is such that (i) it contains $n-1$ points and (ii) $P_n(C) \leq P_{n-1}(C') + 1.$  
\end{claim}

\begin{proof}
Note, by the definition of the collapse operation,
    that $c'_{i_0} = c'_{j_0}$. Hence, $C'$ has at most $n-1$ points, proving part (i) of the claim.

    To prove (ii),
  define $p_b = \max_{c_i, c_j \in C, i\neq j}\frac{|c_i^{(b)} - c_j^{(b)}|}{\|c_i - c_j\|_1}$ and $p_b' = \max_{c'_i, c'_j \in C', i\neq j}\frac{|{c'_i}^{(b)} - {c'_j}^{(b)}|}{\|c'_i - c'_j\|_1}$. 
    We prove that $p_b - p_b' \leq \frac{| c_{i_0}^b - c_{j_0}^b |}{\|c_{i_0} - c_{j_0}\|_1}, \forall b \in [d]$. The claim follows, since $P_k(C) - P_{k-1}(C') = \sum_b (p_b - p_b') \leq \sum_b \frac{| c_{i_0}^{(b)} - c_{j_0}^{(b)} |}{\|c_{i_0} - c_{j_0}\|_1} = 1$.

    Fix some $b$, choose $(u,v) = \argmax_{(i,j)\colon c_i^{(b)} \neq c_j^{(b)}} \frac{| c_i^{(b)} - c_j^{(b)} |}{\|c_i - c_j\|_1}$, i.e. $p_b = \frac{| c_u^{(b)} - c_v^{(b)} |}{\|c_u - c_v\|_1}$.

    If ${c'_u}^{(b)} \neq {c'_v}^{(b)}$, ${p_b}' \geq \frac{| {c'_u}^{(b)} - {c'_v}^{(b)} |}{\|c'_u - c'_v\|_1} \geq \frac{| {c_u^{(b)}} - {c_v^{(b)}} | - |{c_{i_0}^{(b)}} - {c_{j_0}^{(b)}}|}{\|c_u - c_v\|_1}.$ The second inequality follows from \Cref{lemma:collapse-property}. Thus 
    $
    p_b - p_b' \leq \frac{|{c_{i_0}^{(b)}} - {c_{j_0}^{(b)}}|}{\|c_u - c_v\|_1} \leq \frac{|{c_{i_0}^{(b)}} - {c_{j_0}^{(b)}}|}{\|c_{i_0} - c_{j_0}\|_1}.
    $
    If ${c'_u}^{(b)} = {c'_v}^{(b)}$, it means $|{c_u^{(b)}} - {c_v^{(b)}}| \leq |{c_{i_0}^{(b)}} - {c_{j_0}^{(b)}}|$, thus 
    $
    p_b - p_b' \leq p_b = \frac{| c_u^{(b)} - c_v^{(b)} |}{\|c_u - c_v\|_1} \leq \frac{|{c_{i_0}^{(b)}} - {c_{j_0}^{(b)}}|}{\|c_{i_0} - c_{j_0}\|_1}.%\qedhere
    $
\end{proof}
Solving the recurrence given by \cref{claim:collapse} with the boundary condition that for a set $C''$ of two points, $P_2(C'') = 1$, we get that $P_n(C) \leq n$.
Since $P_n(C)$, for the set of $n$ points, is by definition, equal to $\sum_{b \in [d]} p^{(b)}$, the statement of the lemma follows. 
\end{proof}

\begin{claim}\label{clm:I-size-upperbound-l1}
    With probability $1-\delta'$, we have $|I| \leq 2Tn$.    
\end{claim}
\begin{proof}
   We define $X_{t,z}$ for $t \in [T], z \in [d]$ to be the indicator random variable for the event that we add $z$ to $I$ at iteration $t$. Note that $\Pr[X_{t,z} = 1] = p^{(z)}$.
   % we define the following random variables $\forall t\in [T], z\in [d]$,
    %\begin{equation*}
     %   X_{t, z} =  \begin{cases} 
     % 1, & w.p.\; p^{(z)},\quad\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
     % 0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we don't add $z$ to $I$ at iteration $t$.}
      %\end{cases}
    %\end{equation*}
    We can see that $|I| = \sum_{t\in[T], z\in[d]} X_{t,z}$.
    Hence, $\E[|I|] = \sum_{t\in[T], z\in[d]} p^{(z)} \leq T\cdot \sum_{b \in [d]} p^{(b)} \leq T\cdot n$, where the last inequality follows from \cref{lemma:math-program}. Similarly, we can see that 
    $\E[|I|] \geq T$.
    Using Chernoff bound, we have 
      $\Pr\left[|I| - \E\left[|I|\right] \geq \E\left[|I|\right]\right] \leq \exp (-\E[|I|]/3) \leq \exp(-T/3) \leq \delta/4.$
    Thus, with probability $1-\delta/4$, we have $|I| \leq 2 E[|I|] \leq 2Tn$.
\end{proof}

% The expected query complexity bound follows from the above claim. Now let us analyze the space complexity. $M(R)$ is of wordsize $O(n\log(n/\delta)/\epsilon^2)$, $M$ is of wordsize $O(|I|\log(n/\delta)/\epsilon^2)$, $I$ and $\{p^{(b)}| b\in I\}$ are of wordsize $n$ in expectation, $F$ is of constant size. Using Chernoff bound to upper-bound the size of $|I|$ finishes the proof.

\begin{lemma}
    With prob. $1-\delta'$, the space complexity of \cref{alg:sample-reuse-l1} is $O(\frac{n\log^2(n/\delta)\log(d)}{\epsilon^5 \delta^4})$ wordsize, and the number of coordinates that we query is $O(\frac{n\log(n/\delta)}{\epsilon^3 \delta^2})$. 
\end{lemma}
\begin{proof}
    By \cref{clm:I-size-upperbound-l1}, we have that the number of coordinates of $q$ that we query is $|I| = O(Tn) = O(\frac{n\log(n/\delta)}{\epsilon^3 \delta^2})$. Next we analyze the space complexity of the data structure. Matrix $M$ is of wordsize $O(m|I|)$, $M(R)$ is of wordsize $O(mn)$, $I$ is of wordsize $O(|I| \log(d))$. Thus the space complexity of the our data strcuture is $O(m|I| + mn +|I|\log(d)) = O(\frac{n\log^2(n/\delta)\log(d)}{\epsilon^5 \delta^4})$ wordsize.
\end{proof}

 Using union bound, the success probability of the data structure is at least $1-4\delta' = 1-\delta$.





