\section{Warm-Up: Data Structure for \texorpdfstring{$\ell_1$}{l1} Metric with \texorpdfstring{$\tilde{O}(n^2)$}{near-quadratic} Space and \texorpdfstring{$\tilde{O}(n)$}{near-linear} Query Complexity}\label{sec:warm-up}

As a warm-up, we describe in this section our data structure with $O(n^2 \log(n/\delta) \log(d)/\epsilon^2)$ space and $O(n \log (n/\delta)/\epsilon^2)$ query complexity for approximate nearest neighbor problem under the $\ell_1$ metric. For simplicity, we make the assumption that the query is in the scaled bounding box of each pair of points defined as follows.

\begin{definition}[Scaled Bounding Box]
    For any two points $a,b\in \R^d$, the scaled bounding box $B_{a,b}$ specified by $(a,b)$ is $$\begin{aligned}
    \left\{x\in \R^d \mid \forall z\in [d], \min\{a^{(z)}, b^{(z)}\} - 100 \cdot |a^{(z)} - b^{(z)}| \leq x^{(z)} \right.\\
    \left.\leq \max\{a^{(z)}, b^{(z)}\} + 100 \cdot |a^{(z)} - b^{(z)}|\right\}.
    \end{aligned}$$
\end{definition}

We show the following.



\begin{theorem}\label{thm:warm-up-l1}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in \mathbb{R}^d$ equipped with $\ell_1$ metric. Given parameters $0 < \epsilon, \delta < 1$, we can construct a randomized data structure such that for any query point $q\in R^d$, which lies in the bounding box of each pair of points, i.e.\ $\forall i,j\in [n], q \in B_{c_i, c_j}$, the following conditions hold with probability $1 - \delta$. (i) The data structure reads $O(n \log (n/\delta)/\epsilon^2)$ coordinates of $q$. (ii) It returns $i \in [n]$ where $c_i$ is a $(1+\epsilon)$-approximate nearest neighbor of $q$ in $C$. (iii) The data structure has a size of $O(n^2 \log(n/\delta) \log(d)/\epsilon^2)$ words.
\end{theorem}

\cref{thm:warm-up-l1} is a special case of \cref{theorem:Lp-NN}, where a rigorous proof is provided. In this section, we present a more concise proof to provide intuition. Our approach is the following. We first describe a data structure for the approximate nearest neighbor problem for two points (i.e. a 2-point comparator), and then employ a naive min-finding procedure with oracle access to the 2-point comparator, to extend to the approximate nearest neighbor with $n$ points.

\subsection{A Strong Comparator for Two Points}


In this section we describe our approximate nearest neighbor data strucutre for 2 points, which we refer to as 2-point comparator (see \cref{alg:strong-2points}). It gets two points $a, b \in \R^d$ and parameters $\epsilon, \delta \in (0,1)$ as inputs to its preprocessing phase. In the preprocessing phase, it iteratively samples coordinates from $[d]$ to form a multiset $I$. Specifically, in a single iteration, it samples each coordinate with probability proportional to the distance between $a$ and $b$ on that coordinate. The data structure stores $I$ as well as the coordinates of $a$ and $b$ in $I$. In the query phase, it receives a query $q \in B_{a,b}$ upon which it probes $q$ on all coordinates in $I$ to compute estimates $x$ and $y$ of the distances of $q$ to $a$ and $b$, respectively. Its final answer, as to which among $a$ or $b$ is the nearer neighbor of $q$, depends on the ratio $x/y$.


We analyze the correctness of \cref{alg:strong-2points} in \cref{lem:strong-comparator-l1}. In particular, we show the following strong guarantees: (i) if one point is significantly closer to the query than the other point, the comparator outputs the correct point with probability $1- \delta$, (ii) otherwise, the comparator may output a special symbol $\perp$, but never outputs a wrong point as the nearest neighbor. %The space and query complexity of our $2$-point comparator are, with probability $1-\delta$, $$

\begin{algorithm}[htbp]\label{alg:strong-2points}
    \caption{An approximate nearest neighbor data structure $A_{(a,b)}$ for two points $a,b\in \R^d$.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKw{store}{store}
    \preprocessing{$(a,b, \epsilon, \delta)$\tcp*[f]{Inputs: $a,b\in \R^d, \epsilon, \delta\in (0,1)$}}{

        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (1/\delta)/\epsilon^2)$\;
        \For{$t\in [T]$}{
            Sample $i_t\in [d]$, where $\forall z\in [d], \Pr[i_t = z] = p^{(z)} = \frac{\left|b^{(z)} - a^{(z)}\right|}{\|b-a\|_1}$\;
            Add $i_t$ to $I$\;
        }
        \store{$I, a^{(I)}, b^{(I)}$, where $a^{(I)} = \{a^{(i)} | i\in I\}$}.
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in B_{a,b} \subseteq \R^d$}}{
        Let $x,y \leftarrow 0$\;
        \For{$i\in I$}{
            Query $q$ on coordinate ${i}$, i.e. $q^{(i)}$\; 

            Let $x \leftarrow x+\frac{\left|q^{(i)} - a^{(i)}\right|}{p^{(i)}}, y \leftarrow y+\frac{\left|q^{(i)} - b^{(i)}\right|}{p^{(i)}}$\;
        }
        \uIf{$\frac{y}{x} \geq 1+\frac{\epsilon}{2}$}{
        \Return{$a$ as nearest neighbor}
        }
        \uElseIf{$\frac{x}{y} \geq 1+\frac{\epsilon}{2}$}{
            \Return{$b$ as nearest neighbor}
        }
        \Else{
            \Return{$\bot$}
        }
    }
\end{algorithm}

\begin{lemma}[Strong Comparator Correctness]\label{lem:strong-comparator-l1}
   \cref{alg:strong-2points}, given inputs $a,b \in \mathbb{R}^d, \epsilon,\delta \in (0,1)$, satisfies the following conditions with probability $1-\delta$:
    \begin{enumerate}
        \item if $\frac{\|b-q\|_1}{\|a-q\|_1} \geq 1+\epsilon$, it outputs $a$; if $\frac{\|a-q\|_1}{\|b-q\|_1} \geq 1+\epsilon$, it outputs $b$,
        \item if $\frac{\|b-q\|_1}{\|a-q\|_1} \geq 1$, it outputs $a$ or $\bot$; if $\frac{\|a-q\|_1}{\|b-q\|_1} \geq 1$, it outputs $b$ or $\bot$.
    \end{enumerate}
\end{lemma}
\begin{proof}[Proof Sketch]
    In this proof, we assume that $\|b-q\|_1 \geq \|a-q\|_1$, since the other case is symmetric. Together with the fact $\|b-q\|_1 + \|a-q\|_1 \geq \|b-a\|_1$, we get $\|b-q\|_1 \geq \frac12 \|b-a\|_1$.

The algorithm makes its decision based on the relative values of $x$ and $y$, which are estimates for the distances from $q$ to $a$ and from $q$ to $b$, respectively.
    To analyze the ratio $y/x$, we need to define some random variables to analyze how we sample $I$ in the preprocessing. 
    Let $X_t = \frac{\left|q^{(i_t)} - a^{(i_t)}\right|}{p^{(i_t)}}, Y_t = \frac{\left|q^{(i_t)} - b^{(i_t)}\right|}{p^{(i_t)}}, \forall t\in [T]$. We know that $x = \sum_{t\in [T]} X_t$ and $y = \sum_{t\in [T]} Y_t$. These nonnegative random variables are bounded: $X_t = \frac{\left|q^{(i_t)} - a^{(i_t)}\right|}{\left|b^{(i_t)} - a^{(i_t)}\right|}\cdot \|b-a\|_1 \leq 101\cdot\|b-a\|_1$, because $q$ lies in the bounding box specified by $a,b$. Similarly we have $Y_t \leq 101\cdot\|b-a\|_1, \forall t\in [T]$. 
    The expectation of $X_t$ is $\E[X_t] = \sum_{z\in [d]} p^{(z)} \cdot \frac{\left|q^{(z)} - a^{(z)}\right|}{p^{(z)}} = \|a-q\|_1$.
    Similarly $\E[Y_t] = \|b-q\|_1$. 

    Since $\E[Y_t] = \|b-q\|_1 \geq \frac12 \|b-a\|_1$, using Chernoff bound, we have $\Pr\left[|y - \E[y]| > \frac{\epsilon}{8} \E[y]\right] \allowbreak\leq \frac{\delta}{2}$ by choosing $T = \Theta(\log(1/\delta)/\epsilon^2)$.
    To analyze $x$, we consider the following two cases:

    \noindent \underline{Case 1.} If $\E[X_t] = \|a-q\|_1 \geq \frac18 \|b-a\|_1$, then using Chernoff bound, we have \\$\Pr\left[|x - \E[x]| > \frac{\epsilon}{8} \E[x]\right] \leq \frac{\delta}{2}$ by choosing $T = \Theta(\log(1/\delta)/\epsilon^2)$.

    \noindent \underline{Case 2.} If $\E[X_t] = \|a-q\|_1 < \frac18 \|b-a\|_1$, then using Chernoff bound, we have \\$\Pr\left[|x - \E[x]| > \frac{T}8 \|b-a\|_1\right] \leq \frac{\delta}{2}$ by choosing $T = \Omega(\log(1/\delta))$. 

To prove item 1 of~\cref{lem:strong-comparator-l1}, suppose that $\frac{\|b-q\|_1}{\|a-q\|_1} \geq 1+\epsilon$. If we are in Case 1, with probability $1-\delta$ we have $x \approx_{\frac{\epsilon}{8}} T\|a-q\|_1$ and $y \approx_{\frac{\epsilon}{8}} T\|b-q\|_1$. This implies that, with probability $1-\delta$ we get $\frac{y}{x} \geq \frac{1-\frac{\epsilon}{8}}{1+\frac{\epsilon}{8}} \cdot (1+\epsilon) \geq 1+\frac{\epsilon}{2}$. Thus the querying phase correctly outputs $a$ as the nearest neighbor. If we are in Case 2, with probability $1-\delta$ we have $x \leq \frac{1}{4} T\|b-a\|_1$, and $y \approx_{\frac{\epsilon}{8}} T\|b-q\|_1$, which implies that $\frac{y}{x} \geq \frac{(1-\frac{\epsilon}{8})(1-\frac18)}{\frac{1}{4} } \geq 3$. Thus the querying phase correctly outputs $a$.  



    The second item of~\cref{lem:strong-comparator-l1} can be proved similarly.
\end{proof}


\subsection{Data Structure for \texorpdfstring{$\ell_1$}{l1} Metric with \texorpdfstring{$\tilde{O}(n^2)$}{near-quadratic} Space}
In this section, we show that combining \cref{alg:strong-2points} with a naive minimum-finding approach using an imprecise comparison oracle gives a data structure for $n$ points under $\ell_1$ metric (see \cref{alg:naive-min-finding}) that uses  $\tilde{O}(n^2)$ space. \cref{alg:naive-min-finding} maintains a candidate for the nearest neighbor and evaluates each point against this candidate using the two-point comparator. If a point is found to be significantly closer to the query than the current candidate, the candidate is updated accordingly.

\begin{algorithm}[htp]\label{alg:naive-min-finding}
    \caption{An approximate nearest neighbor data structure for $n$ points in $\R^d$ for $\ell_1$ metric.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKwProg{comparator}{$E$}{}{}
    \SetKw{store}{store}
    \preprocessing{$(C, \epsilon, \delta)$\tcp*[f]{Inputs: $C=\{c_1, \dots, c_n\}\subseteq \R^d, \epsilon \in (0, \frac{1}{4}), \delta\in (0,1)$}}{
        \For{$1\leq i < j \leq n$}{
            $Preprocessing(c_i, c_j, \epsilon, \delta/n^2)$ \tcp*{Construct $A_{(c_i, c_j)}$ from \cref{alg:strong-2points}}
        }
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in \R^d, \forall i,j\in [n], q\in B_{c_i, c_j}$}}{
        Let $j = 1$\;
        \For{$2\leq i \leq n$}{
            In $A_{(c_j, c_i)}$, run $Query(q)$\;
            \If{the query outputs $c_i$}{
            Let $j \leftarrow i$\;
            }      
        }
        \Return{$j$}
    }
\end{algorithm}

\begin{proof}(for \cref{thm:warm-up-l1})
    By a union bound, we get that with probability $1 - \delta$, for all $1 \leq i < j \leq n$, the data structure $A_{(c_i,c_j)}$ does not fail. We condition on this event in the rest of the proof. Notice that $j$ is a variable under updating.  

    \cref{alg:naive-min-finding} maintains an index $j \in [n]$ throughout its execution such that $c_j$ is a candidate $(1+\epsilon)$-approximate nearest neighbor of $q$. Initially, $j$ is set to $1$. The algorithm runs the 2-point comparator $n-1$ times, where in the $i$-th iteration, a comparison is made between $c_i$ and the current nearest neighbor candidate $c_j$. If $A_{c_i, c_j}$ outputs $c_i$, then we know, by \cref{lem:strong-comparator-l1}, that $c_i$ is strictly closer to $q$ than $c_j$. Additionally, if $c_i$ were closer to $q$ by a factor of $1 + \epsilon$ or more, then we are guaranteed that $c_i$ is output by $A_{c_i, c_j}$.

    Let $i^*$ be such that $c_{i^*}$ is the true nearest neighbor of $q$. If the value of $j$ is updated in iteration $i^*$, then \cref{alg:naive-min-finding} will not update it in any further iteration and we output the true nearest neighbor. If the value of $j$ is not updated in iteration $i^*$, then it must be the case that $||q - c_j||_1 \leq (1+\epsilon)\cdot ||q - c_{i^*}||_1$ and the final output is also a $1+\epsilon$ approximate nearest neighbor of $q$. 



