\begin{proof}[Proof of \cref{claim:Markovlone}]
    For any $i\in [n]$, we have $\E[\|r_i - u\|_1] = T \|c_i - q\|_1$, because 
    \begin{align*}
        \E[\|r_i - u\|_1] &= \E\left[\sum_{b\in I} \left|r_i^{(b)} - u^{(b)}\right|\right] \\ &= \E\left[\sum_{t\in [T], b\in [d]} \mathbbm{1}_{\{\text{in iteration $t$, we add $b$ to $I$\}}}\left|r_i^{(b)} - u^{(b)}\right|\right] \\
        &= \sum_{t\in [T], b\in [d]} p^{(b)}\left|r_i^{(b)} - u^{(b)}\right| = \sum_{t\in [T], b\in [d]} p^{(b)}\left|\frac{c_i^{(b)}}{p^{(b)}} - \frac{q^{(b)}}{p^{(b)}}\right| \\
        &= \sum_{t\in [T], b\in [d]} \left|c_i^{(b)} - q^{(b)}\right| = T \|c_i - q\|_1.
    \end{align*}
    Using Markov's inequality, we have with probability $1-\delta'$,
\begin{equation*}
    \|r_{i^*} - u\|_1 \leq \frac{1}{\delta'}\E[\|r_i - u\|_1]  \leq \frac{T}{\delta'} \|c_{i^*} - q\|_1. \qedhere 
\end{equation*}
\end{proof}

\begin{proof}[Proof of \cref{lemma:good-region-is-large-l1}]
By scaling the inequality $(1 + \epsilon) \|a - q\|_1 \leq \|b - q\|_1$, we get that
\[
\left(2 + \frac{2}{\epsilon}\right) \|a - q\|_1 \leq \frac{2}{\epsilon} \|b - q\|_1.
\]
Next, by rearranging and using the triangle inequality, we have:
\[
\|b - q\|_1 + \|a - q\|_1 \leq \left(1 + \frac{2}{\epsilon}\right) (\|b-q\|_1 - \|a-q\|_1) \leq \left(1 + \frac{2}{\epsilon}\right) \|b - a\|_1.
\]
Since \(\Bad(a, b, q) \subseteq [d]\), we have:
\begin{equation*}
    \begin{aligned}
        \|b - q\|_1 + \|a - q\|_1 \geq \dist_{\Bad(a, b, q)}(b, q) + \dist_{\Bad(a, b, q)}(a, q) \\
        \geq \sum_{z \in \Bad(a, b, q)} \left(\frac{8}{\epsilon \delta'} + \frac{8}{\epsilon \delta'}\right)|b^{(z)} - a^{(z)}|.
    \end{aligned}
\end{equation*}


This implies that: 
\[ 
\frac{16}{\epsilon \delta'} (\|b - a\|_1 - \dist_{\Good(a, b, q)}(b, a)) \leq \left(1 + \frac{2}{\epsilon}\right) \|b - a\|_1.
\]
Rearranging the terms, we finally get:
\[
\frac{\dist_{\Good(a, b, q)}(b, a)}{\|b - a\|_1} \geq \frac{14 - \epsilon \delta'}{16} \geq \frac{13}{16}. \qedhere
\]
