\begin{proof}[Proof of \cref{lemma:chernoff_for_good_l1}]
    Combining the following two properties,
    \begin{align*}
         \frac{\dist_{\Good} (c_i, q) + \dist_{\Bad} (c_i, q)}{\dist_{\Good} (c_j, q)+\dist_{\Bad} (c_j, q)} = \frac{\|c_i - q\|_1}{\|c_j - q\|_1} \geq 1+\epsilon, \tag{assumption}\\
         \frac{\dist_{\Bad} (c_i, q)}{\dist_{\Bad} (c_j, q)} \leq 1+\frac{\epsilon\delta'}{8} < 1+\epsilon. \tag{definition of bad region}         
    \end{align*}
    implies
    \begin{equation*}
        \frac{\dist_{\Good} (c_i, q)}{\dist_{\Good} (c_j, q)} \geq 1+\epsilon.
    \end{equation*}
    Therefore the first item of the lemma is proved.

    In the algorithm, we construct $\{r_i\mid i\in [n]\}$ and $u$ through sampling a multiset $I$. To analyze how the data structure samples $I$ in the preprocessing, we define the following random variables $\forall t\in [T], z\in \Good$
    \[P_{t, z} =  \begin{cases} 
      \frac{|q^{(z)} - c_i^{(z)}|}{p^{(z)} }, & w.p.\; p^{(z)},\hspace{0.95cm}\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we do not add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   \[Q_{t, z} =  \begin{cases} 
      \frac{|q^{(z)} - c_j^{(z)}|}{p^{(z)} } , & w.p.\; p^{(z)},\hspace{0.95cm}\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we do not add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   Notice that $\sum_{t\in [T],z\in \Good} P_{t,z} = \dist_\Good(r_i, u)$ and $\sum_{t\in [T],z\in \Good} Q_{t,z} = \dist_\Good(r_j, u)$.  

    Observe that $\forall t\in [T], z\in \Good$, $0 \leq P_{t,z} \leq \left(1+\frac{8}{\epsilon\delta'}\right) \|c_i - c_j\|_1$. This is because, if $c_i^{(z)} = c_j^{(z)}$, from the definition of good region we have $q^{(z)} = c_i^{(z)}$, thus $P_{t,z} = 0$; otherwise $c_i^{(z)} \neq c_j^{(z)}$, 
    \begin{align*}
        0 \leq P_{t,z} \leq \frac{|q^{(z)} - c_i^{(z)}|}{|c_i^{(z)} - c_j^{(z)}| } \cdot \|c_i - c_j\|_1 \leq \left(1+\frac{8}{\epsilon\delta'}\right) \|c_i - c_j\|_1,
    \end{align*}
    where the second inequality comes from ``oversampling'': $p^{(z)} \geq \frac{|c_i^{(z)} - c_j^{(z)}|}{\|c_i - c_j\|_1}$, and the third inequality comes from the definition of good region.
    By a similar argument, we have $0 \leq Q_{t,z}\leq \left(1+\frac{8}{\epsilon\delta'}\right) \|c_i - c_j\|_1$. 

    Notice $\forall t\in [T], \E[\sum_{z\in \Good} P_{t,z}] = \dist_{\Good}(c_i, q)$ and  $\E[\sum_{z\in \Good} Q_{t,z}] = \dist_{\Good}(c_j, q)$. Because 
    \begin{equation*}
    \begin{aligned}
        \E[\sum_{z\in \Good} P_{t,z}] &= \sum_{z\in \Good} \E[P_{t,z}] = \sum_{z\in \Good} p^{(z)} \cdot \frac{|q^{(z)} - c_i^{(z)}|}{p^{(z)}} = \sum_{z\in \Good} |q^{(z)} - c_i^{(z)}| \\
        &= \dist_{\Good}(c_i, q).
    \end{aligned}
    \end{equation*}
    Since $\forall t\in [T], \E[\sum_{z\in \Good} (P_{t,z} + Q_{t,z})] = \dist_{\Good}(c_i, q) + \dist_{\Good}(c_j, q)\geq  \dist_{\Good}(c_i, c_j)$, we have $\E[\sum_{z\in \Good}P_{t,z}] \geq \frac{1}{2} \dist_{\Good}(c_i, c_j)$. In the rest of the proof, we use $\E[\sum_{z\in \Good} P_{t,z}]$ without specifying $t\in [T]$, because they have the same value for all $t\in [T]$. Let $0<\epsilon_2 = \epsilon/16 < 1$, using Chernoff bound and \cref{lemma:chernoff_for_good_l1}, \begin{align*}
    &\Pr\left[\left|\sum_{t\in [T], z\in \Good} P_{t,z} - \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right] \\
    \leq &2\exp\left(-\frac{\epsilon_2^2 T \E[\sum_{z\in [d]} P_{t,z}]}{3(1+\frac{8}{\epsilon\delta'}) \|c_i - c_j\|_1}\right) \\
    = & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{8}{\epsilon\delta'})} \frac{\dist_{\Good}(c_i, q)}{\dist_{\Good}(c_i, c_j)} \frac{\dist_{\Good}(c_i, c_j)}{\|c_i - c_j\|_1}\right) \\ 
    \leq & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{8}{\epsilon\delta'})} \cdot \frac12 \cdot \frac{13}{16}\right) \leq \frac{\delta'}{2n},
    \end{align*}
    by choosing 
    $T = \Theta(\frac{\log(n/\delta)}{\epsilon^3 \delta^2} )$. 

    %This proves claim 2 of the lemma.
   % \nithin{The above sentence looks strange.}

    \smallskip 

    \noindent \underline{Case 1.} If $\E[\sum_{z\in \Good} Q_{t,z}] \geq \frac18 \cdot \dist_{\Good}(c_i, c_j)$, using Chernoff bound and \cref{lemma:chernoff_for_good_l1}, we have 

    $$\Pr\left[\left|\sum_{t\in [T], z\in \Good} Q_{t,z} - \E\left[\sum_{t\in [T], z\in \Good} Q_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in \Good} Q_{t,z}\right]\right] \leq \frac{\delta'}{2n},$$
    by choosing 
    $T = \Theta(\frac{\log(n/\delta)}{\epsilon^3 \delta^2} ) $. By union bound, with probability $1-\delta'/n$, we have 
    \begin{equation*}
        \sum_{t\in [T],z\in \Good} P_{t,z}  \approx_{\frac{\epsilon}{16}} \E\left[\sum_{t\in [T],z\in \Good} P_{t,z}\right], \text{ and } \sum_{t\in [T],z\in \Good} Q_{t,z} \approx_{\frac{\epsilon}{16}} \E\left[\sum_{t\in [T],z\in \Good} Q_{t,z}\right].
    \end{equation*}
    Therefore the second item of the lemma is proved.
\smallskip

    \noindent \underline{Case 2.} If $\E[\sum_{z\in \Good} Q_{t,z}] < \frac18 \dist_{\Good}(c_i, c_j)$. Then we have $\E[\sum_{z\in \Good} P_{t,z}] > (1-\frac18) \dist_{\Good}(c_i, c_j)$, which gives that $\frac{\dist_{\Good} (c_i, q)}{\dist_{\Good} (c_j, q)} > 7$.

    % by choosing $T = \Theta( \frac{2^p}{p^2\epsilon^{p+2}}\log(1/\delta)) \geq \Theta(\frac{1}{s}(1+\epsilon)^p \log(1/\delta))$.

    Using Chernoff bound and \cref{lemma:chernoff_for_good_l1}, we get
    \begin{align*}
    & \Pr\left[\left|\sum_{t\in [T],z\in \Good} Q_{t,z} - \E[\sum_{t\in [T], z\in \Good} Q_{t,z}]\right| > \frac{T}8 \cdot \dist_{\Good}(c_i, c_j) \right] \\
    \leq & 2\exp\left( -\frac{T \cdot \frac18\dist_{\Good}(c_i, c_j)}{3(1+\frac{8}{\epsilon\delta'}) \|c_i - c_j\|_1}\right) \\
    \leq & 2\exp\left( -\frac{T  }{24(1+\frac{8}{\epsilon\delta'})} \frac{\dist_{\Good}(c_i, c_j)}{\|c_i - c_j\|_1} \right)\leq \frac{\delta'}{2n}. 
    \end{align*}
    by choosing $T = \Omega(\frac{\log(n/\delta)}{\epsilon \delta} ) $.

    By union bound, with probability $1-\delta'/n$, we have 
    \begin{equation*}
        \sum_{t\in [T],z\in \Good} P_{t,z} \approx_{\frac{\epsilon}{16}} \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right], \text{ and } \sum_{t\in [T],z\in \Good} Q_{t,z} \leq \frac{T}{4} \dist_{\Good}(c_i, c_j).
    \end{equation*}
    Thus 
    \begin{equation*}
        \frac{\sum_{t\in [T],z\in \Good} P_{t,z}}{\sum_{t\in [T],z\in \Good} Q_{t,z}} \geq \frac{(1-\frac{\epsilon}{16})(1-\frac18)\dist_{\Good}(c_i, c_j)}{\frac14 \dist_{\Good}(c_i, c_j)} \geq 3.
    \end{equation*}
    The third item of the lemma is proved.
\end{proof}

\begin{proof}[Proof of \cref{lemma:robust-feature-selection-l1}]
    We know that $\|r_{i^*} - u\|_1 \leq \frac{T}{\delta'} \|c_{i^*} - q\|_1$ holds with probability $1-\delta'$ by \Cref{claim:Markovlone}.
    Thus, it is sufficient to show the statement of the lemma holds under this assumption with probability $1-\delta'$.

    Fix $i\in [n]$. Since we only have 2 points from $C$ that are $c_i$ and $c_{i^*}$, we use $\Good$ for $\Good(c_i, c_{i^*}, q)$.

    Denote $b_1 = \dist_\Bad(c_i, q)$, $b_2 = \dist_\Bad(c_{i^*}, q)$, $g_1 = \dist_\Good(c_i, q)$, $g_2 = \dist_\Good(c_{i^*}, q)$. Also denote $b_1' = \dist_\Bad(r_i, u)/T$, $b_2' = \dist_\Bad(r_{i^*}, u)/T$, $g_1' = \dist_\Good(r_i, u)/T$, $g_2' = \dist_\Good(r_{i^*}, u)/T$.

    For a fixed $i \in [n]$, we have $\frac{\|c_i - q\|_1}{\|c_{i^*} - q\|_1} \geq 1+\epsilon$, which is $\frac{g_1 + b_1}{g_2 + b_2} \geq 1+\epsilon$. We are given that $\|r_{i^*} - u\|_1 \leq T/\delta' \|c_{i^*} - q\|_1$, which is $g_2' + b_2' \leq \frac{1}{\delta'}(g_2 + b_2)$. From the definition of bad region, we know that $1 - \frac{\epsilon\delta'}{8} \leq \frac{b_1}{b_2} \leq 1 + \frac{\epsilon\delta'}{8}$. Also $1 - \frac{\epsilon\delta'}{8} \leq \frac{b_1'}{b_2'} \leq 1 + \frac{\epsilon\delta'}{8}$, because we select and rescale coordinates, which does not affect the ratio.

    Applying \cref{lemma:chernoff_for_good_l1} on $c_i$ and $c_{i^*}$ gives that with probability $1-\delta'/n$,
    \begin{itemize}
        \item either $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $g_2' \approx_{\frac{\epsilon}{16}} g_2$,
        \item or $\frac{g_1}{g_2} > 7$, $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $\frac{g_1'}{g_2'} \geq 3$.
    \end{itemize}
Given these conditions, the following \cref{claim:robust-estimate} gives a lower bound on the ratio $\frac{g_1' + b_1'}{g_2' + b_2'}$. We defer the proof of the claim to the appendix.



    \begin{claim}\label{claim:robust-estimate}
    Suppose $b_1, b_2, g_1, g_2, b_1', b_2', g_1', g_2' \geq 0$. We are given the following conditions:
    \begin{itemize}
        \item $\frac{g_1+b_1}{g_2+b_2} \geq 1+\epsilon$,
        \item $1-\frac{\epsilon\delta'}{8} \leq \frac{b_1}{b_2} \leq 1+\frac{\epsilon\delta'}{8}$, $1-\frac{\epsilon\delta'}{8} \leq \frac{b_1'}{b_2'} \leq 1+\frac{\epsilon\delta'}{8}$,
        \item $g_2' + b_2' \leq \frac{1}{\delta'}(g_2+b_2)$,
        \item $g_1'$ approximates $g_1$, and $g_2'$ approximates $g_2$, i.e.
        \begin{itemize}
            \item either $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $g_2' \approx_{\frac{\epsilon}{16}} g_2$,
            \item or $\frac{g_1}{g_2} > 7$, $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $\frac{g_1'}{g_2'}\geq 3$.
        \end{itemize}
    \end{itemize}  
    then we have $\frac{g_1'+b_1'}{g_2'+b_2'} \geq 1+\epsilon\delta'/4.$
\end{claim}

 Applying \cref{claim:robust-estimate}, we get that $\frac{g_1' + b_1'}{g_2' + b_2'} \geq 1+\epsilon\delta'/4$, which implies $\frac{\|r_i - u\|_1}{\|r_{i^*} - u\|_1} \geq 1+\epsilon\delta'/4$.
    By union bound, this inequality holds for all $i \in [n]$ with probability $1-\delta'$. 
\end{proof}

\begin{claim} \label{claim:approximate-diff-l1}
    Suppose $g_1, w, g_1', w' \geq 0$, and $\frac{g_1}{w} \geq 1+\frac{\epsilon}{2}$. $g_1'$ and $w'$ are estimates of $g_1$ and $w$, where $g_1' \approx_{\epsilon/16} g_1$ and $w' \approx_{\epsilon/16} w$. Then $g_1' - w' \geq \left(\frac{3}{4} - \frac{\epsilon}{16}\right) (g_1 - w)$. 
\end{claim}

\begin{proof}
    From $g_1' \approx_{\epsilon/16} g_1$ and $w' \approx_{\epsilon/16} w$, we have 
    $
    g_1' - w' \geq \left(1-\frac{\epsilon}{16}\right) g_1 - \left(1+\frac{\epsilon}{16}\right) w.
    $
    Let $\rho = \frac{3}{4} - \frac{\epsilon}{16}$. We rewrite $\frac{g_1}{w} \geq 1+\frac{\epsilon}{2}$ as $\left(1-\frac{\epsilon}{16} - \rho\right) g_1 \geq \left(1+\frac{\epsilon}{16} - \rho\right) w$. This shows $\left(1-\frac{\epsilon}{16}\right) g_1 - \left(1+\frac{\epsilon}{16}\right) w \geq \rho (g_1 - w)$. 
    Thus we have $g_1' - w' \geq \rho (g_1 - w)$.
\end{proof}


\begin{proof}[Proof of \Cref{claim:robust-estimate}]

\noindent \underline{Case 1.} If $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $g_2' \approx_{\frac{\epsilon}{16}} g_2$.

Given \( \frac{g_1 + b_1}{g_2 + b_2} \geq 1 + \epsilon \), we start by deducting \( 1 + \frac{\epsilon \delta'}{8} \) on both sides:
$
\frac{g_1 + b_1 - (1 + \frac{\epsilon \delta'}{8})(g_2 + b_2)}{g_2 + b_2} \geq 1 + \epsilon - (1 + \frac{\epsilon \delta'}{8}) \geq \frac{7}{8} \epsilon.
$
Since \( \frac{b_1}{b_2} \leq 1 + \frac{\epsilon \delta'}{8} \), we get
$
\frac{g_1 - (1 + \frac{\epsilon \delta'}{8})g_2}{g_2 + b_2} \geq \frac{7}{8} \epsilon.
$
Using \cref{claim:approximate-diff-l1} and letting \( w = (1 + \frac{\epsilon}{8})g_2 \), we have 
$
\frac{g_1' - (1 + \frac{\epsilon \delta'}{8})g_2'}{g_2 + b_2} \geq \frac{21 - \frac{7 \epsilon}{4}}{32} \epsilon \geq \frac{5 \epsilon}{8}.
$
Since \( g_2' + b_2' \leq \frac{1}{\delta'}(g_2 + b_2) \), we get
$
\frac{g_1' - (1 + \frac{\epsilon \delta'}{8})g_2'}{g_2' + b_2'} \geq \frac{5 \epsilon \delta'}{8}.
$
Rewriting the left-hand side as
$
\frac{g_1' - g_2' + b_1' - b_2' - \frac{\epsilon \delta'}{8}(g_2' + b_2') - b_1' + (1 + \frac{\epsilon \delta'}{8})b_2'}{g_2' + b_2'} \geq \frac{5 \epsilon \delta'}{8}.
$
Rearranging terms gives
$
\frac{g_1' - g_2' + b_1' - b_2' - b_1' + (1 + \frac{\epsilon \delta'}{8})b_2'}{g_2' + b_2'} \geq \frac{5 \epsilon \delta'}{8} + \frac{\epsilon \delta'}{8}.
$
Using \( \frac{b_1'}{b_2'} \geq 1 - \frac{\epsilon \delta'}{8} \), we get
$
\frac{g_1' - g_2' + b_1' - b_2' + (\frac{\epsilon \delta'}{4})b_2'}{g_2' + b_2'} = \frac{g_1' - g_2' + b_1' - b_2' - (1 - \frac{\epsilon \delta'}{8})b_2' + (1 + \frac{\epsilon \delta'}{8})b_2'}{g_2' + b_2'} \geq \frac{3 \epsilon \delta'}{4}.
$

This implies
$
\frac{g_1' - g_2' + b_1' - b_2'}{g_2' + b_2'} \geq \frac{3 \epsilon \delta'}{4} - \frac{\epsilon \delta'}{4} = \frac{\epsilon \delta'}{2}.
$
Finally, we obtain
$
\frac{g_1' + b_1'}{g_2' + b_2'} \geq 1 + \frac{\epsilon \delta'}{2}.
$




    \noindent \underline{Case 2.} If $\frac{g_1}{g_2} > 7$, $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $\frac{g_1'}{g_2'}\geq 3$.

Given \( \frac{g_1 + b_1}{g_2 + b_2} \geq 1 + \epsilon \), we start by deducting \( 1 + \frac{\epsilon \delta'}{8} \) on both sides:
$
\frac{g_1 + b_1 - (1 + \frac{\epsilon \delta'}{8})(g_2 + b_2)}{g_2 + b_2} \geq 1 + \epsilon - (1 + \frac{\epsilon \delta'}{8}) \geq \frac{7}{8} \epsilon,
$
which simplifies to
$
\frac{g_1}{g_2 + b_2} \geq \frac{g_1 - (1 + \frac{\epsilon \delta'}{8})g_2}{g_2 + b_2} \geq \frac{7}{8} \epsilon
$
since \( \frac{b_1}{b_2} \leq 1 + \frac{\epsilon \delta'}{8} \) and \( g_2 \geq 0 \).
Using \( g_1' \approx_{\epsilon / 16} g_1 \), we get
$
\frac{g_1'}{g_2 + b_2} \geq \frac{7 \epsilon}{8 (1 + \epsilon / 16)}.
$
Since \( g_2' + b_2' \leq \frac{1}{\delta'}(g_2 + b_2) \), we have
$
\frac{g_1'}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{8 (1 + \epsilon / 16)}.
$
Using \( \frac{g_1'}{g_2'} \geq 3 \Rightarrow \frac{3}{2}(g_1' - g_2') \geq g_1' \), we obtain
$
\frac{\frac{3}{2}(g_1' - g_2')}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)},
$
which can be rewritten as
$
\frac{g_1' - g_2'}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)}.
$
Since \( (1 - \frac{\epsilon \delta'}{8})g_2' \leq g_2' \), we get
$
\frac{g_1' - (1 + \frac{\epsilon \delta'}{8})g_2'}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)}.
$
Subtracting \( \frac{\epsilon \delta'}{8} \) from both sides:
$
\frac{g_1' - (1 + \frac{\epsilon \delta'}{8})g_2' - \frac{\epsilon \delta'}{8}(g_2' + b_2')}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)} - \frac{\epsilon \delta'}{8}
$
which simplifies to
$
\frac{g_1' - g_2' - \frac{\epsilon \delta'}{8} b_2'}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)} - \frac{\epsilon \delta'}{8}.
$
Rewriting gives
$
\frac{g_1' - g_2' + (1 - \frac{\epsilon \delta'}{8}) b_2' - b_2'}{g_2' + b_2'} \geq \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)} - \frac{\epsilon \delta'}{8}.
$
Since \( \frac{b_1'}{b_2'} \geq 1 - \frac{\epsilon \delta'}{8} \), we get
$
\frac{g_1' - g_2' + b_1' - b_2'}{g_2' + b_2'} \geq \frac{7 \epsilon}{48 (1 + \epsilon / 16)} - \frac{\epsilon}{8}.
$
Finally, we obtain
$
\frac{g_1' + b_1'}{g_2' + b_2'} \geq 1 + \frac{7 \epsilon \delta'}{12 (1 + \epsilon / 16)} - \frac{\epsilon \delta'}{8} \geq 1 + \frac{\epsilon \delta'}{4}.
$


\end{proof}


