\subsection{Data Structure for \texorpdfstring{$\ell_2$}{l2}-metric with Near-linear Space and Query Time}\label{sec:linear-space-l2}

The preprocessing and querying procedures of our data structure are described in \cref{alg:sample-reuse-l2}. At a high level, the preprocessing and querying phases of \cref{alg:sample-reuse-l2} are very similar to that of \cref{alg:sample-reuse-l1}. The main differences are (1) in the choice of the probability distribution used to sample coordinates and (2) in the specific dimension reduction technique. In this case, we use the Johnson Lindenstrauss mapping for the dimension reduction.

\begin{algorithm}[htp]\label{alg:sample-reuse-l2}
    \caption{An approximate nearest neighbor data structure for $n$ points in $\R^d$ for $\ell_2$ metric.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKwProg{comparator}{$E$}{}{}
    \SetKw{store}{store}
    \preprocessing{$(C, \epsilon, \delta)$\tcp*[f]{Inputs: $C=\{c_1, \dots, c_n\}\subseteq \R^d, \epsilon \in (0, \frac{1}{4}), \delta\in (0,1)$}}{
        % Let $\epsilon \leftarrow \epsilon'/\log \log n$ and $\delta \leftarrow \delta' / \Theta(n \log \log n)$\;
        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (n/\delta)/(\epsilon^4\delta^2))$\;
        % \footnote{According to Theorem \ref{theorem:Lp-NN}, it should be $O(\log(1/\delta)/\epsilon^3)$, but we can achieve a better bound of $O(\log(1/\delta)/\epsilon^2)$  by using $0\leq X_t, Y_t\leq 1$, instead of using $0\leq X_t, Y_t\leq 1/\epsilon$ in the proof. }

        \For{$t\in [T]$}{
            \For{$b\in [d]$}{
                Add $b$ to $I$ with probability  $p^{(b)}\triangleq \max_{(i,j)\in {\binom{n}{2}}} \frac{|c_i^{(b)} - c_j^{(b)}|^2}{\|c_i- c_j\|_2^2}$\;
            }
        }
        Let $R=\{r_1, r_2, \dots, r_n\}\subseteq \R^{I}$, where for $i \in [n], b \in I$, we have $r_i^{(b)} = c_i^{(b)} / \sqrt{p^{(b)}}$\;

        Let $m = O(\log(n/\delta)/(\epsilon^2\delta^2))$\;
        Sample $M\in \mathbb{R}^{[m]\times I}$, where each entry of $M$ is chosen uniformly at random from $\left\{\pm \sqrt{\frac1m}\right\}$ \;
        $M(\cdot)\colon \mathbb{R}^{I} \rightarrow \mathbb{R}^{m}$ is an oblivious, linear Johnson-Lindenstrauss mapping\;


        \store{$I$, $M(R) = \{Mr_i\mid i\in [n]\}$, $\{p^{(b)}\mid b\in I\}$, $M$ }
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in \R^d$}}{
        Query $q^{(b)}, b\in I$\;
        Let $u\in \mathbb{R}^{I}$, where $\forall b \in I, u^{(b)} = q^{(b)} / \sqrt{p^{(b)}}$\;
        Let $\hat{i} = \argmin_{i\in [n]} \|Mr_i - Mu\|_2$\;
        \Return{$\hat{i}$}
    }
\end{algorithm}
%\joachim{... each entry ... is chosen from ... uniformly at random}
%\joachim{use $\backslash$mid inside set declarations}

\begin{theorem}\label{theorem:sample-reuse-l2}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in \R^d$ equipped with $\ell_2$ metric. Given $0 < \epsilon < 1/4$ and $0 < \delta < 1$, with probability $(1-\delta)$, we can efficiently construct a randomized data structure (See \cref{alg:sample-reuse-l2}) such that for any query point $q\in \R^d$ the following conditions hold with probability $1-\delta$. (i) The data structure reads $O(n \log (n/\delta)/(\epsilon^4\delta^2))$ coordinates $q$. (ii) It returns $i\in [d]$ where $c_i$ is a $(1+\epsilon)$-approximate nearest neighbor of $q$ in $C$. (iii) The data structure has a size of $O(n \log^2(n/\delta) \log(d)/(\epsilon^6\delta^4))$ words. 
\end{theorem}

We show the proof in the following subsections in line with the proof structure described in \cref{sec:sample-reuse}. 
In particular, we show that each of the following good events, which we restate here for the sake of completeness, hold with probability at least $1-\delta'$, where $\delta' = \delta/4$.
\begin{enumerate}
    \item The first event is that the distance between a query and its nearest neighbor is overestimated at most by the factor $4/\delta$.
    \item The second event is that for a query point the estimated distance to its nearest neighbor is significantly smaller than the estimated distance to any center that is not an approximate nearest neighbor.
    \item The third event is that the dimension reduction preserves the distances between the coordinate-selected points and the query.
    \item The fourth event is that at most near-linear many coordinates are sampled in the preprocessing and accessed in the query phase. 
\end{enumerate}
Although the proof at a high level follows the same structure as for the $\ell_1$ case, there are significant differences between the proofs themselves. The main differences are in the dimension reduction as well as in bounding the space and query complexities.

    \subsubsection{Upper Bound for Estimate of Distance between Query and its Nearest Neighbor}\label{sec:first-section-l2}

    We first show that the squared distance between a query point and its nearest neighbor is overestimated at most by a factor $1/\delta'$ with probability $1-\delta'$. 

    \begin{claim}\label{claim:Markovl2}
    Let $q\in \R^n$ be a query and let $i^*\in [n]$ be the index of its nearest neighbor. It holds that
    \begin{align*}
        \frac{1}{T}\|r_{i^*} - u\|_2^2 \leq \frac{1}{\delta'} \|c_{i^*} - q\|_2^2,
    \end{align*}
    with probability $1-\delta'$.
    \end{claim}
    \begin{proof}
        For any $i\in [n]$, we have $\E[\|r_i - u\|_2^2] = T \|c_i - q\|_2^2$, because 
    \begin{align*}
        \E[\|r_i - u\|_2^2] =& \E\left[\sum_{b\in I} \left(r_i^{(b)} - u^{(b)}\right)^2\right] \\
        =& \E\left[\sum_{t\in [T], b\in [d]} \mathbbm{1}_{\{\text{in iteration $t$, we add $b$ to $I$\}}}\left(r_i^{(b)} - u^{(b)}\right)^2\right] \\
        =& \sum_{t\in [T], b\in [d]} p^{(b)}\left(r_i^{(b)} - u^{(b)}\right)^2 = \sum_{t\in [T], b\in [d]} p^{(b)}\left(\frac{c_i^{(b)}}{\sqrt{p^{(b)}}} - \frac{q^{(b)}}{\sqrt{p^{(b)}}}\right)^2 \\
        =& \sum_{t\in [T], b\in [d]} \left(c_i^{(b)} - q^{(b)}\right)^2 = T \|c_i - q\|_2^2.
    \end{align*}
    Using Markov's inequality, we have with probability $1-\delta'$,
    \begin{equation*}
    \|r_{i^*} - u\|_2^2 \leq \frac{T}{\delta'} \|c_{i^*} - q\|_2^2.\qedhere
    \end{equation*}
    \end{proof}


    \subsubsection{Coordinate Selection Preserves Distance Ratio}

    In this section, we show that, the following holds: 
for any query point $q\in \R^n$, whose nearest neighbor is $c_{i^*}$, with probability $1-2\delta'$, for all $c_i\in C$ such that $\frac{\|c_i-q\|_2}{\|c_{i^*}-q\|_2} \geq 1+\epsilon$,  the estimated ratio is significantly  larger than one, that is $\frac{\|r_i-u\|_2}{\|r_{i^*}-u\|_2} \geq 1+\epsilon\delta'/12$.
This statement is formalized in \Cref{lemma:robust-feature-selection-l2}.

As before, we first partition the coordinates in $[d]$ into good and bad regions for each pair of points. Although the specific definition of the regions are different compared to the $\ell_1$ case, the intuition behind the definitions is the same.

%In the good region are the coordinates on which the query is not too far away from one of the points. 
%The remaining coordinates are in the bad region.
%The intuition is that, restricted to the coordinates in the good region, the distance between one of the points and the query  is bounded.
%This implies that we can estimate these distances using a Chernoff bound.
%For the bad coordinates the intuition is that the distances from the query to the 2 points are so large that the ratio between these distances is close to one. Additionally these distances are not overestimated because of the previous event in \cref{sec:first-section-l2}.

\begin{definition}[Good region and bad region]
    Consider two points $c_1, c_2\in \R^d$, and a query point $q\in\R^d$. We define the good region $\Good(c_1, c_2, q)$ w.r.t.\ $(c_1,c_2,q)$ as $$\{z\in [d] \mid\min\{c_1^{(z)}, c_2^{(z)}\} - \frac{24}{\epsilon \delta'} |c_1^{(z)} - c_2^{(z)}| \leq q^{(z)} \leq \max\{c_1^{(z)}, c_2^{(z)}\} + \frac{24}{\epsilon \delta'} |c_1^{(z)} - c_2^{(z)}|\}.$$ We define the bad region w.r.t.\ $(c_1,c_2,q)$ as $\Bad(c_1, c_2, q) = [d]\setminus \Good(c_1, c_2, q)$. When there is no ambiguity, we use $\Good$ for $\Good(c_1, c_2, q)$, and $\Bad$ for $\Bad(c_1, c_2, q)$. 
\end{definition}
We also define the distance between points restricted to subsets of coordinates as before.
\begin{definition}[Restricted distance]
    Given $x,y \in \R^d$, we define the distance between $x$ and $y$ restricted to region $J\subseteq [d]$ as 
    $\dist_J(x,y) = \left(\sum_{z\in J} \left(x^{(z)} - y^{(z)}\right)^2\right)^{\frac12}$. 
    Furthermore, for $u,v \in \R^I$, where $I$ is a multiset, whose elements are from $[d]$, $\dist_J(u,v) = \left(\sum_{z\in I} \mathbbm{1}_{z\in J}\cdot\left(x^{(z)} - y^{(z)}\right)^2\right)^{\frac12}.$

\end{definition}

%For bounding distance estimates on the good region, we can use Chernoff bound. For distance estimates on the bad region, we need Markov's inequality. 
%This motivates our name of the regions. 

The following lemma is the $\ell_2$ version of \cref{lemma:good-region-is-large-l1}.

\begin{lemma}\label{lemma:good-region-is-large-l2}
    Consider 3 points $a,b,q\in\R^d$. If $\frac{\|b-q\|_2}{\|a-q\|_2} \geq 1+\epsilon$, then $\frac{\dist_{\Good(a,b,q)}(b,a)}{\|b-a\|_2} \geq \frac{13}{16}$.
\end{lemma}
\begin{proof}
We first follow the same steps as in the proof of \cref{lemma:good-region-is-large-l1} and obtain:
 \[
        \dist_{\Bad(a,b,q)}(b,q) + \dist_{\Bad(a,b,q)}(a,q) \leq \left(1+\frac2\epsilon\right) \|b-a\|_2.
    \]
    Squaring both sides, we get:
    \[
        \dist^2_{\Bad(a,b,q)}(b,q) + \dist^2_{\Bad(a,b,q)}(a,q) \leq \left(1+\frac2\epsilon\right)^2 \|b-a\|_2^2.
    \]
    This implies that:
     \begin{align*}
         \frac{1152}{\epsilon^2\delta
    '^2} \left(\|b-a\|_2^2 - \dist^2_{\Good(a,b,q)}(b,a)\right) = \sum_{z\in \Bad(a,b,q)} 2\left(\frac{24}{\epsilon\delta'}\right)^2\left|b^{(z)} - a^{(z)}\right|^2  \\
    \leq \left(1+\frac2\epsilon\right)^2 \|b-a\|_2^2.
     \end{align*}


    Rearranging the terms and simplifying, we get:
    \[
    \frac{\dist^2_{\Good(a,b,q)}(b,a)}{\|b-a\|_2^2} \geq \frac{1143}{1152} \Rightarrow \frac{\dist_{\Good(a,b,q)}(b,a)}{\|b-a\|_2} \geq \frac{13}{16}.\qedhere
    \]
\end{proof}



The following lemma shows that for two points $c_i, c_j$ and a query $q$ such that $q$ is significantly closer to $c_j$, we can estimate the distances, restricted to the good region, between one of the points and the query.
\begin{lemma}\label{lemma:chernoff_for_good_l2}

    Let $c_i, c_j$ where $i,j\in [n]$ be such that for the query point $q \in \R^d$ it holds that $\|c_i - q\|_2 \geq (1+\epsilon)\|c_j - q\|_2$. Let $\Good$ be shorthand for $\Good(c_i, c_j, q)$ and $\Bad$ for $\Bad(c_i, c_j, q)$. The following statements are true:

    \begin{enumerate}
        \item $\dist_{\Good} (c_i, q) \geq (1+\epsilon) \dist_{\Good} (c_j, q)$.
        \item If $\dist^2_{\Good} (c_j, q) \geq \frac1{16} \dist^2_{\Good} (c_i, c_j)$, then with probability $1-\delta'/n$, 
        \begin{align*}
            \dist^2_{\Good} (r_i, u) \approx_{\frac{\epsilon}{16}} T\cdot \dist^2_{\Good}(c_i, q),\\
            \dist^2_{\Good} (r_j, u) \approx_{\frac{\epsilon}{16}} T\cdot \dist^2_{\Good}(c_j, q).
        \end{align*}
        \item If $\dist^2_{\Good} (c_j, q) < \frac1{16} \dist^2_{\Good} (c_i, c_j)$, then $\frac{\dist^2_{\Good} (c_i, q)}{\dist^2_{\Good} (c_j, q)} > 7$. With probability $1-\delta'/n$, 
        \begin{align*}
            \dist^2_{\Good} (r_i, u) &\approx_{\frac{\epsilon}{16}} T\cdot \dist^2_{\Good}(c_i, q),\\
            \frac{\dist^2_{\Good} (r_i, u)}{\dist^2_{\Good} (r_j, u)} &\geq 3.
        \end{align*}
    \end{enumerate}

%     \begin{enumerate}
%         \item $\dist_{\Good} (c_i, q) \geq (1+\epsilon) \dist_{\Good} (c_j, q)$.
%         \item With probability $1-\frac{\delta'}{2n}$ we have $\dist^2_{\Good} (r_i, u) \approx_{\frac{\epsilon}{16}} T\cdot \dist^2_{\Good}(c_i, q)$.
%         \item 
% \begin{enumerate}[(i)]        
%         \item If $\dist^2_{\Good} (c_j, q) \geq \frac1{16} \dist^2_{\Good} (c_i, c_j)$, then with probability $1-\frac{\delta'}{2n}$ we have             $\dist^2_{\Good} (r_j, u) \approx_{\frac{\epsilon}{16}} T\cdot \dist^2_{\Good}(c_j, q)$.

%         \item If $\dist^2_{\Good} (c_j, q) < \frac1{16} \dist^2_{\Good} (c_i, c_j)$,  which implies $\frac{\dist^2_{\Good} (c_i, q)}{\dist^2_{\Good} (c_j, q)} \geq 7$, then with probability $1-\frac{\delta'}{2n}$ we have
%             $\frac{\dist^2_{\Good} (r_i, u)}{\dist^2_{\Good} (r_j, u)} \geq 3$.
%     \end{enumerate}
% \end{enumerate}
    \end{lemma}
\begin{proof}
    Combining the following two properties, 
    \begin{equation*}
        \frac{ \dist^2_{\Bad} (c_i, q)}{\dist^2_{\Bad} (c_j, q)} \leq (1+\frac{\epsilon\delta'}{24})^2 < (1+\epsilon)^2,
    \end{equation*}
    \begin{equation*}
         \frac{\dist^2_{\Good} (c_i, q) + \dist^2_{\Bad} (c_i, q)}{\dist^2_{\Good} (c_j, q)+\dist^2_{\Bad} (c_j, q)} = \frac{\|c_i - q\|_2^2}{\|c_j - q\|_2^2} \geq (1+\epsilon)^2.
    \end{equation*}
    implies
    \begin{equation*}
        \frac{\dist^2_{\Good} (c_i, q)}{\dist^2_{\Good} (c_j, q)} \geq (1+\epsilon)^2.
    \end{equation*}
    Therefore the first item of the lemma is proved.

    In the algorithm, we construct $\{r_i\mid i\in [n]\}$ and $u$ through sampling a multiset $I$. To analyze how the data structure samples $I$ in the preprocessing, we define the following random variables $\forall t\in [T], z\in \Good$
    \[P_{t, z} =  \begin{cases} 
      \frac{|q^{(z)} - c_i^{(z)}|^2}{p^{(z)} }, & w.p.\; p^{(z)},\hspace{0.95cm}\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad \text{i.e. if we do not add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   \[Q_{t, z} =  \begin{cases} 
      \frac{|q^{(z)} - c_j^{(z)}|^2}{p^{(z)} } , & w.p.\; p^{(z)},\hspace{0.95cm}\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we do not add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   Notice that $\sum_{t\in [T],z\in \Good} P_{t,z} = \dist^2_\Good(r_i, u)$ and $\sum_{t\in [T],z\in \Good} Q_{t,z} = \dist^2_\Good(r_j, u)$.  

    Observe that $\forall t\in [T], z\in \Good$, $0 \leq P_{t,z} \leq \left(1+\frac{24}{\epsilon\delta'}\right)^2 \|c_i - c_j\|_2^2$. This is because, if $c_i^{(z)} = c_j^{(z)}$, from the definition of good region we have $q^{(z)} = c_i^{(z)}$, thus $P_{t,z} = 0$; otherwise $c_i^{(z)} \neq c_j^{(z)}$, 
    \begin{align*}
        0 \leq P_{t,z} \leq \frac{|q^{(z)} - c_i^{(z)}|^2}{|c_i^{(z)} - c_j^{(z)}|^2 } \cdot \|c_i - c_j\|_2^2 \leq \left(1+\frac{24}{\epsilon\delta'}\right)^2 \|c_i - c_j\|_2^2,
    \end{align*}
    where the second inequality comes from ``oversampling'': $p^{(z)} \geq \frac{|c_i^{(z)} - c_j^{(z)}|^2}{\|c_i - c_j\|_2^2}$, and the third inequality comes from the definition of good region.
    By a similar argument, we have $0 \leq Q_{t,z}\leq (1+\frac{24}{\epsilon\delta'})^2 \|c_i - c_j\|_2^2$. 

    Notice $\forall t\in [T], \E[\sum_{z\in \Good} P_{t,z}] = \dist^2_{\Good}(c_i, q)$ and $\E[\sum_{z\in \Good} Q_{t,z}] = \dist^2_{\Good}(c_j, q)$. Because 
    \begin{align*}
        \E[\sum_{z\in \Good} P_{t,z}] =& \sum_{z\in \Good} \E[P_{t,z}] \\
        =& \sum_{z\in \Good} p^{(z)}\cdot \left(\frac{q^{(z)} - c_i^{(z)}}{\sqrt{p^{(z)}}}\right)^2 = \sum_{z\in \Good} |q^{(z)} - c_i^{(z)}|^2 = \dist^2_{\Good}(c_i, q).
    \end{align*}
    Since $\forall t\in [T], \E[\sum_{z\in \Good} (P_{t,z} + Q_{t,z})] = \dist^2_{\Good}(c_i, q) + \dist^2_{\Good}(c_j, q) \geq \frac{1}{2} \dist^2_{\Good}(c_i, c_j)$, we have $\E[\sum_{z\in \Good}P_{t,z}] \geq \frac{1}{4} \dist^2_{\Good}(c_i, c_j)$. In the rest of the proof, we use $\E[\sum_{z\in \Good} P_{t,z}]$ without specify which $t\in [T]$, because they have the same value for all $t\in [T]$. 

    Let $0<\epsilon_2 = \epsilon/16 < 1$. Using Chernoff bound and \cref{lemma:good-region-is-large-l2}, we have 
    \begin{align*}
    &\Pr\left[\left|\sum_{t\in [T], z\in \Good} P_{t,z} - \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right] \\
    \leq & 2\exp\left(-\frac{\epsilon_2^2 T \E[\sum_{z\in \Good} P_{t,z}]}{3(1+\frac{24}{\epsilon\delta'})^2 \|c_i - c_j\|_2^2}\right) \\
    = & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{24}{\epsilon\delta'})^2} \frac{\dist^2_{\Good}(c_i, q)}{\dist^2_{\Good}(c_i, c_j)} \frac{\dist^2_{\Good}(c_i, c_j)}{\|c_i - c_j\|_2^2}\right) \\
    \leq & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{24}{\epsilon\delta'})^2} \cdot \frac{1}{4} \cdot \frac{1143}{1152}\right) \leq \frac{\delta'}{2n},
    \end{align*}
    by choosing 
    $T = \Theta(\frac{1}{\epsilon^4 \delta^2} \log(n/\delta)) $. 

    \noindent \underline{Case 1.} If $\E[\sum_{z\in \Good} Q_{t,z}] \geq \frac{1}{16} \cdot \dist^2_{\Good}(c_i, c_j)$, using Chernoff bound and \cref{lemma:good-region-is-large-l2}, we have $$\Pr\left[\left|\sum_{t\in [T], z\in \Good} Q_{t,z} - \E\left[\sum_{t\in [T], z\in \Good} Q_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in \Good} Q_{t,z}\right]\right] \leq \frac{\delta'}{2n},$$
    by choosing 
    $T = \Theta(\frac{1}{\epsilon^4 \delta^2} \log(n/\delta)) $. 

    By union bound, with probability $1-\delta'/n$, we have 
    \begin{equation*}
        \sum_{t\in [T],z\in \Good} P_{t,z}  \approx_{\frac{\epsilon}{16}} \E[\sum_{t\in [T],z\in \Good} P_{t,z}], \text{ and } \sum_{t\in [T],z\in \Good} Q_{t,z} \approx_{\frac{\epsilon}{16}} \E[\sum_{t\in [T],z\in \Good} Q_{t,z}],
    \end{equation*}
    Therefore the second item of the lemma is proved.

    \noindent \underline{Case 2.} If $\E[\sum_{z\in \Good} Q_{t,z}] < \frac{1}{16} \cdot \dist^2_{\Good}(c_i, c_j)$. Then we have $\E[\sum_{z\in \Good} P_{t,z}] > (\frac12-\frac1{16}) \dist^2_{\Good}(c_i, c_j)$, which gives that $\frac{\dist^2_{\Good} (c_i, q)}{\dist^2_{\Good} (c_j, q)} > 7$. Using Chernoff bound and \cref{lemma:good-region-is-large-l2}, we have
    \begin{align*}
    &\Pr\left[\left|\sum_{t\in [T],z\in \Good} Q_{t,z} - \E[\sum_{t\in [T], z\in \Good} Q_{t,z}]\right| > \frac{1}{16}T \cdot \dist^2_{\Good}(c_i, c_j) \right] \\
    <& 2\exp\left( -\frac{T \cdot \frac{1}{16}\dist^2_{\Good}(c_i, c_j)}{3(1+\frac{24}{\epsilon\delta'})^2 \|c_i - c_j\|_2^2}\right) \\
    \leq & 2\exp\left( -\frac{T  }{48(1+\frac{24}{\epsilon\delta'})^2} \frac{\dist^2_{\Good}(c_i, c_j)}{\|c_i - c_j\|_2^2} \right)\leq \frac{\delta'}{2n}. 
    \end{align*}
    by choosing $T = \Omega(\frac{1}{\epsilon^2 \delta^2} \log(n/\delta)) $.

    By union bound, with probability $1-\delta'/n$, we have 
    \begin{equation*}
        \sum_{t\in [T],z\in \Good} P_{t,z} \approx_{\frac{\epsilon}{16}} \E\left[\sum_{t\in[T],z\in \Good} P_{t,z}\right], \text{ and } \sum_{t\in [T],z\in \Good} Q_{t,z} \leq \frac{T}8 \dist^2_{\Good}(c_i, c_j).
    \end{equation*}
    Thus 
    \begin{equation*}
        \frac{\sum_{t\in [T],z\in \Good} P_{t,z}}{\sum_{t\in [T],z\in \Good} Q_{t,z}} \geq \frac{(1-\frac{\epsilon}{16})(\frac12 - \frac18)\dist^2_{\Good}(c_i, c_j)}{\frac18 \dist^2_{\Good}(c_i, c_j)} \geq 3.
    \end{equation*}
    The third item of the lemma is proved.
\end{proof}

