In the following lemma we state that our bounds on the distance estimates are good enough. Concretely, for a point that is not an approximate nearest neighbor, the estimated distance between this point and the query is significantly larger than the estimated distance between the nearest neighbor and the query.
\begin{lemma}\label{lemma:robust-feature-selection-l2}
    For any query point $q \in \R^d$, with probability $1-2\delta'$, it holds for all $i\in [n]$, if $\frac{\|c_i-q\|_1}{\|c_{i^*}-q\|_1} \geq 1+\epsilon$, then $\frac{\|r_i-u\|_2}{\|r_{i^*}-u\|_2} \geq 1+\frac{\epsilon\delta'}{12}$.
\end{lemma}

\begin{proof}
    We know that $\|r_{i^*} - u\|_2^2 \leq \frac{T}{\delta'} \|c_{i^*} - q\|_2^2$ holds with probability $1-\delta'$ by \Cref{claim:Markovl2}.
    Thus, it is sufficient to show the statement of the lemma holds under this assumption with probability $1-\delta'$.

    Fix $i\in [n]$. Since we only have 2 points from $C$ that are $c_i$ and $c_{i^*}$, for simplicity we use $\Good$ for $\Good(c_i, c_{i^*}, q)$ and $\Bad$ for $\Bad(c_i, c_{i^*}, q)$.

    Denote $b_1 = \dist^2_\Bad(c_i, q)$, $b_2 = \dist^2_\Bad(c_{i^*}, q)$, $g_1 = \dist^2_\Good(c_i, q)$, $g_2 = \dist^2_\Good(c_{i^*}, q)$. Also denote $b_1' = \dist^2_\Bad(r_i, u)/T$, $b_2' = \dist^2_\Bad(r_{i^*}, u)/T$, $g_1' = \dist^2_\Good(r_i, u)/T$, $g_2' = \dist^2_\Good(r_{i^*}, u)/T$.

    We have $\frac{\|c_i - q\|_2}{\|c_{i^*} - q\|_2} \geq 1+\epsilon$, which is $\frac{g_1 + b_1}{g_2 + b_2} \geq (1+\epsilon)^2 \geq 1+\epsilon$. We are given that $\|r_{i^*} - u\|_2^2 \leq T/\delta' \|c_{i^*} - q\|_2^2$, which is $g_2' + b_2' \leq \frac{1}{\delta'}(g_2 + b_2)$. From the definition of bad region, we know that $1 - \frac{\epsilon\delta'}{8} \leq (1 - \frac{\epsilon\delta'}{24})^2 \leq \frac{b_1}{b_2} \leq (1 + \frac{\epsilon\delta'}{24})^2 \leq 1 + \frac{\epsilon\delta'}{8}$. Also $1 - \frac{\epsilon\delta'}{8} \leq \frac{b_1'}{b_2'} \leq 1 + \frac{\epsilon\delta'}{8}$, because we select and rescale coordinates.

    Applying \cref{lemma:chernoff_for_good_l2} on $c_i$ and $c_{i^*}$ gives that with probability $1-\delta'/n$,
    \begin{itemize}
        \item either $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $g_2' \approx_{\frac{\epsilon}{16}} g_2$,
        \item or $\frac{g_1}{g_2} > 7$, $g_1' \approx_{\frac{\epsilon}{16}} g_1$, $\frac{g_1'}{g_2'} \geq 3$.
    \end{itemize}

    Applying \cref{claim:robust-estimate}, we prove that $\frac{g_1' + b_1'}{g_2' + b_2'} \geq 1 + \frac{\epsilon\delta'}{4}$, that is $\frac{\|r_i - u\|^2_2}{\|r_{i^*} - u\|^2_2} \geq 1 + \frac{\epsilon\delta'}{4}$. Thus we have $\frac{\|r_i - u\|_2}{\|r_{i^*} - u\|_2} \geq 1 + \frac{\epsilon\delta'}{12}$.
\end{proof}

\subsubsection{\texorpdfstring{$\ell_2$}{l2} Dimension Reduction Preserves the Distance Ratio}

In this section, we bound the distortion introduced by the dimension reduction that our data structure performs. %This is a point of siginificant difference between the proof

\begin{theorem}[distributional Johnson-Lindenstrauss Lemma]\label{thm:distJL}
    Consider 2 points $a, b \in \R^d$ and parameters $0<\epsilon, \delta < 1$. We sample a random matrix $M\in \R^{m \times d}$, where $m = O(\log(1/\delta)/(\epsilon^2))$ and each entry of $M$ is sampled uniformly from $\{\pm \sqrt{1/m}\}$. Then with probability $1-\delta$, $\|Ma- Mb\|_2 \approx_\epsilon \|a-b\|_2$.
\end{theorem}

\begin{claim}
    Let $q\in \R^n$ be a query. Let $i^*\in [n]$ be the index of its nearest neighbor. \Cref{alg:sample-reuse-l2} outputs an index $i$ such that
    \begin{align*}
        \frac{\|c_i - q\|_2}{\|c_{i^*} - q\|_2} \leq 1+\epsilon
    \end{align*}
    with probability $1-3\delta'$.
\end{claim}
\begin{proof}
Applying \cref{thm:distJL} with $m = O(\log(n/\delta')/(\epsilon^2 \delta'^2))$, given any $v \in R$, it holds with probability $1-\delta'/(n+1)$, that $\|Mv- Mu\|_2 \in [1-\epsilon\delta'/100, 1+\epsilon\delta'/100] \|v- u\|_1$. By union bound, with probability $1-\delta'$, it holds for all $v\in R$.
By \Cref{lemma:robust-feature-selection-l2} it holds with probability $1-2\delta'$ that for all $i\in [n]$, if $\frac{\|c_i - q\|_2}{\|c_{i^*} - q\|_2} \geq 1+\epsilon$, then $\frac{\|r_i - u\|_1}{\|r_{i^*} - u\|_1} \geq 1+\epsilon\delta'/12$, thus $\frac{\|Mr_i - Mu\|_2}{\|Mr_{i^*}- Mu\|_2} > 1$ with probability $1-3\delta'$, i.e. the algorithm will not output $i$ as the index of the approximate nearest neighbor.
\end{proof}
\begin{remark}
    Using approximate nearest neighbour technqiues, e.g.\ \cite{indyk-wagner18:apx-nn-limited-space}, can further reduce the space at the cost of slower query, i.e.\ reducing the power of $\frac{\log(n)}{\epsilon\delta}$ in space complexity.
\end{remark}

\subsubsection{Space and Query Complexity}
Next, we argue the space and query complexity.
The main result in this section is that for any set $C$ of $n$ centers the sum of probabilities $\sum_{b\in [d]} p^{(b)}$ is upper bounded by $n$. The techniques used to obtain the bound here is linear algebraic in contrast to the more combinatorial argument given in the $\ell_1$ case. 

\begin{claim}
    \[
    1\leq \sum_{b \in [d]} p^{(b)} = \sum_{b \in [d]} \max_{i\neq j}\frac{|c_i^{(b)} - c_j^{(b)}|^2}{\|c_i - c_j\|_2^2} \leq n.
    \] 
\end{claim}


\begin{proof}
    The argument for the lower bound on $\sum_{b\in [d]} p^{(b)}$ is the following. Fix arbitrary $i_1, j_1 \in [n]$, such that $\|c_{i_1} - c_{j_1}\|_2 \neq 0$. $\sum_{b\in [d]} p^{(b)} \geq \sum_{b\in [d]} \frac{\left|c_{i_1}^{(b)} - c_{j_1}^{(b)}\right|^2}{\|c_{i_1} - c_{j_1}\|_2^2} = 1$.

    Next, we show the upper bound on $\sum_{b\in [d]} p^{(b)}$. 
Let $C \in \R^{n\times d}$ denote a matrix of the $n$ input points. Assume for simplicity that there is no repetition of points and  that $\texttt{rank}(C) = n$. Let the singular value decomposition (SVD) of $C$ be $U\Sigma V^\transpose$, where $U \in \R^{n \times n}, \Sigma \in \R^{n \times d}, V \in \R^{d \times d}$. We use $u_i$ (and $v_i$) to denote the $i$-th column of $U$ (and $V$), and $\sigma_i$ to denote the $i$-th singular value.

    We prove that for each $b\in [d]$, 
    \begin{equation}\label{eq:math-program-l2-b}
        p^{(b)} \leq \sum_{k\in[n] } (V_{b,k})^2.
    \end{equation}
    This would imply that $\sum_{b \in [d]} p^{(b)} \leq \sum_{b \in [d], k\in[n]} (V_{b,k})^2 = \sum_{i\in [n]} \|v_k\|_2^2 = n,$ which proves our claim. 

    To prove \eqref{eq:math-program-l2-b}, it suffices to prove that for each $b\in[d], i,j\in [n], i\neq j$:
    \begin{equation}\label{eq:math-program-l2-bij}
        \frac{|c_i^{(b)} - c_j^{(b)}|^2}{\|c_i - c_j\|_2^2} \leq \sum_{k\in[n] } (V_{b,k})^2.
    \end{equation}
    %Now we prove \eqref{eq:math-program-l2-bij}.

    We know from the SVD decomposition that 
    \[
    C = \sigma_1 u_1 v_1^\transpose + \sigma_2 u_2 v_2^\transpose + \cdots + \sigma_n u_n v_n^\transpose.
    \]
    Now, for each $i\in[n]$
    \[
    c_i = C_{i, \cdot} = \sigma_1 U_{i,1} v_1^\transpose + \sigma_2 U_{i,2} v_2^\transpose + \cdots + \sigma_n U_{i,n} v_n^\transpose.
    \]
    %Let's rewrite LHS from SVD perspective:
    The above implies that:
    \begin{align*}
        |c_i^{(b)} - c_j^{(b)}|^2 &= ((\sigma_1 U_{i,1} V_{1,b} + \cdots + \sigma_n U_{i,n} V_{n,b}) - (\sigma_1 U_{j,1} V_{1,b} + \cdots + \sigma_n U_{j,n} V_{n,b}))^2 \\
        &= (\sigma_1 V_{1,b} (U_{i,1} - U_{j,1}) + \cdots + \sigma_n V_{n,b} (U_{i,n} - U_{j,n}))^2
    \end{align*}
    \begin{align*}
        \|c_i - c_j\|_2^2 &= \|C_{i,\cdot} - C_{j, \cdot}\|_2^2 \\
        &= \|\sigma_1 (U_{i,1} - U_{j,1})v_1^\transpose + \sigma_2 (U_{i,2} - U_{j,2})v_2^\transpose + \cdots + \sigma_n (U_{i,n}-U_{j,n}) v_n^\transpose \|_2^2  \\
        &= (\sigma_1 (U_{i,1} - U_{j,1}))^2 + (\sigma_2 (U_{i,2} - U_{j,2}))^2 + \cdots + (\sigma_n (U_{i,n}-U_{j,n}))^2 
    \end{align*}
    The last equality follows from the fact that $V$ is orthonormal.

    Finally, using Cauchy-Schwarz inequality, 
        \begin{align*}
            \left((\sigma_1 (U_{i,1} - U_{j,1}))^2 + \cdots + (\sigma_n (U_{i,n}-U_{j,n}))^2\right) \left(\sum_{k\in[n] } (V_{b,k})^2\right) \\
            \geq (\sigma_1 V_{1,b} (U_{i,1} - U_{j,1}) + \cdots + \sigma_n V_{n,b} (U_{i,n} - U_{j,n}))^2
        \end{align*}


        which proves \eqref{eq:math-program-l2-bij}.
\end{proof}
The proof of the following claim is analogous to the proof of~\cref{clm:I-size-upperbound-l1} and is omitted for succinctness.
\begin{claim}\label{clm:I-size-upperbound-l2}
    With probability $1-\delta'$, $|I| \leq 2Tn$.    
\end{claim}
\begin{comment}
