 Using union bound, the success probability of the data structure is at least $1-4\delta' = 1-\delta$.



\section{\texorpdfstring{$O(1)$}{O(1)}-Approximate Sublinear Representation of Clusterings}\label{sec:expected-apx}

In this section, we show a data structure with near-linear space and query complexity for approximate nearest neighbor under $\ell_1$ and $\ell_2$ metrics, whose approximation ratio is constant in expectation.

\begin{theorem}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in [-\Delta, \Delta]^d$ equipped with $\ell_1$ or $\ell_2$ metric. We can efficiently construct a randomized data structure such that for any query point $q\in [-\Delta,\Delta]^d$ the following conditions hold. (i) The data structure reads $O(n \polylog(n,d,\Delta)/(\epsilon^3))$ coordinates of $q$. (ii) It returns $i\in [n]$ where $c_i$ is a $(8+\epsilon)$-approximate nearest neighbor of $q$ in $C$ in expectation. (iii) The data structure has a size of $O(n \polylog(n,d,\Delta)/(\epsilon^3))$ words.
\end{theorem}
\begin{definition}[Cost of clustering]
    Consider a set $C=\{c_1, \dots, c_k\}$ of $k$ centers, and a set $P$ of points in $\R^d$ equipped with $\ell_p$-metric. The cost of $C$ w.r.t. partition $\sigma:P\rightarrow [k]$ is $\mathsf{cost}_p(C,P,\sigma) = \sum_{q\in P} \|q-\sigma(q)\|_p^p$. The cost $\mathsf{cost}_p(C,P)=\sum_{q\in P} \min_{c_i\in C}\|q-c_i\|_p^p$ of $C$ is defined as the minimum cost of any partitioning. We call $\mathsf{cost}_1(C,P)$ the \emph{$k$-Median} cost and $\mathsf{cost}_2(C,P)$ the \emph{$k$-Means} cost of $C$, respectively.
\end{definition}

\begin{corollary}
    Consider a set $C$ of $k$ centers $c_1, \dots, c_k \in [-\Delta, \Delta]^d$ equipped with $\ell_p$ metric ($p=1,2$). We can efficiently construct a randomized data structure such that for any set $P \subset [-\Delta,\Delta]^d$ of points the following conditions hold. (i) The data structure reads $O(k \polylog(k,d,\Delta)/(\epsilon^3))$ coordinates of $P$. (ii) It returns a partition $\sigma:P\rightarrow [k]$ (iii) $\mathsf{cost}_p(C,P,\sigma) \leq O(1) \mathsf{cost}_p(C, P)$.
    (iv) The data structure has a size of $O(k \polylog(k,d,\Delta)/(\epsilon^3))$ words.
\end{corollary}

Here we only show the analysis for $\ell_1$ metric, and the analysis for $\ell_2$ metric is similar.

\Cref{alg:expected-l1} describes the data structure that achieves the above guarantees. It is very similar to the data structure in \Cref{sec:l1samplereuse}. We obtain \Cref{alg:expected-l1} from \Cref{sec:l1samplereuse} essentially by restricting the points to $[-\Delta, \Delta]^d$. To be self-contained, we restate the whole algorithm.

\begin{algorithm}[htp]\label{alg:expected-l1}
    \caption{An approximate nearest neighbor data structure for $n$ points in $[-\Delta,\Delta]^d$ for $\ell_1$ metric.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKwProg{comparator}{$E$}{}{}
    \SetKw{store}{store}
    \preprocessing{$(\Delta, C, \epsilon)$\tcp*[f]{Inputs: $\Delta \in \mathbb{N}, C=\{c_1, \dots, c_n\}\subseteq [-\Delta,\Delta]^d, \epsilon \in (0, \frac{1}{4})$}}{
        % Let $\epsilon \leftarrow \epsilon'/\log \log n$ and $\delta \leftarrow \delta' / \Theta(n \log \log n)$\;
        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (n)\log(\Delta d)/(\epsilon^3))$\;
        % \footnote{According to Theorem \ref{theorem:Lp-NN}, it should be $O(\log(1/\delta)/\epsilon^3)$, but we can achieve a better bound of $O(\log(1/\delta)/\epsilon^2)$  by using $0\leq X_t, Y_t\leq 1$, instead of using $0\leq X_t, Y_t\leq 1/\epsilon$ in the proof. }

        \For{$t\in [T]$}{
            \For{$b\in [d]$}{
                Add $b$ to $I$ with probability  $p^{(b)}\triangleq \max_{(i,j)\in {\binom{n}{2}}} \frac{\left|c_i^{(b)} - c_j^{(b)}\right|}{\|c_i- c_j\|_1}$\;
            }
        }
        Let $R=\{r_1, r_2, \dots, r_n\}\subseteq \R^{I}$, where for $i \in [n], b \in I$, we have $r_i^{(b)} = c_i^{(b)} / p^{(b)}$\;
        % \tcp{Apply the $l_1$ dimension reduction $(M, F)$ by \cite{indyk06:l1-dimension-reduction} to $R$. It guarantees that $\forall (i,j)\in {n \choose 2}, F(Mr_i, Mr_j) \in [1-\epsilon\delta/100, 1+\epsilon\delta/100] \|r_i- r_j\|_1$ with probability $1-\delta/4$.}
        Let $m \leftarrow O(\log(n)\log(\Delta d)/(\epsilon^2))$\;
        Sample $M\in \mathbb{R}^{[m] \times I}$, where each entry of $M$ follows the Cauchy distribution, whose density function is $c(x) = \frac{1}{\pi(1+x^2)}$. 
        Notice that $M(\cdot)\colon\mathbb{R}^{I} \rightarrow \mathbb{R}^m$ is an oblivious linear mapping \cite{indyk06:l1-dimension-reduction}\;


        \store{$I$, $M(R) = \{Mr_i|i\in [n]\}$, $\{p^{(b)}| b\in I\}$, $M$ }
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in [-\Delta,\Delta]^d$}}{
        Query $q^{(b)}, \forall b\in I$\;
        Let $u\in \mathbb{R}^{I}$, where $\forall b \in I, u^{(b)} = q^{(b)} / p^{(b)}$\;
        Let $F((x_1, \dots, x_m), (y_1, \dots, y_m)) \coloneq \mathsf{median}(|x_1-y_1|, \dots, |x_m- y_m|)$\;
        Let $\hat{i} = \argmin_{i\in [n]} F(Mr_i, Mu)$\;
        \Return{$\hat{i}$}
    }
\end{algorithm}


Let $\Gamma=\dist(c_{\hat{i}},q)/\dist(c_{i^*},q)$ be the random variable that describes the quality of the solution $\hat{i}$ returned by the algorithm compared to the optimal solution $i^*$. Note that $\hat{i}$ is also a random variable. 

We show that in expectation the algorithm outputs an $O(1)$-nearest neighbor.

\begin{theorem}\label{thm:expectedthm}
$\mathbb{E}[\Gamma] = O(1)$.
\end{theorem}

In the following lemma, we bound the probability of the event that the dimension reduction preserves the distances well. It is a direct consequence of \Cref{thm:indyk06} by plugging in $\delta=1/(4\Delta dn)$ and applying the union bound.   

Let $G_1$ be the event that $F(Mr_i,Mu)\in [1-\eps/2,1+\eps/2]\|r_i-u\|_1$ for all centers $c_i$. 




\begin{lemma}\label{lem:jlfails}
    It holds that $\mathbb{P}[G_1] \ge 1- \epsilon/(4\Delta d )$
\end{lemma}

The definitions of good and bad regions in this case are similar to the ones in \cref{sec:l1samplereuse} except for the specific parameters. We define them in the following for completeness.

%We define the good region and the bad region from \cref{sec:l1samplereuse} again because in \Cref{alg:expected-l1} there is no parameter $\delta$ that the regions can depend on. Thus, the definition below is the same as in \cref{sec:l1samplereuse} but we fix $\delta=1$. 

\begin{definition}[Good and bad regions]
    Consider two points $c_1, c_2\in \R^d$, and a query point $q\in\R^d$. We define the good region $\Good(c_1, c_2, q)$ w.r.t.\ $(c_1,c_2,q)$ as $$\{z\in [d] \mid\min\{c_1^{(z)}, c_2^{(z)}\} - \frac{8}{\epsilon } |c_1^{(z)} - c_2^{(z)}| \leq q^{(z)} \leq \max\{c_1^{(z)}, c_2^{(z)}\} + \frac{8}{\epsilon } |c_1^{(z)} - c_2^{(z)}|\}$$. We define the bad region w.r.t.\ $(c_1,c_2,q)$ as $\Bad(c_1, c_2, q) = [d]\setminus \Good(c_1, c_2, q)$. When there is no ambiguity, we use $\Good$ for $\Good(c_1, c_2, q)$, and $\Bad$ for $\Bad(c_1, c_2, q)$. 
\end{definition}

Let $G_2$ be the event that $\dist_\Good(r_i, u) \approx_\epsilon T\cdot \dist_\Good(c_i, q)$ for all centers $c_i$ such that $(\|c_i- q\|_1)/(\|c_{i^*}-q\|_1)\geq 1+\epsilon$. 
\begin{lemma}\label{lem:G2}
    $\mathbb{P}[G_2] \ge 1-\epsilon/(4\Delta d)$
\end{lemma}

\begin{proof}
Let $c_i\ne c_{i^*}$ be an arbitrary center such that $(\|c_i- q\|_1)/(\|c_{i^*}-q\|_1)\geq 1+\epsilon$.    
In the algorithm, we construct $\{r_i\mid i\in [n]\}$ and $u$ through sampling a multiset $I$. To analyze how the data structure samples $I$ in the preprocessing, we define the following random variable $\forall t\in [T], z\in \Good$
    \[P_{t, z} =  \begin{cases} 
      \frac{|q^{(z)} - c_i^{(z)}|}{p^{(z)} }, & w.p.\; p^{(z)},\hspace{0.95cm}\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we do not add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   In the rest of the proof, we use $\E[\sum_{z\in \Good} P_{t,z}]$ without specifying $t\in [T]$, because they have the same value for all $t\in [T]$.
   We obtain the following four observations by the same argument as in the proof of \cref{lemma:chernoff_for_good_l1}.
   \begin{itemize}
       \item $\sum_{t\in [T],z\in \Good} P_{t,z} = \dist_\Good(r_i, u)$.
       \item $\forall t\in [T], z\in \Good$, $0 \leq P_{t,z} \leq \left(1+\frac{8}{\epsilon}\right) \|c_i - c_{i^*}\|_1$.
        \item  $\E[\sum_{z\in \Good} P_{t,z}] = \dist_{\Good}(c_i, q)$.
        \item $\E[\sum_{z\in \Good}P_{t,z}] \geq \frac{1}{2} \dist_{\Good}(c_i, c_{i^*})$.
   \end{itemize}

     Using Chernoff bound, 
    \begin{align*}
    &\Pr\left[\left|\sum_{t\in [T], z\in \Good} P_{t,z} - \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in \Good} P_{t,z}\right]\right] \\
    \leq & 2\exp\left(-\frac{\epsilon_2^2 T \E[\sum_{z\in [d]} P_{t,z}]}{3(1+\frac{8}{\epsilon}) \|c_i - c_{i^*}\|_1}\right) \\
    = & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{8}{\epsilon})} \frac{\dist_{\Good}(c_i, q)}{\dist_{\Good}(c_i, c_{i^*})} \frac{\dist_{\Good}(c_i, c_{i^*})}{\|c_i - c_{i^*}\|_1}\right) \\
    \leq & 2\exp\left(-\frac{\epsilon_2^2 T }{3(1+\frac{8}{\epsilon})} \cdot \frac12 \cdot \frac{13}{16}\right) \leq \frac{1}{2\Delta n},
    \end{align*}
    by choosing 
    $T = \Theta(\frac{\log(n\Delta )}{\epsilon^3} )$. Note that the second last inequality above follows from \cref{lemma:good-region-is-large-l1}.

    We conclude the lemma by union bound over all $c_i\ne c_{i^*}$ such that $(\|c_i- q\|_1)/(\|c_{i^*}-q\|_1)\geq 1+\epsilon$.
\end{proof}

Let $G = G_1 \wedge G_2$. \Cref{lem:jlfails,lem:G2}, together with union bound gives the following.

\begin{lemma}\label{lem:goodevent}
    $\mathbb{P}[G] \ge 1-\epsilon/(2\Delta d)$.
\end{lemma}


Let $\Lambda = \dist(r_{i^*},u)/(T\cdot\dist(c_{i^*},q))$ be the random variable that describes how well the coordinate selection preserves the distance from the query $q$ to its nearest neighbor $c_{i^*}$.
Let $L$ describe the set of all possible values $\Lambda$ could take over all possible random outcomes of the algorithm. Note that it is finite since there are only finitely many outcomes for the multiset~$I$.
 For $\lambda \in L$, we define $N_\lambda = \{i\in [n] \mid \dist(c_i,q) \le 4\max\{ \lambda,1\} \dist(c_{i^*},q)\}$ and $F_\lambda = \{i\in [n] \mid \dist(c_i,q) > 4\max\{ \lambda,1\}\dist(c_{i^*},q) \}$. For $i\in N_\lambda$ we call $c_i$ $\lambda$-near. Accordingly, we call $c_i$ $\lambda$-far if $i\in F_\lambda$.


We bound the probability of the event that  the distance of ``far'' centers is close to the distance of the nearest neighbor after the coordinate selection.
\begin{lemma}\label{lem:coordinateselectionfails}
    Let $\lambda \in L$. Let $c_i$ be an arbitrary $\lambda$-far center (i.e.\ $i\in F_\lambda$). If event $G$ holds and $\Lambda = \lambda$, then $\dist(r_{i},u)> (1+\epsilon)^2 \dist(r_{i^*},u)$. 
\end{lemma}
\begin{proof}
    If $G$ holds, then $\dist_\Good(r_i, u) \approx_\epsilon T\cdot\dist_\Good(c_i, q)$.
    From the definition of bad region, we have 
    \begin{itemize}
        \item $\dist_\Bad(r_i, u) \approx_\epsilon \dist_\Bad(r_{i^*}, u)$
        \item $\dist_\Bad(c_i, q) \approx_\epsilon \dist_\Bad(c_{i^*}, q)$
    \end{itemize}

    Since $i\in F_\lambda$, we know $\frac{\|c_i - q\|_1}{\|c_{i^*} - q\|_1} \geq 4\max\{1,\lambda\}$. By separating coordinates into good and bad regions, we have $\frac{\dist_\Good(c_i, q) + \dist_\Bad(c_i, q)}{\dist_\Good(c_{i^*}, q) + \dist_\Bad(c_{i^*}, q)} \geq 4\max\{1,\lambda\}$. Subtracting both sides by $(1+\epsilon)$ gives $$\frac{\dist_\Good(c_i, q) + \dist_\Bad(c_i, q) - (1+\epsilon)\cdot\left(\dist_\Good(c_{i^*}, q) + \dist_\Bad(c_{i^*}, q)\right)}{\dist_\Good(c_{i^*}, q) + \dist_\Bad(c_{i^*}, q)} \geq 2\max\{1,\lambda\}.$$
    Since we know that $\dist_\Bad(c_i, q) - (1+\epsilon) \dist_\Bad(c_{i^*}, q) \leq 0$, we have $\frac{\dist_\Good(c_i, q)}{\dist_\Good(c_{i^*}, q) + \dist_\Bad(c_{i^*}, q)} \geq 2\max\{1,\lambda\}$, which is $\frac{\dist_\Good(c_i, q)}{\|c_{i^*} - q\|_1} \geq 2\max\{1,\lambda\}$. Since $\dist_\Good(r_i, u) \approx_\epsilon T\cdot\dist_\Good(c_i,q)$, and $\|r_{i^*} - u\|_1 = \lambda\cdot T\cdot\|c_{i^*}-q\|_1$, we have $\frac{\dist_\Good(r_i, u)}{\|r_{i^*} - u\|_1} \geq \frac{2\max\{1,\lambda\}}{(1+\epsilon)\lambda}$. Thus $\frac{\|r_i - u\|_1}{\|r_{i^*} - u\|_1} \geq 2/(1+\epsilon) \geq (1+\epsilon)^2$.
\end{proof}

We next bound the probability that the algorithm outputs a far center.
\begin{lemma}\label{lem:badevent}
Let $\lambda \in L$. Let $c_i$ be an arbitrary $\lambda$-far center (i.e.\ $i\in F_\lambda$). If event $G$ holds and $\Lambda =\lambda$, then $\hat{i}\ne i$. 
\end{lemma}
\begin{proof}
By \Cref{lem:coordinateselectionfails} it follows that $\dist(r_{i},u)> (1+\epsilon)^2 \dist(r_{i^*},u)$. Since the event $G$ contains the event $G_1$ it follows that $F(Mr_i,Mu) > F(Mr_{i^*},Mu)$. Thus, the algorithm does not output $i$.
\end{proof}
We show that the approximation ratio of the output is linearly bounded by how well the algorithm approximates the distance to the closest center. 
\begin{lemma}\label{lem:linearina}
For $\lambda \in L$ it holds that 
$\mathbb{E}[\Gamma\mid \Lambda=\lambda\wedge G] \le 4\max\{\lambda,1\}$
\end{lemma}
\begin{proof}
The idea is to distinguish between the expected cost for returning ``near'' and ``far'' centers.
\begin{align*}
\mathbb{E}[\Gamma\mid \Lambda=\lambda\wedge G]&\le \mathbb{P}[\hat{i}\in N_\lambda\mid \Lambda = \lambda\wedge G]4\max\{\lambda,1\}+\mathbb{P}[\hat{i}\in F_\lambda\mid \Lambda =\lambda\wedge G]2\Delta d\\
&\le 4\max\{\lambda,1\} + \mathbb{P}[\hat{i}\in F_\lambda \mid \Lambda =\lambda\wedge G]2\Delta d\\
&\le 4\max\{\lambda,1\}
\end{align*}
The last inequality follows from \Cref{lem:badevent}.
\end{proof}

We use \Cref{lem:linearina} to conclude the proof for the constant approximation factor. 
\begin{proof}[Proof of \ref{thm:expectedthm}]
\begin{align}
\mathbb{E}[\Gamma] &=\mathbb{E}[\Gamma\mid \overline{G}]\mathbb{P}[\overline{G}]+\mathbb{E}[\Gamma\mid G]\mathbb{P}[G]\nonumber\\
&\le 2\Delta d \frac{\epsilon}{2\Delta d}+\mathbb{P}[G]\mathbb{E}[\Gamma\mid G]\label{eq:maxdist}\\
&= \epsilon+ \mathbb{P}[G]\sum_{\lambda\in L}\mathbb{E}[\Gamma\mid \Lambda=\lambda\wedge G]\mathbb{P}[\Lambda = \lambda\mid G]\nonumber\\
&\le \epsilon + \sum_{\lambda \in L}\mathbb{E}[\Gamma\mid \Lambda = \lambda\wedge G]\mathbb{P}[\Lambda=\lambda]\label{eq:removecondition}\\
&\le \epsilon + \sum_{\lambda \in L}4\max\{\lambda,1\}\mathbb{P}[\Lambda=\lambda]\label{eq:linearina}\\
&\le \epsilon + \sum_{\lambda \in L}4(\lambda+1)\mathbb{P}[\Lambda = \lambda]\nonumber\\
&\le \epsilon + 4\sum_{\lambda \in L} \lambda\mathbb{P}[\Lambda =\lambda] + 4\sum_{\lambda \in L} \mathbb{P}[\Lambda=\lambda]\nonumber\\
&\le \epsilon + 4\mathbb{E}[\Lambda] + 4 \leq 8+\epsilon\label{eq:lastline}
\end{align}
In Line~\ref{eq:maxdist} we use the fact that the maximal distance inside the $[-\Delta,\Delta]^d$ grid is $2\Delta d$ and \Cref{lem:goodevent}. In Line~\ref{eq:removecondition} we use the fact $\mathbb{P}[\Lambda=\lambda\mid G] \le \mathbb{P}[\Lambda =\lambda]/\mathbb{P}[G]$. In Line~\ref{eq:linearina} we use \cref{lem:linearina}. In Line~\ref{eq:lastline} we use the fact that $\E[\Lambda]=1$.
\end{proof}

It remains to show that with high probability the data structure does not violate the space and query complexity. The analysis is analogous to \cref{sec:l1-space-query-analysis}.
\begin{claim}\label{clm:I-size-upperbound-l1expected}
    With probability $1-1/(nd\Delta)$, we have $|I| \leq 2Tn$.    
\end{claim}
\begin{proof}
   We define $X_{t,z}$ for $t \in [T], z \in [d]$ to be the indicator random variable for the event that we add $z$ to $I$ at iteration $t$. Note that $\Pr[X_{t,z} = 1] = p^{(z)}$.
   % we define the following random variables $\forall t\in [T], z\in [d]$,
    %\begin{equation*}
     %   X_{t, z} =  \begin{cases} 
     % 1, & w.p.\; p^{(z)},\quad\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
     % 0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we don't add $z$ to $I$ at iteration $t$.}
      %\end{cases}
    %\end{equation*}
    We can see that $|I| = \sum_{t\in[T], z\in[d]} X_{t,z}$.
    Hence, $\E[|I|] = \sum_{t\in[T], z\in[d]} p^{(z)} \leq T\cdot \sum_{b \in [d]} p^{(b)} \leq T\cdot n$, where the last inequality follows from \cref{lemma:math-program}. Similarly, we can see that 
    $\E[|I|] \geq T$.

    Using Chernoff bound, we have 
    \begin{equation*}
        \Pr\left[|I| - \E\left[|I|\right] \geq \E\left[|I|\right]\right] \leq \exp (-\E[|I|]/3) \leq \exp(-T/3) \leq 1/(nd\Delta).
    \end{equation*}
    Thus, with probability $1/(nd\Delta)$, we have $|I| \leq 2 E[|I|] \leq 2Tn$.
\end{proof}

\begin{lemma}
    With high probability the data structure has $O(n \polylog(n,d,\Delta)/(\epsilon^3))$ space and $O(n \polylog(n,d,\Delta)/(\epsilon^3))$ query complexity.
\end{lemma}
\begin{proof}
    By \cref{clm:I-size-upperbound-l1expected}, we have that the number of coordinates of $q$ that we query is $|I| = O(Tn) = O(\frac{n\log(n)\log(\Delta d)}{\epsilon^3})$. Next we analyze the space complexity of the data structure. Matrix $M$ is of wordsize $O(m|I|)$, $M(R)$ is of wordsize $O(mn)$, $I$ is of wordsize $O(|I| \log(d))$. Thus the space complexity of the our data strcuture is $O(m|I| + mn +|I|\log(d)) = O(n\polylog(n,d,\Delta)/(\epsilon^3))$ wordsize.
\end{proof}



\section{Data Structure with \texorpdfstring{$\tilde{O}(n^2)$}{near-quadratic} Space for General \texorpdfstring{$\ell_p$}{lp} Metrics}\label{sec:point-reduction}

In this section, we describe our data structure with $O(n^2 \log(n/\delta) \log(d) (\log\log n)^p/\epsilon^{p+2})$ space and $O(n \log (n/\delta) (\log\log n)^p/\epsilon^{p+2})$ query time for the approximate nearest neighbor problem for the $\ell_p$ metric for any $p$ and prove~\cref{theorem:Lp-NN}. 

\begin{theorem}\label{theorem:Lp-NN}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in \mathbb{R}^d$ with $\ell_p$ metric, $1\leq p < \infty$. Given $0 < \epsilon < 1/(4p)$, we can construct a data structure such that the data structure is of word size $O(n^2 \log(n/\delta) \log(d)(\log\log n)^p/\epsilon^{p+2})$, and for any query $q\in R^d$, the following conditions hold. (i) The data structure reads $O(n \log (n/\delta)(\log\log n)^p/\epsilon^{p+2})$ coordinates of $q$. (ii) With probability $1-\delta$, it returns $i$ where $c_i$ is a $(1+\epsilon)$-approximate nearest neighbor of $q$ from $C$.
\end{theorem}

\subsection{A Data Structure for Two Input Points}\label{sec:2-center-lp}

We start with a data structure (see \cref{alg:alg-2points}) answering approximate nearest neighbor queries for the case of $2$ points, say $a$ and $b$. 
It generates \cref{thm:warm-up-l1}, and the main differences are: (1) It works for $\ell_p$ metric. (2) It explicitly use truncation to remove the bounding box assumption.

\begin{lemma}(2-point comparator, $\ell_p$)\label{lem:lp-2-point-comparator}
    Given $0<\epsilon<1/(4p)$, there exists a data structure $A_{(a,b)}$ for any two points $a, b \in \R^d$, such that for any query $q\in \R^d$, the following conditions hold: (i) $A_{(a,b)}$ is of wordsize $O(\log (1/\delta) \log (d)2^p/\epsilon^{p+2})$. (ii) $A_{(a,b)}$ reads $O( \log (1/\delta)2^p/\epsilon^{p+2})$ coordinates of $q$. (iii) $A_{(a,b)}$ returns 
    a $(1+\epsilon)$-approximate nearest neighbor of $q$ in $\ell_p$ metric with probability $1-\delta$.
\end{lemma}


\begin{algorithm}[htbp]\label{alg:alg-2points}
    \caption{An approximate nearest neighbor data structure $A_{(a,b)}$ for two points $a,b\in \R^d$.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKw{store}{store}
    \preprocessing{$(a,b, \epsilon, \delta)$\tcp*[f]{Inputs: $a,b\in \R^d, \epsilon \in (0, \frac{1}{4p}), \delta\in (0,1)$}}{
        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (1/\delta)2^p/\epsilon^{p+2})$\;
        \For{$t\in [T]$}{
            Sample $i_t\in [d]$, where $
        \forall i\in [d], \Pr[i_t = i] = \frac{|b^{(i)} - a^{(i)}|^p}{\sum_{j\in [d]} |b^{(j)} - a^{(j)}|^p}$\;
        }
        \store{$I, a^{(I)}, b^{(I)}$}.
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in \R^d$}}{
        \For{$i\in I$}{
            Query $q$ on coordinate ${i}$, i.e. $q^{(i)}$\; 
            \If{$p>1$ }{
                Let $m(\epsilon, p) = (1+\epsilon)^{p/(p-1)}-1$\;
                $l^{(i)} \leftarrow -\frac{1}{m(\epsilon, p)}(b^{(i)} - a^{(i)}) + a^{(i)}$ and $u^{(i)} \leftarrow (1+\frac{1}{m(\epsilon, p)})(b^{(i)} - a^{(i)})+a^{(i)}$\; \label{line:def-lu-1}
            }
            \Else($p=1$){
                $l^{(i)} \leftarrow a^{(i)}$ and $u^{(i)} \leftarrow b^{(i)}$\; \label{line:def-lu-2}
            }
            Truncate $q'^{(i)} \leftarrow \trunc_{\{l^{(i)}, u^{(i)}\}}(q^{(i)})$\;
            Let $X_t = \frac{|q'^{(i_t)} - a^{(i_t)}|^p}{|b^{(i_t)} - a^{(i_t)}|^p}, Y_t = \frac{|b^{(i_t)} - q'^{(i_t)}|^p}{|b^{(i_t)} - a^{(i_t)}|^p}$\;
        }
        \lIf{$\sum_{t\in [T]} X_t \leq \sum_{t\in [T]} Y_t$}{\Return{$a$} as the approximate nearest neighbor}\lElse{\Return{$b$}}
    }
\end{algorithm}
\begin{proof}
    Assume w.l.o.g.\ that $q\notin \{a,b\}$ to avoid the ratio $\frac{\dist(a,q)}{\dist(b,q)}$ to be $\infty$, and our data structure works without this assumption. 
    The idea is to determine if the ratio of distances $\frac{\dist(a,q)}{\dist(b,q)}$ is greater or smaller than $1$. To achieve this, we \emph{truncate} $q$ to $q'$ so that if
    %to bound the random variables $X_t, Y_t$, disturbing the ratio in a good way, i.e. if 
    $1+\epsilon \leq \frac{\dist(a,q)}{\dist(b,q)}$, then $\frac{\dist(a,q)}{\dist(b,q)} \leq \frac{\dist(a,q')}{\dist(b,q')}$, making it potentially easier to distinguish between $a$ and $b$ based on their distances to $q'$. %, making it easier to distinguish. 

    % If the ratio $\frac{\dist(a,q')}{\dist(b,q')}$ lies in $[\frac{1}{8(1+\epsilon/4)^{9p}}, 8(1+\epsilon/4)^{9p}]$ \zihang{change params}, we give a $(1+\epsilon)$-approximation for the ratio; otherwise, we can distinguish whether the ratio is in $(0, \frac{1}{8(1+\epsilon/4)^{9p}})$ or in $(8(1+\epsilon/4)^{9p}, \infty)$, which suffices to choose the nearest neighbor. 

    In the following, we assume w.l.o.g.\ that $a = (0, 0, \dots, 0)$, $b = (b^{(1)}, b^{(2)}, \dots, b^{(d)})$, where $b^{(i)} \geq 0$. It is okay to make this assumption because we can flip and shift the coordinates. Let $q = (q^{(1)}, \dots, q^{(d)})$. In the rest of the proof, we use $A$ to denote $A_{(a,b)}$.
    \begin{definition}{(Truncate)}\label{def:truncation}
    For $l,u \in \R$, and $l< u$, 
            \begin{equation*}
                \trunc_{\{l,u\}}(x) = 
                \begin{cases}
                    l, & x \leq l,\\
                    x, & l < x < u,\\
                    u, & x \geq u.
                \end{cases}
            \end{equation*}
\end{definition}

    % \paragraph{Preprocessing.} The preprocessing phase of $A$ is to sample a multiset of coordinates $I = \{i_1, i_2, \dots, i_T\}$, where $T = O( \log (1/\delta)2^p/\epsilon^{p+2})$, and each $i_t$ is sampled independently according to the following distribution:
