    % $q_i' = \trunc_{\{-\frac{1}{(1+\epsilon)^{p/(p-1)}-1}(b_i - a_i) + a_i, (1+\frac{1}{(1+\epsilon)^{p/(p-1)}-1})(b_i - a_i)+a_i\}}(q_{i})$. 
    % For $\ell_1$ metric, let $q'$ be a truncated point, where $q_i' = \trunc_{\{a_i, b_i\}}(q_i)$.

    If $\frac{\dist(a,q)}{\dist(b,q)} \geq (1+\epsilon)$, then 
    \begin{equation*}
        \frac{\dist(a,q)}{\dist(b,q)} \leq \frac{\dist(a,q')}{\dist(b,q')}.
    \end{equation*}
    If $\frac{\dist(a,q)}{\dist(b,q)} \leq 1/(1+\epsilon)$, then
    \begin{equation*}
        \frac{\dist(a,q)}{\dist(b,q)} \geq \frac{\dist(a,q')}{\dist(b,q')}.
    \end{equation*}

    \end{claim}

    This claim shows that if we can return a $(1+\epsilon)$-approximate nearest neighbor of $q'$, it would also be a $(1+\epsilon)$-approximate nearest neighbor of $q$. This is because, 
    \begin{itemize}
        \item If $\dist(a,q) > (1+\epsilon)\dist(b,q)$, then from above claim $\dist(a,q') > (1+\epsilon)\dist(b,q')$. Since it returns $(1+\epsilon)$-approximate nearest neighbor of $q'$, it must return $b$. This is the nearest neighbor for $q$.
        \item If $\frac{1}{1+\epsilon} \leq \frac{\dist(a,q)}{\dist(b,q)} \leq (1+\epsilon)$, then both $a$ and $b$ are $(1+\epsilon)$-approximation nearest neighbor. Thus it does not matter which one is returned.
        \item If If $\dist(a,q) < 1/(1+\epsilon)\dist(b,q)$, this is similar to the first case, and it must returns $a$.
    \end{itemize}

    Now let us prove that the data structure $A$ returns a $(1+\epsilon)$-approximate nearest neighbor of $q'$. 

    Assume that $\dist(a,q') \leq \dist(b,q')$, i.e. $a$ is the nearest neighbor of $q'$. Notice $(X_t)^{1/p} + (Y_t)^{1/p} \geq 1$ which gives $X_t + Y_t \geq \frac{1}{2^{p-1}}$, we have $\E[Y_t] \geq \frac{1}{2^p}.$ 
    Since $\E[X_t] = \dist^p(a,q')$ and $\E[Y_t] = \dist^p(b,q')$, we can use Chernoff bound to approximate $\dist(a,q')$ and $\dist(b,q')$.

    Let $s = \frac{1}{2^{p+2}} $.

    \noindent \underline{Case 1.} If $\E[X_t] \geq s$, using Chernoff bound, for $0<\epsilon_2 = p\epsilon/10 < 1$, we have 
    \begin{equation}\label{eq:chernoff-case1-x}
    \Pr\left[\left|\frac1T\sum_t X_t - \E[X_t]\right| \geq \epsilon_2 \E[X_t]\right] \leq 2\exp(-\frac{\epsilon_2^2 T \E[X_t]}{3(1+1/\epsilon)^p}) \leq \delta/2.
    \end{equation}
    by choosing 
    $T = \Theta( \frac{2^p}{p^2\epsilon^{p+2}}\log(1/\delta)) \geq \Theta((1+\frac{1}{\epsilon})^p \frac{1}{\epsilon_2^2} \frac{1}{s}\log(1/\delta)) $.

    Similarly for $Y_t$, using the same choice of $T$, since $\E[Y_t] \geq \frac{1}{2^p} \geq s$, $\Pr[\left|\frac1T\sum_t Y_t - \E[Y_t]\right| > \epsilon_2 \E[Y_t]] < \delta/2.$  

    By union bound, with probability $1-\delta$, we have 
    \begin{align}\label{eq:chernoff-case1}
    \begin{split}
        \frac{1}{T}\sum_t X_t &\in [1-\epsilon_2, 1+\epsilon_2] \E[X_t],\\
    \frac1T\sum_t Y_t &\in [1-\epsilon_2, 1+\epsilon_2] \E[Y_t].
    \end{split}
    \end{align}

    Recall that $a$ is the nearest neighbor of $q'$. If $\dist(b,q')/\dist(a,q') \geq 1+\epsilon$, 
    \begin{equation*}
        \frac{\sum Y_t}{\sum X_t} \geq \frac{1-\epsilon_2}{1+\epsilon_2} \frac{\E[Y_t]}{\E[X_t]} \geq \frac{1-\epsilon_2}{1+\epsilon_2} (1+\epsilon)^p \geq 1.
    \end{equation*}
    Thus $A_{(a,b)}$ will returns $a$ correctly.

    \noindent \underline{Case 2.} If $\E[X_t] < s$. Using Chernoff bound, we have 
    \begin{equation}
    \Pr\left[\left|\frac1T\sum_t X_t - \E[X_t]\right| > s\right] < 2\exp\left( -\frac{Ts}{3(1+1/\epsilon)^p}\right) \leq \delta/2. \label{eq:chernoff-case2-x}
    \end{equation}
    by choosing $T = \Theta( \frac{2^p}{p^2\epsilon^{p+2}}\log(1/\delta)) \geq \Theta(\frac{1}{s}(1+\epsilon)^p \log(1/\delta))$.

    For $Y_t$, since $\E[Y_t] \geq \frac{1}{2^p} \geq s$, $\Pr[\left|\frac1T\sum_t Y_t - \E[Y_t]\right| > \frac12 \E[Y_t]] < \delta/2.$ 

    By union bound, with probability $1-\delta$, we have 
    \begin{equation}\label{eq:chernoff-case2}
        \frac1T\sum_t X_t \leq 2s, \quad\frac1T\sum_t Y_t \in \left[\frac12, \frac32\right] E[Y_t].
    \end{equation}
    Since 
    \[
    \frac{\sum Y_t}{\sum X_t} \geq \frac{1/2 \E[Y_t]}{2s} \geq 1,
    \]
    $A$ will output $a$ with probability $(1-\delta)$.

    To conclude, we proved that $A$ outputs a $(1+\epsilon)$-approximate nearest neighbor of $q'$ with probability $1-\delta$, which is also a $(1+\epsilon)$-approximate nearest neighbor of $q$.

\end{proof}

\begin{proof}{(For Claim \ref{claim:truncate})}
    Recall our assumption that $a = \mathbbm{0}$ and $\forall i, b_i\geq 0 $. We prove that if $\dist(a,q)/\dist(b,q) \geq 1+\epsilon$, \[
    \frac{\dist(a,q)}{\dist(b,q)} \leq \frac{\dist(a,q')}{\dist(b,q')}. \]
    We first argue for the cases of $\ell_1$ and $\ell_2$ metrics to give some intuition, and then give a general proof for the $\ell_p$ metric.

    (1) For $\ell_1$, it is true, because $\dist(a,q) - \dist(a,q') = \dist(b,q) - \dist(b,q') \geq 0$. 
    \smallskip

