\subsection{An Alternate Data Structure for 2 Input Points}
\begin{algorithm}[htp]\label{alg:alternate-alg-2points}
    \caption{An alternate approximate nearest neighbor data structure $B_{(a,b)}$ for two points $a,b \in \R^d$.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKw{store}{store}
    \preprocessing{$(a,b, \epsilon, \delta)$\tcp*[f]{Inputs: $a,b\in \R^d, \epsilon \in (0, \frac{1}{4p}), \delta\in (0,1)$}}{
        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (1/\delta)2^p/\epsilon^{p+2})$\;
        \For{$t\in [T]$}{
            \For{$i\in [d]$}{
                Add $i$ to $I$ with probability  $p^{(i)} \geq \frac{|b_i - a_i|^p}{\sum_j |b_j - a_j|^p}$\;
            }
        }
        \store{$I, \{p^{(i)}|i\in I\}, a^{(I)}, b^{(I)}$ }
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in \R^d$}}{
        Initialize $x\leftarrow 0, y\leftarrow 0$\;
        \For{$i\in I$}{
            Query $q$ on coordinate ${i}$, i.e. $q_{i}$\;
            \If{$p>1$}{
                Let $m(\epsilon, p) = (1+\epsilon)^{p/(p-1)}-1$\;
                $l_i \leftarrow -\frac{1}{m(\epsilon, p)}(b_i - a_i) + a_i$ and $u_i \leftarrow (1+\frac{1}{m(\epsilon, p)})(b_i - a_i)+a_i$\;
            }
            \ElseIf{$p=1$}{
                $l_i \leftarrow a_i$ and $u_i \leftarrow b_i$
            }
            Truncate $q_{i}' \leftarrow \trunc_{\{l_i, u_i\}}(q_{i})$\;
            $x \leftarrow x+ \frac{|q_{i}' - a_{i}|^p}{p^{(i)}}, y \leftarrow y+ \frac{|b_{i} - q_{i}'|^p}{p^{(i)}}$\;
        }
        \lIf{$x\leq y$}{\Return{$a$} as the approximate nearest neighbor}\lElse{\Return{$b$}}
    }
\end{algorithm}
