\begin{lemma}
(Alternate Sampling)\label{claim:another-sampling}
    Let $a,b \in \R^d$ and $0<\epsilon<1/(4p)$, the data structure $B_{(a,b)}$ takes space $O(\log (1/\delta) \log (d)2^p/\epsilon^{p+2}(\sum_{i\in [d]} p^{(i)}))$. For any query $q\in \R^d$, $B_{(a,b)}$ reads $O( \log (1/\delta)2^p/\epsilon^{p+2} (\sum_{i\in [d]} p^{(i)}))$ coordinates of $q$,
    returns 
    a $(1+\epsilon)$-approximate nearest neighbor of $q$ in $\ell_p$ metric, and succeeds with probability $1-\delta$.
\end{lemma}
\begin{proof}
    To analyze how $B_{(a,b)}$ samples $I$ in the preprocessing, we define the following random variables $\forall t\in [T], z\in [d]$
    \[P_{t, z} =  \begin{cases} 
      \frac{|q_z' - a_z|^p}{p^{(z)} }, & w.p.\; p^{(z)},\quad\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we don't add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   \[Q_{t, z} =  \begin{cases} 
      \frac{|q_z' - b_z|^p}{p^{(z)} } , & w.p.\; p^{(z)},\quad\text{i.e. if we add $z$ to $I$ at iteration $t$.}\\
      0, & w.p.\; 1-p^{(z)}, \quad\text{i.e. if we don't add $z$ to $I$ at iteration $t$.}
   \end{cases}\]
   Notice that $x = \sum_{t,z} P_{t,z}$ and $y = \sum_{t,z} Q_{t,z}$.

    The idea is, in the proof of \cref{lem:lp-2-point-comparator}, we only used Chernoff bound to give concentration guarantees for $\sum_{t\in [T]} X_t$ and $\sum_{t\in [T]} Y_t$ (see \cref{eq:chernoff-case1-x,eq:chernoff-case2-x}). Since $\E[\sum_{t,z} P_{t,z}] = \|a-b\|_p^p \cdot \E[\sum_t X_t]$, and $P_{t,z}$ has the same range as $\|a-b\|_p^p X_t, \forall z\in [d]$  (similarly for $Q_{t,z}$ and $Y_t$), we can get similar guarantees for $\sum_{t,z} P_{t,z}$ and $\sum_{t,z} Q_{t,z}$ by Chernoff bound.

    We now present a more detailed proof. Let $q'$ be a truncated point where $q_{i}' = \trunc_{\{l_i, u_i\}}(q_{i})$, $ \forall i\in [d]$, where $l_i$ and $u_i$ are defined in \cref{alg:alternate-alg-2points}.  

    Observe that $\forall t\in [T], z\in [d]$,
    \begin{align*}
        0 \leq P_{t,z} \leq \frac{|q_z' - a_z|^p}{|b_z -a_z|^p } \cdot \|a-b\|_p^p \leq  (1+1/\epsilon)^{p} \|a-b\|_p^p.
    \end{align*}
    where the second inequality comes from ``oversampling'': $p^{(z)} \geq \frac{|a_z - b_z|^p}{\|a-b\|_p^p}$, and the third inequality comes from truncation (similar to \cref{eq:rv-bound}).
    By a similar argument, we have $0 \leq Q_{t,z}\leq (1+1/\epsilon)^{p} \|a-b\|_p^p$. 

    \cref{claim:truncate} shows that if we can return a $(1+\epsilon)$-approximate nearest neighbor of $q'$, it would also be a $(1+\epsilon)$-approximate nearest neighbor of $q$. 
    % This is because, 
    % \begin{itemize}
    %     \item If $\dist(a,q) > (1+\epsilon)\dist(b,q)$, then from above claim $\dist(a,q') > (1+\epsilon)\dist(b,q')$. Since it returns $(1+\epsilon)$-approximate nearest neighbor of $q'$, it must return $b$. This is the nearest neighbor for $q$.
    %     \item If $\frac{1}{1+\epsilon} \leq \frac{\dist(a,q)}{\dist(b,q)} \leq (1+\epsilon)$, then both $a$ and $b$ are $(1+\epsilon)$-approximation nearest neighbor. Thus it doesn't matter which one is returned.
    %     \item If If $\dist(a,q) < 1/(1+\epsilon)\dist(b,q)$, this is similar to the first case, and it must returns $a$.
    % \end{itemize}

    Let us prove that the data structure $B_{(a,b)}$ returns a $(1+\epsilon)$-approximate nearest neighbor of $q'$. 

    Assume w.o.l.g. that $\|a-q'\|_p \leq \|b-q'\|_p$, i.e. $a$ is the nearest neighbor of $q'$. Notice that $\forall t\in [T], \E[\sum_{z\in [d]} P_{t,z}] = \|a-b\|_p^p \|a-q'\|_p^p$ and $\E[\sum_{z\in [d]} Q_{t,z}] = \|a-b\|_p^p \|b-q'\|_p^p$. 
    Since $\forall t\in [T], \E[\sum_{z\in [d]} (P_{t,z} + Q_{t,z})] \geq \frac{1}{2^{p-1}} \|a-b\|_p^p$, we have $\E[\sum_{z\in [d]}Q_{t,z}] \geq \frac{1}{2^p} \|a-b\|_p^p.$ 
    Thus we can use Chernoff bound to approximate $\|a-q'\|_p^p$ and $\|b-q'\|_p^p$. In the rest of the proof, we use $\E[\sum_{z\in [d]} P_{t,z}]$ without specify which $t\in [T]$, because they have the same value for all $t\in [T]$. Let $s = \frac{1}{2^{p+2}} $. 

    \noindent \underline{Case 1.} If $\E[\sum_{z\in [d]} P_{t,z}] \geq s \|a-b\|_p^p$, using Chernoff bound, for $0<\epsilon_2 = p\epsilon/10 < 1$, we have 
    \begin{equation*}
    \Pr\left[\left|\sum_{t\in [T], z\in [d]} P_{t,z} - \E\left[\sum_{t\in [T], z\in [d]} P_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in [d]} P_{t,z}\right]\right] \leq 2\exp\left(-\frac{\epsilon_2^2 T \E[\sum_{z\in [d]} P_{t,z}]}{3(1+1/\epsilon)^p \|a-b\|_p^p}\right) \leq \delta/2.
    \end{equation*}
    by choosing 
    $T = \Theta( \frac{2^p}{p^2\epsilon^{p+2}}\log(1/\delta)) \geq \Theta((1+\frac{1}{\epsilon})^p \frac{1}{\epsilon_2^2} \frac{1}{s}\log(1/\delta)) $.

    Similarly for $Q_{t,z}$, using the same choice of $T$, since $\E[\sum_{z\in [d]}Q_{t,z}] \geq \frac{1}{2^p} \|a-b\|_p^p \geq \|a-b\|_p^p s$, we have $\Pr\left[\left|\sum_{t\in [T], z\in [d]} Q_{t,z} - \E\left[\sum_{t\in [T], z\in [d]} Q_{t,z}\right]\right| \geq \epsilon_2 \E\left[\sum_{t\in [T], z\in [d]} Q_{t,z}\right]\right] \leq \delta/2.$

    By union bound, with probability $1-\delta$, we have 
    \begin{align*}
    \begin{split}
        \frac{1}{T}\sum_{t\in [T],z\in [d]} P_{t,z} \in [1-\epsilon_2, 1+\epsilon_2] \E[\sum_{z\in [d]} P_{t,z}], \text{ and }
    \frac1T\sum_{t\in [T],z\in [d]} Q_{t,z} \in [1-\epsilon_2, 1+\epsilon_2] \E[\sum_{z\in [d]} Q_{t,z}].
    \end{split}
    \end{align*}

    Recall that $a$ is the nearest neighbor of $q'$. If $\|b-q'\|_p/\|a-q'\|_p \geq 1+\epsilon$, then
    \begin{equation*}
        \frac{\sum_{t\in [T],z\in [d]} Q_{t,z}}{\sum_{t\in [T],z\in [d]} P_{t,z}} \geq \frac{1-\epsilon_2}{1+\epsilon_2} \frac{\E[\sum_{z\in [d]} Q_{t,z}]}{\E[\sum_{z\in [d]} P_{t,z}]} \geq \frac{1-\epsilon_2}{1+\epsilon_2} (1+\epsilon)^p \geq 1.
    \end{equation*}
    Thus $B_{(a,b)}$ will returns $a$ correctly.

    \noindent \underline{Case 2.} If $\E[\sum_{z\in [d]} P_{t,z}] < s \|a-b\|_p^p$. Using Chernoff bound, we have 
    \begin{equation*}
    \Pr\left[\left|\frac1T\sum_{t\in [T],z\in [d]} P_{t,z} - \E[\sum_{z\in [d]} P_{t,z}]\right| > s \|a-b\|_p^p \right] < 2\exp\left( -\frac{Ts \|a-b\|_p^p}{3(1+1/\epsilon)^p \|a-b\|_p^p}\right) \leq \delta/2. 
    \end{equation*}
    by choosing $T = \Theta( \frac{2^p}{p^2\epsilon^{p+2}}\log(1/\delta)) \geq \Theta(\frac{1}{s}(1+\epsilon)^p \log(1/\delta))$.

    For $Q_{t,z}$, since $\E[\sum_{z\in [d]}Q_{t,z}] \geq \|a-b\|_p^p s$, we have $\Pr\left[\left|\sum_{t,z} Q_{t,z} - \E\left[\sum_{t,z} Q_{t,z}\right]\right| \geq \frac12 \E\left[\sum_{t,z} Q_{t,z}\right]\right] \leq \delta/2.$

    By union bound, with probability $1-\delta$, we have 
    \begin{equation*}
        \frac{1}{T}\sum_{t\in [T],z\in [d]} P_{t,z} \leq 2s \|a-b\|_p^p, \text{ and }\frac{1}{T}\sum_{t\in [T],z\in [d]} Q_{t,z} \in \left[\frac12, \frac32\right] \E[\sum_{z\in [d]} Q_{t,z}].
    \end{equation*}
    Since 
    \[
    \frac{\sum_{t\in [T], z\in [d]} Q_{t,z}}{\sum_{t\in [T], z\in [d]} P_{t,z}} \geq \frac{1/2 \E[\sum_{z\in [d]} Q_{t,z}]}{2s \|a-b\|_p^p} \geq 1,
    \]
    $B_{(a,b)}$ will output $a$ with probability $(1-\delta)$.

    To conclude, we proved that $B_{(a,b)}$ outputs a $(1+\epsilon)$-approximate nearest neighbor of $q'$ with probability $1-\delta$, which is also a $(1+\epsilon)$-approximate nearest neighbor of $q$.

\end{proof}
