\section{Implication for Range Search} \label{sec:range-search}

In this section, we describe the implications of our results to the approximate range search problem. 

%\subsection{Range Search} 
\begin{definition}[$(1+\epsilon)$-approximate range search problem]
    Given a set $C = \{c_1, c_2, \dots, c_n\}$ of $n$ points in a euclidean space $\mathbb{R}^d$, build a data structure $S$ that, given any query range $R\subseteq \mathbb{R}^d$ defined by two corner points $q_1,q_2 \in \mathbb{R}^d$ with the promise that there is an $i\in [n]$ such that $c_i \in R$, returns all indices $i \in [n]$, such that 
    \[
    c_i \in R
    \]
    but no $i\in [n]$ such that 
    \[
    \mathsf{dist}(c_i,R) > \epsilon \cdot \mathsf{diam}(R).
    \]
\end{definition}
\begin{algorithm}[htp]\label{alg:range-search}
    \caption{An approximate range search data structure for $n$ points in $\R^d$ for $\ell_1$ metric.}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKwProg{comparator}{$E$}{}{}
    \SetKw{store}{store}
    \preprocessing{$(C, \epsilon, \delta)$\tcp*[f]{Inputs: $C=\{c_1, \dots, c_n\}\subseteq \R^d, \epsilon \in (0, \frac{1}{4}), \delta\in (0,1)$}}{
        % Let $\epsilon \leftarrow \epsilon'/\log \log n$ and $\delta \leftarrow \delta' / \Theta(n \log \log n)$\;
        Let $I \leftarrow \emptyset$ be a multiset and
        $T \leftarrow O( \log (n/\delta)/\epsilon)$\;
        % \footnote{According to Theorem \ref{theorem:Lp-NN}, it should be $O(\log(1/\delta)/\epsilon^3)$, but we can achieve a better bound of $O(\log(1/\delta)/\epsilon^2)$  by using $0\leq X_t, Y_t\leq 1$, instead of using $0\leq X_t, Y_t\leq 1/\epsilon$ in the proof. }

        \For{$t\in [T]$}{
            \For{$b\in [d]$}{
                Add $b$ to $I$ with probability  $p^{(b)}\triangleq \max_{(i,j)\in {\binom{n}{2}}} \frac{\left|c_i^{(b)} - c_j^{(b)}\right|}{\|c_i- c_j\|_1}$\;
            }
        }

        \store{$I$, $C^{(I)} = \{c_1^{(I)}, c_2^{(I)}, \dots, c_n^{(I)}\}$. }
    }
    \query{$(q_1, q_2)$ \tcp*[f]{Inputs: $q_1, q_2\in \R^d$}}{
        Query $q_1^{(b)}$ and $q_2^{(b)}, \forall b\in I$\;
        Let $W = \emptyset$\;
        \For{$i\in [n]$}{
            \If{$\forall z\in I, \min\{q_1^{(z)},q_2^{(z)}\} \leq c_i^{(z)} \leq \max\{q_1^{(z)},q_2^{(z)}\}$}{
            Add $i$ to $W$\;
            }
        }
        \Return{$W$}
    }
\end{algorithm}

\begin{theorem}
    Consider a set $C$ of $n$ points $c_1, \dots, c_n \in \mathbb{R}^d$ with $\ell_1$ metric. Given $0 < \epsilon < 1/4$, we can construct a data structure (see \cref{alg:range-search}) of word size $O(n  \log(n/\delta) \log(d)/\epsilon)$ that, given any query range $R$ by the corner points $q_1,q_2 \in R^d$, reads $O(n \log (n/\delta)/\epsilon)$ coordinates of $q_1,q_2$, returns an $(1+\epsilon)$-approximate range search of $q_1,q_2$ from $C$ with probability $1-\delta$.
\end{theorem}
\begin{proof}
    First note that when $c_i\in R$, then we always return $i$.
    It remains to show that for $c_i$ such that $\mathsf{dist}(c_i,R) > \epsilon \cdot \mathsf{diam}(R)$, we do not return $i$ with probability at least $1-\delta$.

    We fix an arbitrary $i\in [n]$ such that $\mathsf{dist}(c_i,R) > \epsilon \cdot \mathsf{diam}(R)$. We partition the coordinates in two sets.
    \begin{align*}
        \mathsf{Good}&= \left\{b\in [d] \mid \min \{q_1^{(b)},q_2^{(b)}\} \le c_i^{(b)} \le \max\{q_1^{(b)},q_2^{(b)}\}\right\}\\
        \mathsf{Bad} &= [d]\setminus \mathsf{Good}
    \end{align*}
    For intuition $\mathsf{Bad}$ is the set of coordinates that certify that $c_i \notin R$.
    We show that a coordinate from $\mathsf{Bad}$ is queried with probability at least $1-\delta$ which concludes the proof.

    Let $\mathsf{dist}_{J}$ for a set of coordinates $J\subseteq [d]$ be the distance of two points projected to the subspace on the coordinates in $J$. 
    Furthermore, let $c_{i^*}$ be the point that is inside the range $R$ which exists by the promise of the problem. 
    \begin{claim}
        \begin{align*}
            \mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*}) \ge \epsilon \mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})
        \end{align*}
    \end{claim}
    \begin{proof}
        Assume towards contradiction that $\mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*}) < \epsilon \mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})$.
        Since $c_i$ projected to $\mathsf{Good}$ is in $R$ projected to $\mathsf{Good}$ by the definition of $\mathsf{Good}$, it follows that $\mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})\le \mathsf{diam}(R)$.
        We conclude 
        \begin{align*}
            \epsilon \mathsf{diam}(R) \ge \epsilon \mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*}) > \mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*}) = \mathsf{dist}(c_i,R).
        \end{align*}
        This is a contradiction to the choice of $c_i$. 
    \end{proof}
    We sample each coordinate $b\in [d]$ in an iteration with probability at least $p^{(b)}=(|c_i^{(b)}-c_{i^*}^{(b)}|)/(\sum_{b'\in [d]}|c_i^{(b')}-c_{i^*}^{(b')}|)$. 
    Thus we sample any coordinate from $\mathsf{Bad}$ with probability at least 
    \begin{align*}
        1-\left(\prod_{b\in \mathsf{Bad}}(1-p^{(b)})\right) &\ge 1-\left(\prod_{b\in \mathsf{Bad}} e^{-p^{(b)}}\right)
        = 1-\exp({-\sum_{b\in \mathsf{Bad}} {p^{(b)}}})
        \ge \left(1-\frac{1}{e}\right)\sum_{b\in \mathsf{Bad}}p^{(b)}\\
        &= \left(1-\frac{1}{e}\right)\frac{\sum_{b\in \mathsf{Bad}}|c_i^{(b)}-c_{i^*}^{(b)}|}{\sum_{b'\in \mathsf{Bad}}|c_i^{(b')}-c_{i^*}^{(b')}|+\sum_{b'\in \mathsf{Good}}|c_i^{(b')}-c_{i^*}^{(b')}|}.
    \end{align*}
    Since we consider $\ell_1$ metric the last expression is
    \begin{align*}
        &\left(1-\frac{1}{e}\right)\frac{\mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*})}{\mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*})+\mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})} \\
        \ge & \left(1-\frac{1}{e}\right)\left(\frac{ \mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*})+\mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})}{\mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*})}\right)^{-1}\\
        \ge &\left(1-\frac{1}{e}\right)\left(1+\frac{ \mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})}{\mathsf{dist}_{\mathsf{Bad}}(c_i,c_{i^*})}\right)^{-1}\\
        \ge & \left(1-\frac{1}{e}\right)\left(1+\frac{ \mathsf{dist}_{\mathsf{Good}}(c_i,c_{i^*})}{\epsilon\mathsf{dist}_{ \mathsf{Good}}(c_i,c_{i^*})}\right)^{-1}\\
        = & \left(1-\frac{1}{e}\right)\frac{1}{1+\frac{1}{\epsilon}} \ge \frac{1}{4}\epsilon
    \end{align*}
    Since we repeat for $T= O( \log (n/\delta)/\epsilon)$ iterations, we sample a coordinate from $\mathsf{Bad}$ with probability at least $1-\delta/n$. Using union bound we succeed for all points $i\in [n]$ with probability at least $1-\delta$.
\end{proof}


\section{Reducing Approximate Nearest Neighbor under \texorpdfstring{$\ell_2$}{l2}-norm to Feature Selection for \texorpdfstring{$k$}{k}-means Clustering}\label{sec:reduction-clustering}

In this section, we show a $(\sqrt{3}+\epsilon)$-approximate nearest neighbor data structure under $\ell_2$-norm, using feature selection for $k$-means clustering. 

\begin{algorithm}[htp]
    \caption{An approximate nearest neighbor data structure for $n$ points in $\R^d$ for $\ell_2$ metric.}
    \label{alg:l2-ANN}
    \SetKwProg{preprocessing}{Preprocessing}{}{}
    \SetKwProg{query}{Query}{}{}
    \SetKwProg{selectfeature}{SelectFeature}{}{}
    \SetKwProg{comparator}{$E$}{}{}
    \SetKw{store}{store}
    \selectfeature{$(Z, t)$ \tcp*[f]{$Z \in \R^{n\times k}, t \in \R$}}{
        Let $Z_i$ be the $i$-th row of $Z$\;
        Let $p^{(i)} = \|Z_i\|_2^2 / \|Z\|_F^2$\;
        Initialize $\Omega = \mathbf{0}^{n \times t}, S = \mathbf{0}^{t \times t}$\;
        \For{$j=1$ to $t$}{
            Sample $i_j\in [n]$, with probabilities $\{p^{(i)}\}$\;
            Set $\Omega_{i_j, j} = 1$ and $S_{j,j} = 1/\sqrt{t p^{(i_j)}}$\;
        }
        \Return{$\Omega, S$}
    }
    \preprocessing{$(C, \epsilon, \delta)$\tcp*[f]{Inputs: $C\in \R^{n\times d}, \epsilon \in (0, \frac{1}{4}), \delta\in (0,1)$}}{
        Let $k = n$\; 
        Compute SVD of $C$, let $Z = V_k(C)$\;
        Determine the sampling probabilities and rescaling: $[\Omega, S] = SelectFeature(Z, t)$, where $t = O(n\log n/\epsilon^2)$\;
        Compute $R = C\Omega S \in \R^{n\times t}$ be the feature-selected centers, where $i$-th row of $R$ is $r_i$\;
        Sample $M\in \R^{t\times \log(n/\epsilon)/\epsilon^2}$ to be a JL-mapping\;        
        \store{$\Omega, S$, $RM = \{r_i M|i\in [n]\}$, $M$}
    }
    \query{$(q)$ \tcp*[f]{Inputs: $q\in \{0, 1\}^d$}}{
        Query $t$ coordinates of $q$ to compute $y^\transpose = q^\transpose \Omega S$\;
        Let $\hat{i} = \argmin_{i\in n} \|r_i M - y^\transpose M \|_2$\;
        \Return{$\hat{i}$}
    }
\end{algorithm}

\begin{theorem}\label{theorem:l2-ann}
    Consider $n$ points $c_1, \dots, c_n \in \R^d$ with $\ell_2$ metric. Given $0 < \epsilon < 1$, we can construct a  data structure (see \cref{alg:l2-ANN}) of word size $\tilde{O}(n/\poly(\epsilon))$ that, given any query $q\in \R^d$, reads $\tilde{O}(n/\poly(\epsilon))$ coordinates of $q$, and with probability $1-\delta$, returns $i$ where $c_i$ is a $(\sqrt{3}+\epsilon)$-approximate nearest neighbor of $q$ in $C$.
\end{theorem}

\subsection{Preliminaries}
Before proving the \cref{theorem:l2-ann}, we introduce some notations. 

For a matrix $A \in \R^{n \times d}$, we write the singular value decomposition (SVD) of $A$ as $A = U(A)\Sigma(A) V(A)^\transpose$, where $U(A) \in \R^{n \times n}$ and $V(A) \in \R^{d \times d}$ are orthonormal matrices, and $\Sigma(A) = diag\{\sigma_1, \sigma_2, \dots, \sigma_{rank(A)}, 0, \dots, 0\}$. For an integer $1 \leq k \leq d$, we use $V_k\in \R^{d\times k}$ to denote $V$ restricted to its first $k$ columns of $V$. The matrix $A_k = U_k(A) \Sigma_k(A) V_k(A)$ is the best rank $k$ approximation for $A$.

\subsection{Main Proof}

Let $C\in \R^{n\times d}$ be the matrix whose rows are the $n$ centers. Let $P \in \R^{1 \times d}$ be the row vector of the query. 
For some large enough $w>0$, we define $B\in \R^{(wn+1) \times d}$ to be
\[
B = \begin{bmatrix}
C\\
C\\
\vdots\\
C\\
P
\end{bmatrix}
% , 
% D = \begin{bmatrix}
% C\\
% C\\
% \vdots\\
% C
% \end{bmatrix}
\]
$B$ can be viewed as a point set of size $(wn+1)$ in $\R^d$ and we use $B$ as the instance of feature selection for $k$-means clustering, where $k = n$.


The following claim shows that $V_n(C) \in \R^{d \times n}$ approximates $V_n(B) \in \R^{d \times n}$.

\begin{claim}
    $\|B - B V_n(C) V_n(C)^\transpose \|_F^2 \leq (1+\epsilon) \| B - B_n\|_F^2$ for sufficiently large $w$.
\end{claim}

\begin{proof}
    $\|B - B V_n(C)V_n(C)^\transpose \|_F^2$ does not increase with $w$, because
    \begin{align*}
        \|B - B V_n(C)V_n(C)^\transpose \|_F^2 &= w \|C - C V_n(C)V_n(C)^\transpose \|_F^2 + \|P - P V_n(C)V_n(C)^\transpose \|_F^2 \\
        &= 0 + \|P - P V_n(C)V_n(C)^\transpose \|_F^2
    \end{align*}

    However, $\| B - B_n\|_F^2$ changes with $w$.
    Define a function $h(w)$:
    \begin{align*}
        h(w) := \|B - B_n \|_F^2 = \sigma_{n+1}^2(B) 
    \end{align*}

    % Since $B$ can be viewed as adding a row to $D$, thus $\sigma_{k}^2(D)\geq \sigma_{k+1}^2(B) \geq \sigma_{k+1}^2(D) = 0$.

    Denote $u = V(C)^\transpose P^\transpose$.
    \begin{align*}
        h(w) &= \lambda_{n+1} (B^\transpose B) = \lambda_{n+1} (wC^\transpose C +P^\transpose P )\\
        &= \lambda_{n+1}(w\Sigma^2(C) + V(C)^\transpose P^\transpose P V(C)) = \lambda_{n+1}(w\Sigma^2(C) + uu^\transpose) 
    \end{align*}
    Denote the $d_i = \sigma_i^2(C)$, thus $w\Sigma^2(C) = diag(wd_1, \dots, wd_n, 0, \dots, 0)\in \R^{d\times d}$.

    To calculate the eigenvalues of $B^\transpose B$, we let $\lambda I - B^\transpose B = 0$. After some manipulation\cite{DBLP:books/ox/07/Golub07e}, we know the eigenvalues $\lambda$ of $B^\transpose B$ corresponds to the solutions of 
    \[
    \sum_{i=1}^n \frac{u_i^2}{wd_i - \lambda} = -1+\sum_{i=n+1}^d \frac{u_i^2}{\lambda}
    \]

    And $h(w) = \lambda_{n+1} (B^\transpose B)$ is the smallest non-zero solution, since it is the smallest non-zero eigenvalue. Consider both sides as functions of $\lambda \in [0, wd_n]$. The LHS increases from a positive number to $\infty$, while the RHS decreases from $\infty$ to $0$. Thus $h(w) \in [0, wd_n]$. If we increase $w$, the RHS remains the same, and the LHS can be viewed as shifted rightwards. This means that $h(w)$ increases if $w$ increases, and $\lim_{w\rightarrow \infty} h(w) = \sum_{i=n+1}^d u_i^2$, which is 

    \begin{align*}
        \lim_{w\rightarrow \infty} h(w) &= \sum_{i=n+1}^d u_i^2 \\
        &=\sum_{i=n+1}^d (pv_{i})^2, \text{ where } v_i \text{ i-th column of V}\\
        &= \|P - PV_n(C)V_n(C)^\transpose\|_F^2.
    \end{align*}

    Thus for any $0< \epsilon < 1$, there exists sufficiently large $w$, such that 
    $\|P - PV_n(C)V_n(C)^\transpose\|_F^2 \allowbreak\leq (1+\epsilon) h(w)$, i.e. 
    $\|B - B V_n(C) V_n(C)^\transpose \|_F^2 \leq (1+\epsilon) \| B - B_n\|_F^2$.



    \end{proof}

    \begin{definition}(Approximate partition for $k$-means clustering) Consider a $k$-means clustering problem with $n$ points $C = \{c_1, \dots, c_n\} \subseteq \R^d$. A partition $\rho: [n] \rightarrow [k]$, describes $c_i$ should be in $\rho(i)$-th cluster. The $j$-th cluster $C_j$ of $\rho$ is ${c_i | i \in \rho^{-1}(j)}$ and the $j$-th center of $\rho$ is $center_j = \sum_{c_i \in C_j} c_i / |C_j|$. The cost of $(C, \rho)$ is $cost(C, \rho) = \sum_{i\in [n]} \|c_i - center_{\rho(i)} \|_2^2$.     
    Let $\rho^*$ be the optimal partition, which minimizes the k-means cost. We say $\rho$ is a $\alpha$-approximation partition if $cost(C, \rho) \leq \alpha cost(C, \rho^*)$.        
    \end{definition}

    \begin{theorem}(Theorem 11 and Lemma 4 of \cite{DBLP:journals/tit/BoutsidisZMD15})\label{theorem:bzmd15}
        Let $B\in \R^{m\times d}$ be a set of $m$ points in $\R^d$, and $k$ be the input of k-means clustering. Let $Z\in \R^{d\times k}$ be an approximation of $V_k(B)$, such that $Z^\transpose Z = I_{k\times k}, (B - BZZ^\transpose)Z = \mathbf{0}_{m\times k}$, and $\|B - BZZ^\transpose\|_F^2 \leq (1+\epsilon) \|B - B_k\|_F^2$. Then let $[\Omega, S] = SelectFeature(Z, t)$, with $t = O(k\log k/\epsilon^2)$. Let $B' = B\Omega S \in \R^{m\times t}$ be the points after feature selection. Then a $\gamma$-approxmation partition $\rho$ for $B'$ is $(1+(2+\epsilon)\gamma)$-approximation parition for $B$ with probability $0.2$.
    \end{theorem}

    \begin{theorem}(Theorem 1.3 of \cite{makarychev-etal19:jl-k-means}) \label{theorem:mmr19}Let $B' \in \R^{m\times t}$ be a set of $m$ points in $\R^t$ and $k$ be the input of $k$-means clustering. Given $0<\epsilon, \delta < 1/4$. Let $r = \log(k/\epsilon\delta)/\epsilon^2$. There exists a family of random maps $\pi:\R^t \rightarrow \R^r$, which is independent of $B'$, such that 
    $\prob{M \sim \pi}{\forall \rho, cost(B', \rho) \approx_{\epsilon} cost(M(B'), \rho) } \geq 1-\delta$. 
    \end{theorem}

    \begin{proof}(for \cref{theorem:l2-ann})
        Recall that $B$ can be viewed as a point set of size $(wn+1)$ in $\R^d$. Let $B' = B\Omega S$ as defined in \cref{theorem:bzmd15}, which can be viewed as a point set of size $(wn+1)$ in $\R^t$. Let $M$ be the random dimension reduction map in \cref{theorem:mmr19}. Then $M(B')$ can be viewed as a point set of size $(wn+1)$ in $\R^r$.

        Let $\rho_1$ be the optimal partition of $k$-means clustering on $B'$ with $k = n$. Let $\rho_2$ be the optimal partition of $k$-means clustering on $M(B')$ with $k = n$.

        From \cref{theorem:mmr19}, we know that with probability $1-\delta$, 
        \begin{align*}
            \cost(B', \rho_1) \approx_{\epsilon} \cost(M(B'), \rho_1) \\
            \cost(B', \rho_2) \approx_{\epsilon} \cost(M(B'), \rho_2)
        \end{align*}
        Because $\rho_1, \rho_2$ are respectively optimal solutions, we have
        \begin{align*}
            \cost(B', \rho_1) \leq \cost(B', \rho_2) \\
            \cost(M(B'), \rho_2) \leq \cost(M(B'), \rho_1)
        \end{align*}

        Combine them gives $\cost(B', \rho_2) \leq (1+\epsilon) \cost(M(B'), \rho_2) \leq (1+\epsilon) (1+\epsilon) \cost(M(B'), \rho_1) \leq (1+\epsilon)^2 \cost(B', \rho_2)$. This shows that $\rho_2$ is $(1+\epsilon)^2$-approximation for $B'$ with probability $1-\delta$. Furthermore, \cref{theorem:bzmd15} tells us that $\rho_2$ is $(3+10\epsilon)$-approximation for $B$ with probability $0.2 - \delta$, i.e. 
        $$\cost(B, \rho_2) \leq (3+10\epsilon) \cost(B, \rho^*).$$

        We claim that $\cost(B, \rho^*) = (\frac{w}{w+1} \dist(q, c^*))^2 + w(\frac{1}{w+1} \dist(q, c^*))^2$, where $c^*$ is the nearest neighbor of $q$ from $C$. Because $B$ is $w$ copies of $n$ centers $c_i$ plus one $q$, for sufficiently large $w$, $\rho^*$ will not map two centers into one cluster. So $q$ will be assigned to a cluster together with $w$ copies of $c^*$.

        Similarly we claim that $\cost(B, \rho_2) = (\frac{w}{w+1} \dist(q, c_{\hat{i}}))^2 + w(\frac{1}{w+1} \dist(q, c_{\hat{i}}))^2$, where $\hat{i}$ is the output index. This is because $\rho_2$ is the optimal partition of $M(B')$, so $M(y)$ will be assigned to a cluster together with $w$ copies of its nearest neighbor, which is $r_{\hat{i}}$. 

        This means $\dist^2(c_{\hat{i}}, q) \leq (3+10\epsilon) \dist^2(c^*, q)$, i.e. $\dist(c_{\hat{i}}, q) \leq \sqrt{3+10\epsilon} \dist(c^*, q)$.

\end{proof}

The reason that we can not use the same trick in \cite{DBLP:conf/stoc/CohenEMMP15} to achieve $(1+\epsilon)$-ANN is, it select features based on $Z = V_n(C)$ and $B-BZZ^\transpose = \begin{bmatrix}
    0\\
    0\\
    \vdots\\
    0\\
    P - PZZ^T
\end{bmatrix}$, which requires some information of the query $q$ in the preprocessing of the nearest neighbor data structure.

