\section{Introduction}

The primary objective of this paper is to address an inverse source problem involving the recovery of the initial electric field from lateral boundary measurements. Notably, our framework is economical in the sense that it does not require internal information such as the initial magnetic field or the internal charge distribution. While this relaxation introduces mathematical challenges due to the under-determined nature of the problem, it significantly reduces the burden of data acquisition and measurement in practical applications.


Let ${\bf E}$ be the electric field, governed by the well-determined Maxwell's equations
\begin{equation}
\begin{cases}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{E}(\mathbf{x}, t) \right) + \varepsilon(\mathbf{x}) \dfrac{\partial^2 \mathbf{E}(\mathbf{x}, t)}{\partial t^2} = \mathbf{0}, & (\mathbf{x}, t) \in \mathbb{R}^3 \times (0, \infty),
\\
\nabla \cdot (\varepsilon(\x) {\bf E}(\x, t)) = \rho(\x) &(\x, t) \in \R^3 \times (0, \infty)
\\
\mathbf{E}_t(\mathbf{x}, 0) = \varepsilon^{-1}(\x) \curl
\mathbf{H}_0(\mathbf{x}) & \mathbf{x} \in \mathbb{R}^3,
\\
\mathbf{E}(\mathbf{x}, 0) = \mathbf{E}_0(\mathbf{x}) & \mathbf{x} \in \mathbb{R}^3.
\end{cases}
\label{Maxwell}
\end{equation}
where $\mathbf{E}_0$ and $\mathbf{H}_0$ are the initial electric and magnetic fields, respectively. The $3 \times 3$ matrix-valued functions $\varepsilon(\mathbf{x})$ and $\mu(\mathbf{x})$ respectively represent the electric permittivity and magnetic permeability of the medium, and are assumed to be smooth and strictly positive definite. The scalar function $\rho(\mathbf{x})$ denotes the static charge density.
We solve the inverse problem formulated below.


\begin{problem}[Inverse initial data problem]
Assume that $\mu$ and $\varepsilon$ are known while $\rho$ and ${\bf H}_0$ are unknown.
Let ${\bf E}$ be the solution to \eqref{Maxwell}. Given the boundary data,
\begin{equation}
\mathbf{F}(\mathbf{x}, t) = \mathbf{E}(\mathbf{x}, t), \quad
\mathbf{G}(\mathbf{x}, t) = \partial_{\nu} \mathbf{E}(\mathbf{x}, t), \quad (\mathbf{x}, t) \in \partial \Omega \times (0, T),
\label{data}
\end{equation}
 reconstruct the initial electric field $\mathbf{E}_0(\mathbf{x}) = \mathbf{E}(\mathbf{x}, 0)$ within the domain $\Omega$.
\label{isp}
\end{problem}

 In general, the uniqueness of the inverse problem under consideration, namely, recovering the initial electric field $\mathbf{E}_0$ from lateral boundary data, is not guaranteed due to the under-determined nature of the formulation. This under-determined issue arises because we do not assume knowledge of the charge density $\rho$ or the initial magnetic field ${\bf H}_0$, which are standard ingredients in the classical Maxwell system. However, in the idealized case where both $\rho$ and ${\bf H}_0$ are known, and the medium is assumed to be homogeneous and isotropic with constant material parameters $\mu = \mu_0$ and $\varepsilon = \varepsilon_0$, the Maxwell system can be reformulated as a system of second-order hyperbolic equations for each component of $\mathbf{E}$.
 The principal operator for this system is $\varepsilon_0\partial_{tt} - \mu_0 \Delta.$
  In such settings, uniqueness and stability results are well-established, leveraging tools such as Carleman estimates for hyperbolic operators (see, e.g., \cite{BeilinaKlibanovBook, ClasonKlibanov:sjsc2007}).
  In contrast, this work considers the more realistic and challenging scenario in which the internal data $\rho$ and ${\bf H}_0$ are not available. To address the resulting non-uniqueness, we employ a minimum-norm formulation that selects, among all admissible solutions, the one minimizing the norm in a suitable Hilbert space, thereby compensating for the absence of $\rho$. To overcome the lack of information on ${\bf H}_0$, we apply a time-domain reduction technique. This combined strategy yields a well-posed formulation of the inverse problem, representing a key theoretical contribution of our work.



Inverse problems for Maxwell's equations have been extensively investigated in various settings, including source identification, material parameter reconstruction, and imaging applications such as magnetoencephalography and non-destructive testing. A broad overview of inverse problems in the Maxwell framework is provided in~\cite{romanov1994inverse}. Classical formulations in the frequency (time-harmonic) domain typically focus on reconstructing current sources using boundary or far-field measurements. Owing to the inherent ill-posedness of these problems, multi-frequency techniques have been widely employed to improve both stability and resolution.
Despite notable advances, comprehensive stability results for inverse source problems in the full Maxwell system under general conditions remain limited. A significant contribution in this direction is found in~\cite{bao2020stability}, where increasing stability was demonstrated for both elastic and electromagnetic wave equations with multi-frequency data. The analysis established that higher-frequency source components become negligible, thereby enhancing the quality of reconstructions.
In \cite{HarrisLeNguyen2024}, a fast and robust numerical method has been developed to reconstruct point-like or small-volume sources in the time-harmonic Maxwell equations from Cauchy data at a fixed frequency. This approach leverages imaging functions and asymptotic expansions, offering stable recovery of source locations and moments without relying on Carleman estimates.
In the context of anisotropic or inhomogeneous media,~\cite{li2005anisotropic} and~\cite{isakov2021} obtained uniqueness and increasing stability results through the use of Carleman estimates and analytic continuation techniques in the frequency domain. These studies underscore the importance of combining broadband data with structural assumptions on the medium to mitigate the effects of instability. Additionally,~\cite{albanese2006inverse} investigated non-uniqueness in determining volume current densities from boundary observations, showing that uniqueness can be restored under structural assumptions, such as dipole or surface-supported sources.
On the computational side, several reconstruction strategies have been developed. For example,~\cite{griesmaier2018windowed} introduced a qualitative imaging approach based on the windowed Fourier transform for time-harmonic Maxwell equations, enabling effective identification of radiating source supports. Similarly,~\cite{ammari2002inverse} addressed the recovery of dipole sources in magnetoencephalography using a low-frequency asymptotic expansion, establishing uniqueness, stability, and a practical inversion method.
Time-domain inverse source problems have also attracted growing interest. In~\cite{benoit2015time}, a numerical optimization framework was developed to identify time-dependent current sources, motivated by applications in fault detection and antenna design. A convergent algorithm for reconstructing temporal source functions from normal electric field measurements was proposed in~\cite{slodicka2016recovery}, while~\cite{kang2018reconstruction} introduced a potential-based formulation and proved both uniqueness and convergence for the associated reconstruction scheme.
Despite these advances, the problem of recovering the initial condition $\mathbf{E}_0(\mathbf{x})$ from finite-time boundary measurements, distinct from recovering source terms or material parameters, has received relatively little attention. This problem is particularly challenging due to the vectorial and coupled nature of Maxwell's system, which complicates inversion procedures.
In this work, we address this gap by studying the recovery of the initial electric field $\mathbf{E}_0(\mathbf{x})$ using boundary measurements of $\mathbf{E}(\mathbf{x}, t)$ and its normal derivative on $\partial \Omega \times (0, T)$. This setting is motivated by practical scenarios in which internal field data are inaccessible and only surface measurements can be obtained. 
Our objective is to design an effective numerical reconstruction method based on the theoretical structure of the problem and informed by the broader literature on inverse wave and electromagnetic problems.


For completeness, we list here some important works for the inverse initial data problem for hyperbolic equations.
The problem of recovering initial conditions in hyperbolic wave models has been extensively studied. In particular, when wave propagation occurs in free space, a number of explicit reconstruction formulas have been developed; see, for example, \cite{DoKunyansky:ip2018, Haltmeier:cma2013, Natterer:ipi2012, Linh:ipi2009}. Other commonly used approaches include the time reversal method \cite{Hristova:ip2009, HristovaKuchmentLinh:ip2006, KatsnelsonNguyen:aml2018, Stefanov:ip2009, Stefanov:ip2011}, the quasi-reversibility method \cite{ClasonKlibanov:sjsc2007, LeNguyenNguyenPowell:JOSC2021}, and a variety of iterative reconstruction techniques \cite{Huangetal:IEEE2013, Paltaufetal:ip2007, Paltaufetal:osa2002}.
These contributions primarily focus on simplified wave propagation models assuming isotropic and non-dissipative media. More advanced models incorporating damping or attenuation effects have also been analyzed in the literature; see \cite{Acosta:jde2018, Ammarietal:cm2011, Ammarielal:sp2012, Burgholzer:pspie2007, Haltmeier:jmiv2019, Homan:ipi2013, Kowar:SISI2014, Kowar:sp2012, Nachman1990}.

Our approach introduces a time-dimension reduction framework that transforms the original space-time inverse problem into a sequence of coupled spatial problems. This is achieved by projecting the time-dependent electric field onto a Legendre polynomial-exponential basis first developed in \cite{TrongElastic}, which ensures rapid decay of higher-order temporal modes and facilitates numerical stability. Each spatial mode satisfies a curl-curl-type equation involving the projection of the second time derivative of the true field. These equations are solved using a quasi-reversibility method formulated in a minimum-norm setting, which enables stable recovery under an underdetermined formulation. The method does not require knowledge of the initial magnetic field or the charge density and is designed to accommodate noisy boundary measurements. We prove convergence of the regularized solutions to the true electric field under appropriate parameter regimes and noise levels. Numerical results in fully three-dimensional configurations demonstrate the method's robustness and accuracy, even in the presence of substantial noise in the input data.



The remainder of the paper is organized as follows. In Section \ref{sec:legendre_basis}, we present the forward model for Maxwell's equations under an under-determined formulation and describe the inverse problem setup. Section \ref{sec_min} introduces the minimum-norm framework used to address the non-uniqueness arising from the under-determined setting. In Section \ref{sec4}, we develop the time-dimension reduction method based on a Legendre polynomial-exponential basis and derive the corresponding spatial systems. Section \ref{quasi} provides the convergence analysis of the regularized solution in the presence of noisy boundary data. Section \ref{sec6} presents numerical experiments that demonstrate the accuracy and stability of the proposed approach. Finally, Section \ref{sec7} concludes the paper with a summary and discussion of possible extensions.

\section{Preliminaries on the Legendre polynomial-exponential basis}
\label{sec:legendre_basis}

In this section, we review the construction and essential properties of the Legendre polynomial exponential basis, originally introduced in~\cite{TrongElastic}. This basis plays a central role in the time-dimensional reduction framework due to its favorable approximation and spectral properties.

Let $P_n(x)$ denote the classical Legendre polynomial of degree $n \geq 0$ on the interval $(-1, 1)$, defined by Rodrigues' formula:
\[
P_n(x) = \frac{1}{2^n n!} \frac{d^n}{dx^n}(x^2 - 1)^n.
\]
To define an analogous family on the interval $(0, T)$, we apply the change of variable $x = \frac{2t}{T} - 1$, yielding the rescaled orthonormal system:
\[
Q_n(t) = \sqrt{\frac{2n + 1}{T}} \, P_n\left( \frac{2t}{T} - 1 \right), \quad t \in (0, T),
\]
which forms an orthonormal basis of $L^2(0, T)$. Multiplying this by an exponential weight, we obtain the Legendre polynomial-exponential basis:
\[
\Psi_n(t) := e^t Q_n(t), \quad t \in (0, T).
\]
The collection $\{\Psi_n\}_{n \geq 0}$ constitutes an orthonormal basis of the square-integrable space with the weight $e^{-2t}$
\[
L^2_{e^{-2t}}(0, T) := \left\{ u \in L^2(0, T) \ \middle| \ \int_0^T e^{-2t} |u(t)|^2 \, dt < \infty \right\},
\]
equipped with the inner product
\[
\langle u, v \rangle_{L^2_{e^{-2t}}(0, T)} := \int_0^T e^{-2t} u(t) v(t) \, dt.
\]

Let $H$ be a Hilbert space. Throughout this paper, we denote by
\[
L^2_{e^{-2t}}((0, T); H) := \left\{ u : (0, T) \to H \ \middle| \ \int_0^T e^{-2t} \|u(t)\|_H^2 \, dt < \infty \right\}
\]
the space of $H$-valued functions that are square-integrable over $(0, T)$ with respect to the exponential weight $e^{-2t}$.

In particular, when $H$ is $H^p(\Omega)^3$ with $p \geq 0$,
we view the space  $L^2_{e^{-2t}}((0, T); H)$ as
\[
L^2_{e^{-2t}}((0, T); H) = \left\{ u : \Omega \times (0, T) \to \mathbb{R} \ \middle| \ \int_0^T e^{-2t} \|u(\cdot, t)\|_{H}^2 \, dt < \infty \right\},
\]
where the norm $\|u(\cdot, t)\|_H$ is interpreted with respect to the spatial variable for each fixed time $t$.
Also in the case when $H$ is $H^p(\Omega)^3$ with $p \geq 0$, we introduce several useful operators for functions $u \in L^2_{e^{-2t}((0, T); H)}$:

\begin{enumerate}
    \item Let $u(\mathbf{x}, t) \in L^2_{e^{-2t}}((0, T); H)$. The vector of its $(N+1)$ first Fourier coefficients with respect to the orthonormal basis $\{\Psi_n\}_{n=0}^N$ is defined as
    \begin{equation*}
        \mathbb{F}^N[u](\mathbf{x}) := 
        \begin{bmatrix}
            u_0(\mathbf{x}) & u_1(\mathbf{x}) & \dots & u_N(\mathbf{x})
        \end{bmatrix}^\top,
        \quad \x \in \Omega,
       % \label{FN}
    \end{equation*}
    where each coefficient is given by
    \begin{equation}
    u_n(\mathbf{x}) := \int_0^T e^{-2t} u(\mathbf{x}, t) \Psi_n(t) \, dt, \quad n \geq 0,  \x \in \Omega.
    \label{un}
    \end{equation}

    \item Given a coefficient vector $\mathbf{U}(\mathbf{x}) := \begin{bmatrix}
    u_0(\mathbf{x}) & u_1(\mathbf{x}) & \dots & u_N(\mathbf{x})
    \end{bmatrix}^\top \in H^{N + 1}$, its associated space-time expansion is defined as
    \begin{equation}
        \mathbb{S}^N[\mathbf{U}](\mathbf{x}, t) := \sum_{n = 0}^N u_n(\mathbf{x}) \Psi_n(t), \quad (\x, t) \in \Omega \times (0, T).
        \label{SN1}
    \end{equation}

    \item Let $u(\mathbf{x}, t) \in L^2_{e^{-2t}}((0, T); H)$. Its projection onto the finite-dimensional subspace
    \[
    \mathbb{V}^N := \mathrm{span} \{\Psi_0, \Psi_1, \dots, \Psi_N\}
    \]
    is given by the truncated expansion
    \begin{equation}
        \mathbb{P}^N[u](\mathbf{x}, t) := \sum_{n = 0}^N u_n(\mathbf{x}) \Psi_n(t),
        \label{SN}
    \end{equation}
    where the coefficients $\{u_n(\mathbf{x})\}_{n = 0}^N$ are as defined in item 1.
\end{enumerate}

\begin{remark}
Let $p \geq 0$ and $H = H^p(\Omega)^3$.
For any $N \geq 0$, the composition $\mathbb{S}^N \circ \mathbb{F}^N$ coincides with the orthogonal projection $\mathbb{P}^N$ onto the subspace $\mathbb{V}^N$. That is,
\begin{equation*}
\mathbb{S}^N[\mathbb{F}^N[u]] = \mathbb{P}^N[u], \quad \text{for all } u(\mathbf{x}, t) \in L^2_{e^{-2t}}((0, T); H).
%\label{2.4444}
\end{equation*}

Furthermore, Parseval's identity implies the following norm relation:
\begin{equation}
\|\mathbb{P}^N[u]\|_{L^2_{e^{-2t}}((0, T); H)} = \|\mathbb{S}^N[\mathbf{U}]\|_{L^2_{e^{-2t}}((0, T); H)} = \|\mathbf{U}\|_{H^{(N+1)}} \leq \|u\|_{L^2_{e^{-2t}}((0, T); H)},
\label{2.4}
\end{equation}
where $\mathbf{U} = \mathbb{F}^N[u]$ denotes the vector of Fourier coefficients.
%The definitions of the operators $\mathbb{F}^N$, $\mathbb{S}^N$, and $\mathbb{P}^N$ are independent of the specific choice of the Hilbert space $H$. 
\end{remark}






