\section{The Time Dimension Reduction Method} \label{sec4}





To reduce the computational complexity of the inverse problem, we introduce a spectral time-projection method that eliminates the time variable from the Maxwell system. This reduction transforms the original $(3+1)$-dimensional formulation into a purely three-dimensional problem, thereby facilitating the numerical solution.

For each $N \geq 1$, we apply the time-projection operator $\mathbb{P}^N$, as defined in~\eqref{SN}, to both sides of the equation~\eqref{Maxwell}. This yields the projected equation:
\begin{equation}
\sum_{n = 0}^N \nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_n(\mathbf{x}) \right) \Psi_n(t)
+ \varepsilon(\mathbf{x}) \, \mathbb{P}^N\left[ \frac{\partial^2 \mathbf{E}(\mathbf{x}, t)}{\partial t^2} \right]
= \mathbf{0}, \quad \mathbf{x} \in \mathbb{R}^3, \quad t > 0,
\label{3.1}
\end{equation}
where
the vector
\begin{equation*}    
\begin{bmatrix} \mathbf{e}_0 & \mathbf{e}_1 & \dots & \mathbf{e}_N \end{bmatrix}^{\top} = \mathbb{F}^N[\mathbf{E}]
%\label{3.5}
\end{equation*}
represents the Fourier coefficients of $\mathbf{E}$.
To eliminate the time variable, we multiply both sides of \eqref{3.1} by $e^{-2t} \Psi_m(t)$ and integrate over $(0, T)$ for each $m \in \{0, 1, \dots, N\}$. Using the orthonormality of $\{\Psi_n\}_{n \geq 0}$ in $L^2_{e^{-2t}}(0, T)$, we obtain
\begin{equation}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_m(\mathbf{x}) \right)
+ \varepsilon(\mathbf{x}) \int_{0}^T e^{-2t} \mathbf{E}_{tt}(\mathbf{x}, t) \Psi_m(t) \, dt
= {\bf 0}, \quad \mathbf{x} \in \Omega.
\label{3.2}
\end{equation}
Define the coefficient matrix
\begin{equation*}
s_{mn} = \langle \Psi''_n, \Psi_m\rangle_{L^2_{e^{-2t}}(0, T)} = \int_0^T e^{-2t} \Psi_n''(t) \Psi_m(t) \, dt,
%\label{smn}
\end{equation*}
and add the term $\varepsilon(\mathbf{x}) \sum_{n = 0}^N s_{mn} \mathbf{e}_n(\mathbf{x})$ to both sides of \eqref{3.2}, giving
\begin{multline}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_m(\mathbf{x}) \right)
+ \varepsilon(\mathbf{x}) \sum_{n = 0}^N s_{mn} \mathbf{e}_n(\mathbf{x}) \\
= \varepsilon(\mathbf{x}) \sum_{n = 0}^N s_{mn} \mathbf{e}_n(\mathbf{x}) 
- \varepsilon(\mathbf{x}) \int_0^T e^{-2t} \mathbf{E}_{tt}(\mathbf{x}, t) \Psi_m(t) \, d t.
\label{3.3}
\end{multline}


We now state a result for approximating the right-hand side of \eqref{3.3}:

\begin{Lemma}
Let $u \in H^2((0, T); L^2(\Omega))$. Let $\begin{bmatrix} u_0 & u_1 & \dots & u_N \end{bmatrix}^{\top} = \mathbb{F}^N[u]$. Then
\[
\lim_{N \to \infty} \sum_{m = 0}^\infty \left\|
    \sum_{n = 0}^N s_{mn} u_n(\mathbf{x}) 
    - \int_0^T e^{-2t} u_{tt}(\mathbf{x}, t) \Psi_m(t) \, dt
\right\|_{L^2(\Omega)}^2 = 0.
\]
\label{lem3.1}
\end{Lemma}

\begin{proof}
By Proposition~\ref{Prop_Trong}, we have
\begin{equation}
\lim_{N \to \infty} \left\|
    \sum_{n=0}^N \left\langle u(\cdot, \cdot), \Psi_n \right\rangle_{L^2_{e^{-2t}}(0, T)} \Psi_n''(t)
    - \frac{\partial^2 u}{\partial t^2}
\right\|^2_{L^2_{e^{-2t}}((0, T); L^2(\Omega))} = 0.
\label{3.6}
\end{equation}

Using Parseval's identity and the orthonormality of $\{\Psi_n\}$, we can write the left-hand side of \eqref{3.6} as
\begin{equation}
\sum_{m = 0}^\infty \int_{\Omega} \left| \left\langle
    \sum_{n=0}^N \left\langle u(\mathbf{x}, \cdot), \Psi_n \right\rangle \Psi_n''(t)
    - \frac{\partial^2 u(\mathbf{x}, \cdot)}{\partial t^2}, \Psi_m(t)
\right\rangle_{L^2_{e^{-2t}}(0, T)} \right|^2 d\mathbf{x}.
\label{3.7}
\end{equation}

The definitions of $s_{mn}$ and $u_n$ give
\[
\left\langle \sum_{n=0}^N \left\langle u(\mathbf{x}, \cdot), \Psi_n \right\rangle \Psi_n'', \Psi_m \right\rangle_{L^2_{e^{-2t}}(0, T)} = \sum_{n=0}^N s_{mn} u_n(\mathbf{x}),
\]
and
\[
\left\langle \frac{\partial^2 u(\mathbf{x}, \cdot)}{\partial t^2}, \Psi_m \right\rangle_{L^2_{e^{-2t}}(0, T)} = \int_0^T e^{-2t} u_{tt}(\mathbf{x}, t) \Psi_m(t) \, dt.
\]

Substituting into \eqref{3.7} and combining with \eqref{3.6} gives
\begin{multline*}
\left\|
    \sum_{n=0}^N \left\langle u(\cdot, \cdot), \Psi_n \right\rangle \Psi_n''(t)
    - \frac{\partial^2 u}{\partial t^2}
\right\|^2_{L^2_{e^{-2t}}((0, T); L^2(\Omega))} \\
= \sum_{m = 0}^\infty \int_{\Omega} \left| \sum_{n=0}^N s_{mn} u_n(\mathbf{x}) 
- \int_0^T e^{-2t} u_{tt}(\mathbf{x}, t) \Psi_m(t) \, dt \right|^2 d\mathbf{x},
%\label{3.8}
\end{multline*}
which yields the desired convergence.
\end{proof}

Thanks to Lemma~\ref{lem3.1}, the right-hand side of \eqref{3.3} vanishes as $N \to \infty$, leading to the simplified equation
\begin{equation}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_m(\mathbf{x}) \right)
+ \varepsilon(\mathbf{x}) \sum_{n = 0}^N s_{mn} \mathbf{e}_n(\mathbf{x}) 
= \mathbf{0}, \quad \mathbf{x} \in \Omega.
\label{3.4}
\end{equation}

This system represents a coupled family of elliptic equations in three spatial dimensions, with each $\mathbf{e}_m$ corresponding to a temporal mode of the electric field. The boundary conditions for $\mathbf{e}_m$ are derived from the measured data via time-projection as given in equations \eqref{Dir} and \eqref{Neu}, completing the full reduction of the original $(3+1)$-dimensional problem to a sequence of 3D systems.

To determine boundary conditions for each $\mathbf{e}_m$, we apply the Fourier operator $\mathbb{F}^N$ to the boundary data in \eqref{data}, yielding:
\begin{equation}
\mathbf{e}_m(\mathbf{x}) = \int_0^T e^{-2t} \mathbf{E}(\mathbf{x}, t) \Psi_m(t) \, dt
= \int_0^T e^{-2t} \mathbf{F}(\mathbf{x}, t) \Psi_m(t) \, dt =: \mathbf{f}_m(\mathbf{x}),
\label{Dir}
\end{equation}
and
\begin{equation}
\partial_\nu \mathbf{e}_m(\mathbf{x}) = \int_0^T e^{-2t} \partial_\nu \mathbf{E}(\mathbf{x}, t) \Psi_m(t) \, dt
= \int_0^T e^{-2t} \mathbf{G}(\mathbf{x}, t) \Psi_m(t) \, dt =: \mathbf{g}_m(\mathbf{x}).
\label{Neu}
\end{equation}

Combining the reduced system \eqref{3.4} with the boundary conditions \eqref{Dir} and \eqref{Neu}, we obtain the following system of equations for each $m = 0, \dots, N$:
\begin{equation}
\begin{cases}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_m(\mathbf{x}) \right)
+ \varepsilon(\mathbf{x}) \sum_{n=0}^N s_{mn} \mathbf{e}_n(\mathbf{x}) = \mathbf{0}, & \mathbf{x} \in \Omega, \\
\mathbf{e}_m(\mathbf{x}) = \mathbf{f}_m(\mathbf{x}), & \mathbf{x} \in \partial\Omega, \\
\partial_\nu \mathbf{e}_m(\mathbf{x}) = \mathbf{g}_m(\mathbf{x}), & \mathbf{x} \in \partial\Omega.
\end{cases}
\label{3.11}
\end{equation}

\begin{remark}
Solving the system \eqref{3.11} for the vector of coefficients \[\mathbb{F}^N[\mathbf{E}] = \begin{bmatrix} \mathbf{e}_0 & \cdots & \mathbf{e}_N \end{bmatrix}^\top\] enables the reconstruction of the electric field $\mathbf{E}(\mathbf{x}, t)$ via the spectral expansion $\mathbb{S}^N[\mathbf{E}]$. In particular, the initial state $\mathbf{E}_0 = \mathbf{E}(\cdot, 0)$ can be directly recovered, which is essential for solving the inverse problem numerically.
\end{remark}

\begin{remark}
The Legendre-polynomial exponential basis $\{ \Psi_n \}_{n \geq 0}$ satisfies $\Psi_n'' \not\equiv 0$ for all $n \geq 0$. This property is essential for ensuring the accuracy of our numerical approximation. If a different basis $\{\phi_n\}_{n \geq 0}$ is chosen such that $\phi_n'' \equiv 0$ for some $n$, key components of the solution may be omitted. 

Notable examples include the standard Fourier basis and classical Legendre polynomials without the exponential weight. In such cases, the coefficients
\[
s_{mn} = \int_0^T \phi_n''(t) \phi_m(t) \, dt
\]
vanish for all $m$, causing the corresponding term $\mathbf{e}_n$ to disappear from equation~\eqref{3.4}. This results in a significant loss of information in the numerical reconstruction.

An alternative to the Legendre-polynomial exponential basis is the polynomial-exponential basis introduced in~\cite{Klibanov:jiip2017}, which also satisfies the condition $\phi_n'' \not\equiv 0$ and yields comparable numerical performance.
\label{rem31}
\end{remark}

Having reduced the original time-dependent Maxwell system to the static system~\eqref{3.11} through time-projection and Fourier expansion, we now focus on its numerical resolution. In the next section, we present a quasi-reversibility method for solving this system and establish a convergence theorem that includes a stability analysis in the presence of measurement noise.


\section{The quasi-reversibility method} \label{quasi}

Recall that $\mathbf{F}$ and $\mathbf{G}$ represent the measured boundary data defined in~\eqref{data}. Let $\mathbf{F}^*$ and $\mathbf{G}^*$ denote their corresponding noise-free versions, and let $\mathbf{F}^\delta$ and $\mathbf{G}^\delta$ represent the noisy measurements. The measurement noise is assumed to satisfy the bound
\begin{equation}
    \|\mathbf{F}^* - \mathbf{F}^{\delta}\|_{L^2_{e^{-2t}}((0, T); L^2(\partial \Omega)^3)}^2 + 
    \|\mathbf{G}^* - \mathbf{G}^{\delta}\|_{L^2_{e^{-2t}}((0, T); L^2(\partial \Omega)^3)}^2 \leq \delta^2,
    \label{noise}
\end{equation}
where $\delta > 0$ denotes the noise level.
The corresponding noise-free and noisy Fourier coefficients of the boundary data used in~\eqref{3.11} are denoted by $\mathbf{f}_m^*$ and $\mathbf{g}_m^*$, and $\mathbf{f}_m^\delta$ and $\mathbf{g}_m^\delta$, respectively, for each $m \in \{0, \dots, N\}$. Then, by Parseval's identity and the bound in~\eqref{noise}, we obtain
\begin{equation}
    \sum_{m = 0}^N \left[
        \|\mathbf{f}_m^* - \mathbf{f}_m^\delta\|_{L^2(\partial \Omega)^3}^2 + 
        \|\mathbf{g}_m^* - \mathbf{g}_m^\delta\|_{L^2(\partial \Omega)^3}^2
    \right] \leq \delta^2.
    \label{noise_m}
\end{equation}


The boundary value problem in equation~\eqref{3.11} is over-determined and, in general, may not possess a solution, especially when the boundary data $\mathbf{f}_m$ and $\mathbf{g}_m$ are replaced by their noisy versions $\mathbf{f}_m^\delta$ and $\mathbf{g}^\delta_m$ respectively. To address this challenge, we seek the best-fit solution by minimizing the following Tikhonov-type regularized functional:
\begin{multline}
	J_{N, \delta, \epsilon}(\mathbf{V}) = \sum_{m=0}^N \Bigg[ \int_{\Omega} \left| \nabla \times (\mu^{-1}(\x)\nabla \times \mathbf{v}_m(\mathbf{x})) + \varepsilon(\x)\sum_{n=0}^N s_{mn} \mathbf{v}_n(\mathbf{x})\right|^2 \, d\mathbf{x} \\
	+ \int_{\partial \Omega} \left| \mathbf{v}_m(\mathbf{x}) - \mathbf{f}_m^\delta(\mathbf{x}) \right|^2 \, d\sigma(\mathbf{x}) 
	+ \int_{\partial \Omega} \left| \partial_{\nu} \mathbf{v}_m(\mathbf{x}) - \mathbf{g}_m^\delta(\mathbf{x}) \right|^2 \, d\sigma(\mathbf{x}) 
	+ \epsilon \| \mathbf{v}_m \|_{H^3(\Omega)^3}^2 \Bigg],
	\label{4.1}
\end{multline}
where $\mathbf{V} = \begin{bmatrix} \mathbf{v}_0 & \mathbf{v}_1 & \dots & \mathbf{v}_N \end{bmatrix}^\top \in H^3(\Omega)^{3 \times (N+1)}$, and $\epsilon > 0$ is a regularization parameter.
We minimize $J_{N, \delta, \epsilon}$ over the Hilbert space
\[
	H = \left\{ \mathbf{V} = \begin{bmatrix} \mathbf{v}_0 & \mathbf{v}_1 & \dots & \mathbf{v}_N \end{bmatrix}^\top : \mathbf{v}_m \in H^3(\Omega)^3 \text{ for } m = 0, \dots, N \right\},
\]
and denote by $\mathbf{V}_{\min}^{N, \delta, \epsilon} = \begin{bmatrix} \mathbf{v}_0^{N, \delta, \epsilon} & \mathbf{v}_1^{N, \delta, \epsilon} & \dots & \mathbf{v}_N^{N, \delta, \epsilon} \end{bmatrix}^\top$ the unique minimizer of the functional.




\begin{remark}[The existence of ${\bf V}_{\min}^{N, \delta, \epsilon}$]
The functional $J_{N, \delta, \epsilon}$ defined in \eqref{4.1} admits a unique minimizer in the space $H$. This is because $J_{N, \delta, \epsilon}$ is strictly convex, coercive, and continuous on $H$. The strict convexity stems from the regularization term $\epsilon \| \mathbf{v}_m \|^2_{H^3(\Omega)^3}$, which enforces smoothness and ensures that the second variation of $J_{N, \delta, \epsilon}$ is strictly positive. Coercivity is also a consequence of this term, as it guarantees that $J_\epsilon(\mathbf{V}) \to \infty$ whenever $\| \mathbf{V} \|_{H^3(\Omega)^{3 \times (N + 1)}} \to \infty$. Along with the weak lower semicontinuity of $J_{N, \delta, \epsilon}$, these properties collectively ensure the existence and uniqueness of a minimizer $\mathbf{V}_{\min}^{N, \delta,\epsilon} \in H$.
\end{remark}


As described in Remark \ref{rem31}, our time-dimensional reduction strategy employs the space-time expansion $\mathbb{S}^N[\mathbf{V}^{N, \delta, \epsilon}_{\mathrm{min}}]$, defined in \eqref{SN1}, to approximate the true minimum-norm solution $\mathbf{E}^*$ to \eqref{3_1}.
 While this approximation is computationally practical and often accurate in practice, it naturally raises a theoretical question regarding its reliability. The remainder of this section is devoted to addressing this question affirmatively.

The following is our main convergence result.

\begin{Theorem}[ Convergence of the quasi-reversibility method for noisy data]
Suppose the noisy boundary data $\mathbf{F}^\delta$ and $\mathbf{G}^\delta$ satisfy the noise constraint~\eqref{noise}, and assume that $\delta^2 = o(\epsilon)$ as $\delta, \epsilon \to 0$ where $\epsilon$ is the regularization parameter. Then:

\begin{enumerate}
    \item There exists an integer $N(\delta) > 0$ such that for all $N > N(\delta)$, the following estimate holds:
    \begin{equation}
        \sum_{m=0}^N \int_{\Omega} \left|  
        \varepsilon(\mathbf{x}) \sum_{n=1}^N s_{mn} \mathbf{e}_n^*(\mathbf{x}) 
        - \varepsilon(\mathbf{x}) \int_0^T e^{-2t} \partial_{tt} \mathbf{E}^*(\mathbf{x}, t) \Psi_m(t) \, dt 
        \right|^2 d\mathbf{x} \leq \delta^2.
        \label{4.10}
    \end{equation}

    \item Define the parameter set
    \begin{equation}
        \Theta := \left\{ (N, \delta, \epsilon): N \geq N(\delta), \, \delta^2 = o(\epsilon) \right\}.
        \label{5.5}
    \end{equation}
    Then, as $(N, \delta, \epsilon) \in \Theta$ tends to $(\infty, 0^+, 0^+)$, we have the following convergence results:
    \begin{equation}
        \lim_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} \left\| \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] - \mathbf{E}^* \right\|_{L^2((0, T); H^2(\Omega)^3)} = 0,
        \label{5.6}
    \end{equation}
    \begin{equation}
        \lim_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} \left\| \partial_t \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] - \partial_t \mathbf{E}^* \right\|_{L^2((0, T); L^2(\Omega)^3)} = 0,
        \label{5.7}
    \end{equation}
    \begin{equation}
        \lim_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} \left\| \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}](\cdot, 0) - \mathbf{E}^*(\cdot, 0) \right\|_{L^2(\Omega)^3} = 0.
        \label{5.8888}
    \end{equation}
\end{enumerate}
\label{thm41}
\end{Theorem}

\begin{proof}

The existence of $N(\delta)$ and the estimate in~\eqref{4.10} follow from Lemma~\ref{lem3.1} directly.  
We now focus on proving the second part of the theorem. The argument is divided into several steps.


{\bf Step 1.}
We begin by applying the time-projection operator $\mathbb{P}^N$ to both sides of the exact model~\eqref{3_1}. This leads to the following equation for each Fourier mode $\mathbf{e}_m^*(\mathbf{x})$ of $\mathbb{F}^N[\mathbf{E}^*]$:
\begin{equation}
\nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{e}_m^*(\mathbf{x}) \right)
+ \varepsilon(\mathbf{x}) \int_0^T e^{-2t} \mathbf{E}_{tt}^*(\mathbf{x}, t) \Psi_m(t) \, dt
= \mathbf{0}, \quad \mathbf{x} \in \Omega.
\label{4.8}
\end{equation}

Next, using the minimality of $\mathbf{V}_{\min}^{N, \delta, \epsilon}$, the noise estimate~\eqref{noise_m}, and the inequality $(a + b)^2 \leq 2a^2 + 2b^2$, we obtain:
\begin{align}
&J_{N, \delta, \epsilon}(\mathbf{V}_{\min}^{N, \delta, \epsilon}) 
\leq J_{N, \delta, \epsilon}(\mathbb{F}^N[\mathbf{E}^*]) \notag \\
&\quad \leq \sum_{m=0}^N \Bigg[
\int_{\Omega} \left| \nabla \times (\mu^{-1}(\x) \nabla \times \mathbf{e}_m^*(\x)) + \varepsilon(\x) \sum_{n=1}^N s_{mn} \mathbf{e}_n^*(\x) \right|^2 \, d\mathbf{x} \\
& \hspace{1cm} +  \delta^2 + \epsilon \| \mathbf{e}_m^*(\x) \|_{H^3(\Omega)^3}^2
\Bigg] \notag \\
&\quad\leq \sum_{m=0}^N \Bigg[
2\int_{\Omega} \left| \nabla \times (\mu^{-1}(\x) \nabla \times \mathbf{e}_m^*(\x)) + \varepsilon(\x) \int_0^T e^{-2t} \partial_{tt} \mathbf{E}^*(\x, t) \, dt \right|^2 \, d\mathbf{x} \notag \\
&\hspace{1cm} + 2\int_{\Omega} \left| -\varepsilon(\x) \int_0^T e^{-2t} \partial_{tt} \mathbf{E}^*(\x, t) \, dt + \varepsilon(\x) \sum_{n=1}^N s_{mn} \mathbf{e}_n^*(\x) \right|^2 \, d\mathbf{x} \\
& \hspace{1cm} + \delta^2 + \epsilon \| \mathbf{e}_m^* \|_{H^3(\Omega)^3}^2
\Bigg]
\label{4.7}
\end{align}
for all $N \geq N(\delta)$.
Using \eqref{4.10}, \eqref{4.8}, and \eqref{4.7}, we obtain the bound:
\begin{equation}
	J_{N, \delta, \epsilon}(\mathbf{V}_{\min}^{N, \delta, \epsilon}) \leq 3\delta^2 + \epsilon \sum_{m = 0}^N \| \mathbf{e}_m^* \|^2_{H^3(\Omega)^3}.
	\label{5.8}
\end{equation}
Combining this with \eqref{4.1} and using \eqref{2.4}, we get:
\begin{equation}
	\| \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \|^2_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)} = \sum_{m=0}^N \| \mathbf{v}_m \|^2_{H^3(\Omega)^3} \leq \frac{3\delta^2}{\epsilon} + \sum_{m=0}^N \| \mathbf{e}_m^* \|^2_{H^3(\Omega)^3} \leq C,
	\label{5.9}
\end{equation}
provided that $\delta^2 = o(\epsilon)$ and $N > N(\delta)$.


\textbf{Step 2.} We next establish bounds for $\partial_t \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]$ and $\partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]$. More precisely,
\begin{align}
\| \varepsilon & \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)}
\notag
\\
&\leq \left\| \varepsilon \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]
+ \nabla \times (\mu^{-1} \nabla \times \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]) \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} \notag
\\
&\hspace{4cm}
 + \left\| \nabla \times (\mu^{-1} \nabla \times \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]) \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} \notag \\
&\leq \left( \sum_{m=0}^N \left| \left\langle \varepsilon \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] + \nabla \times (\mu^{-1} \nabla \times \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]), \Psi_m \right\rangle_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} \right|^2 \right)^{\frac{1}{2}} \notag \\
&\hspace{4cm} + C \| \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \|_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)},
\label{5.10}
\end{align}
where Parseval's identity has been applied.
A direct computation shows that
\begin{multline}
\sum_{m=0}^N \left| \left\langle \varepsilon \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] + \nabla \times \left( \mu^{-1} \nabla \times \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \right), \Psi_m \right\rangle \right|^2 \\
= \sum_{m=0}^N \int_{\Omega} \left| \sum_{n=0}^N \varepsilon s_{mn} \mathbf{v}_n^{N, \delta, \epsilon} + \nabla \times \left( \mu^{-1} \nabla \times \mathbf{v}_m^{N, \delta, \epsilon} \right) \right|^2 \, d\mathbf{x}
\leq J_{N, \delta, \epsilon}(\mathbf{V}_{\min}^{N, \delta, \epsilon}).
\label{5.11}
\end{multline}
Combining inequalities \eqref{5.8}, \eqref{5.9}, \eqref{5.10}, and \eqref{5.11}, we obtain the uniform estimate
\begin{equation}
\left\| \varepsilon \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} \leq C.
\label{5.12}
\end{equation}

This result provides a bound on the second time derivative of $\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]$. To control the first time derivative, we apply Lemma \ref{lem4.2}, which implies that
\begin{multline}
\left\| \varepsilon \, \partial_t \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} 
\\
\leq C(\left\| \varepsilon \,  \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)} + \left\| \varepsilon \, \partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \right\|_{L^2_{e^{-2t}}((0, T); L^2(\Omega)^3)}) \leq C
\label{5.13}
\end{multline}


\textbf{Step 3.}  
Using the uniform bounds established in \eqref{5.9}, \eqref{5.12}, and \eqref{5.13}, we conclude that the family  
\[
\left\{ \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] : (N, \delta, \epsilon) \in \Theta \right\}
\]  
is bounded in both $L^2((0, T); H^3(\Omega)^3)$ and $H^2((0, T); L^2(\Omega)^3)$, where $\Theta$ is the set defined in \eqref{5.5}. By compactness of Sobolev embeddings, there exists a subsequence, still denoted by $\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]$, that converges as $(N, \delta, \epsilon) \in \Theta \to (\infty, 0^+, 0^+)$ in the following sense:
\[
\partial_{tt} \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \rightharpoonup \mathbf{z} \quad \text{weakly in } L^2((0, T); H^2(\Omega)^3),
\]
\[
\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \to \mathbf{z} \quad \text{strongly in } L^2((0, T); H^2(\Omega)^3),
\]
\[
\partial_t \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \to \partial_t \mathbf{z} \quad \text{strongly in } L^2((0, T); L^2(\Omega)^3),
\]
\[
\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \to \mathbf{z} \quad \text{strongly in } L^2_{e^{-2t}}((0, T); L^2(\partial \Omega)^3),
\]
\[
\partial_\nu \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \to \partial_\nu \mathbf{z} \quad \text{strongly in } L^2_{e^{-2t}}((0, T); L^2(\partial \Omega)^3).
\]

We now verify that the limiting function $\mathbf{z}$ solves the original problem \eqref{3_1}. In fact, we have the inequality:
\begin{multline}
\int_{\Omega_T} \left| \nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{z} \right) + \varepsilon(\mathbf{x}) \partial_{tt} \mathbf{z} \right|^2 d\mathbf{x} \, dt
+ \int_{\Gamma_T} \left| \mathbf{z} - \mathbf{F}^* \right|^2 d\sigma(\mathbf{x}) \, dt \\
+ \int_{\Gamma_T} \left| \partial_\nu \mathbf{z} - \mathbf{G}^* \right|^2 d\sigma(\mathbf{x}) \, dt
\leq \liminf_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} J_{N, \delta, \epsilon}(\mathbf{V}_{\min}^{N, \delta, \epsilon}),
\label{5.14}
\end{multline}
where we used the lower semi-continuity of convex functionals and the convergence results above.
Substituting the bound from \eqref{5.8} into \eqref{5.14}, and recalling that $\delta^2 = o(\epsilon)$, we obtain
\begin{multline*}
\int_{\Omega_T} \left| \nabla \times \left( \mu^{-1}(\mathbf{x}) \nabla \times \mathbf{z} \right) + \varepsilon(\mathbf{x}) \partial_{tt} \mathbf{z} \right|^2 d\mathbf{x} \, dt
+ \int_{\Gamma_T} \left| \mathbf{z} - \mathbf{F}^* \right|^2 d\sigma(\mathbf{x}) \, dt \\
+ \int_{\Gamma_T} \left| \partial_\nu \mathbf{z} - \mathbf{G}^* \right|^2 d\sigma(\mathbf{x}) \, dt \\
\leq \liminf_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} \left[ 3\delta^2 + \epsilon \| \mathbf{E}^* \|^2_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)} \right] = 0.
\end{multline*}
Therefore, $\mathbf{z}$ satisfies the original model \eqref{3_1}.


\textbf{Step 4.}  
We now demonstrate that $\mathbf{z} = \mathbf{E}^*$. From the strong convergence of $\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}]$ to $\mathbf{z}$ and the bound \eqref{5.9}, together with the assumption $\delta^2 = o(\epsilon)$, we obtain
\begin{align*}
\| \mathbf{z} \|^2_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)} 
&= \lim_{\Theta \ni (N, \delta, \epsilon) \to (\infty, 0^+, 0^+)} 
\| \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}] \|^2_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)} \\
&\leq \lim_{\delta^2 = o(\epsilon) \to 0} \left( \frac{3\delta^2}{\epsilon} + \sum_{m=0}^N \| \mathbf{e}_m^* \|^2_{H^3(\Omega)^3} \right) \\
&\leq \| \mathbf{E}^* \|^2_{L^2_{e^{-2t}}((0, T); H^3(\Omega)^3)}.
\end{align*}

Since $\mathbf{z}$ belongs to the admissible set and achieves the minimum norm, the uniqueness of the minimizer implies that $\mathbf{z} = \mathbf{E}^*$.  
This completes the proof of convergence estimates \eqref{5.6} and \eqref{5.7}.  
Finally, estimate \eqref{5.8888} follows directly from \eqref{5.7} by the standard trace theorem.

\end{proof}





\section{Numerical study}\label{sec6}


In our numerical simulations, we set the computational domain $\Omega = (-1, 1)^3$ and the final time $T = 2.5$. The electric permittivity is taken to be constant, $\varepsilon(\mathbf{x}) = 1$, while the magnetic permeability $\mu(\mathbf{x})$ is defined as
\[
\mu(\mathbf{x}) = 
\begin{cases}
\displaystyle \frac{1}{1 + 0.1 \exp\left(-\dfrac{|\mathbf{x}|^2}{0.5^2 - |\mathbf{x}|^2}\right)}, & \text{if } |\mathbf{x}| < 0.5, \\
1, & \text{otherwise}.
\end{cases}
\]
To generate the simulated data, we numerically solve equation~\eqref{Maxwell} using a prescribed initial condition $\mathbf{E}_0$. Since solving Maxwell's equations on the entire space $\mathbb{R}^3$ is not practical when the magnetic permeability $\mu$ varies spatially, we instead consider a bounded computational domain $G = (-2.5, 2.5)^3 \supset \Omega$ and employ an explicit time-stepping scheme. Provided that the final time $T$ is chosen not too large so that the electromagnetic field does not interact with the boundary of $G$, the resulting solution within $G$, and in particular within $\Omega$, serves as a good approximation of the restriction of the true solution in the full space. When solving the forward problem to generate the data, we impose the additional condition $\partial_t \mathbf{E}(\mathbf{x}, 0) = 0$ to ensure well-posedness of the simulation. However, this initial velocity information is deliberately excluded from the inverse problem formulation to reflect the practical limitation of incomplete data and test our reconstruction method's robustness under under-determined settings.


After computing the electric field $\mathbf{E}^*$ by solving the forward problem, we extract the exact boundary data $\mathbf{F}^*$ and $\mathbf{G}^*$ by evaluating $\mathbf{F}^*(\mathbf{x}, t) = \mathbf{E}^*(\mathbf{x}, t)$ and $\mathbf{G}^*(\mathbf{x}, t) = (\nabla \times \mathbf{E}^*(\mathbf{x}, t)) \times \nu$ for $(\mathbf{x}, t) \in \Gamma_T$. To simulate measurement errors, we perturb these data with additive noise to obtain the noisy boundary observations $\mathbf{F}^\delta$ and $\mathbf{G}^\delta$, corresponding to a relative noise level of $\delta = 10\%$. The noisy data are generated according to
\[
\mathbf{F}^\delta = \mathbf{F}^*(1 + \delta  \texttt{rand}), \quad
\mathbf{G}^\delta = \mathbf{G}^*(1 + \delta  \texttt{rand}),
\]
where \texttt{rand} is a random function returning uniformly distributed values in the interval $[-1, 1]$.







Remark~\ref{rem31} and Theorem~\ref{thm41}, especially \eqref{5.8888}, motivate the following procedure, summarized in Algorithm~\ref{alg}, for computing the initial electric field $\mathbf{E}_0$.
We implement the proposed Algorithm \ref{alg} using a finite difference scheme. The computational domain $\Omega = (-1, 1)^3$ is discretized using a uniform Cartesian grid consisting of $20 \times 20 \times 20$ points. For the time interval $[0, T]$ with $T = 2.5$, we employ a uniform temporal discretization with 73 time steps, resulting in a time step size of $\Delta t = \frac{2.5}{72} \approx 0.0347$. This spatial-temporal discretization is used consistently throughout the numerical simulation to approximate spatial derivatives and advance the electric field in time.

\begin{algorithm}[ht]
\caption{\label{alg} Time-Dimensional Reduction Method for Reconstructing the Initial Electric Field}
\begin{algorithmic}[1]

\Input Measured boundary data $\mathbf{F}^\delta(\mathbf{x}, t)$ and $\mathbf{G}^\delta(\mathbf{x}, t)$, noise level $\delta$.
\Output Approximate initial field $\mathbf{E}_{\mathrm{comp}}(\mathbf{x}) \approx \mathbf{E}^*(\mathbf{x}, 0)$.

\State Choose a regularization parameter $\epsilon$ and truncation order $N$. \label{s1}
\State Construct the basis functions $\{\Psi_n(t)\}_{n=0}^N$.
\State Compute the Fourier modes of the boundary data and source term:
\begin{equation*}
    \begin{array}{rcl}
          \mathbf{f}_m^\delta(\mathbf{x}) &:= \ds\int_0^T e^{-2t} \mathbf{F}^\delta(\mathbf{x}, t) \Psi_m(t) \, dt, \\
    \mathbf{g}_m^\delta(\mathbf{x}) &:= \ds\int_0^T e^{-2t} \mathbf{G}^\delta(\mathbf{x}, t) \Psi_m(t) \, dt. \\
    % \mathbf{j}_m(\mathbf{x}) &:= \ds\int_0^T e^{-2t} \frac{\partial \mathbf{J}}{\partial t}(\mathbf{x}, t) \Psi_m(t) \, dt, 
    \end{array}
    \quad \mbox{for } \x \in \Omega, m \in \{0, 1, \dots, N\}.
\end{equation*}
\State Minimize the cost functional $J_{N, \delta, \epsilon}(\mathbf{V})$ defined in~\eqref{4.1}; let ${\bf V}_{\mathrm{comp}} = \mathbf{V}_{\min}^{N, \delta, \epsilon}$ denote the obtained minimizer. \label{s4}

\State Reconstruct the time-dependent approximation:
\[
\mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}](\mathbf{x}, t) := \sum_{n = 0}^N \mathbf{v}_n^{N, \delta, \epsilon}(\mathbf{x}) \Psi_n(t) 
\quad (\x, t) \in \Omega_T.
\]

\State Output the approximate initial field:
\[
\mathbf{E}_{\mathrm{comp}}(\mathbf{x}) := \mathbb{S}^N[\mathbf{V}_{\min}^{N, \delta, \epsilon}](\mathbf{x}, 0).
\]
\end{algorithmic}
\end{algorithm}

We determine the regularization parameter $\epsilon$ and the truncation order $N$ in Step~\ref{s1} of Algorithm~\ref{alg} through a trial-and-error process. Specifically, we select Test~1 as a reference case and manually tune the values of $N$ and $\epsilon$ to obtain satisfactory reconstruction results. Once acceptable performance is achieved for this reference test, we fix these parameters and apply the same values for all subsequent experiments. In our implementation, we choose $N = 15$ and $\epsilon = 10^{-6}$.


To minimize the functional $J_{N, \delta, \epsilon}$ in Step~\ref{s4} of Algorithm~\ref{alg}, we employ a linear algebra routine available in MATLAB. Since $J_{N, \delta, \epsilon}$ has a least-squares form involving only linear expressions of the unknowns, the minimization reduces to solving a large linear system. However, due to the high dimensionality of our 3D inverse problem and the fact that the electric field $\mathbf{E}$ has three vector components, standard solvers such as \texttt{lsqlin} are not suitable in our case, as they require more memory than is available on our machine. Instead, we use MATLAB's \texttt{pcg} (preconditioned conjugate gradient) method to efficiently solve the system. For further details on the usage of \texttt{pcg}, we refer the reader to the MATLAB documentation.

The remaining steps of Algorithm~\ref{alg} are straightforward to implement and do not pose significant computational difficulties. Once the basis functions are constructed and the Fourier modes of the data are computed via numerical quadrature, the reconstruction of the space-time approximation and the evaluation of the initial field follow directly from the definition of the truncated expansion $\mathbb{S}^N$. These steps involve basic operations such as function evaluations, summations, and interpolation on the computational grid.


\subsection*{Test 1}

