\subsubsection{$\ms T^\mathcal{H}$ is indeed a doctrine}

The proof of this result will require some preliminary lemmas and the introduction of some terminology. When $\mc D$ is a \emph{large} lex category, we will use $\psh(\mc D)$ to denote the category of \emph{small} presheaves on $\mc D$, i.e. those presheaves arising as small colimits of representables. $\psh(\mc D)$ has the correct universal property, which is the free cocompletion of $\mc D$ under all small colimits.

\begin{term}
    Given $F : \mc C \to \mc D$ in $\LEX$ with $\mc C$ small, it induces an adjoint triple between the corresponding (small) presheaf categories as follows,
    \[\begin{tikzcd}
    	{\psh(\mc C)} & {\psh(\mc D)}
    	\arrow[""{name=0, anchor=center, inner sep=0}, "{F_!}", curve={height=-12pt}, from=1-1, to=1-2]
    	\arrow[""{name=1, anchor=center, inner sep=0}, "{F_*}"', curve={height=12pt}, from=1-1, to=1-2]
    	\arrow[""{name=2, anchor=center, inner sep=0}, "{F^*}"{description}, from=1-2, to=1-1]
    	\arrow["\dashv"{anchor=center, rotate=-91}, draw=none, from=0, to=2]
    	\arrow["\dashv"{anchor=center, rotate=-89}, draw=none, from=2, to=1]
    \end{tikzcd}\]
    The left adjoint $F_!$ exists since $\psh(\mc D)$ is cocomplete, hence has pointwise left Kan extension; it is also left exact because $F$ is. The right adjoint $F_*$ exists follows from the special adjoint functor theorem (cf.~\cite[Prop. 2.2.10]{di2024formal}). We still use the notation of geometric morphism to denote them $\Sigma F : \psh(\mc C) \leftrightarrows \psh(\mc D) : \mc PF$, where
    \[ (\mc PF)_* = F^* = (\Sigma F)^*, \quad (\mc PF)^* = F_!, \quad (\Sigma F)_* = F_*. \]
\end{term}

\begin{lem}
    For any $\mc C$ in $\ms{lex}$, we have a fully faithful unit $\eta : \mc C \hook \ms T^{\mc H}(\mc C)$ in $\LEX$.
\end{lem}
\begin{proof}
    For any $\mc C$ in $\ms{lex}$, it is easy to see we have a fully faithful unit $\eta : \mc C \hook \ms T^{\mc H}(\mc C)$, since the representable $\yo_c : \psh(\mc C) \to \Set[\mbb O]$ is a right adjoint in $\Topoi$ for any $c\in\mc C$, thus preserves all right Kan extensions. Fully faithfulness follows from Yoneda. It is left exact by construction.
\end{proof}

Now given $F : \mc C \to \ms T^{\mc H}(\mc D)$, to construct the extension $\qsi F : \ms T^{\mc H}(\mc C) \to \ms T^{\mc H}(\mc D)$ it would be equivalent to construct a geometric morphism $\psh(\mc D) \to \psh(\mc C)$ in $\WRInj(\mc H)$, since then we can then take $\qsi F$ to be given by pre-composition w.r.t. this map,
\[ \qsi F : \ms T^{\mc H}(\mc C) \simeq \WRInj(\psh(\mc C),\Set[\mbb O]) \to \WRInj(\psh(\mc D),\Set[\mbb O]) \simeq \ms T^{\mc H}(\mc D). \]
The only way to build this is as follows,
\[\begin{tikzcd}
	& {\mc D} \ar[drr, draw=none, "\mapsto"description] &&& {\psh(\mc D)} \\
	{\mc C} & {\ms T^{\mc H}(\mc D)} && {\psh(\mc C)} & {\psh(\ms T^{\mc H}(\mc D))}
	\arrow["\eta", hook, from=1-2, to=2-2]
	\arrow["F"', from=2-1, to=2-2]
	\arrow["{\mc PF}", from=2-5, to=2-4]
	\arrow["{\Sigma\eta}", hook, from=1-5, to=2-5]
\end{tikzcd}\]

\begin{lem}
    The composite geometric morphism $\mc PF \circ \Sigma \eta : \psh(\mc C) \to \psh(\mc C)$ always lies in $\WRInj(\mc H)$.
\end{lem}
\begin{proof}
    Let $f : \mc E \to \mc F$ be a map in $\mc H$ and $x : \mc E \to \psh(\mc D)$. Since the right Kan extensions for free topoi are pointwise as shown in Example~\ref{exm:ranfree}, we have
    \[ (\mc PF \circ \Sigma\eta \circ \ran_fx)^* \cong (\ran_fx)^* \circ \eta^* \circ F_!. \]
    Now we observe that $\eta^*$ is itself a left Kan extension of $\sigma : \ms T^{\mc H}(\mc D) \hook \psh(\mc D)$,
    \[
    \begin{tikzcd}
        \ms T^{\mc H}(\mc D) \ar[r, hook, "\sigma"] \ar[d, "\yo"'] & \psh(\mc D) \\
        \psh(\ms T^{\mc H}(\mc D)) \ar[ur, "\lan_{\yo}\sigma\cong\eta^*"']
    \end{tikzcd}
    \]
    Since $(\ran_fx)^*$ is a left adjoint, we then have
    \[ (\mc PF \circ \Sigma\eta \circ \ran_fx)^* \cong (\lan_{\yo}(\ran_fx)^*\sigma) \circ F_!. \]
    Since by assumption, objects lying in the image of $\sigma$ preserves right Kan extension along maps in $\mc H$, and by Example~\ref{exa:directimagerightKan} right Kan extensions for $\Set[\mbb O]$ are computed by direct images, we can perform the computation below, 
    \[ \lan_{\yo}(\ran_fx)^*\sigma \cong \lan_{\yo}f_*x^*\sigma \cong \lan_{\yo}f_*x^*\eta^*\yo. \]
    It follows that
    \begin{align*}
   (\lan_{\yo}(\ran_fx)^*\sigma) \circ F_!     \cong &(\lan_{\yo}f_*x^*\eta^*\yo) \circ F_! \\
        \cong &\lan_{\yo}f_*x^*\eta^*\yo F \\ 
        \cong &\lan_{\yo}f_*x^*F_!\yo \\ 
        \cong &(\ran_f\mc PF \circ \Sigma\eta \circ x)^*.
    \end{align*}
    Hence, $\mc PF \circ \Sigma\eta$ lies in $\WRInj(\mc H)$.
\end{proof}

