\begin{thm}\label{thm:laxidempotentmonad}
    $\ms T^{\mc H}$ is a lax-idempotent relative pseudomonad.
\end{thm}
\begin{proof}
    \emph{Extension}: For any $F : \mc C \to \ms T^{\mc H}(\mc D)$, by construction we have $\qsi F \circ \eta_{\mc C} \cong F$. 

    \emph{Unit}: By construction the extension $\qsi\eta$ of $\eta : \mc C \hook \ms T^{\mc H}(\mc C)$ corresponds to the geometric morphism $\mc P\eta \circ \Sigma\eta \cong 1$. 

    \emph{Multiplication}: Suppose we have $F : \mc C \to \ms T^{\mc H}(\mc D)$ and $G : \mc D \to \ms T^{\mc H}\mc E$. By construction of $\qsi G$, the following diagram commutes,
    \[
    \begin{tikzcd}
        \psh(\mc E) \ar[d, "\Sigma\eta_{\mc E}"'] \ar[r, "\mc PG \circ \Sigma\eta_{\mc E}"] & \psh(\mc D) \ar[d, hook, "\Sigma\eta_{\mc D}"] \\ 
        \psh(\ms T^{\mc H}\mc E) \ar[r, "\mc P\qsi G"'] & \psh(\ms T^{\mc H}(\mc D))
    \end{tikzcd}
    \]
    Now the extension $\qsi{\qsi G F}$ corresponds to the map
    \[ \mc P(\qsi GF) \circ \Sigma\eta_{\mc E} \cong \mc PF \circ \mc P\qsi G \circ \Sigma\eta_{\mc E} \cong \mc PF \circ \Sigma\eta_{\mc D} \circ \mc PG \circ \Sigma\eta_{\mc E}, \]
    which is exactly the map corresponds to the composition $\qsi G \circ \qsi F$. Verifying they satisfy the coherent axioms is routine.
\end{proof}

Finally, the following result shows we in practice have a morphism of lax-idempotent relative pseudomonad from $\ms T^{\mc H}$ to $\psh$: 

\begin{prop}\label{prop:morphismofpsalg}
    The inclusion $\sigma : \ms T^{\mc H}(\mc C) \hook \psh(\mc C)$ for any $\mc C$ in $\lex$ induces a pseudonatural transformation $\sigma : \ms T^{\mc H} \nt \psh$, which is computed as a left Kan extension in $\LEX$ as below,
    \[
    \begin{tikzcd}
        \mc C \ar[d, hook, "\eta"'] \ar[r, hook, "\yo"] & \psh(\mc C) \\ 
        \ms T^{\mc H}(\mc C) \ar[ur, hook, "\sigma \cong \lan_{\eta}\yo"']
    \end{tikzcd}
    \]
\end{prop}
\begin{proof}
    For any $X\in\ms T^{\mc H}(\mc C)$, notice that by definition the two comma categories $\eta \downarrow X$ and $\yo \downarrow \sigma X$ coincides. Hence, by Yoneda we have
    \[ \sigma X \cong \ct_{C \in \yo\downarrow \sigma X}\yo_C \cong \ct_{C\in\eta\downarrow X} \yo_C \cong (\lan_\eta\yo) X. \]
    The final isomorphism holds because $\lan_\eta\yo$ is computed pointwise in $\CAT$.
\end{proof}

\subsection{Algebras for $\mathsf{T}^{\Hcal}$ and classifying topoi}

In this subsection we discuss some important properties for the $2$-category of algebras of $\mathsf{T}^{\Hcal}$. More specifically for us, we use the definition of \emph{lax-idempotent pseudoalgebras} for a lax-idempotent relative pseudomonad introduced in~\cite[Def. 5.1 and Prop. 5.14]{arkor2025bicategories}. This is our default notion, thus by algebra we will always mean a lax-idempotent pseudo one. Concretely, an algebra structure on a (possibly large) lex category $\mc C$ is essentially unique, and it exists iff for any $f : \mc A \to \mc C$ in $\LEX$ from a small lex category, the left Kan extension $a^f$ in $\LEX$ exists,
% https://q.uiver.app/#q=WzAsMyxbMCwwLCJcXG1jIEEiXSxbMSwwLCJcXG1jIEMiXSxbMCwxLCJcXG1hdGhzZntUfV57XFxIY2FsfShcXG1jIEEpIl0sWzAsMSwiZiJdLFswLDIsIntcXGV0YX0iLDJdLFsyLDEsIntcXGxhbl97XFxldGF9Zn0iLDIseyJzdHlsZSI6eyJib2R5Ijp7Im5hbWUiOiJkYXNoZWQifX19XV0=
\[\begin{tikzcd}
	{\mc A} & {\mc C} \\
	{\mathsf{T}^{\Hcal}(\mc A)}
	\arrow["f", from=1-1, to=1-2]
	\arrow["{{\eta}}"', from=1-1, to=2-1]
	\arrow["{a^f}"', dashed, from=2-1, to=1-2]
\end{tikzcd}\]
which satisfies the following conditions:
\begin{itemize}
    \item The unit $1 \cong a^f\eta$ is invertible;
    \item These left Kan extensions are stable in the sense that for any $g : \mc B \to \ms T^{\Hcal}(\mc A)$ in $\LEX$ from a small $\mc B$, we have $a^f\qsi g \cong a^{a^fg}$ as shown below,
    % https://q.uiver.app/#
    \[\begin{tikzcd}
    	& {\mc A} & {\mc C} \\
    	{\mc B} & {\mathsf{T}^{\Hcal}(\mc A)} \\
    	{\ms T^{\Hcal}(\mc B)}
    	\arrow["f", from=1-2, to=1-3]
    	\arrow["{{\eta}}"', from=1-2, to=2-2]
    	\arrow["g", from=2-1, to=2-2]
    	\arrow["\eta"', from=2-1, to=3-1]
    	\arrow["{a^f}"description, dashed, from=2-2, to=1-3]
    	\arrow["{a^{a^fg}}"', curve={height=30pt}, dashed, from=3-1, to=1-3]
    	\arrow["{\qsi g}"description, from=3-1, to=2-2]
    \end{tikzcd}\]
\end{itemize}
A morphism between algebras are exactly a functor preserving these left Kan extensions.

It is easy to see that when $\mc C$ is itself small, the above condition is reduced to the fact that there is a left adjoint $a \dashv \eta$ to the unit $\eta : \mc C \to \ms T^{\Hcal}(\mc C)$ in $\LEX$, since for any $f : \mc A \to \mc C$, the left Kan extension $a^f$ would be induced as a composite $a^f \cong a \ms T^{\mc H}(f)$,
% https://q.uiver.app/#
\[\begin{tikzcd}
	{\mc A} &&& {\mc C} \\
	{\mathsf{T}^{\Hcal}(\mc A)} & {\mc C} \\
	& {\mathsf{T}^{\Hcal}(\mc C)}
	\arrow["f", from=1-1, to=1-4]
	\arrow["\eta"', from=1-1, to=2-1]
	\arrow["f"{description}, from=1-1, to=2-2]
	\arrow["{a^f}"{description}, dashed, from=2-1, to=1-4]
	\arrow["{\ms T^{\Hcal}(f)}"', from=2-1, to=3-2]
	\arrow["{\text{id}}"{description}, from=2-2, to=1-4]
	\arrow["\eta"', from=2-2, to=3-2]
	\arrow["a"{description}, dashed, from=3-2, to=1-4]
\end{tikzcd}\]

\begin{defn}[$2$-categories of algebras for $\mathsf{T}^{\Hcal}$]
We use $\mathsf{alg}(\mathsf{T}^{\Hcal})$ to denote the 2-category of small (!) algebras of $\ms T^{\Hcal}$. $\mathsf{Alg}(\mathsf{T}^{\Hcal})$ will be the 2-category of (possibly large) algebras.
\end{defn}

As commented before, in practice $\sigma : \ms T^{\mc H} \nt \psh$ will be a morphism between relative lax-idempotent pseudomonad. Though we lack a general theory of this in the current literature, we can show the following result directly:

\begin{prop}\label{lessinterestingly}
    Every infinitary pretopos is a $\mathsf{T}^{\Hcal}$-algebra for every ${\Hcal}$, i.e. there is a forgetful functor over $\LEX$
    \[ \ms{Pretopoi}_\infty \to \ms{Alg}(\ms T^{\mc H}). \]
\end{prop}
\begin{proof}
    Let $\mc X$ be an infinitary pretopos. For any small lex category $\mc C$ with $f : \mc C \to \mc X$ in $\LEX$, consider the following diagram,
    % https://q.uiver.app/#q=WzAsNCxbMCwwLCJcXG1jIEMiXSxbMSwwLCJcXG1jIFgiXSxbMSwxLCJcXHBzaChcXG1jIEMpIl0sWzAsMSwiXFxtcyBUXntcXEhjYWx9KFxcbWMgQykiXSxbMCwxLCJmIl0sWzAsMywiXFxldGEiLDJdLFszLDIsIlxcc2lnbWEiLDJdLFsyLDEsIlxcbGFuX3tcXHlvfWYiLDJdLFszLDEsImFeZiIsMSx7InN0eWxlIjp7ImJvZHkiOnsibmFtZSI6ImRhc2hlZCJ9fX1dXQ==
    \[\begin{tikzcd}
    	{\mc C} & {\mc X} \\
    	{\ms T^{\Hcal}(\mc C)} & {\psh(\mc C)}
    	\arrow["f", from=1-1, to=1-2]
    	\arrow["\eta"', from=1-1, to=2-1]
    	\arrow["{a^f}"{description}, dashed, from=2-1, to=1-2]
    	\arrow["\sigma"', from=2-1, to=2-2]
    	\arrow["{\lan_{\yo}f}"', from=2-2, to=1-2]
    \end{tikzcd}\]
    where we define $a^f$ to be the composite as shown above. The left Kan extension $\lan_{\yo}f$ exists in $\LEX$ precisely because infinitary pretopoi are precisely the $\psh$-algebras \cite[Prop 2.5]{lex}. By \Cref{prop:morphismofpsalg}, we have
    \[ a^f := \lan_{\yo}f \circ \sigma \cong \lan_{\yo}f \circ \lan_\eta\yo \cong \lan_{\eta} f. \]
    The unity and associativity condition of $a^f$ can be easily verified, since the above left Kan extensions are computed pointwise in $\CAT$.
\end{proof}

