\paragraph{Lexical views.}

\noindent\textbf{(1) Single ontology.}
For any ontology
\(
  \mathcal{O}
  =
  (\mathcal{C},\mathcal{P},\mathcal{A},\mathcal{M}),
  \;\mathcal{P}
  =
  \mathcal{P}^{\mathrm{obj}}\!\cup\!\mathcal{P}^{\mathrm{data}},
\)
define its \emph{lexical view}

\begin{align*}
\Lex(\mathcal{O})
=\;&
\underbrace{\bigl\{\,
  \lambda \;\bigm|\;
  \exists\,e\!\in\!
    \mathcal{C}\cup\mathcal{P}^{\mathrm{obj}}\cup\mathcal{P}^{\mathrm{data}}\!:
    \langle e,\texttt{rdfs{:}label},\lambda\rangle\in\mathcal{M}
\bigr\}}_{\text{labels of classes \& properties}}
\\[4pt]
\cup\;&
\underbrace{\bigl\{\,
  \lambda \mid
  \lambda\in\mathcal{M}
  \land
  \lambda\text{ is a string literal}
\bigr\}}_{\text{other textual annotations}}\;.
\end{align*}


\noindent\textbf{(2) Relational schema.}
\[
  \Lex(\mathcal{S})
  :=
  \bigl\{\textit{name}(r)\mid r\in\rel\bigr\}
  \cup
  \bigl\{\textit{name}(a)\mid r\in\rel,\;a\in\col(r)\bigr\}.
\]


\paragraph{Universe of texts.}

Let
\(
  \mathcal{E}= \{\mathcal{O}^{(1)},\dots,\mathcal{O}^{(n)}\}
\)
and let \textit{docTable}, \textit{docAttr} be the
documentation functions.  Then

\[
  \mathcal{X}
  :=
  \Lex(\mathcal{S})
  \;\cup\;
  \Lex(\mathcal{O}_t)
  \;\cup\;
  \bigcup_{i=1}^{n}\Lex\!\bigl(\mathcal{O}^{(i)}\bigr)
  \;\cup\;
  \text{range}(\textit{docTable})
  \;\cup\;
  \text{range}(\textit{docAttr}),
\]

so every \(x\in\mathcal{X}\) is a natural-language string suitable for the embedding function, described in \autoref{sec:dense-retrieval}.


\subsection{Embedding-based Retrieval of Relevant Knowledge}
\label{sec:dense-retrieval}
 % \steffen{I do not understand the notion of `dense' retrieval. What is it? What would be `non-dense retrieval'?}
To provide contextual knowledge about each table $r \in \rel$,
our pipeline performs embedding-based retrieval over the three knowledge sources (core ontology $\mathcal{O}_t$, description of database schema  $\mathcal{D}$, and external ontology repository $\mathcal{E}$) (\autoref{fig:promptbox}-(a), (b), (c)).
% \steffen{DocTable and DocCol are not knowledge sources, but functions! When you refer, e.g., to the core ontology, it is sufficient to say $\mathcal{O}_t$, ie. without `core ontology' --- because you formalized it before! (sometimes it may improve readability to have it)}


\noindent\textbf{Embedding function.} 
With the pre-trained model \texttt{all-mpnet-base-v2}, we define
\[
  \phi : \mathcal{X} \;\longrightarrow\; \mathbb{R}^d,
  \qquad
  \mathbf{v}_x \;=\; \phi(x)
  \quad\text{for each }x\in\mathcal{X},
\]
where $d$ is the embedding dimension (768 for the chosen model).
All relevant elements are first embedded into a unified semantic vector space.
%Let $\mathcal{T}$ denote the set of tables and columns from the relational database schema $\schema$, $\mathcal{O}_t$ denote the current core ontology at iteration $t$, $\mathcal{E}$ represent external ontology repositories, and $\text{DocCol}$, $\text{DocTable}$ be the textual documentation for columns and tables, respectively.
% \steffen{signature is broken}
% We define the embedding function $\phi: \mathcal{X} \rightarrow \mathbb{R}^d,$ where $\mathcal{X} = \mathcal{S} \cup \mathcal{O}_t \cup \mathcal{E} \cup \text{DocCol} \cup \text{DocTable}$, and $d$ is the dimensionality of the embedding space.
% For each element $x \in \mathcal{X}$, its dense vector representation is computed as $\mathbf{v}_x = \phi(x).$
% \steffen{Also note that an ontology $\mathcal{O}$ is not a set. Therefore $x\in\mathcal{O}$ does not make sense.
% You could say ``We define $\bar\in$ in the following way: $x\in X$ implies $x\bar\in X$'' and ``if $X=(...,x,...)$ then $x\bar\in X$ and ... then you can use this `flattened $\bar\in$'. However, this will probably not be enough, because you do not want to embed, e.g., the set of all entities!}

All embeddings $\{\mathbf{v}_x|x\in X\}$ are indexed using Faiss \cite{douze2024faiss} for efficient approximate nearest neighbor (ANN) search based on cosine similarity. The similarity between two vectors $\mathbf{v}_x$ and $\mathbf{v}_y$ is defined as $\text{sim}(\mathbf{v}_x, \mathbf{v}_y) = \frac{\mathbf{v}_x \cdot \mathbf{v}_y}{\|\mathbf{v}_x\| \, \|\mathbf{v}_y\|}.$

% \steffen{In embedding space I would always question the use of the cosine as similarity. Of course, this should not be changed until tomorrow but noted for later. (I know that many papers use cosine --- and I do not understand why! In word-document space I understand why, but not in embedding space.)}


Given a query embedding $\mathbf{v}_u = \phi(u)$ for the target table $r$ or its column $a$, we retrieve the top-$k$ most relevant elements from each source by computing:
 % \steffen{make sure that no huge whitespace remains}
 %  \steffen{the following formulas are broken. They retrieve similarity values (i.e. numbers), but no embeddings. $x$ from the two functions does not work}
\begin{align}
\mathcal{N}^{\mathcal{O}_t}_u &=
  \mathrm{proj}_1\Bigl(
    \text{Top}_k\bigl\{\,
      \bigl(x,\text{sim}(\mathbf v_u,\mathbf v_x)\bigr)
      \mid x\in\Lex(\mathcal{O}_t)
    \bigr\}
  \Bigr), \\[2pt]
\mathcal{N}^{\mathcal{E}}_u &=
  \mathrm{proj}_1\Bigl(
    \text{Top}_k\bigl\{\,
      \bigl(x,\text{sim}(\mathbf v_u,\mathbf v_x)\bigr)
      \mid x\in\Lex(\mathcal{E})
    \bigr\}
  \Bigr), \\[2pt]
