\subsection{Zero-Shot Prompt (0SP)~\cite{pan2024lost}}
\begin{lstlisting}[language=Python]
content = "".join(prompt) + f"\n# Translate the above {source} code to {to}. Print only the {to} code and end with the comment \"End of Code\".\n"

message = [{"role": "system", "content": "You are a helpful assistant."},
    {"role": "user", "content": content}]
\end{lstlisting}

\subsection{One-Shot Prompt (1SP)}
\begin{lstlisting}[language=Python]
content = "".join(input_code) + f"\n# Translate the following {source} code to {to}. Please provide only the translated {to} code without any extra explanation or commentary. End the output with the comment \"// End of Code\". Do not include any explanations or outputs that are not part of the translated code itself. Proceed step by step to ensure the translation is correct.\n"

sample_input = """
// Example: Translate the above Python code to C.
N, K = map(int, input().split()) 
if N % K == 0: 
    print(0) 
else: 
    print(1)
"""

sample_output = """
// Response:
int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    if (N % K == 0) {
        printf("0\n");
    } else {
        printf("1\n");
    }
    return 0;
}

// End of Code
"""

message = [{"role": "system", "content": "You are a helpful assistant."},
    {"role": "user", "content": content + "\n" + sample_input + "\n" + sample_output}]
\end{lstlisting}

\subsection{Two-Step Prompt with an Intermediate Natural Language Summary (2S-NL)}
