\section{Preliminaries}
\label{sec:Preliminaries}

Most of the definitions and notions presented in this section are taken from \cite{AB09}, and we restate them here for completeness and ease of reading.

\subsection{Uniform models of computation}
\label{sec:UniformModel}

\begin{defn}[Function and language recognition]
\label{def:FunctionNlanguageRecognition}
Let $f: \{0,1\}^{*} \rightarrow \{0,1\}$ be a Boolean function. The language corresponding to $f$ is the set of strings $L_f$ on which $f$ evaluates to $1$, i.e., $\forall x \in \{0,1\}^*$,
\begin{equation*}
    x \in L_f \iff f(x)=1.
\end{equation*}
Additionally, we say a Turing machine $M$ \emph{decides} a language $L_f$ if for all $x \in \{0,1\}^*$, whenever $M$ is initialized to the start configuration on input $x$, the machine $M$ halts with $f(x)$ written on its output tape.
\end{defn}


\begin{defn}[$\textsc{DTIME}$, Definition~1.12 in \cite{AB09}]
Let $T: \mathbb{N} \rightarrow \mathbb{N}$ be a function. A language $L$ is in $\DTIME{T(n)}$ if there exists a Turing machine $M$, and there exists a constant $c$, such that $\forall n, \forall x \in \{0,1\}^n$, $M$ on input $x$ runs in $c\cdot T(n)$ steps and decides $L$. 
\end{defn} 

\begin{defn}[$\textsc{BQTIME}$, adapting Definition 10.9 in~\cite{AB09}]
Let $f: \{0,1\}^*\rightarrow \{0,1\}$ and $T: \mathbb{N} \rightarrow \mathbb{N}$ be a function. We say $f$ is computable in quantum $T(n)$-time, or (equivalently) say $L_f\in \BQTIME{T(n)}$, if there is a classical polynomial-time Turing machine that, for every $n\in\mathbb{N}$, on input $(1^n,1^{T(n)})$ outputs the descriptions of a $T(n)$-size quantum circuit,\footnote{\label{footnote:ckt_description}A few clarifications.\begin{itemize}
      \item A description of a $T$-size quantum circuit $F\coloneqq (F_1,\ldots,F_{T})$ is an ordered sequence of $T$ elements, where $\forall i \in [T]$ each element $F_i=(G_i,w_i)$ specifies a quantum elementary gate $G_i \in \{\texttt{CNOT}\} \cup \{~\text{set of all $1$-qubit operations}~\}$ and the label(s) of the wire(s) $w_i$ on which gate $G_i$ will be applied.
      \item The action ``applying an elementary quantum operation $F_i=(G_i,w_i)$'' means applying the elementary gate $G_i$ on wire specified by location(s) $w_i$.
      \item The size of the quantum circuit, on the other hand, is the number of elements in its description.
  \end{itemize}} let us denote it by $F \coloneqq (F_1,\ldots,F_{T(n)})$, such that for every $x\in\{0,1\}^n$, the output of the following process is $f(x)$ with probability at least $2/3$:
\begin{enumerate}
    \item Initialize an $m$-qubit quantum state $\ket{x}\ket{0^{m-n}}$, where $m\leq T(n)$.
    \item Apply one after the other $T(n)$ elementary quantum operations $F_1,\ldots,F_{T(n)}$ to the state.\footnote{See \cref{footnote:ckt_description}.}
    \item Measure the last qubit in the computational basis and output the measurement outcome. 
\end{enumerate}
\end{defn}
A language $L_f$ corresponding to a Boolean function $f:\{0,1\}^*\rightarrow \{0,1\}$ is in BQP if there exists a polynomial $p$ such that $f$ is computable in quantum $p(n)$-time, or equivalently, $L_f\in\BQTIME{p(n)}$.

\subsection{Non-uniform model of computation - Boolean circuits and circuit families}
\label{sec:BooleanCircuitsNcircuitFamily}

\begin{defn}[Boolean circuits, Definition~6.1 in \cite{AB09}]
\label{sec:BooleanCircuits}
For every $n \in \mathbb{N}$, an $n$-input, single-output Boolean circuit is a directed acyclic graph with $n$ sources (i.e., vertices with no incoming edges but could have an unbounded number of outgoing edges) and one sink (i.e., vertex with no outgoing edges); let us denote the sink vertex by $s$. All non-source vertices are called gates and are labeled with one of $\land$, $\lor$ or $\neg$ (the logical operations AND, OR and NOT, respectively). The vertices labeled with $\land$ and $\lor$ have fan-in equal to $2$ and those labeled with $\neg$ gate have fan-in $1$. The source vertices are labeled with indices $i \in [n]$. We use $\texttt{label}(v)$ to denote the label of a vertex $v$. The circuit-size of $\circuit{C}$, denoted by $|\circuit{C}|$, is the total number of vertices in it.

If $\circuit{C}$ is a Boolean circuit and $x \in \{0,1\}^n$ is some input, then the output of $\circuit{C}$ on $x$, denoted by $\circuit{C}(x)$, is defined in the natural way. More formally, for every vertex $v$ of $\circuit{C}$ we define a $\texttt{val}(v)$ as follows: if $\texttt{label}(v)=i$ then $\texttt{val}(v)=x_i$ and otherwise $\texttt{val}(v)$ is defined recursively by applying the logical operation of $v$ labeled by $\texttt{label}(v)$ on the values of vertices connected to $v$. The output $\circuit{C}(x)$ is the value of the sink vertex $\texttt{val}(s)$.
\end{defn}

In any situation, if we require that the Boolean circuits are only allowed to have $\land$ and $\lor$ gates with fan-in $2$, as opposed to these gates having unbounded fan-in, then we explicitly mention it.

\begin{defn}[Circuit family and language recognition, Definition~6.2 in \cite{AB09}]
\label{def:CircuitFamily}
Let $T: \mathbb{N} \rightarrow \mathbb{N}$ be a function. A \emph{$T(n)$-size circuit family} is a sequence $\{C_n\}_{n \in \mathbb{N}}$ of Boolean circuits where for every $n$, $C_n$ has $n$ inputs and a single output and its circuit size $|C_n| \leq T(n)$.
\end{defn}

\begin{defn}[\textsf{SIZE}]
Let $T: \mathbb{N} \rightarrow \mathbb{N}$ be a function. We say a language $L \in \Size{T}$ if there exists a $T(n)$-size circuit family $\{C_n\}_{n \in \mathbb{N}}$ such that $\forall n$, $C_n$ consists of $\land$ and $\lor$ gates with fan-in $2$ and $\neg$ gates of fan-in $1$ and, moreover, $\forall x \in \{0,1\}^n, x \in L \iff C_n(x)=1$.
\end{defn}

\begin{defn}[Complexity class]
\label{def:ComplexityClass} 
A complexity class is a set of languages. 
\end{defn}

\begin{defn}[Circuit family corresponding to a language] Let $L$ be a language (as in \cref{def:FunctionNlanguageRecognition}). We say a family of circuits $\{C_n\}_{n \in \mathbb{N}}$ corresponds to language $L$, if $\forall n$, $\forall x \in \{0,1\}^n$, we have $x \in L \iff C_n(x)=1$. 
\end{defn}

\begin{defn}[$\Ppoly$, Definition~6.5 in \cite{AB09}]
    $\Ppoly$ is the class of languages that are decidable by polynomial-sized circuit families, or equivalently, $\Ppoly=\cup_{c,d}\Size{c \cdot n^d}=\cup_{c,d}\SizeArg{c}{d}$.
\end{defn}

%Since a language $L \in \Size{T(n)}$ can be recognized by a $T(n)$-size circuit family, we can say a family $\{C_n\}_{n\in \mathbb{N}}$ of circuits is in $\Ppoly$ if and only if there exists a polynomial $p$, for all $n$, $C_n$ has circuit-size at most $p(n)$.

\begin{defn}[$\AC$ and $\ACp$, Adapting Definition~6.25 in \cite{AB09}]
\label{def:AC0circuits}
A language $L$ is in $\AC$ if there exists a polynomial $p:\mathbb{N} \rightarrow \mathbb{N}$ and there exists a $p(n)$-size circuit family $\{C_n\}_{n \in \mathbb{N}}$ corresponding to $L$ where $\forall n$, circuit $C_n$ uses $\neg$, $\land$ and $\lor$ gates, with latter two allowed to have unbounded fan-in, and has depth at most $2$.

Moreover, for every polynomial $p: \mathbb{N} \rightarrow \mathbb{N}$ we define a complexity class $\ACp$. We say a language $L$ is in $\ACp$ if there exists a family of Boolean circuits $\{C_n\}_{n\in \mathbb{N}}$ corresponding to $L$ such that $\forall n$, $C_n$ uses $\neg$, $\land$ and $\lor$ gates, with latter two allowed to have unbounded fan-in, and has depth at most $2$ and circuit-size $|C_n| \leq p(n)$.
\end{defn}

\begin{defn}[$\TypeO$ complexity class]
\label{def:SizeableComplexityClass} 
We say a complexity class is of $\TypeO$ if it is any of the following complexity classes:
\begin{enumerate}
    \item For every $d \in \mathbb{N}$ and $k \in \mathbb{N}$, we include the class $\ACarg{d}{k}$; we say a language $L \in \ACarg{d}{k}$ if there exists a family of Boolean circuits $\{C_n\}_{n \in \mathbb{N}}$ corresponding to $L$ such that $\forall n$, $C_n$ uses $\neg$, $\land$ and $\lor$ gates, with latter two allowed to have unbounded fan-in, and has depth at most $d$ and circuit size $|C_n| \leq n^k$. 
    \item For every $d \in \mathbb{N}$ and $k \in \mathbb{N}$, we include the class $\NCarg{d}{k}$; we say a language $L \in \NCarg{d}{k}$ if there exists a family of Boolean circuits $\{C_n\}_{n \in \mathbb{N}}$ corresponding to $L$ such that $\forall n$, $C_n$ has depth at most $\log^d n$ and circuit size $|C_n| \leq n^k$. 
    \item For every $d \in \mathbb{N}$ and $k \in \mathbb{N}$, we include the class $\SizeArg{d}{k}$; we say a language $L \in \SizeArg{d}{k}$ if there exists a family of Boolean circuits $\{C_n\}_{n \in \mathbb{N}}$ corresponding to $L$ such that $\forall n$, $C_n$ has circuit size $|C_n| \leq d \cdot n^k$.
\end{enumerate}
\end{defn}

\subsection{Truth tables of circuits, languages and a few other useful notations}

A truth table is binary string capturing the outputs of a Boolean function. If a function is defined on $n$ binary inputs then its corresponding truth table is a Boolean string in $\{0,1\}^{2^n}$. The notion of a truth table can also be extended to capture the membership of strings in a language by fixing the length of the strings. We formally define these notions as follows.

\begin{defn}[Truth tables] 
\label{def:Truthtables}
For any $n \in \mathbb{N}$, let $f_n : \{0,1\}^n \rightarrow \{0,1\}$ be a Boolean function. Then the truth table of $f_n$, denoted by $\truthtable(f_n)$, is a $2^n$-length binary string constructed in the following way:
\begin{equation*}
    \truthtable(f_n)=\concatenate_{a \in \{0,1\}^n} f_n(a).
\end{equation*}
Here $f_n(a)$ denotes the output $f_n$ on input $a$. And for the concatenation, the strings $a \in \{0,1\}^n$ are taken in lexicographic order.

For a language $L \subseteq \{0,1\}^*$ the notion of truth table is as follows: for any $n \in \mathbb{N}$, the truth table of $L$ at $n$, denoted by $\truthtable(L, n)$, is a $2^n$-length binary vector that can be obtained by concatenating the outputs $b_a \coloneqq [a \in L]$ for all $a \in \{0,1\}^n$ taken in lexicographic order.  
\end{defn}

\paragraph{Other useful notations.}
Let $n$ be an integer. Let $f_n:\{0,1\}^n \rightarrow \{0,1\}$ be a Boolean function on $n$ input variables. 
\begin{itemize}
    \item We use $\setOfAllStrings_n$ to denote the set of \textit{all} Boolean functions defined on $n$ input variables; We represent $\setOfAllStrings_n = \{ \truthtable(f_n) \mid f_n \text{ is a Boolean function on }n \text{ variables} \}$ as the set of truth tables of all functions $f_n:\{0,1\}^n \rightarrow \{0,1\}$, implying $\setOfAllStrings_n = \{0,1\}^{2^n}$ and $|\setOfAllStrings_n|=2^{2^n}$. We also use $N=2^n$.
    \item We overload the notation of $\truthtable(\cdot)$ on sets of Boolean functions to denote the following: if $S$ is a set of Boolean functions on $n$ variables then $\truthtable(S)= \{\truthtable(f_n) \mid f_n \in S \}$.
    \item Let $\Lambda$ be a complexity class. Let $L \in \Lambda$. Furthermore, let $f_n:{0,1}^n \rightarrow \{0,1\}$ be a Boolean function such that $\truthtable(f_n)=\truthtable(L,n)$ then we say $f_n$ \emph{is a sub-element of} $\Lambda$.
    \item We sometimes also overload the notation of $\truthtable(\cdot)$ on complexity classes to denote the following: if $\Lambda$ is a complexity class then $\truthtable(\Lambda,n)= \{\truthtable(f_n) \mid f_n \textnormal{ sub-element in } \Lambda \}$ or equivalently $\truthtable(\Lambda,n)= \{\truthtable(L,n) \mid L \in \Lambda \}$. Furthermore, we use $\truthtable(\Lambda)=\bigcup_{n \in \mathbb{N}} \truthtable(\Lambda,n)$.
\end{itemize}

\section{The QSETH framework}
\label{sec:QSETHframework}

\subsection{Definitions}

\begin{defn}[Property]
\label{def:BooleanProperty}
A Boolean property (or just property) is a sequence $\propertyP \coloneqq\big( \propertyP_n\big)_{n\in\mathbb{N}}$ where each $\propertyP_n$ is a set of Boolean functions defined on $n$ variables.
\end{defn}

Alternatively, one can view $\propertyP_n$ as a set of $2^n$-length Boolean strings that are truth tables of functions $f_n \in \propertyP_n$, or equivalently view it as a function $\propertyP_n: \{0,1\}^{2^n} \rightarrow \{0,1\}$ such that $\propertyP_n(\truthtable(f_n))=1$ if and only if $f_n \in \propertyP_n$; see \Cref{def:Truthtables} for the definition of a truth table. Also note that it is possible for a property $\propertyP$ to be \emph{partial}. In such a case, for every $n$, there could be some functions $f_n$ for which we don't care whether or not they belong to $\propertyP_n$.\footnote{For example, both the properties $\mathrm{PP}_{\mathrm{edit}}$ and $\mathrm{PP}_{\mathrm{lcs}}$ considered in \cite{BPS21} are partial.}

\paragraph{Quantum query complexity of $\propertyP$} The (bounded-error) quantum query complexity is defined only in a non-uniform setting; therefore, we define this notion for $\propertyP_n$ for every $n \in \mathbb{N}$.  A quantum query
algorithm $\mathcal{B}$ for $\propertyP_n: \{0,1\}^{2^n} \rightarrow \{0,1\}$, on an input $x \in \{0,1\}^{2^n}$ begins in a fixed initial state $\ket{\psi_0}$, applies a sequence of unitaries $U_0, O_x, U_1, O_x, \ldots, U_T$, and performs a measurement whose outcome is denoted by $z$. Here, the initial state $\ket{\psi_0}$ and the unitaries $U_0, U_1, \ldots, U_T$ are independent of the input $x$. The unitary $O_x$ represents the ``query'' operation, and maps $\ket{i}\ket{b}$ to $\ket{i}\ket{b + x_i \textnormal{ mod } 2}$ for all $i \in [2^n]-1$. 
%and maps $\ket{0}$ to $\ket{0}$. 
We say that $\mathcal{B}$ is a $1/3$-bounded-error algorithm computing $\propertyP_n$ if for all $x$ in the domain of $\propertyP_n$, the success probability of outputting $z=\propertyP_n(x)$ is at least $2/3$. Let cost$(\mathcal{B})$ denote the number of queries $\mathcal{B}$ makes to $O_x$ throughout the algorithm. The $1/3$-bounded-error quantum query complexity of $\propertyP_n$, denoted by $\Q_{1/3}(\propertyP_n)$, is defined as 
$\Q_{1/3}(\propertyP_n)=\min\{\text{cost}(\mathcal{B}):\mathcal{B} \text{ computes } \propertyP_n \text{ with error probability } \leq 1/3\}$.\footnote{Note that if $\propertyParity \coloneqq (\propertyParity_n)_{n \in \mathbb{N}}$ is the property we are considering, under our definition of $\propertyParity_n$ the value of $\Q(\propertyParity_{n})$ is equal to $\Omega(2^{n})$ and not $\Omega(n)$. For the property $\propertyOR \coloneqq (\propertyOR_n)_{n \in \mathbb{N}}$ then $Q(\propertyOR_{n})=\Omega(2^{\frac{n}{2}})$.}

\paragraph{Algorithms computing a property $\propertyP$ in black-/white-box setting} We say a (bounded-error quantum) algorithm $\mathcal{A}$ computes a property $\propertyP$ (as in \Cref{def:BooleanProperty}) in the \emph{black-box} setting if for all $n\in \mathbb{N}$, for all $f_n$ given its truth table as input, i.e., a $2^n$-length Boolean string, $\mathcal{A}$ makes (quantum) queries to this input and (with success probability at least $2/3$) determines whether or not $f_n \in \propertyP_n$. An algorithm computing $\propertyP$ in the \emph{white-box} setting gets a circuit description of $f_n$, which is possibly a more succinct description of $f_n$'s truth table, and the algorithm has to determine whether or not $f_n \in \propertyP_n$. We emphasize that, in both the black-/white-box setting, we care about the \emph{time} that algorithm $\mathcal{A}$ takes when deciding whether or not $f_n \in \propertyP_n$.
\newline

We now present the definition of compression-oblivious properties. In simple terms, these are the properties whose quantum query complexity is a lower bound for the time complexity to compute the property even for inputs that are ``compressible'' as a truth table of small formulas (or circuits). Formally,

