\begin{defn}[$\Gamma_{d,k}$-compression-oblivious properties]
\label{def:CompressionOblivious}
Let $d,k \in \mathbb{N}$. Let $\Gamma_{d,k}$ denote a $\TypeO$ complexity class as stated in \cref{def:SizeableComplexityClass} parameterized by $d$ and $k$. We say a property $\propertyP$ is \emph{$\Gamma_{d,k}$-compression-oblivious}, denoted by $\propertyP \in \mathcal{CO}(\Gamma_{d,k})$, if for every constant $\delta>0$, for every quantum algorithm $\mathcal{A}$ that computes $\propertyP$ in the \textbf{black-box} setting, $\forall n' \in \mathbb{N}, \exists n \geq n'$ and $\exists$ a set $L=\{L^1, L^2, \ldots\} \subseteq \Gamma_{d,k}$ of `hard languages', such that $\forall$ circuit families $\{C^1_n\}_{n \in \mathbb{N}}$ corresponding to $L^1$, $\forall$ circuit families $\{C^2_n\}_{n \in \mathbb{N}}$ corresponding to $L^2$, $\ldots$, the algorithm $\mathcal{A}$ uses at least $\Q_{1/3}(\propertyP_{n})^{1-\delta}$ quantum time on at least one of the inputs in $\{C^i_n\}_{i \in [|L|]}$.
\end{defn}

%\snote{Can we put a footnote for why CO is laboriously defined when the defn can be made simpler?}

\begin{defn}[compression-oblivious properties w.r.t.\  $\AC$, $\NC$, $\Ppoly$]
\label{def:COforGeneralComplexityClass}
We say a property $\propertyP : \{0,1\}^* \rightarrow \{0,1\}$ is
\begin{enumerate}
    \item $\propertyP \in \mathcal{CO}(\AC)$ if $d=2$ and $\exists k \in \mathbb{N}$ such that $\propertyP \in \mathcal{CO}(\ACarg{d}{k})$, 
    \item $\propertyP \in \mathcal{CO}(\ACconstDepth)$ if $\exists d \in \mathbb{N}, \exists k \in \mathbb{N}$ such that $\propertyP \in \mathcal{CO}(\ACarg{d}{k})$, 
    \item $\propertyP \in \mathcal{CO}(\NC)$ if $\exists d \in \mathbb{N}, \exists k \in \mathbb{N}$ such that $\propertyP \in \mathcal{CO}(\NCarg{d}{k})$, and
    \item $\propertyP \in \mathcal{CO}(\Ppoly)$ if $\exists d \in \mathbb{N}, \exists k \in \mathbb{N}$ such that $\propertyP \in \mathcal{CO}(\SizeArg{d}{k})$.
\end{enumerate}

\end{defn}


The original definition of compression-oblivious properties, as presented in Section~2.2 of \cite{BPS21}, does not clearly enforce a unique ordering of the quantifiers, which can potentially lead to undesirable consequences. Hence, we make the effort of presenting a more formal definition of $\Gamma$-compression-oblivious properties in  \Cref{def:CompressionOblivious,def:COforGeneralComplexityClass} (with the approval of the authors \cite{BPS21}). 

Having formally defined $\Gamma$-compression-oblivious properties for all $\Gamma \in \{\AC, \ACconstDepth, \NC, \Ppoly \}$ we now state the $\Gamma$-QSETH conjecture. Earlier in this section, we discussed the difference between computing a Boolean property in a black-box setting versus computing the same property in a white-box setting. The compression-oblivious properties are those properties for which its corresponding quantum query complexity lower bounds the time complexity in the \emph{black-box} setting. For such properties, Buhrman \textit{et al.}\ conjectured that the time complexity of computing these properties in the \emph{white-box} setting is as bad as it is in the black-box setting. This assumes that the succinct description of the Boolean functions doesn't help in computing the properties more efficiently. (This is similar to the \textit{Black-Box Hypothesis (BBH)} stated in \cite{IKKMR17CircuitHelp}.) More formally,
%\fnote{I think the readability of this conjecture and the the definition of compression-oblivious properties are some of the parts that readers might stumble on. However, I don't have a concrete improvement, so maybe it is what it is.}

\begin{conjecture}[$\Gamma$-$\QSETH$, a more formal presentation of Conjecture~5 in \cite{BPS21}]
Let $\Gamma \in \{\AC, \ACconstDepth, \NC, \Ppoly \}$ be a complexity class (as in \cref{def:ComplexityClass}). Let $\propertyP$ be a \emph{$\Gamma$-compression-oblivious} property. The $\Gamma$-$\QSETH$ conjecture states that $\exists d, \exists k \in \mathbb{N}$, such that for every constant $\delta>0$, for every quantum algorithm $\mathcal{A}$ that computes $\propertyP$ in the \textbf{white-box} setting, $\forall n' \in \mathbb{N},\exists n \geq n'$, $\exists$ a set $L=\{L^1, L^2, \ldots\} \subseteq \Gamma_{d,k}$, $\forall $ circuit families $\{C^1_n\}_{n\in \mathbb{N}}$ corresponding to $L^1$, $\forall$ circuit families $\{C^2_n\}_{n\in \mathbb{N}}$ corresponding to $L^2$, $\ldots$, the algorithm $\mathcal{A}$ uses at least $\Q_{1/3}(\propertyP_{n})^{1-\delta}$ quantum time on at least one of the inputs in $\{C^i_n\}_{i \in [|L|]}$. Note that $\Gamma_{d,k}$ is a $\TypeO$ complexity class corresponding to $\Gamma$.
\end{conjecture}

\subsection{Relevance}

Note that a basic version of the $\QSETH$ conjecture and its implications has already been discussed in complementary works \cite{BasicQSETH-Aaronson-2020, BPS21}, and other variants of $\QSETH$ are discussed more recently in \cite{CCKSS23QSETH} and in Chen's PhD thesis \cite{Che24Thesis}. For example,

\begin{conjecture}[Basic-$\QSETH$, Conjecture~8.3 in \cite{Che24Thesis}]
\label{conj:BasicQSETHfromYanlinThesis}
For each constant $\delta >0$, there exists $c>0$ such that there is no bounded-error quantum algorithm that solves $\CNFSAT$ (even restricted to formulas with at most $cn^2$ many clauses) in $O(2^{\frac{n(1-\delta)}{2}})$ time.    
\end{conjecture}

\begin{conjecture}[$\oplus\QSETH$, Conjecture~8.9 in \cite{Che24Thesis}]
\label{conj:ParityQSETHfromYanlinThesis}
For each constant $\delta >0$, there exists $c>0$ such that there is no bounded-error quantum algorithm that solves $\oplus\CNFSAT$ (even restricted to formulas with at most $cn^2$ many clauses) in $O(2^{n(1-\delta)})$ time.    
\end{conjecture}

\begin{conjecture}[$\#\QSETH$, Conjecture~8.8 in \cite{Che24Thesis}]
\label{conj:CountingQSETHfromYanlinThesis}
For each constant $\delta >0$, there exists $c>0$ such that there is no bounded-error quantum algorithm that solves $\#\CNFSAT$ (even restricted to formulas with at most $cn^2$ many clauses) in $O(2^{n(1-\delta)})$ time.    
\end{conjecture}

We are able to get these conjectures as a corollary to our QSETH framework. More precisely,

\begin{corollary}
\label{cor:AC2QSETHimpliesConjectureInYanlinThesis}
The $\AC$-$\QSETH$ implies \Cref{conj:BasicQSETHfromYanlinThesis}. Additionally, if we assume that $\propertyParity \in \mathcal{CO}(\AC)$ then $\AC$-$\QSETH$ implies \Cref{conj:ParityQSETHfromYanlinThesis,conj:CountingQSETHfromYanlinThesis}.
\end{corollary}
\begin{proof}
The proof of $\propertyOR \in \mathcal{CO}(\AC)$ was first given in \cite{BPS21} (we also present the proof in \Cref{Appsec:OldObservationsAboutCO}). Thereafter, setting $d=2$ and $k=3$ for $\AC$-$\QSETH$ conjecture implies \Cref{conj:BasicQSETHfromYanlinThesis,conj:ParityQSETHfromYanlinThesis,conj:CountingQSETHfromYanlinThesis}.
\end{proof}

Therefore, all the $\QSETH$-based lower bounds presented in Chen's PhD thesis \cite{Che24Thesis} immediately follow from our $\QSETH$ framework.

\section{When certain properties are not $\Ppoly$-compression-oblivious}
\label{sec:COproperties}

%we make some new observations about compression-oblivious properties that constitute an integral part of this paper. Additionally, we verify if the observations about compression-oblivious properties made in \cite{BPS21} correctly hold with our newly proposed \Cref{def:CompressionOblivious,def:COforGeneralComplexityClass}; we do so in the \Cref{Appsec:OldObservationsAboutCO}.  

In this section, we show that it is reasonable to conjecture that there exist $d',k' \in \mathbb{N}$ and $d'',k'' \in \mathbb{N}$ for which properties such as $\propertyParity$ and $\propertyMajority$ are $\SizeArg{d'}{k'}$-compression-oblivious and $\SizeArg{d''}{k''}$-compression-oblivious, respectively. We do so by relating this conjecture to topics in circuit complexity and pseudorandomness. In fact, we are able to show similar consequences for properties that satisfy certain constraints. $\propertyParity$ and $\propertyMajority$ happen to be such properties.

Following the notation about natural proofs from \cite{RR94} and \cite{Cho11}, we now define the following.

\begin{defn}[$\Upsilon$-natural property with density $\delta$]
\label{defn:UpsilonNaturalProperty}
Let $\Upsilon$ be a complexity class (as in \cref{def:ComplexityClass}) and let $\delta \coloneqq (\delta_n)_{n \in \mathbb{N}}$ denote a sequence of positive integers. A property $D\coloneqq (D_n)_{n \in \mathbb{N}}$ (as in \cref{def:BooleanProperty}) is $\Upsilon$-natural with density $\delta \coloneqq (\delta_n)_{n \in \mathbb{N}}$ if the following statements hold:
\begin{enumerate}
    \item largeness: $\exists n', \forall n>n'$, $|D_n| \geq 2^{2^n} \cdot \delta_n$, and
    \item constructivity: the problem of determining whether a Boolean function $f_n \in D_n$, when given as input the truth table of $f_n$ on $n$ variables, is decidable in $\Upsilon$, which in more formal terms translates to saying $L_{D} \in \Upsilon$ where $L_{D}\coloneqq \bigcup_{n \in \mathbb{N}} \{\truthtable(f_n) \mid f_n \in D_n \}$.
\end{enumerate}  
\end{defn}

\begin{defn}[Quasi-useful property, Definition~5 in \cite{Cho11}]\footnote{Note that Razborov and Rudich use the notion of \emph{useful} property which is defined for infinitely many $n$. However, for our results the notion of \emph{quasi-useful} property (defined for all sufficiently large $n$) makes more sense so we use this instead.}
\label{defn:Quasi-UsefulProperty}
Let $\Lambda$ denotes a complexity class. A property $D \coloneqq (D_n)$, or equivalently the corresponding language $L_{D}\coloneqq \bigcup_{n \in \mathbb{N}} \{\truthtable(g_n) \mid g_n \in D_n \}$, is quasi-useful against complexity class $\Lambda$ if $\forall (f_n)$, we have $(f_n) \notin \Lambda$ whenever $(f_n)$ is sequence of Boolean functions satisfying $f_n \in D_n$ for all sufficiently large $n$.
\end{defn}

