\section{Observations on compression-oblivious properties made in \cite{BPS21}}
\label{Appsec:OldObservationsAboutCO}

To ensure that our detailed definition of compression oblivious is valid, and is what the authors of \cite{BPS21} had in mind, we reprove their results about compression oblivious properties again here. The proof ideas are almost the same, the extra details in our proofs are to make their proofs consistent with our proposed definitions of compression oblivious properties.

\begin{lemma}[Example~6 in \cite{BPS21}]
\label{thm:ORisCOforAC}
Let $\propertyOR:\{0,1\}^* \rightarrow \{0,1\}$ be a Boolean property such that $\forall x \in \{0,1\}^*$ the $\propertyOR(x)=1$ if and only if $|x|\geq 1$. Then $\propertyOR \in \mathcal{CO}(\AC)$. Here $|x|$ denotes the hamming weight of $x$, i.e., the number of $1$s in $x$.
\end{lemma}
The proof idea is to construct a hard set of languages for every $n \in \mathbb{N}$ that makes it difficult to compute $\propertyOR_n$ in a black-box way when given access to the set of $n$-input circuits each corresponding to a language in this hard set of languages. 
\begin{proof}
To prove that $\propertyOR \in \mathcal{CO}(\AC)$, we show that there exists a $k' \in \mathbb{N}$ such that $\propertyOR \in \mathcal{CO}(\ACarg{2}{k'})$. For every value of $n \in \mathbb{N}$ we will exhibit a set $L = \{L^0, L^1, \ldots \} \subseteq \ACarg{2}{k'}$ whose respective truth tables, i.e., the set $\{ \truthtable(L^i,n)\}_{i \in [|L|]}$, form a hard set for computing $\propertyOR_n$ on them. In fact, the value of $k'$ in our construction will be $2$.

\paragraph{The construction for $L$.} Let $n \in \mathbb{N}$. Let $L_0=\emptyset$. We will construct the languages $L_1, L_2, \ldots$ so that each language $L_i$ contains exactly one Boolean string of length $k$.
\begin{enumerate}
    \item For every $k \in [n]$, starting with $k=1$ in an increasing order, go over all the strings $z \in \{0,1\}^k$ in a lexicographical order. Place the string $z$ in set $L_i$ (for an $i>0$) only if no $L_j$ with $j \leq i$ contains the string $z$. Once the placement of $z$ is decided, set $z$ to be the next string in the lexicographic ordering of $\{0,1\}^k$. 
    \item For $k> n$, we put no $k$-length binary strings in any of these $L^i$s.
\end{enumerate}

\paragraph{All these $L^i$s are in $\ACarg{2}{2}$.} For every $i$, let $\{C^i_n\}_{n \in \mathbb{N}}$ denote a family of circuits corresponding to $L^i \in L$. We will now show that there exist families such that $|C^i_n| <=n$ for all $n \in \mathbb{N}$. 
\begin{enumerate}
    \item It is easy to see that the $\{C^0_n\}_{n \in \mathbb{N}}$ can be constructed using circuits of constant size as $L^0$ has no accepting strings of any length. Therefore, for all $n \in \mathbb{N}$, $|C^0_n|<n^2$.
    \item Now for the other $L^i$s:
    \begin{enumerate}
        \item For an $k <=n$, for any $L^i$ with $i>0$, the corresponding $C^i_k$ accepts exactly one $k$-length string and such a circuit can be constructed using one $\land$ gate with $k$-fanin. Therefore, $|C^i_k|=k+1<k^2$. (For computing the size, we count the number of vertices in the circuit.)
        \item For an $k >n$, $C^i_k$ can be constructed using constant size circuits as there are no accepting $k$-length strings for any $L^i$.
    \end{enumerate}
    Therefore, for all $n\in \mathbb{N}$ and for all $i \in [|L|]$ we have that $|C^i_n| < n^2$, which means $L \subseteq \ACarg{2}{2}$.
\end{enumerate}

\paragraph{Invoking the quantum query lower bound for $\propertyOR_n$.} What remains to show is that no quantum algorithm can compute $\propertyOR_n$ on the strings $\{ \truthtable(L^i, n)\}_{i \in [|L|]}$ in $\Q_{1/3}(\propertyOR_n)^{1-\delta}$ time for any constant $\delta>0$. Towards contradiction, say that such a $\delta$ existed. Then this algorithm can compute $\propertyOR_n$ on $2^n$-length strings that have hamming weight at most $1$ in $2^{\frac{n(1-\delta)}{2}}$ time, hence in $2^{\frac{n(1-\delta)}{2}}$ queries. This is not possible because using the quantum adversary method \cite{Ambainis02-QuantumAdversaryMethod} one can show that any quantum algorithm computing $\propertyOR_n$ on these strings requires at least $c \cdot 2^{\frac{n}{2}}$ many queries.

Combining all these observations, we can conclude that $\propertyOR \in \mathcal{CO(\ACarg{2}{2})}$. Therefore, using \Cref{def:COforGeneralComplexityClass},
we get $\propertyOR \in \mathcal{CO(\AC)}$.
\end{proof}

One can use similar arguments to show that $\propertyAND$ is compression-oblivious with respect to $\ACconstDepth$.

\begin{corollary}[Example~6 in \cite{BPS21}]
Let $\propertyAND:\{0,1\}^* \rightarrow \{0,1\}$ be a Boolean property such that $\forall x \in \{0,1\}^*$ the $\propertyAND(x)=1$ if and only if $|x|=\mathsf{len}(x)$. Then $\propertyAND \in \mathcal{CO}(\AC)$. Here $\mathsf{len}(x)$ denotes the length of the binary string $x$.  
\end{corollary}

\begin{lemma}[Fact~15 in \cite{BPS21}]
\label{thm:CompressionObliviousProperties} 
Let $\zeta$ and $\gamma$ be two complexity classes in $\{\AC, \ACconstDepth, \NC, \Ppoly \}$. Furthermore, let $\zeta \subseteq \gamma$, then for every property $\propertyP$, we have $\propertyP \in \mathcal{CO}(\gamma)$ whenever $\propertyP \in \mathcal{CO}(\zeta)$.   
\end{lemma}
\begin{proof}
Without loss of generality, let us assume that $\zeta$ is $\ACconstDepth$.
If a property $\propertyP \in \mathcal{CO}(\ACconstDepth)$ then there exists $d, k \in \mathbb{N}$ such that $\propertyP \in \mathcal{CO}(\ACarg{d}{k})$; see \Cref{def:COforGeneralComplexityClass}. From \Cref{def:SizeableComplexityClass} we know that for every value of $d, k$ we can constructively (by constructing explicit circuits) show that there exists $d',k'$ and $d'',k''$ such that $\ACarg{d}{k} \subseteq \NCarg{d'}{k'} \subseteq \SizeArg{d''}{k''}$. Therefore, any set of hard languages in $\ACconstDepth$ that witnesses that $\propertyP$ is compression-oblivious with respect to $\ACconstDepth$ will also witness that $\propertyP$ is compression-oblivious with respect to $\{\NC, \Ppoly \}$. Therefore, $\propertyP \in \mathcal{CO}(\gamma)$ for any $\gamma \in \{ \NC, \Ppoly\}$. We can make a similar argument for other combinations of $\zeta, \gamma \in \{\ACconstDepth, \NC, \Ppoly \}$ satisfying $\zeta \subseteq \gamma$.
\end{proof}

We saw that properties such as $\propertyOR$ and $\propertyAND$ are compression-oblivious with respect to $\ACconstDepth, \NC, \Ppoly$. One can also construct properties that are not compression-oblivious for any of these complexity classes.

\begin{lemma}[Example~7 in \cite{BPS21}] Consider the following Boolean property $\propertyP_{\mathtt{large-c}}(z)=(\propertyP_{\mathtt{large-c},n}(z))_{n \in \mathbb{N}}$ that for all $z \in \{0,1\}^{2^n}$,
\begin{equation*}
    \propertyP_{\mathtt{large-c},n}(z) = \propertyParity_{n}(z) \land [\text{$\nexists$ circuit $C$ on $n$ inputs of size less than $2^{\frac{n}{100}}$ s.t. $z = \truthtable(C)$}].
\end{equation*}
The property $\propertyP_{\mathtt{large-c}}$ is not compression-oblivious with respect to $\{\ACconstDepth, \NC, \Ppoly\}$.
\end{lemma}
\begin{proof}
First, notice that the query complexity of $\propertyP_{\mathtt{large-c},n}$ is very high; this is because most strings are not a truth table of small circuits, the query complexity of this property is close to the query complexity of $\propertyParity_n$, i.e., $\Q_{1/3}(\propertyP_{\mathtt{large-c}})=\Omega(2^n)$. Moreover, there exists an algorithm $\mathcal{A}$ that can compute $\propertyP_{\mathtt{large-c}}$ in $0$ queries no matter the length of the input: $\mathcal{A}$ always outputs $0$. This fixes $\delta=1$. When $\Lambda=\{\ACconstDepth, \NC, \Ppoly\}$, $\forall n \in \mathbb{N}$, Algorithm $\mathcal{A}$ computes $\propertyP_{\mathtt{large-c}}$ on all strings in $\truthtable( \Lambda, n)$ in constant time. Hence, $\propertyP_{\mathtt{large-c}}$ is not compression-oblivious for $\Ppoly$ or any smaller class of representations.
\end{proof}

Now, moving on to more complexity-theoretic consequences.

\begin{theorem}[Theorem~9 in \cite{BPS21}] If there exists a property $\propertyP=(\propertyP_n)_{n \in \mathbb{N}}$ and constant $p>0$ s.t.\ $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+p}$ and $\propertyP \in \mathsf{polyL}(N)$ and $\propertyP \in \mathcal{CO}(\Ppoly)$, then $\P \neq \PSPACE$. Here $N=2^n$.\footnote{\label{footnote:SlightChangePropertyConditions} Buhrman \textit{et al.}, under their notion of compression oblivious properties proved this theorem for properties $\propertyP=(\propertyP_n)_{n \in \mathbb{N}}$ that are in $\mathsf{polyL}(N)$ and satisfy $\Q_{1/3}(\propertyP_{n}) = \widetilde{\omega}(\sqrt{N})$ but with our proposed definition of compression oblivious we need that the properties satisfy $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+p}$ for some constant $p>0$ that only depends on $\propertyP$.}
\end{theorem}
Here $\mathsf{polyL}(N)$ is the same as $\mathsf{SPACE}(\polylog (N))$, i.e., class of properties $\propertyP$ (or the corresponding languange $L_{\propertyP}$) computable in $\polylog(N)$ amount of space. 
\begin{proof}
We prove the contrapositive of this statement. Let $d, k \in \mathbb{N}$ and let $\Lambda=\SizeArg{d}{k}$. Let $\propertyP=(\propertyP_n)_{n \in \mathbb{N}}$ be a property satisfying $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+p}$ and $\propertyP \in \mathsf{polyL}(N)$ and suppose that $\P =\PSPACE$ then we can show that  $\propertyP \notin \mathcal{CO}(\SizeArg{d}{k})$ for all $d, k \in \mathbb{N}$. Let us first fix a pair $d,k \in \mathbb{N}$, under the assumption of $\P = \PSPACE$ for this $\propertyP$ we show that there exists a $c,n' \in \mathbb{N}$ and we can construct an algorithm $\mathcal{A}$ such that $\forall n>n'$ for all inputs in $\{0,1\}^{N}$ the algorithm $\mathcal{A}$ computes $\propertyP_n$ in a black-box manner in at most $c \cdot d \cdot n^k \cdot \sqrt{N}$ time. (Algorithm $\mathcal{A}$ is basically the oracle identification algorithm of \cite{Kothari14} which can be made time efficient by using $\P=\PSPACE$.) As all the properties $\propertyP$ in consideration have their respective $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+O(1)}$ therefore for each property $\propertyP$ there is corresponding $\delta>0$ such that $c \cdot d \cdot n^k \cdot \sqrt{N} = \Q_{1/3}(\propertyP_n)^{1-\delta}$ for all $n > n'$. 

We can do this for every property $\propertyP = (\propertyP_n)_{n \in \mathbb{N}}$ satisfying $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+O(1)}$ and $\propertyP \in \mathsf{polyL}(N)$. The values of $c, n'$ and $\delta$ differ with each property but the algorithm $\mathcal{A}$ is the same. For the construction of Algorithm $\mathcal{A}$, we refer the reader to the proof of Theorem~9 in \cite{BPS21}. 

As we can do this for every pair $d, k \in \mathbb{N}$ we can (under the assumption of $\P=\PSPACE$) show that $\propertyP \notin \mathcal{CO}(\Ppoly)$. Hence, proved.
\end{proof}

\begin{theorem}[Theorem~10 in \cite{BPS21}] There exists an oracle relative to which the basic-\QSETH{} holds, but any property $\propertyP=(\propertyP_n)_{n \in \mathbb{N}}$ with $\propertyP \in \mathsf{polyL}(N)$ for which $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+O(1)}$ is not compression oblivious with respect to $\Ppoly$, i.e., $\propertyP \notin \mathcal{CO}(\Ppoly)$. Here $N=2^n$.\footnote{See \Cref{footnote:SlightChangePropertyConditions}.}
\end{theorem}
\begin{proof} The idea is to first prove this statement for the complexity class $\SizeArg{d}{k}$ for a fixed pair $d, k \in \mathbb{N}$ and then show that we can repeat the argument for every $d,k \in \mathbb{N}$. Having once chosen a pair $d,k$, we construct the oracle \emph{exactly} as it is constructed in the proof of Theorem~10 in \cite{BPS21}. The only part where our proof differs is in the assumption that $\Q_{1/3}(\propertyP_{n}) = N^{\frac{1}{2}+O(1)}$ instead of $\Q_{1/3}(\propertyP_{n}) = \widetilde{\omega}(\sqrt{N})$ as originally done in the statement of Theorem~10 in \cite{BPS21}; this change makes this theorem true with the definition of compression oblivious properties we propose in this paper. 
\end{proof}




\section{Proofs of \cref{thm:parityIsHardEvenForSmallerSets,thm:majorityAndStrictIsHardEvenForSmallerSets}}
\label{AppSec:ProofsRelevantToSupportingCOassumption}

\begin{lemma}
\label{Appthm:ParityIsHardEvenForSmallerSets}
Let $S\in \{0,1\}^N$ be a subset of size $s\geq 0.8\cdot2^N$. Every quantum algorithm that, with success probability at least $\geq 2/3$, computes $\propertyParity$ on each $x \in S$ uses $\Omega(N)$ queries.
\end{lemma}
\begin{proof}
 Suppose there exists a $T$-query bounded-error quantum algorithm $\mathcal{A}_S$ to compute parity on each $x \in S$ with worst-case error probability $\leq 1/3$. Here, without loss of generality, we assume the output of $\mathcal{A}_S$ is $\in \{-1,1\}$, where $1$ means odd parity and $-1$ means even parity. Let $P(x)$ be the polynomial that represents $\mathcal{A}_S$'s probability of outputting $-1$ on input $x$. Since $\mathcal{A}_S$ has worst-case error probability at most $1/3$ on each $x\in S$, we can immediately see $(1-2P(x))\cdot (-1)^{|x|}\geq 1/3$ for every $x\in S$, where $|x|$ denotes the Hamming weight of $x$.

 Observe that $\text{deg}(P(x))=\text{deg}(1-2P(x))$ and  $\E_{x\in \{0,1\}^N}[(1-2P(x))(-1)^{|x|}]$ is the Fourier coefficient of the degree-$N$ term of $(1-2P(x))$. We obtain
 \begin{align*}
     \E_{x\in \{0,1\}^N}[(1-2P(x))(-1)^{|x|}] =& \frac{1}{2^N}\big(\sum_{x\in S}[(1-2P(x))(-1)^{|x|}]+\sum_{x\in \{0,1\}^N\setminus S}[(1-2P(x))(-1)^{|x|}]\big)\\
     \geq & \frac{1}{2^N}\cdot \big(s/3-(2^N-s) \big)>0,
 \end{align*}
 implying that $\text{deg}(P(x))\geq N$. 
 Then by polynomial method~\cite{BBCMW01},~\footnote{By the polynomial method we know if the amplitudes of the final state are degree-$N$ polynomials of $x$ then we need to make at least $T\geq N/2$ queries.} we immediately obtain $T\geq N/2$.
\end{proof}

\begin{lemma}[Theorem~5.19 in \cite{Ryan21Fourier}]
\label{thm:FourierCoefficientsOfMajority}
Let $N$ be an odd integer and let $\propertyOddMajority:\{0,1\}^N \rightarrow \{0,1\}$ be defined as 
\begin{equation*}
\propertyOddMajority(x)=
    \begin{cases}
    1, & \text{if } |x|>\frac{N}{2},\\
    0, & \text{otherwise},
\end{cases}    
\end{equation*}
where $|x|=|\{i \mid i \in [N] \text{ and } x_i=1\}|$. If the Fourier expansion of $\propertyOddMajority$ is 
\begin{equation*}
\propertyOddMajority(x)=\sum_{B \subseteq \{0,1\}^N} \fourierCoefficients{odd-maj}{B} \chi_{B}(x),
\end{equation*}
where $\chi_{B}(x)=(-1)^{x.B}$, then $\fourierCoefficients{odd-maj}{B}=0$ whenever $|B|==0 \mod 2$ and for $|B|=N$ we have
\begin{equation*}
    \fourierCoefficients{odd-maj}{B}^2=\frac{4}{4^N} {N-1 \choose \frac{N-1}{2}}^2 \geq \frac{6}{\pi (3N-1)} > \frac{2}{\pi N}.
\end{equation*}
\end{lemma}

\begin{lemma}
\label{Appthm:OddMajorityIsHardEvenForSmallerSets}
Let $N$ be an odd integer and let $S \in \{0,1\}^N$ be a subset of size $s \geq 2^N\left(1-\frac{1}{N^{2}}\right)$. Every quantum algorithm that, with error probability $\epsilon \leq \frac{1}{2\cdot N^{2}}$, computes $\propertyOddMajority$ on each $x \in S$ uses $\Omega(N)$ queries.    
\end{lemma}
