\title{Context-Aware CodeLLM Eviction for AI-assisted Coding}


\author{
    \IEEEauthorblockN{Kishanthan Thangarajah\IEEEauthorrefmark{1}, Boyuan Chen\IEEEauthorrefmark{1}, Shi Chang\IEEEauthorrefmark{2},
    Ahmed E. Hassan\IEEEauthorrefmark{3}}
