\section{System Model and Problem Formulation}
\label{sec:SystemModel}

\begin{figure}[t]
	\centering
	\includegraphics[width = 0.45 \textwidth]{figs/Fig01_system.eps}
	\caption{System model.}
	\label{figmodel}
\end{figure}


As shown in Fig. \ref{figmodel}, we consider a secure UAV-aided ISCC system consisting of $K$ single-antenna users ($U_k, k =  {1,2, \cdots, K}$) and a UAV ($S$) acts as an aerial BS. 
To reduce the local computation pressure of latency-sensitive users, we assume that they can partially offload their computation tasks to $ S$ \cite{LeiH2024JMASS}. 
A potential terrestrial single-antenna eavesdropper ($E$) overhears the uplink offloading signals from $U_k$ to $S$. 
At the same time, {$S$ is equipped with two identical uniform planar arrays (UPAs) for transmitting radar signals and receiving signals}  with $M = {M_x} \times {M_y}$ antennas where ${M_x}$ and ${M_y}$ denote the number of elements along the $x$- and $y$- axis, respectively. 
The adjacent antenna elements are separated by half a wavelength.
It is assumed that $S$ flies at a constant altitude $H$, and the total flight time is represented as $T$, which is equally divided into $N$ slots, and each slot with a duration of ${\delta _t} = \frac{T}{N}$ \cite{LeiH2024TCCN3D}, \cite{LeiH2024TCCNmultiUAV}. 
It is also assumed that $S$ has the location information of $U_k$, which is expressed as ${\mathbf{q}}_k = {\left[ {{x_k},{y_k}} \right]^T}$.
{Like \cite{MengH2024TWC}, the location of $E$, which denotes as ${\mathbf q}_e$,  is imperfect, i.e. 
	$ {{\mathbf q}_\Delta } = \left\{ {{{\left[ {{x_e},{y_e}} \right]}^T}|{x_e} \in \left[ {{{\tilde x}_e} - \Delta ,{{\tilde x}_e} + \Delta } \right],{y_e} \in \left[ {{{\tilde y}_e} - \Delta ,{{\tilde y}_e} + \Delta } \right]} \right\}$ are known, where $\left( {{{\tilde x}_e},{{\tilde y}_e}} \right)$ is the location of the center of the range and $\Delta$ represents half of the side length of the range. }
In the $n$-th slot, the horizontal coordinate of $S$ is expressed as  
${\mathbf{q}}_s\left[ n \right] = {\left[ {{x_s}\left[ n \right],{y_s}\left[ n \right]} \right]^T}$, and the Euclidean distance from $S$ to $U_k$ and $E$ are expressed as 
${d_{sk}}\left[ n \right] = \sqrt {\parallel {\mathbf{q}}_s\left[ n \right] - {\mathbf q}_k{\parallel ^2} + {H^2}} $ 
and 
${d_{se}}\left[ n \right] = \sqrt {\parallel {\mathbf{q}}_s\left[ n \right] - {\mathbf{q}}_e{\parallel ^2} + {H^2}} $, respectively.

\subsection{Communication and Sensing Model}


Similar to \cite{LiuP2023TVT}, the ground-to-ground (G2G) channel between $E$ and $U_k$ is characterized as Rayleigh fading model, which is expressed as
\begin{align}\label{hek}
	{h_{ek}} = \sqrt {\frac{{{\beta _0}}}{{\parallel {\mathbf{q}}_k - {\mathbf{q}}_e{\parallel ^2}}}} {\tilde h_{ek}}
\end{align}%$E$到用户的信道
where ${\beta _0}$ denotes the reference channel gain at 1 meter and ${\tilde h_{ek}}  \sim \mathcal{CN}\left( {0,1} \right)$.


Similar to \cite{LyuZ2023TWC}, \cite{WangX2022ComL} and \cite{XuS2025TMC}, we assume that the G2A channel is a LoS link\footnote{
	For the scenarios wherein there is multipath and the channel may experience Rician or Nakagami models, the power gains are random variables. Then, the formulated problem is a stochastic optimization problem \cite{ZhaoC2025ArXiv}. 
	In existing works, like \cite{HuaM2020TCOM}, \cite{LeiH2024TVT}, and \cite{DanQ2025TCCN}, a standard method for stochastic optimization problems is approximated the RVs (power gains) by their expectation, which is the results with LoS model. 
	For the scenarios where the UAV works in a 3D trajectory and the G2A link is probabilistic LoS. 
	Based on the results in \cite{LeiH2024TCCN3D}, the average rate of the cases with probabilistic LoS/NLoS can be approximated as the rate of the cases with LoS model, which denotes the results in this work can be utilized as a benchmark of 3D scenarios.
}. In the $n$-th slot, the channel from $S$ to $U_k$ and $E$ are expressed as
\begin{align}\label{hsk}
	{{\mathbf{h}}_{sk}}\left[ n \right] = \sqrt {\frac{{{\beta _0}}}{{d_{sk}^2\left[ n \right]}}} {{\mathbf{a}}_R}\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_k}} \right]
\end{align}%无人机到用户k的信道
and
\begin{align}\label{hse}
	{{\mathbf{h}}_{se}}\left[ n \right] = \sqrt {\frac{{{\beta _0}}}{{d_{se}^2\left[ n \right]}}} {\mathbf{a}}_T^H\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right],
\end{align}%无人机到$E$的信道
respectively. 

The round-trip channel between $S$ and $E$ is given by 
\begin{align}\label{hses}
	{{\mathbf{h}}_{ses}}\left[ n \right] = \sqrt {\frac{{{\beta _0}\xi }}{{d_{se}^4\left[ n \right]}}} {{\mathbf{a}}_R}\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right]{\mathbf{a}}_T^H\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right]
\end{align} %往返信道
{where  ${\mathbf{a}}_R^H\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_k}} \right] = \left[ {1,{e^{j\pi {\Phi _k}\left[ n \right]}}, \cdots ,{e^{j\pi \left( {{M_x} - 1} \right){\Phi _k}\left[ n \right]}}} \right] \otimes \left[ {1,{e^{j\pi {\Omega _k}\left[ n \right]}}, \cdots ,{e^{j\pi \left( {{M_y} - 1} \right){\Omega _k}\left[ n \right]}}} \right]$,
	${\mathbf{a}}_T^H\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right] = {\mathbf{a}}_R^H\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right] = \left[ {1,{e^{j\pi {\Phi _e}\left[ n \right]}}, \cdots ,{e^{j\pi \left( {{M_x} - 1} \right){\Phi _e}\left[ n \right]}}} \right] \otimes \left[ {1,{e^{j\pi {\Omega _e}\left[ n \right]}}, \cdots ,{e^{j\pi \left( {{M_y} - 1} \right){\Omega _e}\left[ n \right]}}} \right]$ denote the receive steering vector and the transmit steering vector of $S$ antenna array respectively, 
	${\Phi _k}\left[ n \right] = \frac{{{x_s}\left[ n \right] - {x_k}}}{{{d_{sk}}\left[ n \right]}}$,
	${\Omega _k}\left[ n \right] = \frac{{{y_s}\left[ n \right] - {y_k}}}{{{d_{sk}}\left[ n \right]}}$,
	${\Phi _e}\left[ n \right] = \frac{{{x_s}\left[ n \right] - {x_e}}}{{{d_{se}}\left[ n \right]}}$,  
	and 
	${\Omega _e}\left[ n \right] = \frac{{{y_s}\left[ n \right] - {y_e}}}{{{d_{se}}\left[ n \right]}}$, $\xi$ denotes the radar cross-section \cite{MengK2023TWC}. 
}

For effective data offloading among users during the $S$'s flight, a binary variable ${\theta _k}\left[ n \right]$ is employed to represent the scheduling decision, where  ${\theta _k}\left[n\right]= 1 $ denotes that $U_k$ is allocated to communicate with $S$ in the $n$-th time slot.
Thus, we have	
\begin{align}
	\sum\limits_{k = 1}^K {{\theta _k}\left[ n \right] }  \le 1,\forall n, \label{theita1}\\
	{\theta _k}\left[ n \right]  \in \left\{ {0,\left. 1 \right\}} \right.,\forall n,k. \label{theita2}
\end{align}	

{
	To reduce unnecessary energy expenditure, the sensing signals are transmitted only during user offloading periods.
The received signal by $S$ is expressed as
\begin{align}\label{ysk}
	{{\mathbf{y}}_s}\left[ n \right] &= \sum\limits_{k = 1}^K {{\theta _k}\left[ n \right]\sqrt {{P_u}} {{\mathbf{h}}_{sk}}\left[ n \right]{s_k}} \notag \\
	&+ {{\theta _r}\left[ n \right]}{\mathbf{h}_{ses}}\left[ n \right]\mathbf{w}\left[ n \right]{s_r} + {{\mathbf{n}}_s} 
\end{align}%无人机接收到的信号
where ${{\theta _r}\left[ n \right]} = {\sum\limits_{k = 1}^K {{\theta _k}\left[ n \right]} }$,  $P_u$ denotes the transmit power of $U_k$,
${s_k} \in \mathcal{C}\mathcal{N}\left( {0,1} \right)$ represents the uplink offloading signal from $U_k$ to $S$, 
$s_r \in {\cal C}{\cal N}\left( {0,1} \right)$ denotes the radar symbol,
${\mathbf{w}}\left[ n \right] \in {\mathbb{C}^{M \times 1}}$ denotes the precoding vector for detecting, 
	${{\mathbf{n}}_s}\in {\cal C}{\cal N}\left( {0,\sigma _s^2{{\mathbf{I}}_{M \times 1}}} \right)$ denotes additive white Gaussian noise (AWGN) at $S$.
	Then, the worst-case signal-to-interference-plus-noise ratio (SINR) of $S$ for decoding $s_k$ is obtained as 
\begin{align}\label{SINRsk}
	{\gamma _{sk}}\left[ n \right] = \frac{{{P_u}{\theta _k}\left[ n \right]{{\left\| {{{\mathbf{h}}_{sk}}\left[ n \right]} \right\|}^2}}}{{\sum\limits_{i = 1,i \ne k}^K {{\theta _i}\left[ n \right]{{\left\| {{{\bf{h}}_{si}}\left[ n \right]} \right\|}^2}} } + {{\theta _r}\left[ n \right]}{P_{ses}}\left[ n \right] + \sigma _s^2}
\end{align}%无人机接受信息的信干噪比
where  
${P_{ses}}\left[ n \right] = \mathop {\max }\limits_{{{\mathbf{q}}_e} \in {{\mathbf{q}}_\Delta }} \left\{ {{\textrm {tr}}\left( {{{\mathbf{h}}_{ses}}\left[ n \right]{\mathbf{W}}\left[ n \right]{\mathbf{h}}_{ses}^H\left[ n \right]} \right)} \right\}$,
${\mathbf{W}}\left[ n \right] = {\mathbf{w}}\left[ n \right]{{\mathbf{w}}^H}\left[ n \right] $. The offloading rate of $U_k$ is expressed as
\begin{align}\label{R_sk0}
	{R_{sk}}\left[ n \right] = {\log _2}\left( {1 + \gamma _{sk}\left[ n \right]} \right).
\end{align}%无人机可达信息速率
The received signal by $E$ is expressed as
\begin{align}
	{{{y}}_e}\left[ n \right] = \sum\limits_{k = 1}^K {{\theta _k}\left[ n \right]\sqrt {{P_u}} {{{h}}_{ek}}{s_k}}  +  {{\theta _r}\left[ n \right]} {\mathbf{h}_{se}}\left[ n \right]\mathbf{w}\left[ n \right]{s_r} + {n_e} 
\end{align}
where 
${n_e} \in \mathcal{CN}\left( {0,\sigma _e^2} \right)$ denotes AWGN at $E$.
The SINR for $E$ to wiretap the signal from $U_k$ is obtained as 
{\small{\begin{align}\label{SINRek}
			{\gamma _{ek}}\left[ n \right] = \frac{{{P_u}{\theta _k}\left[ n \right]{{\left| {{h_{ek}}} \right|}^2}}}{{\sum\limits_{i = 1,i \ne k}^K {{\theta _i}\left[ n \right]{{\left| {{{{h}}_{ei}}\left[ n \right]} \right|}^2}} } + {{\theta _r}\left[ n \right]}{{\mathbf{h}}_{se}}\left[ n \right]{\mathbf{W}}\left[ n \right]{\mathbf{h}}_{se}^H\left[ n \right] + \sigma _e^2}.
		\end{align}%窃听者接受信息的信干噪比}
}
It must be noted that since ${h_{ek}}$ is a random variable, ${\gamma _{ek}}\left[ n \right]$ is a random variable. Thus, with the method in Refs. \cite{HuaM2020TCOM}, \cite{LeiH2024TVT}, and \cite{DanQ2025TCCN}, ${\gamma _{ek}}\left[ n \right]$ is approximated as 
\begin{align}
	{\bar \gamma _{ek}} \left[ n \right] & = \frac{{{P_u}{\theta _k}\left[ n \right]{\mathbb{E}}\left\{ {{{\left| {{h_{ek}}} \right|}^2}} \right\}}}{{\sum\limits_{i = 1,i \ne k}^K {{\theta _i}\left[ n \right]{{\left| {{{{h}}_{ei}}\left[ n \right]} \right|}^2}} } + {{\theta _r}\left[ n \right]}{{\mathbf{h}}_{se}}\left[ n \right]{\mathbf{W}}\left[ n \right]{\mathbf{h}}_{se}^H\left[ n \right] + \sigma _e^2} \notag	\\
	&= \frac{{{{P_u}{\theta _k}\left[ n \right]{\beta _0}} \parallel {{\mathbf q}_k} - {{\mathbf q}_e}{\parallel ^{-2}}}}{{\sum\limits_{i = 1,i \ne k}^K {{\theta _i}\left[ n \right]{{\left| {{{{h}}_{ei}}\left[ n \right]} \right|}^2}} } +  {{{\theta _r}\left[ n \right]}{{\mathbf{h}}_{se}}\left[ n \right]{\mathbf{W}}\left[ n \right]{\mathbf{h}}_{se}^H\left[ n \right] + \sigma _e^2}}.
\end{align}	
The worst-case eavesdropping rate of $E$ is 
\begin{align}
	{R_{ek}}\left[ n \right] = \mathop {\max }\limits_{{{\mathbf{q}}_e} \in {{\mathbf{q}}_\Delta }} \left\{ {{{\log }_2}\left( {1 + {{\bar \gamma }_{ek}}}\left[ n \right] \right)} \right\}.
\end{align}}

The objective of the sensing is target parameter estimation, and the transmit beampattern gains are adopted as the metric for sensing performance. 
To meet the requirement of detecting, the following constraint should be satisfies \cite{HuangL2020TMC},
\begin{align}\label{sensing_requirement}
	{{\theta _r}\left[ n \right]}P\left[ n \right] \ge {{\theta _r}\left[ n \right]}d_{se}^2\left[ n \right]{\Gamma _{{\textrm {sen}}}},\forall n,\forall {{\mathbf{q}}_e} \in {{\mathbf{q}}_\Delta }
\end{align}%波束图增益约束
where ${\Gamma _{\textrm {sen}}}$ is a perceived threshold and $P\left[ n \right]$ denotes the transmit beampattern gain from $S$ to $E$, which is expressed as \cite{MengK2022WCL}, \cite{StoicaP2007Trans}
\begin{align}\label{beampatterngain}
	P\left[ n \right] = {{\mathbf{a}}_T^H}\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right]{\mathbf{W}}\left[ n \right]{\mathbf{a}}_T\left[ {{{\mathbf{q}}_s}\left[ n \right],{{\mathbf{q}}_e}} \right].
\end{align}%波束图增益
}

\subsection{Computing Model}

We assume that $U_k$ has ${D_k}$ (bit) computational task in total and these data can be divided into any amount of data to deal with. All the tasks are required to be completed within flight time $T$. 
Like \cite{LeiH2024JMASS}, since the data of the computation result is very small, the delay and energy consumption of back transmission can be ignored. 
In the $n$-th time slot, we define ${\alpha _k}\left[ n \right] \in \left[ {0,1} \right]$ as the proportion of data offloaded by $U_k$, which signifies that 
$\sum\limits_{n = 1}^N {{\alpha _k}\left[ n \right]}  \leqslant 1,\forall k$. 
Thus the proportion computation locally at $U_k$ is expressed as
$1 - \sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]{\alpha _k}\left[ n \right]} $.
The computing time and energy consumption at $U_k$ are given by \cite{ChenC2024WCL}
\begin{align}\label{T_{loc}}
	T_k^{\textrm {loc}} = \left( {1 - \sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]{\alpha _k}\left[ n \right]} } \right){D_k}{F_k}/{f_k}
\end{align}%用户本地计算时延
and
\begin{align}\label{E_{loc}}
	{E}_k^{\textrm {loc}} = \kappa \left( {1 - \sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]{\alpha _k}\left[ n \right]} } \right){D_k}{F_k}f_k^2
\end{align}%用户本地计算能耗
where 
${F_k}$ (cycles/bit) is the required CPU cycles per bit at $U_k$, 
${f_k}$ (cycles/s) represents the local computing capacity for the task at $U_k$, 
and 
$\kappa$ denotes the energy efficiency coefficient of the CPU at $U_k$ \cite{HuangL2020TMC}.

The time and the offloading energy consumption required for the $U_k$ in slot $n$ are expressed as
\begin{align}\label{T_off}
	T_k^{\textrm{{offload}}}\left[ n \right] = \frac{{\theta _k}\left[ n \right] {{\alpha _k}\left[ n \right]{D_k}}}{{B{{\hat R}_{sk}}\left[ n \right]}}
\end{align}%用户卸载时延
and
\begin{align}\label{E_off}
	{E}_k^{\textrm{{offload}}}\left[ n \right] = \frac{{{P_u}{\theta _k}\left[ n \right] {\alpha _k}\left[ n \right]{D_k}}}{{B{{\hat R}_{sk}}\left[ n \right]}}
\end{align}%用户卸载能耗
respectively, 
where $B$ denotes the channel bandwidth and 
${\hat R_{sk}}\left[ n \right] = {\log _2}\left( {1 + \frac{{{P_u}{{\left\| {{{\mathbf{h}}_{sk}}\left[ n \right]} \right\|}^2}}}{{{{\theta _r}\left[ n \right]}{P_{ses}}\left[ n \right] + \sigma _s^2}}} \right)$.
%$T_k^{\textrm{{offload}}}\left[ n \right] = 0$, ${E}_k^{\textrm{{offload}}}\left[ n \right] = 0$ if ${\theta _k}\left[ n \right] = 0$.
The time and energy consumption at $S$ to deal with the offloaded data from $U_k$ in the $n$-th time slot are expressed as 
\begin{align}\label{T_{com}}
	T_k^{\textrm {com}}\left[ n \right] = {\alpha _k}\left[ n \right]{D_k}{F_s}/{f_s}
\end{align}%无人机计算时延
and
\begin{align}\label{E_{com}}
	{E}_k^{\textrm {com}}\left[ n \right] = \kappa {\alpha _k}\left[ n \right]{D_k}{F_s}f_s^2,
\end{align}%无人机计算能耗
respectively, 
where
${F_s}$ (cycles/bit) is the required CPU cycles per bit and 
${f_s}$ (cycles/s) represents the computing capacity for the task at $S$.

To ensure that data offloaded in the $n$-th time slot can be fully dealt with, the following constraint must be satisfied \cite{LeiC2025JSAC}, \cite{BiS2018TWC},
\begin{align}\label{OneTimeSlot}
	\left( {T_k^{\textrm {offload}}\left[ n \right] + T_k^{\textrm {com}}\left[ n \right]} \right){\theta _k}\left[ n \right] \leqslant {{\theta _k}\left[ n \right]}{\delta _t},\forall n,k.
\end{align}%单时隙要求

The total energy consumption of $U_k$ and $S$ are expressed as 
\begin{align}\label{E_user}
	{{E}_k} = {E}_k^{\textrm {loc}} + \sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]{E}_k^{\textrm {offload}}\left[ n \right]}
\end{align}%用户总能耗
and
\begin{align}\label{E_UAV}
	{{E}_S} = {{E}_{\textrm {fly}}} + {{E}_{\textrm {sen}}} + \sum\limits_{k = 1}^K {\sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]E_k^{\textrm {com}}\left[ n \right]} },
\end{align}%无人机总能耗
respectively,
where 
${{E}_{\textrm {sen}}} = \sum\limits_{n = 1}^N {{\delta _t}\textrm {tr}} \left( {{\mathbf{W}}\left[ n \right]} \right)$ 
and  
${{E}_{\textrm {fly}}} = \sum\limits_{n = 1}^N {{\delta _t}{P_{\textrm {fly}}}\left[ n \right]}  $ denote the energy consumption for sensing and propulsion, respectively, % is expressed as 
%\begin{align}\label{P_UAV}
	${P_{\textrm{{fly}}}}\left[ n \right]  =  {P_{\rm i}}{\left( {\sqrt {1 + \frac{{{v ^4}\left[ n \right]}}{{4v _0^4}}}  - \frac{{{v ^2}\left[ n \right]}}{{2v _0^2}}} \right)^{\frac{1}{2}}} + \frac{1}{2}{d_0}\rho sA{v ^3}\left[ n \right] + {P_{\rm b}}\left( {1 + \frac{{3{v ^2}\left[ n \right]}}{{U_{\rm tip}^2}}} \right) $ denotes the propulsion power of $S$, 
%\end{align}%无人机推进功率
%where 
$v\left[ n \right] = \frac{{\left\| {{{\mathbf{q}}_s}\left[ {n + 1} \right] - {{\mathbf{q}}_s}\left[ n \right]} \right\|}}{{{\delta _t}}}$ denotes the speed of $S$, 
${P_{\rm b}}$ and ${P_{\rm i}}$ denote the blade profile and the induced power in hover state, 
${U_{\rm tip}}$ signifies the tip velocity of the rotor blade, 
${v_0}$ denotes the mean rotor induced speed in hover, 
${d_0}$, $\rho $, $s$, and $A$ represent the drag ratio of the fuselage, the air density, solidity of the rotor and rotor disc area, respectively \cite{ZengY2019TWC}.

\subsection{Problem Formulation}

{In this work, like \cite{DingC2022JSAC}, the total energy consumption for all users is minimized with respect to user offloading ratio, user scheduling, transmit beamforming, and UAV trajectory\footnote{This assumption is important for the scenarios wherein the user's battery capacity is limited and charging facilities are scarce.}. }
Let 
${{\mathbf A}} = \left\{ {{\alpha _k}\left[ n \right],\forall k,n} \right\}$,
${{\mathbf B}} = \left\{ {{\theta _k}\left[ n \right],\forall k,n} \right\}$,
${\mathbf {\tilde W}} = \left\{ {{\mathbf w}\left[ n \right],\forall n} \right\}$ and 
${{\mathbf{Q}}_s} = \left\{ {{{\mathbf{q}}_s}\left[ n \right],\forall n} \right\}$.
Therefore, we have the following optimization problem
\begin{subequations}\label{Opt}
	\begin{align}
		\mathcal{P}_{0} \,:\,&\mathop {\min}\limits_{{{\mathbf A}},{{\mathbf B}},{\mathbf {\tilde W}},{{\mathbf{Q}}_s}} \sum\limits_{k = 1}^K {{{E}_k}}    \label{Opta} \\
		{\mathrm{s.t.}}\; &{\theta _k}\left[ n \right] \in \left\{ {0,1} \right\},\forall k,n \label{Optb} \\
		&\sum\limits_{k = 1}^K {{\theta _k}\left[ n \right]}  \leqslant 1,\forall n  \label{Optc}\\
		&{\alpha _k}\left[ n \right] \in \left[ {0,1} \right],\forall k,n \label{Optd} \\
		&\sum\limits_{n = 1}^N {{\alpha _k}\left[ n \right]}  \leqslant 1,\forall k \label{Opte} \\
		&{{\mathbf q}_s}\left[ 1 \right] = {\mathbf q}_s^0,{{\mathbf q}_s}\left[ N \right] = {\mathbf q}_s^F  \label{Optf} \\
		&\left\| {{\mathbf{q}}_s\left[ {n + 1} \right] - {\mathbf{q}}_s\left[ n \right]} \right\| \leqslant {\delta _t}{V_{\max }},\forall n \label{Optg} \\
		&{\gamma _{sk}}\left[ n \right] \geqslant {\theta _k}\left[ n \right]{\Gamma _s},\forall k,n \label{Opth} \\
		&{\bar \gamma _{ek}}\left[ n \right] \leqslant {\theta _k}\left[ n \right]{\Gamma _e},\forall k,n,\forall {{\mathbf{q}}_e} \in {{\mathbf{q}}_\Delta }\label{Opti} \\
		&{\mathop{\textrm {tr}}\nolimits} \left( {{\mathbf{W}}\left[ n \right]} \right) \le {P_{\max }},\forall n \label{Optj} \\
		&{E_S} \leqslant {E_{\max }} \label{Optk} \\
		&(\textrm{\ref{sensing_requirement}}),(\textrm{\ref{OneTimeSlot}})  \label{Optl}
	\end{align}%优化问题
\end{subequations}
where 
${\mathbf q}_s^0$ and ${\mathbf q}_s^F$ signify the initial position and the final position of $S$, respectively, 
${V_{\max }}$ denotes the maximum velocity of $S$, 
${\Gamma _s}$ and ${\Gamma _e}$ denote the threshold for communication, eavesdropping, respectively, 
and  ${\Gamma _{\textrm{{sen}}}}$ denotes the threshold for sensing, 
${P_{\max }}$ denotes the maximum transmitting power of $S$, 
and  
${E_{\max }}$ is $S$'s battery capacity. 
(\ref{Optb}) and (\ref{Optc}) are the user scheduling constraints, 
(\ref{Optd}) and (\ref{Opte}) are the constraints on offloading ratio,
(\ref{Optf}) and (\ref{Optg}) denote constraints on trajectory of $S$,
(\ref{Opth}) and (\ref{Opti}) represent the requirements of secure communication, 
(\ref{Optj}) signifies the constraint on transmission power in each time slot, 
and 
(\ref{Optk}) represents the total energy of UAV constraint. 


It can be observed that $\mathcal{P}_{0}$ is difficult to solve by the traditional algorithm. First, the objective function is a function of $\mathbf A$, $\mathbf B$, $\mathbf {{\tilde{W}}}$, and ${\mathbf Q}_s$, which is too complex to determine the concavity and convexity. 
Second,  (\textrm{\ref{sensing_requirement}}),  (\textrm{\ref{OneTimeSlot}}), (\ref{Opth}) and (\ref{Opti}) are non-convex since the strong coupling of $\mathbf {{\tilde{W}}}$ and ${\mathbf Q}_s$. 
Third, the non-convexity of (\ref{Optk}) stems from the complexity of ${{E}_S}$, which violates the convexity constraint. Consequently, directly solving the original problem $\mathcal{P}_{0}$ proves to be mathematically intractable.


\section{Proposed Solution}
\label{sec:proposed solution}


To solve $\mathcal{P}_{0}$, alternating optimization method is utilized to optimize user offloading ratio ${{\mathbf{A}}}$, user scheduling  ${{\mathbf{B}}}$, transmit beamforming ${{\mathbf{\tilde  W}}}$, and $S$ trajectory ${{\mathbf{Q }}_s}$ in an alternating way, by considering the others to be given.

\subsection{Subproblem 1: Offloading Proportion Optimization}
In this subsection, ${\mathbf A}$ is optimized with given  
$\left\{ {{\mathbf B},{\mathbf {\tilde W}},{\mathbf{Q}}_s} \right\}$. 
$\mathcal{P}_{0}$ is rewritten as 
\begin{subequations}\label{Opt1.1}
	\begin{align}
		\mathcal{P}_{1.1} \,:\,&\mathop {\min} \limits_{{{\mathbf A}}} \sum\limits_{k = 1}^K {{{E}_k}}    \label{Opt1.1a} \\
		{\mathrm{s.t.}}\; & (\textrm{\ref{OneTimeSlot}}), (\textrm{\ref{Optd}}), (\textrm{\ref{Opte}}), (\textrm{\ref{Optk}}).  \nonumber
	\end{align}%子优化问题1
\end{subequations}
$\mathcal{P}_{1.1}$ is a linear programming (LP), which can be solved by existing optimization tools such as CVX.

\subsection{Subproblem 2: User Scheduling Optimization}
In this subsection, ${\mathbf B}$ is optimized with given 
$\left\{ {{\mathbf A},{\mathbf {\tilde W}},{\mathbf Q}_s} \right\}$. 
Firstly, like \cite{LeiH2024TCCN3D}, ${\theta _k}\left[ n \right]$ is relaxed into a continuous variable, ranging from 0 to 1, to restrain this binary constraint. Then, ${\mathcal{P}_{0}}$ is expressed as 
\begin{subequations}\label{Opt2.1}
	\begin{align}
		{\mathcal{P}_{2.1}}:&\mathop {\min}\limits_{{{\mathbf B}}} \sum\limits_{k = 1}^K {{{E}_k}}     \label{Opt2.1a} \\
		{\mathrm{s.t.}}\;&(\textrm{\ref{sensing_requirement}}), (\textrm{\ref{OneTimeSlot}}), (\textrm{\ref{Optb}}), (\textrm{\ref{Optc}}), (\textrm{\ref{Opth}}), (\textrm{\ref{Opti}}), (\textrm{\ref{Optk}}).   \nonumber %\label{Opt2.1b}
	\end{align}%子优化问题2
\end{subequations}
${\mathcal{P}_{2.1}}$ is a linear programming problem, which can be solved by CVX.


\subsection{Subproblem 3: Transmit Beamforming Optimization} 
In this subsection, ${\mathbf {{\tilde{W}}}}$ is optimized with given $\left\{ {\mathbf A},{{\mathbf B},{\mathbf{Q}}_s} \right\}$. 
%{\color{red}removing the operator [x]+ does not affect the optimal value of P1 because the secrecy rate can be obtained by setting the transmit power to zero when it is less than zero.}
Based on (\ref{E_user}), one can find that ${E}_k^{\textrm {loc}}$ is a constant for given ${\mathbf A}$ and ${\mathbf B}$. Thus, ${\mathcal{P}_{0}}$ is rewritten as 
\begin{subequations}\label{Opt3.1}
	\begin{align}
		{\mathcal{P}_{3.1}}:&\mathop {\min }\limits_{\mathbf {\tilde W}} \sum\limits_{k = 1}^K {\sum\limits_{n = 1}^N {{\theta _k}\left[ n \right]E_k^{\textrm {offload}}\left[ n \right]} }    \label{Opt3.1a} \\
		{\mathrm{s.t.}}\;&{\mathbf{W}}\left[ n \right] \succeq 0  \label{Opt3.1b} \\
		& {\textrm {rank}}\left( {{\mathbf{W}}\left[ n \right]} \right) = 1  \label{Opt3.1c} \\
		&(\textrm{\ref{sensing_requirement}}),  (\textrm{\ref{OneTimeSlot}}), (\textrm{\ref{Opth}}) - (\textrm{\ref{Optk}}). \nonumber 
	\end{align}%子优化问题3.1 
\end{subequations}
It should be noted that the objective function is non-convex with respect to ${\mathbf{\tilde W}}\left[ n \right]$.
To solve it, a slack variable ${\eta _k}\left[ n \right]$ is introduced which is satisfied the following constraint
\begin{align}\label{E_Q}
	{\eta _k}\left[ n \right] \ge {\theta _k}\left[ n \right]E_k^{\textrm {offload}}\left[ n \right] = \frac{{{P_u}{c_k}\left[ n \right]}}{{{{\hat R}_{sk}}\left[ n \right]}}
\end{align}%优化问题3的目标函数约束
{where 
	${c_k}\left[ n \right] = \frac{{{\theta _k}\left[ n \right]{\alpha _k}\left[ n \right]{D_k}}}{B}$.
	Moreover, ${{\hat R}_{sk}}\left[ n \right]$ is rewritten as ${{\hat R}_{sk}}\left[ n \right] = {\log _2}\left( {1 + \frac{{{P_u}{{\left\| {{{\mathbf h}_{sk}}\left[ n \right]} \right\|}^2}}}{{{X_{w1}}\left[ n \right]}}} \right)$, where 
