	\label{E_Q2}
\end{align}
It should be noted that (\ref{E_Q2}) is non-convex with respect to ${\mathbf {\tilde{W}}}$ since the left-hand side of it is convex but not concave.
To tackle this problem, the first-order Taylor expansion is utilized to transform (\ref{E_Q2}) into (\ref{E_QT}),
where ${\left(  \cdot  \right)^{\left( m \right)}}$ denotes a given feasible point in the $m$-th iteration.
\begin{align}\label{E_QT}
	&{\log _2}\left( {1 + \frac{{{P_u}{{\left\| {{{\mathbf h}_{sk}}\left[ n \right]} \right\|}^2}}}{{X_{w1}^{\left( m \right)}\left[ n \right]}}} \right) - \notag \\
	& \frac{{{P_u}{{\left\| {{{\mathbf h}_{sk}}\left[ n \right]} \right\|}^2}\left( {{X_{w1}}\left[ n \right] - X_{w1}^{\left( m \right)}\left[ n \right]} \right)}}{{\ln 2\left( {{{\left( {X_{w1}^{\left( m \right)}\left[ n \right]} \right)}^2} + X_{w1}^{\left( m \right)}\left[ n \right]{P_u}{{\left\| {{{\mathbf h}_{sk}}\left[ n \right]} \right\|}^2}} \right)}} \geqslant \frac{{{P_u}{c_k}\left[ n \right]}}{{{\eta _k}\left[ n \right]}}
\end{align}%优化问题3的目标函数约束一届泰勒展开

By ignoring the rank-one constraint, ${\mathcal{P}_{3.1}}$ is converted to 
\begin{subequations}\label{Opt3.2}
	\begin{align}
		{\mathcal{P}_{3.2}}:&\mathop {\min }\limits_{{\mathbf{\tilde W}},{\eta _k}\left[ n \right]} \sum\limits_{k = 1}^K {\sum\limits_{n = 1}^N {{\eta _k}\left[ n \right]} }      \label{Opt3.2a} \\
		{\mathrm{s.t.}}\;&{\mathbf{W}}\left[ n \right] \succeq 0  \label{Opt3.2b} \\
		&{\eta _k}\left[ n \right] \geqslant 0 \label{Opt3.2c} \\
		&(\textrm{\ref{sensing_requirement}}),  (\textrm{\ref{OneTimeSlot}}), (\textrm{\ref{Opth}}) - (\textrm{\ref{Optk}}), (\textrm{\ref{E_QT}}).  \nonumber
	\end{align}%子优化问题3.2
\end{subequations}
${\mathcal{P}_{3.2}}$ is a semidefinite programming (SDP) problem, which can be solved with CVX. 
Subsequently, some technologies, such as the Gaussian randomization, singular value decomposition, or the similar method proposed in \cite{DanQ2025TVT}, can be utilized to solve the rank-one constraint.


