${\mathcal{P}_{4.2}}$ is a convex problem and can be solved by existing optimization tools such as CVX.}

\begin{algorithm}[t]

	\caption{Iterative Procedure of $\mathcal{P}_{0}$}
	\label{algorithm1}
	\KwIn{
		{Initialize ${P_{u}}$, ${{\bf{Q}}_s}$, $\Delta$, $K$, $\alpha$, $\theta$, and ${\mathbf{w}}$.}
	}
	\Do{$E\left( {{\mathbf A}^{\left( {m} \right)},{\mathbf B}^{\left( {m} \right)},{{\mathbf {\tilde{W}}}^{\left( {m} \right)}},{\mathbf Q}_s^{\left( {m} \right)}} \right) - E\left( {{\mathbf A}^{\left( {m-1} \right)},{\mathbf B}^{\left( {m-1} \right)},{{\mathbf {\tilde{W}}}^{\left( {m-1} \right)}},{\mathbf Q}_s^{\left( {m-1} \right)}} \right) \succ \varepsilon $}
	{   1. Obtain the solution ${\mathbf A}^{\left( {m + 1} \right)}$ by solving ($\mathcal{P}_{1.1}$) for given $\left\{ {{\mathbf B}^{\left( m \right)},{{\mathbf {\tilde{W}}}^{\left( m \right)}},{\mathbf Q}_s^{\left( m \right)}} \right\}$;\\
		2. Obtain the solution ${\mathbf B}^{\left( {m + 1} \right)}$ by solving ($\mathcal{P}_{2.1}$) for given $\left\{ {{\mathbf A}^{\left( {m + 1} \right)},{{\mathbf {\tilde{W}}}^{\left( m \right)}},{\mathbf Q}_s^{\left( m \right)}} \right\}$;\\
		3. Obtain the solution ${{\mathbf {\tilde{W}}}^{\left( {m + 1} \right)}}$ by solving ($\mathcal{P}_{3.2}$) for given $\left\{ {{\mathbf A}^{\left( {m + 1} \right)},{\mathbf B}^{\left( {m + 1} \right)},{\mathbf Q}_s^{\left( m \right)}} \right\}$;\\
		4. Obtain the solution ${\mathbf Q}_s^{\left( {m + 1} \right)}$ by solving ($\mathcal{P}_{4.2}$) for given $\left\{ {{\mathbf A}^{\left( {m + 1} \right)},{\mathbf B}^{\left( {m + 1} \right)},{{\mathbf {\tilde{W}}}^{\left( {m + 1} \right)}}} \right\}$;\\
		5. $m = m + 1$;
		%6. Compute the objective value $E\left( {{\mathbf A}^{\left( m \right)},{\mathbf B}^{\left( m \right)},{{\mathbf {\tilde{W}}}^{\left( m \right)}},{\mathbf Q}_s^{\left( m \right)}} \right)$.
	}
	\KwOut{${\mathbf A}^{\left( m \right)}$, ${\mathbf B}^{\left( m \right)}$, $ {{\mathbf {\tilde{W}}}^{\left( m \right)}}$, $ {\mathbf Q}_s^{\left( m \right)}$}
\end{algorithm}

