	\\	\ \scalam!Send[$p$, $q$, (($t_1$, $L_1$), $\ldots$, ($t_n$, $L_n$))]!, & $pq \send \famxx{t_i \pre L_i}{1 \leq i \leq n}$,
	\\	\ \scalam!Recv[$p$, $q$, (($t_1$, $L_1$), $\ldots$, ($t_n$, $L_n$))]!, & $pq \recv \famxx{t_i \pre L_i}{1 \leq i \leq n}$,
	\\	\ \scala!End!, \scalam!Loop[$X$, $L$]!, \scalam!Recur[$X$]! & $\one$, $\recx{X} \pre L$, $X$
	\\	%\midrule
		\textbf{Processes}
	\\	\ \scalam!$x$.send($q$, $e$, (_) => $P$)!, & $x\atx{pq} \send e$,
	\\	\ \scalam!$x$.recv($p$, (($x_1$: $t_1$, _) => $P_1$, $\ldots$, ($x_n$: $t_n$, _) => $P_n$))!, & $x \atx{pq} \recv \famxx{x_i \isa t_i \pre P_i}{1 \leq i \leq n}$,
	\\	\ \scalam!$x$.loop((recur, _) => $P$)!, \scalam!recur($x$)! & $\loopx[x]{P}$, $\recur[x]$
	\\	\bottomrule
	\end{tabular}

	\caption{Correspondence between \tool (left) and MPST theory (right)}
	\label{fig:relation}
\end{figure}

\autoref{fig:relation} (top rows) shows the correspondence between global types
in \tool and in MPST theory. In \tool, each global type $G$ is built from
classes \scala!Com!, \scala!End!, \scala!Loop!, and \scala!Recur!. The third
type parameter of \scala!Com! is an $n$-ary product type, called ``the
branches''. Type parameter $X$ of \scala!Loop! is bound in type parameter $G$ to
the whole \scalam!Loop[$X$, $G$]!, to embed a recursive type. Each role $p$ or
$q$, and each recursion variable $X$, is a Scala \textit{string literal type}
(e.g., \scalatype!"foo"! is a type with one inhabitant, \scala!"foo"!). Each
data type $t$ is a Scala type.

