  Com[P, Q, ((Propose,
    Loop["X",
      U[Q, P,
        U[P, Q, Recur["X"]]]]))]
		\end{lstlisting}
	\end{minipage}%
	\hfill%
	\begin{minipage}[t]{\linewidth*4/7-2mm}
