			\text{ and }
				\varGamma, x \typed L_j \vdash P
			\text{, for some } j \in I
			}{
				\varGamma, x \typed pq \send \famxx{t_i \pre L_i}{i \in I} \vdash x \atx{pq} \send e \pre P
			}
