			}{
				\varGamma, x \typed pq \recv \famxx{t_i \pre L_i}{i \in I}) \vdash x \atx{pq} \recv \famxx{x_i \isa t_i \pre P_i}{i \in I}
			}
		\qquad
			\rulexxx{Unfold}{
				\varGamma, x \typed L [\recx{X} \pre L / X] \vdash P
			}{
