This paper consists of five sections. The second section introduces the method for calculating the determinant of $k$-CM, which is essential for inversion. The third section presents the fast algorithms for inverting $k$-CM while the fourth section is for $k$-CBM. The final section summarizes the work of the entire paper.

\section{Determinants of $k$-diagonal circulant matrices \label{s2}}

In this section, we take $k=5$ and $n > 8$ as an example and provide a general formula applicable to all $k$ at the end. This is the necessary preparation for calculating the inverse of $k$-CM.

Firstly, we can transform a $k$-CM $M$ into $M'$ as in Eq.\ref{M'} by swapping its columns. We have $\begin{vmatrix}M\end{vmatrix} = (-1)^{2n-4} \begin{vmatrix}M'\end{vmatrix} = \begin{vmatrix}M'\end{vmatrix}$. In subsequent calculations, we will no longer categorize based on the swapped versions of the matrix.
\begin{equation}
\setcounter{MaxMatrixCols}{20}
\label{M'}
M' = 
\begin{bmatrix}
	x_{5} & 0 & 0 & \cdots & 0 & x_{1} & x_{2} & x_{3} & x_{4}\\
	x_{4} & x_{5} & 0 & 0 & \cdots & 0 & x_{1} & x_{2} & x_{3}\\
	x_{3} & x_{4} & x_{5} & 0 & 0 & \cdots & 0 & x_{1} & x_{2}\\
	x_{2} & x_{3} & x_{4} & x_{5} & 0 & 0 & \cdots & 0 & x_{1}\\
	x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0 & 0 & \ddots & 0\\
	\vdots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \vdots\\
	0 & \cdots & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0\\
	0 & 0 & \cdots & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5}
\end{bmatrix}_{n*n}.
\end{equation}
Next, we use the first column of the matrix $M'$ to set other elements of the first row of $M'$ to 0, as shown locally in Eq.\ref{xy}.
\begin{equation}
\label{xy}
\renewcommand\arraystretch{1.3}
\begin{bmatrix}
	x_{5} & \cdots & y_{11} & y_{12} & y_{13} & y_{14}\\
	x_{4} & \cdots & y_{21} & y_{22} & y_{23} & y_{24}\\
	x_{3} & \cdots & y_{31} & y_{32} & y_{33} & y_{34}\\
	x_{2} & \cdots & y_{41} & y_{42} & y_{43} & y_{44}\\
	x_{1} & \cdots & 0 & 0 & 0 & 0\\
	\vdots & \ddots  & \vdots & \vdots & \vdots & \vdots
\end{bmatrix}
\Longrightarrow 
\begin{bmatrix}
	x_{5} & \cdots & 0 & 0 & 0 & 0\\
	x_{4} & \cdots & y_{21}-\frac{y_{11}x_{4}}{x_{5}} & y_{22}-\frac{y_{12}x_{4}}{x_{5}} & y_{23}-\frac{y_{13}x_{4}}{x_{5}} & y_{24}-\frac{y_{14}x_{4}}{x_{5}}\\
	x_{3} & \cdots & y_{31}-\frac{y_{11}x_{3}}{x_{5}} & y_{32}-\frac{y_{12}x_{3}}{x_{5}} & y_{33}-\frac{y_{13}x_{3}}{x_{5}} & y_{34}-\frac{y_{14}x_{3}}{x_{5}}\\
	x_{2} & \cdots & y_{41}-\frac{y_{11}x_{2}}{x_{5}} & y_{42}-\frac{y_{12}x_{2}}{x_{5}} & y_{43}-\frac{y_{13}x_{2}}{x_{5}} & y_{44}-\frac{y_{14}x_{2}}{x_{5}}\\
	x_{1} & \cdots & -\frac{y_{11}x_{1}}{x_{5}} & -\frac{y_{12}x_{1}}{x_{5}} & -\frac{y_{13}x_{1}}{x_{5}} & -\frac{y_{14}x_{1}}{x_{5}}\\
	\vdots & \ddots  & \vdots & \vdots & \vdots & \vdots
\end{bmatrix}.
\end{equation}
Meanwhile, another equation is very important, as shown in Eq.\ref{xty}.
\begin{equation}
\label{xty}
\renewcommand\arraystretch{1.3}
\begin{bmatrix}
	y_{21}-\frac{y_{11}x_{4}}{x_{5}} & y_{22}-\frac{y_{12}x_{4}}{x_{5}} & y_{23}-\frac{y_{13}x_{4}}{x_{5}} & y_{24}-\frac{y_{14}x_{4}}{x_{5}}\\
	y_{31}-\frac{y_{11}x_{3}}{x_{5}} & y_{32}-\frac{y_{12}x_{3}}{x_{5}} & y_{33}-\frac{y_{13}x_{3}}{x_{5}} & y_{34}-\frac{y_{14}x_{3}}{x_{5}}\\
	y_{41}-\frac{y_{11}x_{2}}{x_{5}} & y_{42}-\frac{y_{12}x_{2}}{x_{5}} & y_{43}-\frac{y_{13}x_{2}}{x_{5}} & y_{44}-\frac{y_{14}x_{2}}{x_{5}}\\
	-\frac{y_{11}x_{1}}{x_{5}} & -\frac{y_{12}x_{1}}{x_{5}} & -\frac{y_{13}x_{1}}{x_{5}} & -\frac{y_{14}x_{1}}{x_{5}}\\
\end{bmatrix}
=
\begin{bmatrix}
	-\frac{x_{4}}{x_{5}} & 1 & 0 & 0 \\
	-\frac{x_{3}}{x_{5}} & 0 & 1 & 0 \\
	-\frac{x_{2}}{x_{5}} & 0 & 0 & 1 \\
	-\frac{x_{1}}{x_{5}} & 0 & 0 & 0
\end{bmatrix}
\times 
\begin{bmatrix}
	y_{11} & y_{12} & y_{13} & y_{14}\\
	y_{21} & y_{22} & y_{23} & y_{24}\\
	y_{31} & y_{32} & y_{33} & y_{34}\\
	y_{41} & y_{42} & y_{43} & y_{44}
\end{bmatrix}.
\end{equation}
The matrix after one transformation is shown as in Eq. \ref{B1}.
\begin{equation}
\label{B1}
\begin{bmatrix}
	x_{5} & 0 & \cdots & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0\\
	x_{4} & x_{5} & 0 & \cdots & 0 & 0 & 0 & \\
	x_{3} & x_{4} & x_{5} & 0 & \cdots & 0 & 0 \\
	x_{2} & x_{3} & x_{4} & x_{5} & 0 & \cdots & 0 &  & B_{1}\\
	x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0 & \ddots & \\
	0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0 & \ddots & 0 & 0 & 0\\
	\vdots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \vdots & \vdots\\
	0 & \cdots & 0 & 0 & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0\\
	0 & 0 & \cdots & 0 & 0 & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5}
\end{bmatrix}_{n*n}.
\end{equation}
In this way, we can extract an $x_{5}$, and we have

\begin{equation}
B_{1} = TB = 
\begin{bmatrix}
	-\frac{x_{4}}{x_{5}} & 1 & 0 & 0 \\
	-\frac{x_{3}}{x_{5}} & 0 & 1 & 0 \\
	-\frac{x_{2}}{x_{5}} & 0 & 0 & 1 \\
	-\frac{x_{1}}{x_{5}} & 0 & 0 & 0
\end{bmatrix}\times
\begin{bmatrix}
	x_{1} & x_{2} & x_{3} & x_{4}\\
	0 & x_{1} & x_{2} & x_{3}\\
	0 & 0 & x_{1} & x_{2}\\
	0 & 0 & 0 & x_{1}
\end{bmatrix}.
\end{equation}

So, each time we perform the operation in Eq.\ref{xy}, we can reduce the size of the matrix and extract a $x_{5}$. Eventually, the matrix will be reduced to an $8 \times 8$ matrix as shown in Eq.\ref{24}.

\begin{equation}
\label{24}
\begin{bmatrix}
	x_{5} & 0 & 0 & 0 &  &  &  & \\
	x_{4} & x_{5} & 0 & 0 &  &  &  & \\
	x_{3} & x_{4} & x_{5} & 0 &  & B_{n-8} &  & \\
	x_{2} & x_{3} & x_{4} & x_{5} &  &  &  & \\
	x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0 & 0 & 0\\
	0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0 & 0\\
	0 & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & 0\\
	0 & 0 & 0 & x_{1} & x_{2} & x_{3} & x_{4} & x_{5}
\end{bmatrix}.
\end{equation}
According to Eq.\ref{xty}, we can get the matrix $B'$.
\begin{equation}
\label{25}
B_{n-8} = T^{n-8}B = 
\begin{bmatrix}
	-\frac{x_{4}}{x_{5}} & 1 & 0 & 0 \\
	-\frac{x_{3}}{x_{5}} & 0 & 1 & 0 \\
	-\frac{x_{2}}{x_{5}} & 0 & 0 & 1 \\
	-\frac{x_{1}}{x_{5}} & 0 & 0 & 0
\end{bmatrix}^{n-8}\times
\begin{bmatrix}
	x_{1} & x_{2} & x_{3} & x_{4}\\
	0 & x_{1} & x_{2} & x_{3}\\
	0 & 0 & x_{1} & x_{2}\\
	0 & 0 & 0 & x_{1}
\end{bmatrix}.
\end{equation}
Now we get the answer shown in Eq.\ref{M} when $k=5$.
\begin{equation}
\label{df}
\begin{vmatrix}M\end{vmatrix} = (-1)^{(k-i)(n-k+i)} x_{k}^{n-k+1} \begin{vmatrix}D-CA^{-1}T^{n-2k+2}B\end{vmatrix},
\end{equation}
where the element in the upper left corner of the matrix is $x_{i}$ ($i\leq k$, in the example of Eq.\ref{M}, $i = 3$) and 
\begin{equation}
\label{abcdt}
A = D =
\begin{bmatrix}
	x_{k} & 0 & \cdots & 0\\
	x_{k-1} & x_{k} & \cdots & 0\\
	\vdots & \vdots & \ddots & \vdots\\
	x_{2} & x_{3} & \cdots & x_{k}
\end{bmatrix}
,B = C = 
\begin{bmatrix}
	x_{1} & x_{2} & \cdots & x_{k-1}\\
	0 & x_{1} & \cdots & x_{k-2}\\
	\vdots & \vdots & \ddots & \vdots\\
	0 & 0 & \cdots & x_{1}
\end{bmatrix},
T = 
\begin{bmatrix}
	-\frac{x_{k-1}}{x_{k}} & 1 & 0  & \cdots & 0\\
	-\frac{x_{k-2}}{x_{k}} & 0 & 1  & \cdots & 0\\
	\vdots & \vdots & \ddots & \ddots & \vdots\\
	-\frac{x_{2}}{x_{k}} & 0 & \cdots & 0 & 1\\
	-\frac{x_{1}}{x_{k}}  & 0 & \cdots & 0 & 0
\end{bmatrix}.
\end{equation}

\begin{proposition}
We can solve the determinant of a $k$-CM in $O(k^3 \log n)$.
\end{proposition}
\begin{proof}
Since matrices $A$, $B$, $C$, and $D$ are all of order $k-1$, the complexity of their computation is $O{(k^3)}$. For $T^{n-2k+2}$, we can use the fast matrix exponentiation method to calculate it.
\begin{equation}	
	T^n=
	\begin{cases}
		T^{\frac{n}{2}}*T^{\frac{n}{2}} & \text{ if } n \text{ mod } 2 =0 \\
		T^{\frac{n-1}{2}} * T^{\frac{n-1}{2}}* T & \text{ if } n \text{ mod } 2 =1 
	\end{cases}
\end{equation}

By doing so, we reduce the computation of the $n$th power of $T$ to logarithmic complexity, hence the complexity is $O(k^3 \log n)$. Furthermore, using the Jordan canonical form method can also solve the problem with logarithmic complexity, but when the problem is approached within a finite field, errors caused by inaccuracies may occur.
\end{proof}

The algorithm can solve the determinant of a $k$-CM in $O(k^3 \log n)$. Similar computation will also be utilized in the next section.

\section{Inverse of $k$-diagonal circulant matrices\label{s3}}

The algorithm mentioned in this paper is mainly based on the following formula:
\begin{equation}
\label{i1}
A^{-1} = \frac{A^*}{|A|}.
\end{equation}
$|A|$ has already been calculated in the previous section, so this section mainly computes $A^*$. We begin with the following simple theorem:

\begin{proposition}
The inverse of a circulant matrix is still a circulant matrix \cite{horn2012matrix}.
\end{proposition}


Since a circulant matrix can be represented as a vector, we only need to compute one entire row of the inverse $k$-CM matrix, which means $n$ distinct inverse elements.

Following we will introduce our algorithm using $k=5$ as an example, which can solve the inverse of $k$-CM with a complexity of $O(k^3 \log n+k^4)+kn$.


We first perform row and column swaps on the matrix to achieve the following form, requiring only one non-zero element in the upper right corner. Then compute the algebraic cofactors of these $k-1$ elements in boxes. By dividing them by $|M|$, we obtain the first $k-1$ elements of the first column of the inverse matrix.

\begin{equation}
\label{i2}
\setlength{\arraycolsep}{3.5pt}
M = 
\begin{bmatrix}
	\boxed{x_{2}} & \boxed{x_{3}} & \boxed{x_{4}} & \boxed{x_{5}} & 0 & \cdots & 0 & x_{1}\\
	x_{1} & x_{2} & x_{3} & x_{4} & x_{5} & \ddots & 0 & 0 \\
	0 & x_{1} & x_{2} & x_{3} & x_{4} & \ddots & 0 & 0 \\
	\vdots & \ddots & \ddots & \ddots & \ddots & \ddots & \vdots & \vdots \\
	0 &  0 & 0 & \cdots & x_{2} & x_{3} & x_{4} & x_{5}\\ 
	x_{5} & 0 & 0 & \cdots & x_{1} & x_{2} & x_{3} & x_{4} \\
	x_{4} & x_{5} & 0 & \cdots & 0 & x_{1} & x_{2} & x_{3} \\
	x_{3} & x_{4} & x_{5} & \cdots & 0 & 0 & x_{1} & x_{2} \\
\end{bmatrix}
\end{equation}

The algebraic cofactors we need can be obtained using the fast algorithm from Section 2. Their values are equal to the determinant of the following block matrix. We denote the value of the $i$th element we are seeking as $y_i$. $A_i$ and $C_i$ represent the matrices obtained by removing the $i$th column from matrices $A$ and $C$, respectively.

\begin{equation}
\label{i3}
y_i= 
\frac{(-1)^{(i+1)+k(n-2k+2)}x_{k}^{n-2k+2}
	\begin{vmatrix}
		T^{n-2k+2}A_i & B\\
		C_i & D
\end{vmatrix}}{|M|} \ \ (i=1,2,\cdots, k-1)
\end{equation}
\begin{equation}
\setlength{\arraycolsep}{3.5pt}
\nonumber
A=
\begin{bmatrix}
	x_{1} & x_{2} & \cdots & x_{k-1}\\
	0 & x_{1} & \cdots & x_{k-2}\\
	\vdots & \vdots & \ddots & \vdots\\
	0 & 0 & \cdots & x_{1}
\end{bmatrix}_{(k-1)^2},
B=
\begin{bmatrix}
	x_{k} & 0 & \cdots & 0\\
	x_{k-1} & x_{k} & \cdots & 0\\
	\vdots & \vdots & \ddots & \vdots\\
	x_{2} & x_{3} & \cdots & x_{k}
\end{bmatrix}_{(k-1)^2},
T=
\begin{bmatrix}
	-\frac{x_{k-1}}{x_{k}} & 1 & 0  & \cdots & 0\\
	-\frac{x_{k-2}}{x_{k}} & 0 & 1  & \cdots & 0\\
	\vdots & \vdots & \ddots & \ddots & \vdots\\
	-\frac{x_{2}}{x_{k}} & 0 & \cdots & 0 & 1\\
	-\frac{x_{1}}{x_{k}}  & 0 & \cdots & 0 & 0
\end{bmatrix}_{(k-1)^2},
\end{equation}
\begin{equation}
\setlength{\arraycolsep}{3.5pt}
\nonumber
C=
\begin{bmatrix}
	x_{k} & 0 & \cdots & 0 &0\\
	x_{k-1} & x_{k} & \cdots & 0 &0\\
	\vdots & \vdots & \ddots & \vdots &\vdots\\
	x_{3} & x_{4} & \cdots & x_{k} &0 \\
\end{bmatrix}_{(k-2)*{(k-1)}},
D=
\begin{bmatrix}
	x_{1} & x_{2} & \cdots & x_{k-2} & x_{k-1}\\
	0 & x_{1} & \cdots & x_{k-3} & x_{k-2}\\
	\vdots & \vdots & \ddots & \vdots &\vdots \\
	0 & 0 & \cdots & x_{1} & x_{2}
\end{bmatrix}_{(k-2)*{(k-1)}}.
\end{equation}

%A=
%\begin{bmatrix}
%	x_{1} & x_{2} & x_{3} & x_{4} \\
%	0 & x_{1} & x_{2} & x_{3} \\
%	0 & 0 & x_{1} & x_{2}\\
%	0 & 0 & 0 & x_{1} 
%\end{bmatrix},
%B=
%\begin{bmatrix}
%	x_{5} & 0 & 0 & 0\\
%	x_{4} & x_{5} & 0 & 0\\
%	x_{3} & x_{4} & x_{5} & 0\\
%	x_{2} & x_{3} & x_{4} & x_{5}
%\end{bmatrix},
%C=
%\begin{bmatrix}
%	x_{5} & 0 & 0 & 0\\
%	x_{4} & x_{5} & 0 & 0\\
%	x_{3} & x_{4} & x_{5} & 0\\
%\end{bmatrix},
%D=
%\begin{bmatrix}
