%\end{bmatrix}, T =\begin{bmatrix}
%	-\frac{x_{4}}{x_{5}} & 1 & 0 & 0 \\
%	-\frac{x_{3}}{x_{5}} & 0 & 1 & 0 \\
%	-\frac{x_{2}}{x_{5}} & 0 & 0 & 1 \\
%	-\frac{x_{1}}{x_{5}} & 0 & 0 & 0
%\end{bmatrix}



If we set the first column of the inverse matrix as $y$, we can list the following set of equations:
\begin{equation}
\label{i4}
\begin{cases}
	x_1y_n+x_2y_1+x_3y_2+x_4y_3+ \cdots +x_{k}y_{k-1} &= 1\\
	x_1y_1+x_2y_2+x_3y_3+x_4y_4+ \cdots +x_{k}y_{k} & = 0\\ 
	x_1y_2+x_2y_3+x_3y_4+x_4y_5+ \cdots +x_{k}y_{k+1} &= 0\\ 
	x_1y_3+x_2y_4+x_3y_5+x_4y_6+ \cdots +x_{k}y_{k+2} &= 0\\ 
	\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \  \vdots \\
	x_1y_{n-1}+x_2y_n+x_3y_1+x_4y_2+ \cdots +x_{k}y_{k-2} &= 0\\ 
\end{cases},
\end{equation}
where $x_1$ to $x_{k}$ are known quantities and $y_1$ to $y_{k-1}$ have already been solved in previous steps. Therefore, we can directly derive the other elements in vector $y$ through the following recurrence formula.

\begin{equation}
y_{i} = -\frac{ x_1y_{i-k+1}+x_2y_{i-k+2}+x_3y_{i-k+3}+ \cdots x_{k-1}y_{i-1}}{x_k} \ \ (i=k,k+1,\cdots,n).
\end{equation}
We summarize the above calculation method into Algorithm \ref{a1}.
\begin{algorithm}[h]
\SetAlgoLined
\label{a1}
Input a matrix $M$ in the form of Eq. \ref{i2} \;
calculate $|M|$\;
calculate $y_1,y_2,\cdots,y_{k-1}$ according to Eq. \ref{i3}\;
calculate $y_k,y_{k+1},\cdots,y_{n}$ according to Eq. \ref{i4}\;
construct and return $M^{-1}$
\caption{Inverse of $k$-diagonal circulant matrix $M$.}
\end{algorithm}

\begin{proposition}
We can solve the inverse of a $k$-CM in $O(k^3 \log n+k^4)+kn$.
\end{proposition}
\begin{proof}
We have already proven that the complexity of step 2 is $O(k^3 \log n)$. In step 3, $T^{n-2k+2}$ only needs to be calculated once, with a complexity of $O(k^3 \log n)$. The complexity of other matrix operations is $O(k^4)$. In step 4, the number of calculations for each unknown is $k$, so the cost of step 4 is $kn$.
\end{proof}


We believe that the complexity of this algorithm may have already been reduced to the optimization. In general, $k$ is much smaller than $n$, so the coefficient of $n$ has the greatest impact on the algorithm's speed. Through the method of recurrence relations, we have reduced the coefficient of $n$ to $k$, and even the constant term is only 1. We think that it is almost impossible to continue optimizing further. Furthermore, this algorithm is extremely simple, requiring only five steps, and each step can be directly substituted into a formula, which is also a very commendable aspect. 


\section{Inverse of $k$-diagonal cyclic banded matrices\label{s2}}


The calculation of the inverse of $k$-CBM is similar to that of $k$-CM. It still involves first solving for the determinant, then using the algebraic cofactors to solve for some elements in the inverse matrix, and finally solving the entire inverse matrix by solving a system of linear equations. Because the calculation process is mostly similar, we will omit many of the computational steps in this section. However, we will still present the final calculation formulas.

The determinant of a $k$-CBM satisfies the following equation:
\begin{equation}
\begin{vmatrix}M_{n * n}\end{vmatrix} = (-1)^{(k-i)(n-k+i)} 
\begin{vmatrix}D-CA^{-1}(\prod_{j=1}^{n-2k+2}T_j)B\end{vmatrix}  \prod_{j=1}^{n-k+1}x^{(j)}_k,
\end{equation}
where  $n \ge 2k-2$ and the element in the upper left corner of the matrix is $x_{i}$ $(i \leq k$, in example of Eq.\ref{M}, $i = 3$).
\begin{equation}
\renewcommand\arraystretch{1.5}
A = 
\begin{bmatrix}
	x^{(n-2k+3)}_{k} & 0 & \cdots & 0\\
	x^{(n-2k+4)}_{k-1} & x^{(n-2k+4)}_{k}  & \cdots & 0\\
	\vdots & \vdots & \ddots & \vdots\\
	x^{(n-k+1)}_{2} & x^{(n-k+1)}_{3} & \cdots & x^{(n-k+1)}_{k}
\end{bmatrix},
B = 
\begin{bmatrix}
	x^{(1)}_1 & x^{(1)}_2 & \cdots & x^{(1)}_{k-1}\\
	0 & x^{(2)}_1 & \cdots & x^{(2)}_{k-2}\\
	\vdots & \vdots  & \ddots & \vdots\\
	0 & 0 & \cdots & x^{(k-1)}_{1}
\end{bmatrix} ,
T_j =
\begin{bmatrix}
	-\frac{x^{(j+1)}_{k-1}}{x^{(j)}_k} & 1 & 0  & \cdots & 0\\
	-\frac{x^{(j+2)}_{k-2}}{x^{(j)}_k} & 0 & 1  & \cdots & 0\\
	\vdots & \vdots & \ddots & \ddots & \vdots\\
	-\frac{x^{(j+k-2)}_{2}}{x^{(j)}_k} & 0 & \cdots & 0 & 1\\
	-\frac{x^{(j+k-1)}_{1}}{x^{(j)}_k}  & 0 & \cdots & 0 & 0
\end{bmatrix},
\end{equation}
\begin{equation}
\label{e11}
\renewcommand\arraystretch{1.5}
C = 
\begin{bmatrix}
	x^{(n-k+2)}_{1} & x^{(n-k+2)}_{2} & \cdots & x^{(n-k+2)}_{k-1}\\
	0 & x^{(n-k+3)}_{1} & \cdots & x^{(n-k+3)}_{k-2}\\
	\vdots & \vdots & \ddots & \vdots \\
	0 & 0 & \cdots & x^{(n)}_{1}
\end{bmatrix},
D = 
\begin{bmatrix}
	x^{(n-k+2)}_{k} & 0 & \cdots & 0\\
	x^{(n-k+3)}_{k-1} & x^{(n-k+3)}_{k} & \cdots & 0\\
	\vdots & \vdots & \ddots & \vdots\\
	x^{(n)}_{2} & x^{(n)}_{3} & \cdots & x^{(n)}_{k}
\end{bmatrix}.
\end{equation}


We can quickly conclude that the complexity of calculating the determinant of a $k$-CBM is $O(k^3n)$.
Next, unlike with $k$-CM, we need to calculate the algebraic cofactors of the $(k-1)^2$ elements marked in boxes. For ease of demonstration, we will still use $k=5$ as an example.

\begin{equation}
\label{CBM}
M = 
\begin{bmatrix}
	\boxed{x_{2}^{(1)}} & \boxed{x_{3}^{(1)}} & \boxed{x_{4}^{(1)}} & \boxed{x_{5}^{(1)}} & 0 & 0 & 0 & \cdots & 0 & x_{1}^{(1)}\\
	x_{1}^{(2)} & \boxed{x_{2}^{(2)}} & \boxed{x_{3}^{(2)}} & \boxed{x_{4}^{(2)}} & \boxed{x_{5}^{(2)}} & 0 & 0 & \ddots & 0 & 0 \\
	0 & x_{1}^{(3)} & \boxed{x_{2}^{(3)}} & \boxed{x_{3}^{(3)}} & \boxed{x_{4}^{(3)}} & \boxed{x_{5}^{(3)}} & 0 & \ddots & 0 & 0 \\
	0 & 0 & x_{1}^{(4)} & \boxed{x_{2}^{(4)}} & \boxed{x_{3}^{(4)}} & \boxed{x_{4}^{(4)}} & \boxed{x_{5}^{(4)}} & \ddots & 0 & 0  \\
	\vdots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \ddots & \vdots & \vdots \\
	0 &  0 & 0 & \cdots & 0 & x_{1}^{(n-3)} & x_{2}^{(n-3)} & x_{3}^{(n-3)} & x_{4}^{(n-3)} & x_{5}^{(n-3)}\\ 
	x_{5}^{(n-2)} & 0 & 0 & \cdots & 0 & 0 & x_{1}^{(n-2)} & x_{2}^{(n-2)} & x_{3}^{(n-2)} & x_{4}^{(n-2)} \\
	x_{4}^{(n-1)} & x_{5}^{(n-1)} & 0 & \cdots & 0 & 0 & 0 & x_{1}^{(n-1)} & x_{2}^{(n-1)} & x_{3}^{(n-1)} \\
	x_{3}^{(n)} & x_{4}^{(n)} & x_{5}^{(n)} & \cdots & 0 & 0 & 0 & 0 & x_{1}^{(n)} & x_{2}^{(n)} \\
\end{bmatrix}
\end{equation}

For the algebraic cofactors of the elements in the first row, we have already calculated them previously. For the elements in the second row, we can calculate them in the same manner by moving the first row of the matrix to the bottom and the first column to the rightmost, and so on. By dividing the results by $|M|$, we obtain the $(k-1)^2$ elements in the inverse matrix. We use $M^{-1}_{i,j}$ to represent the element in the $i$th row and $j$th column of the matrix $M^{-1}$. $A_{i,j}$ and $C_{i,j}$ represent the matrices obtained by removing the $i$th column from matrices $A_{j}$ and $C_{j}$, respectively. Moreover, when the indices (superscripts and subscripts $i$ and $j$) exceed $n$, they should automatically modulo $n$ and similarly, if they are less than $n$, then $n$ should automatically be added.
\begin{equation}
\label{CBM-1}
M^{-1}_{i+j-1,j}= 
\frac{(-1)^{(i+1)+k(n-2k+2)}\prod_{p=j+1}^{n-2k+2+j}x^{(p)}_k
	\begin{vmatrix}
		\prod_{p=j+1}^{n-2k+2+j}T_pA_{i,j} & B_{j}\\
		C_{i,j} & D_{j}
\end{vmatrix}}{|M|} \ \ (i, j = 1,2,\cdots ,k-1)
\end{equation}
\begin{equation}
\setlength{\arraycolsep}{2pt}
\nonumber
A_{j}=
\begin{bmatrix}
	x_{1}^{(j+1)} & x_{2}^{(j+1)} & \cdots & x_{k-1}^{(j+1)}\\
	0 & x_{1}^{(j+2)} & \cdots & x_{k-2}^{(j+2)}\\
	\vdots & \vdots & \ddots & \vdots\\
	0 & 0 & \cdots & x_{1}^{(j+k-1)}
\end{bmatrix}_{(k-1)^2},
B_{j}=
\begin{bmatrix}
	x_{k}^{(n+j-2k+3)} & 0 & \cdots & 0\\
	x_{k-1}^{(n+j-2k+4)} & x_{k}^{(n+j-2k+4)} & \cdots & 0\\
	\vdots & \vdots & \ddots & \vdots\\
	x_{2}^{(n+j-k+1)} & x_{3}^{(n+j-k+1)} & \cdots & x_{k}^{(n+j-k+1)}
\end{bmatrix}_{(k-1)^2},
T_{j} =
\begin{bmatrix}
	-\frac{x^{(j+1)}_{k-1}}{x^{(j)}_k} & 1 & 0  & \cdots & 0\\
	-\frac{x^{(j+2)}_{k-2}}{x^{(j)}_k} & 0 & 1  & \cdots & 0\\
	\vdots & \vdots & \ddots & \ddots & \vdots\\
	-\frac{x^{(j+k-2)}_{2}}{x^{(j)}_k} & 0 & \cdots & 0 & 1\\
	-\frac{x^{(j+k-1)}_{1}}{x^{(j)}_k}  & 0 & \cdots & 0 & 0
\end{bmatrix}_{(k-1)^2}
\end{equation}
\begin{equation}
\setlength{\arraycolsep}{2pt}
\nonumber
C_{j}=
\begin{bmatrix}
	x_{k}^{(n+j-k+2)} & 0 & \cdots & 0 &0\\
	x_{k-1}^{(n+j-k+3)} & x_{k}^{(n+j-k+3)} & \cdots & 0 &0\\
	\vdots & \vdots & \ddots & \vdots &\vdots\\
	x_{3}^{(n+j-1)} & x_{4}^{(n+j-1)} & \cdots & x_{k}^{(n+j-1)} &0 \\
\end{bmatrix}_{(k-2)*{(k-1)}},
D_{j}=
\begin{bmatrix}
	x_{1}^{(n+j-k+2)} & x_{2}^{(n+j-k+2)} & \cdots & x_{k-2}^{(n+j-k+2)} & x_{k-1}^{(n+j-k+2)}\\
	0 & x_{1}^{(n+j-k+3)} & \cdots & x_{k-3}^{(n+j-k+3)} & x_{k-2}^{(n+j-k+3)}\\
	\vdots & \vdots & \ddots & \vdots &\vdots \\
	0 & 0 & \cdots & x_{1}^{(n+j-1)} & x_{2}^{(n+j-1)}
\end{bmatrix}_{(k-2)*{(k-1)}}.
\end{equation}



Now that we have $k-1$ known elements in one column, we can set up a system of equations to solve for all the elements in these $k-1$ columns. For each $i=1,2,\cdots ,n$ and $j=1,2,\cdots ,k-1$, we have

\begin{equation}
\label{CBM-2}
M^{-1}_{i,j}=-\frac{ x_{1}^{(i-k+2)}M^{-1}_{i-k+1,j}+x_{2}^{(i-k+2)}M^{-1}_{i-k+2,j}+x_{3}^{(i-k+2)}M^{-1}_{i-k+3,j}+ \cdots + x_{k-1}^{(i-k+2)}M^{-1}_{i-1,j}}{x_{k}^{(i-k+2)}} .
\end{equation}

If $AB=E$, then $BA=E$ as well. We can use these known $k-1$ columns to continue setting up equations, and thereby quickly solve for the entire matrix. For each $i=1,2,\cdots , n$ and $j = k, k+1, \cdots ,n$, we have

\begin{equation}
\label{CBM-3}
M^{-1}_{i,j}=
\begin{cases}
	-\frac{x_{k}^{(j-k+1)}M^{-1}_{i,j-k+1}+x_{k-1}^{(j-k+2)}M^{-1}_{i,j-k+2}+x_{k-2}^{(j-k+3)}M^{-1}_{i,j-k+3}+ \cdots +x_{2}^{(j-1)}M^{-1}_{i,j-1}}{x_{1}^{(j)}} & \text{if}\ i \neq j-1 \\
	\frac{1-x_{k}^{(j-k+1)}M^{-1}_{i,j-k+1}-x_{k-1}^{(j-k+2)}M^{-1}_{i,j-k+2}-x_{k-2}^{(j-k+3)}M^{-1}_{i,j-k+3}- \cdots -x_{2}^{(j-1)}M^{-1}_{i,j-1}}{x_{1}^{(j)}} & \text{if}\ i = j-1
\end{cases}.
\end{equation}

We summarize the above calculation method into Algorithm \ref{a2}.
\begin{algorithm}[h]
\SetAlgoLined
\label{a2}
Input a matrix $M$ in the form of Eq. \ref{CBM} \;
calculate $|M|$\;

\For{$i = 1; i < k; i++$}{
	\For{$j = 1; j < k; j++$}{
		calculate $M^{-1}_{i+j-1,j}$ according to Eq. \ref{CBM-1}\;
	}
}
\For{$j = 1; j < k; j++$}{
	\For{$i = k-1+j; i < n+j; i++$}{
		calculate $M^{-1}_{((i-1)\ mod\ n)+1,j}$ according to Eq. \ref{CBM-2}\;
	}	
}
\For{$i=1; i \leq n; i++$}{
	\For{$j = k;j \leq n; j++$}{
		calculate $M^{-1}_{i,j}$ according to Eq. \ref{CBM-3}\;
	}

}
construct and return $M^{-1}$
\caption{Inverse of $k$-diagonal cyclic banded matrix $M$.}
\end{algorithm}

\begin{proposition}
We can solve the determinant of a $k$-CBM in $O(k^3 n+k^5)+kn^2$.
\end{proposition}
\begin{proof}
In steps 3 to 7, $\prod_{p=k}^{n-2k+3}T_p$ and $\prod_{p=k}^{n-2k+3}x_{k}^{(p)}$ only needs to be calculated once, with a complexity of $O(k^3 n)$. The complexity of other matrix operations is $O(k^5)$. In steps 8 to 17, the number of calculations for each unknown is $k$, so its cost is $kn^2$.
\end{proof}


In cases where $k$ is much smaller than $n$, the inverse of a $k$-CBM can almost be found within a complexity of $kn^2$ through an iterative solution of linear equations. Notably, the coefficient for $kn^2$ is 1. Moreover, this algorithm is also very simple and easy to understand. This makes the algorithm exceptionally excellent from any perspective.



\section{Conclusion \label{s3}}
In this paper, we first introduced a method for calculating the determinant of $k$-CMs with a complexity of $O(k^3\log n)$. Based on this, we presented fast computation methods for the inverses of $k$-CMs and $k$-CBMs, with complexities of $O(k^3 \log n+k^4)+kn$ and $O(k^3 n+k^5)+kn^2$, respectively. These two calculation methods have the following advantages. First, their inverses can be rapidly represented. Second, most steps are directly substituted into formulas. Finally, the coefficients of $kn$ and $kn^2$ have been reduced to the minimum. Finally, our computations are also applicable to finite fields.

