\section{Pseudocode}\label{sec:pseudocode}

We define a function $\fnSuccIndex(u)$, that returns the \succIndex{} for a node $u$ in $O(1)$ time.
Further, we assume that $\Sigma$ and the range of factor indices $[0..z]$ are disjoint such that 
we can interpret the output correctly even if the returned reference is a character run (cf.~Line~\ref{alg:longestrepetition:characterRepetition} in \cref{alg:longestrepetition}), or a reference to a previous factor.
For instance, a pragmatic way is to encode characters by negative numbers.


\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the longest reference or return a single character}
  \label{alg:longestref}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestRef}{GetLongestFactorRef}
  \Def{\FLongestRef{$T$, $k$, previousFactors}}{
    \tcp{Initialize the longest factor with the empty factor $F_0$}
    $y \gets \{ factor \gets 0, \ length \gets 0 \}$ \;
    \tcp{Initialize the current node and current index}
    $u \gets \text{root node of $previousFactors$}$ \;
    $i \gets 0$ \; \label{alg:longestref:initindex}
    \While{$k + i \leq n$}{
      \tcp{Get end node of edge that starts with the current character}
      $v \gets u.\child(T[k + i])$ \;
      \If{$v = \bot$}{
        \tcp{Edge does not exist}
        \tcp{We were unable to read the character, therefore break loop}
        \Break \;
      }
      \tcp{Get edge from $u$ to $v$}
      $e \gets (u, v)$ \;
\tcp{Find length of longest common prefix of $T[k+i..]$ and edge label of $e$}
      $commonLength \gets T.\LimitedLCE(k + i, e.\fnPos, e.\fnLen)$ \;
      \label{alg:longestref:edgelce}

      \eIf{$commonLength \geq e.\fnLen$}{
        \tcp{edge label successfully read, increase $i$}
        $i \gets i + e.\fnLen$ \;
        \tcp{Go to next node}
        $u \gets v$ \;
        \If{$\text{$u$ is not split node}$}{ \label{alg:longestref:updatefactor}
          \tcp{Update factor}
          $y \gets \{ factor \gets \factorIndex(u), \ length \gets i \}$ \;
        }
      }{
        \tcp{Mismatch during edge label of $e$, could not reach next node}
        \Break \;
      }
    }

    \tcp{Use single character if no matching factor found, or when factor has length $1$}
    \If{$k \leq n$ $\boldsymbol{and}$ $y.length \leq 1$}{
      $y \gets \{ factor \gets T[k], \ length \gets 1 \}$ \;
    }

    \Return $y$ \;
  }
\end{algorithm}

\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the next longest LZD factor}
  \label{alg:nextlzdfactor}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \KwResult{the next longest LZD factor}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestLZDFactor}{NextLongestLzdFactor}
  \SetKwFunction{FLongestRef}{GetLongestFactorRef}
  \SetKwFunction{FLongestTruncation}{GetLongestFactorTruncation}
  \SetKwFunction{FLongestRepetition}{GetLongestFactorRepetition}
  \Def{\FLongestLZDFactor{$T$, $k$, previousFactors}}{
    \tcp{Combination factor (\Cref{alg:longestref})}
    $cf1 \gets \FLongestRef{T, k, previousFactors}$ \;
    $cf2 \gets \FLongestRef{T, $k + cf1.length$, previousFactors}$ \;
    \nosemic $cf \gets \{$ \;
      \pushline\nosemic $firstFactor \gets cf1.factor$, \;
      \nosemic $secondFactor \gets cf2.factor$, \;
      \nosemic $length \gets cf1.length + cf2.length$ \;
    \popline\nosemic $\}$ \;
    \Return $cf$ \;
  }
\end{algorithm}
\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the longest truncation of a previous factor}
  \label{alg:longesttruncation}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestTruncation}{GetLongestFactorTruncation}
  \Def{\FLongestTruncation{$T$, $k$, previousFactors}}{
    \tcp{Initialize the longest factor with the empty factor $F_0$}
    $y \gets \{ factor \gets 0, \ length \gets 0 \}$ \;
    \tcp{Initialize the current node and current index}
    $u \gets \text{root node of $previousFactors$}$ \;
    $i \gets 0$ \;
    \While{$k + i \leq n$}{ \label{alg:longesttruncation:whiledef}
      \tcp{Get end node of edge that starts with the current character}
      $v \gets u.\child(T[k + i])$ \;
      \If{$v = \bot$}{
        \tcp{Edge does not exist}
        \tcp{We were unable to read the character, therefore break loop}
        \Break \;
      }
      \tcp{Get edge from $u$ to $v$}
      $e \gets (u, v)$ \;
      \tcp{Find length of longest common prefix of $T[k+i..]$ and edge label of $e$}
      $commonLength \gets T.\LimitedLCE(k + i, e.\fnPos, e.\fnLen)$ \;
      \eIf{$commonLength \geq e.\fnLen$}{
        \tcp{edge label successfully read, increase $i$}
        $i \gets i + e.\fnLen$ \;
        \tcp{Go to next node}
        $u \gets v$ \;
        \tcp{Update factor}
        $y \gets \{ factor \gets \fnSuccIndex(u), \ length \gets i \}$ \; \label{alg:longesttruncation:alwaysupdate}
      }{
        \tcp{Mismatch during edge label of $e$, could not reach next node}
        $i \gets i + commonLength$ \; \label{alg:longesttruncation:extraupdate}
        \tcp{Update factor}
        $y \gets \{ factor \gets \fnSuccIndex(v), \ length \gets i \}$ \;
        \Break \;
      }
    }
    \Return $y$ \;
  }
\end{algorithm}

\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the next longest LZD+ factor in $O(\ell)$ time}
  \label{alg:nextlzdpfactor}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \KwResult{the next longest LZD+ factor of length $\ell$}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestLZDPFactor}{NextLongestLzdpFactor}
  \SetKwFunction{FLongestRef}{GetLongestFactorRef}
  \SetKwFunction{FLongestTruncation}{GetLongestFactorTruncation}
  \SetKwFunction{FLongestRepetition}{GetLongestFactorRepetition}
  \Def{\FLongestLZDPFactor{$T$, $k$, previousFactors}}{
    \tcp{Combination factor (\Cref{alg:longestref,alg:longesttruncation})}
    $cf1 \gets \FLongestRef{T, k, previousFactors}$ \;
    $cf2 \gets \FLongestTruncation{T, $k + cf1.length$, previousFactors}$ \;
    \tcp{Use single character for $F_{i_2}$ if no truncation found, or when factor has length $1$} \pushline
    \popline\nosemic \If{$k + cf1.length \leq n$ $\boldsymbol{and}$ $cf2.length \leq 1$}{
      $cf2 \gets \{ factor \gets T[k + cf1.length], \ length \gets 1 \}$ \;
    }
    \nosemic $cf \gets \{$ \;
      \pushline\nosemic $firstFactor \gets cf1.factor$, \;
      \nosemic $secondFactor \gets cf2.factor$, \;
      \nosemic $length \gets cf1.length + cf2.length$ \;
    \popline\nosemic $\}$ \;
    \tcp{Truncation factor (\Cref{alg:longesttruncation})}
    $tf \gets \FLongestTruncation{T, k, previousFactors}$ \;
    \Return longest factor from $cf$ and $tf$, where ties are broken such that combination is preferred \;
  }
\end{algorithm}

\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the next longest repetition of a previous factor or single character}
  \label{alg:longestrepetition}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestRepetition}{GetLongestFactorRepetition}
  \Def{\FLongestRepetition{$T$, $k$, previousFactors}}{
    \tcp{Initialize the longest factor with the empty factor $F_0$}
    $y \gets \{ factor \gets 0, \ length \gets 0 \}$ \;
    \tcp{Initialize the current node and current index}
    $u \gets \text{root node of $previousFactors$}$ \;
    $i \gets 0$ \;
    \While{$k + i \leq n$}{
      \tcp{Get end node of edge that starts with the current character}
      $v \gets u.\child(T[k + i])$ \;
      \If{$v = \bot$}{
        \tcp{Edge does not exist}
        \tcp{We were unable to read the character, therefore break loop}
        \Break \;
      }
      \tcp{Get edge from $u$ to $v$}
      $e \gets (u, v)$ \;

      \tcp{Find length of longest common prefix of $T[k+i..]$ and edge label of $e$}
      $commonLength \gets T.\LimitedLCE(k + i, e.\fnPos, e.\fnLen)$ \;

      \eIf{$commonLength \geq e.\fnLen$}{
        \tcp{edge label successfully read, increase $i$}
        $i \gets i + e.\fnLen$ \;
        \tcp{Go to next node}
        $u \gets v$ \;
        \If{$\text{$u$ is not split node}$}{
          \tcp{Update factor if longer}
          $repetitionLength \gets i + T.\fnLCE(k, k + i)$ \; \label{alg:longestrepetition:changedupdate}
          \If{$repetitionLength > y.length$}{
            $y \gets \{ factor \gets \factorIndex(u), \ length \gets repetitionLength \}$ \;
	    \label{alg:longestrepetition:characterRepetition}
          }
        }
      }{
        \tcp{Mismatch during edge label of $e$, could not reach next node}
        \Break \;
      }
    }

    \tcp{Use single character repetition if longer or equal to current length}
    \If{$k \leq n$}{
      $repetitionLength \gets 1 + T.\fnLCE(k, k + 1)$ \; \label{alg:longestrepetition:singleupdate}
      \If{$repetitionLength \geq y.length$}{
        $y \gets \{ factor \gets T[k], \ length \gets repetitionLength \}$ \;
      }
    }

    \Return $y$ \;
  }
\end{algorithm}

\begin{algorithm}
  \scriptsize
  \DontPrintSemicolon
  \caption{Finding the next longest LZDR factor in $O(\ell)$ time}
  \label{alg:nextlzdrfactor}
  \KwData{Entire input string $T$ of length $n$, starting position for current factor $k \in \mathbb{N}^+$, $previousFactors$ as radix trie}
  \KwResult{the next longest LZDR factor of length $\ell$}
  \SetKwProg{Def}{def}{:}{}
  \SetKwFunction{FLongestLZDRFactor}{NextLongestLzdrFactor}
  \SetKwFunction{FLongestRef}{GetLongestFactorRef}
  \SetKwFunction{FLongestTruncation}{GetLongestFactorTruncation}
  \SetKwFunction{FLongestRepetition}{GetLongestFactorRepetition}
  \Def{\FLongestLZDRFactor{$T$, $k$, previousFactors}}{
    \tcp{Combination factor (\Cref{alg:longestref,alg:longesttruncation})}
    $cf1 \gets \FLongestRef{T, k, previousFactors}$ \;
    $cf2 \gets \FLongestTruncation{T, $k + cf1.length$, previousFactors}$ \;
    \tcp{Use single character for $F_{i_2}$ if no truncation found, or when factor has length $1$} \pushline
    \popline\nosemic \If{$k + cf1.length \leq n$ $\boldsymbol{and}$ $cf2.length \leq 1$}{
      $cf2 \gets \{ factor \gets T[k + cf1.length], \ length \gets 1 \}$ \;
    }
    \nosemic $cf \gets \{$ \;
      \pushline\nosemic $firstFactor \gets cf1.factor$, \;
      \nosemic $secondFactor \gets cf2.factor$, \;
      \nosemic $length \gets cf1.length + cf2.length$ \;
    \popline\nosemic $\}$ \;
    \tcp{Truncation factor (\Cref{alg:longesttruncation})}
    $tf \gets \FLongestTruncation{T, k, previousFactors}$ \;
    \tcp{Repetition factor (\Cref{alg:longestrepetition})}
    $rf \gets \FLongestRepetition{T, k, previousFactors}$ \;
    \Return longest factor from $cf$, $tf$ and $rf$, where ties are broken such that combination is preferred most and repetition least \;
  }
\end{algorithm}

\section{Repetition-Variant of LZ78}

It is also possible to define an LZ78 variant, which we call LZ78R, that uses the repetition rule like LZDR\@.
So when computing an LZ78 rule, we also track the longest repetition or truncation of a factor that can be used to represent the current factor.
Preliminary experiments listed in \cref{tabLZ78R} show however that LZ78R does not yield better results than the standard LZ78 variant.

