    \centering
    \includesvg[width=.9\linewidth]{diagrams-queries_rank.svg}
    \caption{Example of querying the number of occurrences of symbol $c$ in the interval $[0, 6)$ using the wavelet tree of text $T = dbdcaacbcd$.}
    \label{fig:rank_query}
\end{figure}

\subsubsection{Rank query optimization}
Being so similar to the access query, the rank query benefits from all the optimizations covered before. Additionally, the same CUDA graph can be used to launch rank queries from the host, since the exact kernel that will be launched can be changed after instantiating the graph.

\subsection{Select query}\label{select_sec}
The select query is quite different from the other two. Since we want to find the position of a specific occurrence of a symbol, we need to start at a leaf node and then traverse upwards until we reach the root node. Algorithm \ref{alg:select} and  Figure \ref{fig:select_query} illustrate this process. As with the rank query, we already know how to traverse the tree, since the symbol is given in the query itself. Since we are looking for the second occurrence of the symbol $c$, we will perform a $select_0(2)$ to get its position in the right node of the second level, which is our starting point. Since in the current node the desired occurrence is at position three, we know that in the parent node it will be the fourth one-bit. To find the position of the fourth one-bit, we do a $select_1(4)$. If the tree had more levels we would continue as we have until now, but since we have reached the root node, we are done.

\begin{algorithm}[hbt!]
\caption{Wavelet tree select query. Inner workings of $getNodeStart$ function on line 5 are shown in Algorithm \ref{alg:getNodePos}.}
\label{alg:select}
\KwIn{Wavelet tree $wt$, index $i$, starting from $1$, and symbol $c$.}
\KwOut{Position of the $i-th$ occurrence of $c$.}
\Comment{Interval $[start\_symbol, end\_symbol)$ covered by current node.}
$start\_symbol \gets c$\;
$encoded\_symbol \gets encode(c)$\;
$result \gets i$\;
\For{$l \gets encoded\_symbol.length - 1$ \KwTo $0$}{
\Comment{If current node is right child of parent.}
\If{$getBit(encoded\_symbol.code,wt.num\_levels - 1 -l)  == 1$}{
    $start\_symbol \gets getNodeStart(start\_symbol, l, num\_levels)$\;
    \Comment{Number of occurences of symbols smaller than $start\_symbol$. Corresponds to the start of the node in the level.} 
    $counts \gets wt.cum\_histogram[start\_symbol]$\;

    \Comment{Number of ones until start of node.}
    $start \gets wt.rank_1(l, counts)$\;
    $result \gets wt.select_1(l, start + result) +1$\ \Comment*{1-indexed.}
}
\Else{
    $counts \gets wt.cum\_histogram[start\_symbol]$\;

    \Comment{Number of zeros until start of node.}
    $start \gets wt.rank_0(l, counts)$\;
    $result \gets wt.select_0(l, start + result) +1$\ \Comment*{1-indexed.}
}
\Comment{Make result relative to start of node.}
$result \gets result - counts$\;
}
\Return $result-1$\ \Comment*{0-indexed.}
\end{algorithm}

\begin{algorithm}[hbt!]
\caption{Algorithm to find at which symbol a wavelet tree node starts given a symbol it covers and its level.}
\label{alg:getNodePos}
\KwIn{Symbol $c$, level $l$ and wavelet tree $wt$.}
\KwOut{Symbol at which the node starts.}
$node\_start \gets 0$\;
\If{$isPowTwo(wt.alphabet\_size)$}{
    $node\_len\_at\_level \gets 1 \ll (wt.num\_levels - l)$\;
    $node\_start \gets c\ \&~(node\_len\_at\_level - 1)$\;
}
\Else{
    $code \gets wt.encode(symbol)$\;
    $is\_rightmost\_node \gets popcount(code.code \gg (wt.num\_levels - l)) == l$\;
    \If{$is\_rightmost\_node$}{
        \For{$i \gets 0$ \KwTo $l$}{
            $node\_start \gets node\_start + getPrevPowTwo(wt.alphabet\_size-node\_start)$\;
        }
    }
    \Else{
        $node\_start \gets c - 2^{code.len - l -1}$\;
    }
}
\Return $node\_start$

\end{algorithm}

