\subsection{The convergence analysis}

The following result demonstrates that $\varphi_i^{NN}\in V_{n_i}^{\sigma}\cap B$ is a good approximation to $\varphi_i$, and $\langle r(u_{i-1}), \varphi_i^{NN} \rangle$ is equivalent to the true error $|||u-u_{i-1}|||$ under some mild conditions.

\begin{lemma} \label{residualappro}
Let $0< \tau_i < 1$ be given. Choose $\delta_i= (\frac{2\tau_i}{2-\tau_i})^2$. Then there exists $n(\tau_i, u_{i-1})\in \mathbb{N}$ such that if $n\geq n(\tau_i, u_{i-1})$, $\varphi_i^{NN}\in V_{n_i}^{\sigma}\cap B$ defined in {\bf Definition 4.1} satisfies the approximation:
\be \label{phiappro22}
||| \varphi_i^{NN} - \varphi_i ||| \leq \frac{2^{\frac{3}{2}}\tau_i}{2-\tau_i},
\en
and $\langle r(u_{i-1}), \varphi_i^{NN} \rangle$ is equivalent to the true error $|||u-u_{i-1}|||$, provided that $\tau_i< \frac{2}{1+2^{\frac{3}{2}}}$,
\be \label{iteraalgo}
\frac{2-\tau_i}{2+(2^{\frac{3}{2}}-1)\tau_i}  \eta(u_{i-1}, \varphi_i^{NN})  \leq |||u-u_{i-1}||| \leq \frac{2-\tau_i}{2+(2^{\frac{3}{2}}+1)\tau_i} \eta(u_{i-1}, \varphi_i^{NN}).
\en
\end{lemma}

{\it Proof.} By the universal approximation property, there exists $n(\tau_i, u_{i-1})\in \mathbb{N}$ and $\tilde{\varphi}_i \in V_{n(\tau_i, u_{i-1})}^{\sigma}$ such that
$||| \varphi_i - \tilde{\varphi}_i ||| < \frac{\tau_i}{2}$, which indicates that, by the triangle inequality,  $1- \frac{\tau_i}{2}  < | | |  \tilde{\varphi}_i | | |  < 1 + \frac{\tau_i}{2}$. Let $\hat{\varphi}_i  = \tilde{\varphi}_i/|||\tilde{\varphi}_i|||\in V_{n(\tau_i, u_{i-1})}^{\sigma}\cap B$. Then
$$|||\varphi_i-\hat{\varphi}_i|||= \frac{ ||| \varphi_i ||| \tilde{\varphi}_i ||| - \tilde{\varphi}_i ||| }{||| \tilde{\varphi}_i|||}
= \frac{ ||| \varphi_i ||| \tilde{\varphi}_i ||| - \varphi_i + \varphi_i - \tilde{\varphi}_i ||| }{||| \tilde{\varphi}_i|||}
 \leq \frac{ ||| \varphi_i ||| \tilde{\varphi}_i ||| - \varphi_i ||| + ||| \varphi_i - \tilde{\varphi}_i ||| }{||| \tilde{\varphi}_i|||}
 \leq \frac{2\tau_i}{2-\tau_i}.  $$


Let $n\geq n(\tau_i, u_{i-1})$. The solution of (\ref{iteradisminmum}) satisfies
$$ \text{Re} \{ a(\varphi_i, \varphi_i^{NN})\} \geq \sup\limits_{v\in V_{n_i}^{\sigma}\cap B} ~\text{Re} \{ a(\varphi_i, v) \} - \delta_i.$$
Thus we get, noting that $\delta_i= (\frac{2\tau_i}{2-\tau_i})^2$,
$$||| \varphi_i - \varphi_i^{NN}  |||^2 = 2 - 2\text{Re} \{ a(\varphi_i, \varphi_i^{NN}) \} \leq  2 - 2\text{Re} \{ a(\varphi_i, \hat{\varphi}_i ) \} + \delta_i = ||| \varphi_i - \hat{\varphi}_i  |||^2  + \delta_i \leq 2(\frac{2\tau_i}{2-\tau_i})^2.$$

Since $$\langle r(u_{i-1}), \varphi_i \rangle = \text{Re} \{ L(v) - a(u_{i-1}, \varphi_i) \} = \text{Re} \{ a(u-u_{i-1}, \varphi_i) \} = |||u-u_{i-1}|||,$$
we have, by (\ref{etaequa}) and (\ref{conmax}),
\be
| \eta(u_{i-1}, \varphi_i^{NN}) - |||u-u_{i-1}||| | = | \langle r(u_{i-1}), \varphi_i^{NN}- \varphi_i \rangle | = | \text{Re} \{ a(u-u_{i-1}, \varphi_i^{NN}- \varphi_i ) \}| \leq |||u-u_{i-1}||| \frac{2^{\frac{3}{2}}\tau_i}{2-\tau_i}.
\en
By the triangle inequality, we obtain
\be
(1 - \frac{2^{\frac{3}{2}}\tau_i}{2-\tau_i}) |||u-u_{i-1}||| \leq \eta(u_{i-1}, \varphi_i^{NN}) \leq (1 + \frac{2^{\frac{3}{2}}\tau_i}{2-\tau_i}) |||u-u_{i-1}|||,
\en
namely (\ref{iteraalgo}).

$\hfill\Box$


The next result addresses the convergence of the proposed recursive algorithm.

\begin{theorem} \label{helmtheom}
Assume that, for $j=1,\cdots,i$,~$|||u-u_{j-1}|||>0$,~$0<\tau_j < 1$ and $\delta_j= (\frac{2\tau_j}{2-\tau_j})^2$. Let $n(\tau_j, u_{j-1})\in \mathbb{N}$ and
$\varphi_j^{NN}\in V_{n_j}^{\sigma}\cap B$ with $n_j\geq n(\tau_j, u_{j-1})$ be determined as in Lemma \ref{residualappro} ($j=1,\cdots,i$).
Then the resulting approximate solution $u_r$ has the estimate:
\be \label{conver}
|||u-u_i||| < |||u-u_0|||~\prod_{j=1}^i \min\big\{1, \frac{2^{\frac{3}{2}}\tau_j}{2-\tau_j}\big\}.
\en
\end{theorem}

{\it Proof.} On the one hand, when we choose $v=u_{i-1}\in \Phi_{i-1}^{NN} \subset \Phi_{i}^{NN}$, from Galerkin orthogonality and continuity of $a(\cdot,\cdot)$ in (\ref{dgappro}), we have $|||u-u_i||| \leq |||u-u_{i-1}|||$. On the other hand, when we choose $v=u_{i-1} + |||u-u_{i-1}|||\varphi_{i}^{NN}$, we obtain
\beq \label{iteresti}
|||u-u_i||| & \leq &  ||| u-u_{i-1} - |||u-u_{i-1}|||\varphi_{i}^{NN} |||
= ||| \varphi_{i} |||u-u_{i-1}||| - |||u-u_{i-1}||| \varphi_{i}^{NN} ||| \cr
%&& \vdots
 & = & |||u-u_{i-1}||| \cdot ||| \varphi_{i} - \varphi_{i}^{NN} |||
 \leq  |||u-u_{i-1}||| \cdot \frac{2^{\frac{3}{2}}\tau_i}{2-\tau_i}.
 % \cr && \vdots
  % \cr
% & \leq &  |||u-u_0|||~\prod_{j=1}^r \min\big\{1, \frac{2^{\frac{3}{2}}\tau_j}{2-\tau_j}\big\}.
\eq
Thus, we have
$$|||u-u_i|||  \leq |||u-u_{i-1}||| \cdot \min\big\{1, \frac{2^{\frac{3}{2}}\tau_{i}}{2-\tau_{i}}\big\}.$$
Iterating this process forward gives the desired result.

$\hfill\Box$

Particularly, (\ref{iteraalgo}) provides a computable estimate of the error $|||u-u_{i-1}|||$ that can be used as a stopping criterion for the recursive solution procedure as follows: Given a tolerance $tol > 0$, if $\eta(u_{i-1}, \varphi_i^{NN}) > tol$, then we augment the discontinuous Galerkin subspace $\Phi_{i-1}^{NN}$ to $\Phi_i^{NN}=\Phi_{i-1}^{NN}\oplus \{\varphi_i^{NN}\}$  and compute an updated approximation $u_i$; otherwise, the approximation $u_{i-1}$ is deemed satisfactory, and the procedure terminates. Additionally, owing to augmenting the discontinuous Galerkin subspace, (\ref{conver}) produces the convergence of the recursive procedure.



%We omit the proof due to the essential similarity to the proof details of the propositions 2.3-2.7 in \cite{AD}.
The following estimate of condition numbers can be viewed as the extensions to the discontinuous Galerkin plane wave neural networks of the existing results of \cite[Proposition 2.11]{AD}. We omit the proof.

\begin{lemma}
 Denote by $K^{(j)}\hat u = F^{(j)}$ the linear system (\ref{dgappro}). Then the functions $\{\varphi_i^{NN}\}_{i=1}^j$ are linearly independent. Moreover, if $\gamma = \sum\limits_{i=1}^j 2\tau_i/(1-\tau_i) <1$, the condition number of the stiffness matrix $K^{(j)}$ satisfies $\text{cond}(K^{(j)})< \frac{1+\gamma }{1-\gamma }$.
\end{lemma}

{\it Proof.} see \cite[Proposition 2.11]{AD}.

